window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["26936065"]={"book":{"id":26936065,"title":"请停止无效努力","author":"孙圈圈","translator":"","publisher":"团结出版社","pubdate":"2017-1-1","isbn":"9787512646759","tags":["自我提升","学习方法","方法论","思维","成长","好书","值得一读","请停止无效努力","发现自我","改变自我"],"memCount":25},"np":1,"pb":[46],"idx":[{"i":19446,"t":"请停止无效努力片段“为什么说，每个人都有天赋呢？”拆解","l":"TF1-1","c":"可乐","g":1,"p":1},{"i":18373,"t":"请停止无效努力","l":"TF2-2","c":"方芳","g":1,"p":1},{"i":17997,"t":"停止无效努力","l":"TF2-1","c":"方芳","g":1,"p":1},{"i":16066,"t":"如何让你的表达结构化","l":"TF1-1","c":"xiaobai","g":1,"p":1},{"i":14098,"t":"快速提升学习能力","l":"TF3-3","c":"Andy-2021","g":1,"p":1},{"i":12191,"t":"结构化思维让表达更轻松","l":"TF2-1","c":"A苏杭","g":1,"p":1},{"i":12064,"t":"如何愉快沟通","l":"TF2-3","c":"羽沐-蚂蚁","g":1,"p":1},{"i":12039,"t":"如何用正确的方法快速进阶","l":"TF2-1","c":"A苏杭","g":1,"p":1},{"i":11993,"t":"如何说服他人","l":"TF2-2","c":"羽沐-蚂蚁","g":1,"p":1},{"i":11819,"t":"临时发言没有思路，怎么办？","l":"TF1-2","c":"Andy-2021","g":1,"p":1},{"i":11756,"t":"把知识纳入知识体系的方法","l":"TF1-1","c":"Andy-2021","g":1,"p":1},{"i":11719,"t":"“结构化思维”","l":"TF2-1","c":"羽沐-蚂蚁","g":1,"p":1},{"i":11629,"t":"“刻意练习”","l":"TF1-2","c":"羽沐-蚂蚁","g":1,"p":1},{"i":11565,"t":"刻意练习的四要素","l":"TF2-2","c":"吴韬","g":1,"p":1},{"i":11332,"t":"快速搭建临场发言框架","l":"TF2-1","c":"吴韬","g":1,"p":1},{"i":10934,"t":"如何找到真正的问题","l":"TF1-2","c":"树夏","g":1,"p":1},{"i":10556,"t":"构建高价值人脉圈","l":"TF3-1","c":"林佳鸿","g":1,"p":1},{"i":10520,"t":"如何构建高价值人脉圈","l":"TF3-1","c":"林佳鸿","g":1,"p":1},{"i":10333,"t":"觉察自我情绪","l":"TF1-2","c":"微视觉","g":1,"p":1},{"i":9834,"t":"请停止无效努力","l":"TF1-2","c":"楚江","g":0,"p":1},{"i":9795,"t":"请停止无效努力","l":"TF1-1","c":"楚江","g":1,"p":1},{"i":6505,"t":"运用结构化思维，让临场表达更轻松","l":"TF1-2","c":"sheren","g":1,"p":1},{"i":6488,"t":"运用结构化思维，让临场发言更精彩","l":"TF1-2","c":"美珍","g":1,"p":1},{"i":5735,"t":"如何发现自己的优点","l":"TF2-3","c":"阿拉丁","g":1,"p":1},{"i":5070,"t":"当你感到自己陷入情绪而无法自拔的时候，我们到底该怎么办？","l":"TF2-1","c":"彭飞舞","g":0,"p":1},{"i":5011,"t":"拓展“弱联系”","l":"TF3-1","c":"柯佳","g":1,"p":1},{"i":4695,"t":"临场发言没有思路，怎么破？","l":"TF2-1","c":"管凤华","g":1,"p":1},{"i":4479,"t":"开拓自己的人脉圈","l":"TF3-3","c":"Tangcoco","g":1,"p":1},{"i":4437,"t":"巧用信息结构化，实现高效沟通","l":"TF1-1","c":"石美英","g":1,"p":1},{"i":4358,"t":"用信息结构化让自己做优秀的临场表达","l":"TF2-4","c":"Tangcoco","g":1,"p":1},{"i":4155,"t":"成人学习目标锁定","l":"TF3-2","c":"朱依凌（鱼小刺）","g":1,"p":1},{"i":4061,"t":"如何练习才能快速掌握一项技能？","l":"TF2-2","c":"张诗悦","g":1,"p":1},{"i":4000,"t":"用结构化思维的模式汇报工作或临场发言","l":"TF2-1","c":"上善若水jydd","g":1,"p":1},{"i":3949,"t":"如何做好临场发言","l":"TF2-4","c":"Tangcoco","g":1,"p":1},{"i":3944,"t":"如何快速发现自己的天赋","l":"TF2-1","c":"张诗悦","g":1,"p":1},{"i":3848,"t":"如何运用结构化思维做好临场发言","l":"TF3-2","c":"Tangcoco","g":1,"p":1},{"i":3783,"t":"临场发言没有思路，怎么破","l":"TF1-2","c":"管凤华","g":1,"p":1},{"i":3683,"t":"如何让你的演讲信息结构化 +如何讲好主题","l":"TF2-4","c":"树袋熊贝贝","g":1,"p":1},{"i":3647,"t":"构建临时发言的结构","l":"TF3-1","c":"雨点小","g":1,"p":1},{"i":3428,"t":"打造临时发言的结构","l":"TF3-1","c":"雨点小","g":1,"p":1},{"i":3426,"t":"讲故事","l":"TF2-4","c":"雨点小","g":1,"p":1},{"i":3422,"t":"如何说服他人","l":"TF2-3","c":"雨点小","g":1,"p":1},{"i":3418,"t":"美英TF1-2定级训练","l":"TF1-2","c":"石美英","g":1,"p":1},{"i":3027,"t":"如何与对方感同身受？","l":"TF1-2","c":"龚陟","g":1,"p":1},{"i":2814,"t":"如何表达认同感","l":"TF1-1","c":"黄淑群","g":0,"p":1},{"i":2420,"t":"思考结构化","l":"TF1-1","c":"雨点小","g":1,"p":1}],"ms":[{"id":19446,"topic":"请停止无效努力片段“为什么说，每个人都有天赋呢？”拆解","learn_goal":"","remark":"请停止无效努力片段“为什么说，每个人都有天赋呢？”拆解","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"可乐","city":"银川市"},"club":{"name":"银川拉拉缨分舵","city":"银川"},"prologue":"\u003cp> 一分钟自我介绍\u003c/p>\u003cp>大家好，首先感谢大家的陪伴赋能。不破不能立，不拆不成器，我是张洁，用三个标签自我介绍，1.我是一个20岁小伙子和一条9岁泰迪狗狗的优质妈妈2.在不惑之年依然对这个世界保有好奇心和探索欲3.擅长把常规工作加点脑洞滤镜。非常高兴在这个场合认识大家。\u003c/p>","ratings_count":1,"texts":[{"id":23819,"quote":"\u003cp>《请停止无效努力》作者孙圈圈 P63\u003c/p>\u003cp>为什么说，每个人都有天赋呢？\u003c/p>\u003cp>从意愿天赋来说，每个人都有自己的性格、动机和价值观，当然也就有自己独特的天赋。\u003c/p>\u003cp>从能力天赋来说，这句话也是成立的。为什么呢？因为我们每个人在不同领域上的潜力是不同的，我可能更有人际敏感度，你可能更有数据敏感度，他可能在乐感方面更加擅长。我们或许没有像莫扎特一样出众的音乐天赋，也没有像爱因斯坦那样的高智商。然而，我们忽略了相对天赋的概念。也就是说，跟你自己相比，你在A方面是比B方面更有潜力的，那么你花同样的时间，在A方面是比B方面成长快很多的，如果选择一个能利用A方面天赋的领域，你会起到事半功倍的效果。从这个角度来说，我们每个人都有天赋，也都需要利用天赋。\u003c/p>","explains":"\u003cp> \u003cstrong>What :\u003c/strong>\u003c/p>\u003cp> 找到你的天赋、潜力，等于找到你的开挂加速器。核心是聚焦全局，不如聚焦优势，让长板更长，让局部带动全局。\u003c/p>\u003cp>\u003cstrong>Why: \u003c/strong>\u003c/p>\u003cp>1. 避免“事倍功半”：硬拼自己的弱势领域，往往付出10分努力只获3分结果；聚焦天赋领域，能实现“事半功倍”。\u003c/p>\u003cp>2. 提升成就感：做契合天赋的事，更容易获得正向反馈，减少内耗，增强自信。\u003c/p>\u003cp>3. 实现差异化成长：天赋是你的“独特标签”，不用和别人比绝对优势，只需把自己的相对天赋发挥到极致，就能在对应领域站稳脚跟。\u003c/p>\u003cp>\u003cstrong>Where :\u003c/strong>\u003c/p>\u003cp>\u003cstrong>职业选择：\u003c/strong>优先匹配能用到核心天赋的岗位（如人际敏感度强适合客户服务、乐感好适合文创相关）。\u003c/p>\u003cp>\u003cstrong>家庭教育:\u003c/strong>发现孩子的天赋，潜能。帮助孩子成长。\u003c/p>\u003cp>\u003cstrong>个人成长：\u003c/strong>充分了解自己，优先选择契合天赋的方向，避免盲目跟风。\u003c/p>\u003cp>\u003cstrong>How:\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.自我复盘：\u003c/strong>列出最近3件你做起来“轻松又有成就感”的事（比如数据分析、安抚他人、策划活动），提炼背后的核心能力（如逻辑分析、共情力、统筹力）。\u003c/p>\u003cp>\u003cstrong>2. 对比提问：\u003c/strong>针对提炼的能力，问自己“这件事我比其他事学得快吗？”“别人是否常夸我在这方面做得好？”，筛选出2-3个相对优势。\u003c/p>\u003cp>\u003cstrong>3. 场景落地：\u003c/strong>在工作或生活中找天赋“用武之地”。\u003c/p>\u003cp>通过以上3个办法就可以很快的定位我们的天赋了。\u003c/p>\u003cp>例如：我觉得我的优势是表达力较好、富有创意，我常负责学校大型活动、家长会、跨校教研、检查接待等主持工作。这样的平台让我自信心倍增，主动学习的劲头更足，每日坚持听书、读书积累沉淀。在“认可—成长—精进”的良性循环中，能力与心态同步进步。【反思】：找到优势，找到天赋，了解自己，让成长看的见。\u003c/p>","interaction":"\u003cp>基于以上知识点我给自己定了个具体行动计划\u003c/p>\u003cp>A2分享 便签    规划应用\u003c/p>\u003cp>\u003cstrong>目标：\u003c/strong>\u003c/p>\u003cp>SMART（具体）:周日与老公开展1次“天赋探索”家庭互动游戏，通过定向提问+自我复盘，把他藏着的“隐藏技能”给挖出来～\u003c/p>\u003cp>行动计划：\u003c/p>\u003cp>1：攒够3条别人夸他的“彩虹屁”、扒3件他干着不累还嘚瑟的事儿，最后锁定1个能直接用的天赋\u003c/p>\u003cp>2：全程1小时搞定！不搞复杂问卷，就聊八卦似的提问，复盘主打“想到啥说啥”，拒绝烧脑emo\u003c/p>\u003cp>3：既帮他认清“原来我这么牛”，又能趁机多唠两句增进感情，顺便为以后“精准夸人”找素材。\u003c/p>\u003cp>4：周日当天拍完板，挖到的天赋1周内必须小试牛刀（比如厨艺天赋就让他做顿饭，嘴甜天赋就让他夸我3天不重样）\u003c/p>\u003cp> 以上就是我的分享，希望这个知识点能帮助到大家，今天的拆书就到这里结束了。再次谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1763543456000,"updated_at":1765781685000,"ria":true},{"id":18373,"topic":"请停止无效努力","learn_goal":"","remark":"请停止无效努力","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"方芳","city":"南京市"},"club":{"name":"南京玄武分舵","city":"南京"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>各位书友大家上午好！\u003c/p>\u003cp>非常高兴参加今天的拆书活动，先做一个简单的自我介绍。我叫方芳。用三个标签来介绍我自己，第一是企业运营,我是乳制品行业的线上外卖运营；第二是新晋拆书家；第三是八段锦运动爱好者，我坚持了两年的八段锦，这项运动对于调整理体质很有用。愿与大家一起坚持拆书学习，成为更好的自己。\u003c/p>\u003cp>\u003cstrong>图书介绍\u003c/strong>\u003c/p>\u003cp>今天我给大家带来的拆书是《请停止无效努力》\u003c/p>\u003cp>F （Feature特征）（核心是“书”，用于满足好奇心）：\u003c/p>\u003cp> 作者孙圈圈，曾任全球顶级咨询公司的咨询总监，现在创业中，是长文公众号“圈外”的掌门。这本书主要讲的是职业发展和个人提升的方法论。\u003c/p>\u003cp>A （Advantage，优势）：\u003c/p>\u003cp> 豆瓣评分8.4分，这本书是职场类图书中很畅销，适合初入职场的小白，也适合对自己未来规划和能力提升迷茫的人。\u003c/p>\u003cp>B（ Benefit利益）\u003c/p>\u003cp> 这本书所讲的关于努力的方法和思路可以用来分析我们在生活、工作和学习中遇到的大多数问题。今天的拆页片段是让大家学习如何通过4个问题，来找到自己的长处，发现自己的天赋。\u003c/p>\u003cp>\u003cstrong>学习目标：\u003c/strong>\u003c/p>\u003cp>通过本次拆书，可以让我们学习如何找到自己的天赋，各位小伙伴在跟随我完成本次现场学习后，能够通过自我提问和他问找到自己优点，发现自己的“天赋”。\u003c/p>","ratings_count":1,"texts":[{"id":22663,"quote":"\u003cp>如果你的阅历已经够丰富，并且也一直关注自己的行为、常常反思，那么，除了记录瞬间，也可以通过问自己一些问题，帮自己找到天赋。当然，问题还是围绕天赋的四个特征。并且，也依然要排除欲望和享受相关的事情。\u003c/p>\u003cp>第一类问题：自我效能相关\u003c/p>\u003cp>你认为，自己能够教别人什么？\u003c/p>\u003cp>或者，别人常常向你请教什么？\u003c/p>\u003cp>你跟他人聊天的时候，倾向聊什么？\u003c/p>\u003cp>以及，聊什么话题你会更有自信？\u003c/p>\u003cp>你在做什么事情的时候，不会感到焦虑和担心？\u003c/p>\u003cp>第二类问题：本能相关\u003c/p>\u003cp>你在做什么事情的时候，很少拖延？\u003c/p>\u003cp>长时间休假后，你最想念工作的哪个方面、哪个内容？\u003c/p>\u003cp>你宁愿放弃休息时间，也要做的事情，是什么？\u003c/p>\u003cp>第三类问题：成长／专注相关\u003c/p>\u003cp>有什么事情，让你沉浸其中忘记吃饭／睡觉？\u003c/p>\u003cp>你在做什么事情的时候，会暂时忘记刷社交网络？\u003c/p>\u003cp>你在做什么事情的时候，不容易感到疲倦和厌烦？\u003c/p>\u003cp> 第四类问题：满足相关\u003c/p>\u003cp>过去的工作和生活中，有什么能让你获得巨大的成就感和满足感？\u003c/p>","explains":"\u003cp>【过渡语】 好的，我看到大家已经基本阅读完了。接下来就由我带领大家共同拆解下，如何利用4类问题来发现自己的天赋。\u003c/p>\u003cp>【WHAT】\u003c/p>\u003cp>片段提到的是从发现天赋的四个角度来问自己一些问题，来找到我们自己的天赋和优势。\u003c/p>\u003cp>【WHY】（不这么做的坏处）\u003c/p>\u003cp>中国人大多比较谦虚，习惯反省和自我批评，找出自己的不足，但很少会去整理自己的优点。我们觉得和其他人对比，优点是不能挂在嘴边的，担心别人说自己骄傲自满。但我们都忙着去补足短板的时候，也错过了加强优势发挥天赋的机会。因为不知道自己的优势，可能在某些场合失去表现的机会，比如，在相亲场合和求职面试中因为不会应用优势失去心仪的对象或者入职机会。\u003c/p>\u003cp>【HOW】\u003c/p>\u003cp>原文针对如何找到自己的天赋，提出了四类问题，那么我来讲讲我的想法，再对这些问题进行细化：\u003c/p>\u003cp>如何才能找到自己的优势或者天赋呢？\u003c/p>\u003cp>【首先】，问自己四类问题\u003c/p>\u003cp>1、 自我能力问题\u003c/p>\u003cp>自认为最强的能力或者能驾驭的事情是什么？\u003c/p>\u003cp>别人最多夸你的是什么事情？\u003c/p>\u003cp>2、 自发愿意去做的事情\u003c/p>\u003cp>哪些事情让你自己愿意立即去做并且会不计时间成本？\u003c/p>\u003cp>3、 让你专注其中并且感受到快乐的事情\u003c/p>\u003cp>你平时投入时间精力最多的活动是什么？\u003c/p>\u003cp>4、 让你获得成就感的事情\u003c/p>\u003cp>在你工作学习和生活中，有哪些比较特别的经历让你觉得很自豪？\u003c/p>\u003cp>【其次】，写下每个问题的答案（答案可以有很多个），\u003c/p>\u003cp>【最后】，筛选整理自己天赋和优势。\u003c/p>\u003cp>【举例】\u003c/p>\u003cp>朋友要去面试，让我帮她梳理下工作经历和能力。首先，我提问了她这4类问题，第二步，让她把答案写在电脑上，最后，让她用思维导图去分类汇总，得出她几个主要的优点，并且对应了不同场合。一下子帮她找到了自信，打开了思路。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>有人会问，我问了这些问题但还是找不到自己的优点，怎么办？\u003c/p>\u003cp>可以去找熟悉的朋友亲人同事去提问，帮助你一起去寻找，打开思路。\u003c/p>\u003cp>【Where】——适用边界\u003c/p>\u003cp>适用于任何需要自我认知、职业规划、个人成长或领导力提升的场合，能够帮助个体更好地认识自己，挖掘内在潜能，实现个人价值和目标。但不适用于紧急、正式、时间紧迫或社交性场合中，会显得不合时宜或过于冗长。\u003c/p>","interaction":"\u003cp>分步催化1\u003c/p>\u003cp>好了，大家听完我对“如何找到自己天赋和优点”的拆解，相信也有了自己的收获。\u003c/p>\u003cp>现在请大家设想一下，在未来一周或者一个月内，你可能会遇到的这样的场景：\u003c/p>\u003cp>场景一、打算换工作，希望找到能发挥自己天赋又能带来满足感的工作，想探究自己真正的天赋所在。\u003c/p>\u003cp>场景二、作为单身去参加联谊会，如何找到自己的优点，在开场白中吸引异性？\u003c/p>\u003cp>场景三、公司有一个内部竞聘岗位，如何总结自己的长处以获得这份升职机会？\u003c/p>\u003cp>现在给大家1分钟时间先思考下在小组内分享，稍后我再邀请小伙伴来分享。请在表述场景的时候，加上这几个要素：时间、地点、人物，发生的事情以及你的感受。\u003c/p>\u003cp>给大家两分钟讨论，然后请书友分享一下。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>分享者：桑桑\u003c/p>\u003cp> 桑桑老师分析自己今年转行，因为考虑到身体和家庭原因，从产品经理换到其他的工作赛道。\u003c/p>\u003cp>接下来再请大家思考一下，结合你刚想到的那个场景，运用今天的所学，你准备如何找到自己的天赋和优势呢？ 我们回顾一下找到天赋和优势的四个步骤：1.提问四类问题；2.记录答案；3.筛选整理。\u003c/p>\u003cp>通过思考，大家先在便签纸上写出具体的行动计划，然后小组内分享。2分钟后我会邀请小伙伴分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>分享者：桑桑\u003c/p>\u003cp> 桑桑老师首先让朋友对她进行”灵魂拷问“，哪些是让她哪些是有成就感的事情，记录下来发现产品交付时候最有成就感，所以选择了保险行业，也是同样具有成就感的工作，符合她善于沟通，做事完结度高的优点\u003c/p>\u003cp>总结：\u003c/p>\u003cp>非常感谢小伙伴们的分享。\u003c/p>\u003cp>今天的分享就到这里了，非常感谢小伙伴的参与!同时希望大家把这个方法用起来，找到自己的天赋和优势，更好地认识自己，实现个人价值。我们下期再见！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1732173581000,"updated_at":1732274117000,"ria":true},{"id":17997,"topic":"停止无效努力","learn_goal":"","remark":"本书作者孙圈圈是在线职业教育品牌——圈外同学创始人，曾任全球著名管理咨询公司Mercer咨询总监，拥有9年企业人才管理咨询经验。很多时候，我们不是不努力，只是没找到正确的努力方法。\n\n《请停止无效努力》这本书从发掘天赋、提升能力、选择平台、回归自己等几大方面详细阐述了努力的正确模式。书里所讲的关于努力的方法与思路可以用来分析我们生活、学习和工作中遇到的大多数问题。","level":"TF2-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"方芳","city":"南京市"},"club":{"name":"南京玄武分舵","city":"南京"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>各位书友上午好，很高兴能参加今天的拆书活动，我是今天的拆书家方芳。用三个标签来介绍我自己，第一是企业运营,我是乳制品行业的线上外卖运营；第二是新晋拆书家；第三是八段锦运动爱好者，我坚持了两年的八段锦，这项运动对于调整理体质很有用。愿与大家一起坚持拆书学习，成为更好的自己。为方便我们接下来的讨论，先将现场小伙伴分为两组，靠我左边的同学为一组，靠我右边的同学为一组。\u003c/p>\u003cp> \u003cstrong>一、学习目标：\u003c/strong>\u003c/p>\u003cp>通过本次拆书，可以让我们学习如何做好临场发言，各位小伙伴在跟随我完成本次现场学习后，能够运用结构化的表达方式，让临场发言逻辑清晰有条理。\u003c/p>\u003cp>\u003cstrong>二、图书介绍\u003c/strong>（1-2分钟）\u003c/p>\u003cp>今天我给大家带来的拆书是《请停止无效努力》\u003c/p>\u003cp>F 特征（核心是“书”，用于满足好奇心）：\u003c/p>\u003cp> 作者孙圈圈，曾任全球顶级咨询公司的咨询总监，现在创业中，是长文公众号“圈外”的掌门。这本书主要讲的是职业发展和个人提升的方法论。\u003c/p>\u003cp>A 优势（重点是“比较”，用于建立安全感）：\u003c/p>\u003cp> 豆瓣评分8.4分，这本书是职场类图书中很畅销，适合初入职场的小白，也适合对自己未来规划和能力提升迷茫的人。\u003c/p>\u003cp>B 利益（强调的是“学习者”的利益，用于引发兴趣）\u003c/p>\u003cp> 这本书所讲的关于努力的方法和思路可以用来分析我们在生活、工作和学习中遇到的大多数问题。今天的拆页片段是让大家学习如何利用结构化思维，来轻松应对自我介绍，临场发言，即兴演讲等等。\u003c/p>\u003cp>请大家花2分钟时间简单的看一下拆页，看完后抬头示意我一下。\u003c/p>","ratings_count":1,"texts":[{"id":22241,"quote":"\u003cp>临场发言时，我们是有压力的。这种压力，要不让我们的大脑一片空白、胡言乱语，要不让我们的大脑信息泛滥、毫无头绪。这两种情况，听众听起来都会比较痛苦，不明白你到底想表达的是什么。\u003c/p>\u003cp>如果说，有一个清晰的结构，发言就变得容易了。一方面，如果你的大脑是杂乱无章的状态，它可以帮你把信息快速整理并输出；另一方面，如果你的大脑是一片空白的状态，它可以作为提示语帮你联想起一些有用信息。\u003c/p>\u003cp>用结构化思维，帮助你在短时间内更好地沟通，关键是三个步骤：\u003c/p>\u003cp>第一步，想主题：迅速找到一个切入点，第一句就说出自己的观点。\u003c/p>\u003cp>第二步，搭架子：在论证观点时，思考一个结构（时间、空间、程度），并只说三点，这称之为三个“架子”。\u003c/p>\u003cp>第三步，填素材：每一个架子里，填充一些事例、数据等，来推进论据向观点靠近。\u003c/p>","explains":"\u003cp>【WHAT】\u003c/p>\u003cp>片段提到结构化思维的三个步骤，帮助我们短时间内搭建即兴发言的框架结构，快速表达想法和观点。\u003c/p>\u003cp>【WHY】\u003c/p>\u003cp>大家有没有过这样的经历：我们往往会被领导突如起来的要求汇报搞的头大，工作或者临时被要求发言整的语无伦次，有口难言，思路混乱，说着说着就忘词了。在这里推荐大家练习结构化思维，来助力我们汇报工作临时发言，或者即兴演讲。\u003c/p>\u003cp>【HOW】\u003c/p>\u003cp>原文针对结构化思维沟通，已经给了我们清晰的步骤，那么我来讲讲我的想法：\u003c/p>\u003cp>如何快速组织一个即兴演讲\u003c/p>\u003cp>1、 想主题\u003c/p>\u003cp>在不用的应用场景需要不同的主题，我们可以选择适合的主题，根据主题快速找到一个切入点，第一句就亮明自己的观点，让别人清楚你要讲什么。比如汇报工作，那主题就是汇报的项目名称。\u003c/p>\u003cp>2、 搭架子\u003c/p>\u003cp>根据主题思考一个结构，可从时间维度、空间维度、程度上三个方面思考，并且只3点。\u003c/p>\u003cp>3、 填素材\u003c/p>\u003cp>在三个架子里填充一些事例、数据等作为论据来支持论点，让架子丰富起来，内容详细。比如汇报项目时这样说：项目何时开始时间，截止目前的完成情况。\u003c/p>\u003cp>【Where】——适用边界\u003c/p>\u003cp>结构化思维适用项目汇报、即兴演讲、大型场合的自我介绍等正式的场合。\u003c/p>\u003cp>但不适用于和朋友，家庭成员，恋人之间的沟通，真诚的情感表达比结构化思考更走心。\u003c/p>\u003cp>反面案例：今年的一天下午，公司领导突然要求我汇报下最近跟进的项目进度，给我准备的时间只有10分钟，非常匆忙，只能在手机上简单写了下要点。我汇报的内容杂乱逻辑不清晰，甚至出现了停顿卡壳，让领导很不满意。\u003c/p>\u003cp>学习本片段之后，我回忆了当时的场景，其实还是可以更好表现的。\u003c/p>\u003cp>比如，我可以这样表述：\u003c/p>\u003cp>（定主题）项目汇报的主题是某某项目的进度，成果以及问题。\u003c/p>\u003cp>（搭架子）从时间段，目前完成进度，产品和客户等维度方面分析。\u003c/p>\u003cp>（填素材）可以加一些具体数据和案例，比如从今年2月到8月总共进货多少家，遇到什么困难，如何解决的，需要哪些资源协助。\u003c/p>","interaction":"\u003cp>好了，大家听完我对“结构化思维”的拆解，相信也有了自己的收获。\u003c/p>\u003cp>请大家回忆最近一月自己不满意的临场发言，比如你跟老板在偶然遇到时候,老板突然提问你:最近工作怎么样? 有没有觉得头脑中信息很多,但是一时没办法有条理的说出来呢？\u003c/p>\u003cp>或者在自我介绍时，只能说出简单的兴趣爱好后就大脑一片空白呢？\u003c/p>\u003cp>给大家两分钟讨论，然后请书友分享一下。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>分享者王老师分享了领导开会时突然提问不知道如何组织语言，业务学习需要发言很紧张的案例\u003c/p>\u003cp>分享者高老师分享了工作中被客户突然提问的案例。\u003c/p>\u003cp>谢谢各位小伙伴的分享。\u003c/p>\u003cp>A1+反思加工（5分钟）：\u003c/p>\u003cp>通过今天的片段，大家学习了结构化思维的三步骤，大家可以想一想，自己在过去半年中有没有汇报工作、自我介绍，即兴演讲的场景，你都是怎么说的呢？如果回到当时那个场景，你会如何表达呢？\u003c/p>\u003cp>请花三分钟的时间小组内互相分享一下，分享自己的故事、经验时，尽量加上时间、地点、人物、起因、经过、结果，最后还有反思，在便利贴上写一下。\u003c/p>\u003cp>然后请一位学习者分享一下怎样运用本片段中结构化思维的表达方式，言之有物且符合逻辑,条理清晰。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>分享者高老师分享在遇到领导提问时，先不要立马回答，可以先思考下要讲的项目主题。第二步如果领导有时间去听，和领导汇报项目进展不顺利的原因，是资金还是人的问题，第三步，如果领导还有时间再补充一些细节。\u003c/p>\u003cp>总结：\u003c/p>\u003cp>这次我们学习了利用结构化思维应对临场发言，这期的RIA拆书课就此结束了，非常感谢小伙伴的参与，下期再见！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":22242,"quote":"\u003cp>1\u003c/p>","explains":null,"interaction":null,"flags":{"r":true,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1724640427000,"updated_at":1726975333000,"ria":true},{"id":16066,"topic":"如何让你的表达结构化","learn_goal":"","remark":"今天就向大家推荐《请停止无效努力》，可以让我们通过简单的3个步骤，“想主题，搭架子，填素材”，让我们在短时间内快速的组织好语言，更好地沟通。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"xiaobai","city":"青岛市"},"club":{"name":"青岛五月风分舵","city":"青岛"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>大家好，我是白晶，很高兴参加青岛五月风分舵的拆书过级活动。\u003c/p>\u003cp>我的三个标签分别是：终身学习者、职业规划师和未来拆书家。\u003c/p>\u003cp>【三个标签】\u003c/p>\u003cp>（1）职业规划师：跟随职业招聘公司CEO，学习践行职业规划1年；\u003c/p>\u003cp>（2）AI应用者：拥抱AI，理解AI，应用AI于自己的生活工作中;\u003c/p>\u003cp>（3）终身学习者：爱读书、爱思考，践行学以致用、知行合一。\u003c/p>\u003cp>未来我们可以一起探讨，一起努力，共同进步！\u003c/p>\u003cp>\u003cstrong>【拆书帮介绍】\u003c/strong>\u003c/p>\u003cp>下面，我简单为大家介绍一下拆书法和拆书帮。\u003c/p>\u003cp>“拆书法”是一种学习方法论。“拆书”的拆不是“拆开”，而是把书中知识，在自己的层面进行转化和内化。它强调以学习者自己为中心，而不是以“书”中的知识为中心，强调学以致用，知行合一，而不是为读书而读书，为学习而学习。\u003c/p>\u003cp>“拆书法”分为应用于个人学习的RIA便签读书法和应用于组织学习的现场拆书学习法。个人学习应用后，可以破局“为什么读了这么多书，却依然过不好这一生”；组织学习应用后，可以破局“举办了这么多培训，为什么员工就是学不会、做不好”，而你恰好可以成为组织学习中的重要角色，拆书家。\u003c/p>\u003cp>“拆书帮”是基于拆书法的学习爱好者社群。在全国各地都有分舵。比如在青岛，就是五月风分舵。拆书帮分舵是非营利性自组织，使命是帮助更多学习爱好者成长为独当一面的拆书家，主打个人成长，引导促进，相互学习，利人利己。\u003c/p>","ratings_count":1,"texts":[{"id":20148,"quote":"\u003cp>今天我要进行的是TF1-1拆书过级，主题是如何让你的表达结构化，时间10分钟。接下来，正式进入今天的分享环节。我分享的拆页来自《请停止无效努力》这本书，作者孙圈圈，曾任全球著名管理咨询公司咨询总监，现为创业公司CEO。她专注于解决努力和付出却没有回报这一类问题，帮助人们走出低效努力和重复努力的困境。\u003c/p>\u003cp>下面，先请大家用1-2分钟的时间阅读原书拆页，拆页刚刚已经分发给大家了，读完的伙伴请举手示意我一下。\u003c/p>\u003cp>\u003cstrong>【R原文片段】\u003c/strong>\u003c/p>\u003cp>如何让你的表达结构化 \u003c/p>\u003cp>《请停止无效努力》 孙圈圈 P119-120\u003c/p>\u003cp>在本书之前关于结构化思维的文章里，曾经提到过，人类大脑在处理信息时有两个习惯：\u003c/p>\u003cp>第一、不能一次太多，因为信息太长会让大脑的负荷过大；\u003c/p>\u003cp>第二、喜欢有规律的信息。\u003c/p>\u003cp>临场发言时，我们是有压力的。这种压力，要不让我们的大脑一片空白、胡言乱语，要不让我们的大脑信息泛滥、毫无头绪。这两种情况，听众听起来都会比较痛苦，不明白你到底想表达的是什么。\u003c/p>\u003cp>如果说，有一个清晰的结构，发言就变得容易了。一方面，如果你的大脑是杂乱无章的状态，它可以帮你把信息快速整理并输出；另一方面，如何你的大脑是一片空白的状态，它可以做为提示语帮你联想起一些有用信息。\u003c/p>\u003cp>用结构化思维，帮助你在短时间内更好地沟通，关键是三步骤：\u003c/p>\u003cp>第一步，想主题：迅速找到一个切入点，第一句就说出自己的观点。\u003c/p>\u003cp>第二步，搭架子：在论证观点时，思考一个结构（时间、空间、程度），并只说三点，这称为三个&quot;架子&quot;。\u003c/p>\u003cp>第三步，填素材：每个架子里，填充一些事例、数据等，来推进论据向观点靠近。\u003c/p>","explains":"\u003cp>\u003cstrong>【分享I便签】\u003c/strong>\u003c/p>\u003cp>好的，我看到大家都已经读完了原书拆页。\u003c/p>\u003cp>\u003cstrong>【WHAT】\u003c/strong>\u003c/p>\u003cp>这个片段为我们提供了一种结构化表达的方法，可以用在演讲、发言或者沟通等方面。能让我们在短时间内更好的表达自己，同时，让听众更好的理解我们表达的观点。\u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>\u003c/p>\u003cp>现在来想象一个常见的场景，在某一次开会时，你突然被点名要求发言，你是否会大脑一片空白，胡言乱语，事后又会对自己不太好的表现懊恼不已。久而久之，别人会对你有负面看法。如果表达清晰，有理有据，则容易被领导看见，更快的升职加薪。\u003c/p>\u003cp>所以，我们需要有一种短时间内更好表达自己的方法：结构化表达。因为人类的大脑处理信息有两个习惯：不能一次处理太多信息；喜欢有规律的信息。因此，提供一个清晰的结构可以帮助大脑更有效地处理和传达信息。\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp>进行结构化表达，关键有三步：\u003c/p>\u003cp>首先，想主题，迅速找到一个切入点，一开始就说出自己的观点；\u003c/p>\u003cp>其次，搭架子，构建一个结构或框架来支持你的观点，如时间，空间，程度，并只说三个点；\u003c/p>\u003cp>最后，填素材，在每个框架中填充一些具体的例子、数据等，来有效说明我们的观点。\u003c/p>\u003cp>\u003cstrong>【WHERE】\u003c/strong>\u003c/p>\u003cp>知道了结构化表达，我们还需要了解在哪些情况下可以使用它，让我们在工作生活中所向披靡。它最好的使用场景包括：会议发言、当众演讲、亲子沟通、临场应答、现场点评等。\u003c/p>","interaction":"\u003cp>【A1经验】\u003c/p>\u003cp>和大家分享一个近期发生在我身上的一个故事。\u003c/p>\u003cp>我是一个有两儿子的父亲。我们家大孩今年11岁，5年级，这个年龄的他对手机游戏特别感兴趣。但我又不希望他玩物丧志，所以在这个问题上，我们一直来回拉锯。我给他直接定下规矩：写完作业可以玩大约10分钟，他老是说太少了，但我总是说规矩就是规矩。\u003c/p>\u003cp>在上周三，大孩的游戏瘾上来了。他写完了作业，拿走我的手机，玩了30多分钟。但我发现严重超时时，我夺过手机，粗暴的告诉他，之后不要再玩我的手机了。他伤心的哭了，我也因为大声说他而很不舒服。可以说这是一次非常失败的经历了。\u003c/p>\u003cp>【A1反思】\u003c/p>\u003cp>为什么我会直接粗暴的告诉他“以后不要再玩我的手机了”。而不是和他进行沟通，看看如何引导他适度的玩手机游戏。从结构化表达来看，当我发现他不遵守我定的规矩时，我突然大脑一片空白，不知道要说什么。同时，大脑里没有结构化表达的习惯，没有第一时间想清楚沟通的主题，就在处理这件事情上断了沟通这条路。所以，本该可以用沟通解决的问题，变成了暴力解决，对他对我都是伤害。\u003c/p>\u003cp>【A2目标】\u003c/p>\u003cp>接下来，我要在这周日，和孩子就如何玩手机游戏的事情进行沟通。采用结构化表达，梳理自己的沟通话术，最终让孩子明白我为什么要限制他玩手机的时间。\u003c/p>\u003cp>【A2行动】\u003c/p>\u003cp>我在本周日，用结构化表达来构思自己和孩子沟通的内容：\u003c/p>\u003cp>1、确定主题：为什么需要限制每天的手机游戏时间。我会在谈话的一开始就明确地表达这个观点，比如我可以说：&quot;哥哥，我们今天谈谈为什么需要限制你每天玩手机游戏的时间。&quot;\u003c/p>\u003cp>2、建立框架：我会构建一个“问题--解决方案”的架子来支持我的主题。架子为：问题（过度玩手机游戏的后果），原因（为什么会过度玩手机游戏），解决方案（我们如何限制手机游戏的时间）。\u003c/p>\u003cp>3、填充材料：对于每个部分，我都会准备一些具体的例子或事实来支持我的观点。比如在讲解过度玩手机游戏的后果时，我可能会分享一些关于眼睛疲劳、睡眠不足和学业影响的事实；在讨论如何限制手机游戏时间时，我会提出一些具体的建议，比如设置每天玩游戏的时间限制，确保完成学习任务后才能玩游戏等。\u003c/p>\u003cp>通过这种方式，我可以提供一个清晰的结构来帮助我的孩子理解我为什么要限制他玩手机游戏的时间，以及我们如何共同解决这个问题。未来我还可以继续用这种方式，做好亲子沟通，增强亲子关系。\u003c/p>\u003cp>今天我的分享就到这里，结构化表达是一个工作生活中非常实用的方法，希望对大家有所帮助，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1686963808000,"updated_at":1687149657000,"ria":true},{"id":14098,"topic":"快速提升学习能力","learn_goal":"","remark":"世界瞬息万变，我们一生都离不开学习。在相同条件下，我们学习效果却差别人一大截，到底我们与别人的学习能力差距究竟在哪？不是因为你不够努力，也不是学得时间不够多，而是因为你没有掌握从错误中学习的方法。今天我们不但带来实用的方法，让你提升学习效率，避免无效努力，并且还提供练习的方法，让你通过有效练习让你用最少的重复、最短的时间快速提升学习能力。","level":"TF3-3","duration":60,"status":30,"type":0,"chaishujia":{"username":"Andy-2021","city":"南宁市"},"club":{"name":"南宁清澄分舵","city":"南宁"},"prologue":"\u003cp>【开场】大家好，我是今天的拆书家Andy。感谢大家今天来指导我们的拆书过级。我的三个标签是：1、高级项目经理 2、周更公众号2年 3、头马会员\u003c/p>\u003cp>【分组】我们在正式开始拆书之前，先进行一个小的分组，从这边开始3个人一组，方便我们一会儿会进行小组讨论。\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>学习能力是我们的必备能力。今天的学习主题围绕的是：高效学习。它能够帮助我们提高效率，更快成长。我们将学习2个拆页片断都是高效学习的方法，拆页一是学习从错误中学习方法，拆页二是学习突破瓶颈期。\u003c/p>\u003cp>分别来自于2本书《请停止无效努力》和《刻意练习》。通过现场学习，希望大家运用“在错误中学习”的方法，面对学习场景时，能设计出行动规划；同时在面对学习停滞期时，使用“突破停滞期”的方法，能设计出行动方案，跨跃停滞期。\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>【事件场景】你有没有这样的经历？读书时，一个班的同学，坐在同一间教室，听同一个老师的课，学一样的教科书，你拿到考题苦思冥想，学霸甚至看上去不咋学习，轻轻松松提前交卷却考得比你高？\u003c/p>\u003cp>工作后，一起入职的同事，两三年过后，有人已经可以独挡一面，晋升为团队主管，有人只学会了按部就班，领导叫做什么，就做什么，始终是个职场小白。\u003c/p>\u003cp>【提问】我们一生都离不开学习，相同条件下，我们学习效果却差别人一大截，到底差在哪？\u003c/p>\u003cp>【影响】低效学习不但学习效果无法保证，还浪费了大量的时间、精力，学生时成绩一般，工作后升职加薪比别人慢，时间越长与别人差距越大。\u003c/p>\u003cp>【解决】是不是我们做题多一点，学习时间长一点，更努力一点就能从解决问题？想要提升学习效率，避免无效努力？我们需要正确的学习方法。《请停止无效努力》一书中给出了我们快速提升学习效率的方法——从错误中学习。运用“从错误码中学习三步法”，你可以用最短的时间、最少的重复，提升学习效率。\u003c/p>\u003cp>【学习目标1】 拆页一学习目标：\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够使用 “从错误中学习的三步法”，在面对未来如何学习的场景中，设计出该场景的具体行动规划。\u003c/p>\u003cp>【I拆书家讲解引导】\u003c/p>\u003cp>【A1量表自测】\u003c/p>\u003cp>在开始今天的拆页内容之前，我想请大家先做一个小小的自测，看看自己是否有定期在错误中学习的习惯。下面的每道题目，如果完全符合你的情况，请打6分；如果完全不符合，请打1分。现在给大家1分钟的时间，请根据自己的实际情况完成自我测试。\u003c/p>\u003cp>【I部分】自测题得分分析\u003c/p>\u003cp>我看很多小伙伴都已经完成了测试，现在请大家给我一些相应的反馈。\u003c/p>\u003cp>1.现场得分超过25分的小伙伴请举手。说明你已经有了良好的定期在错误中学习的习惯。\u003c/p>\u003cp>2.现场得分介于15—25分的小伙伴请举手。说明这些小伙伴已经有了在错误中学习的意识，只要稍加练习将在错误中学习例行化，就能够养成定期在错误中学习的习惯。\u003c/p>\u003cp>3.现场得分低于15分的小伙伴也不用灰心，你在今天的拆书活动中也将是受益最多的，只要你认真践行我们这次拆书中的在错误中学习方法，就一定能够养成定期在错误中学习的习惯，极大的提升学习效率。\u003c/p>\u003cp>【自测量表预防异议】\u003c/p>\u003cp>小伙伴们不用和别人比分数，这个表格只是一个辅助工具，用以测量自己状态。要有成长型心态，现在的状态并不代表将来，现在学会在错误中学习的方法也不会晚。\u003c/p>\u003cp>好，接下来请大家用1分钟的时间来阅读原文拆页，读完的小伙伴，可以举手示意我一下。\u003c/p>","ratings_count":2,"texts":[{"id":18104,"quote":"\u003cp>【R原文阅读】《请停止无效努力》P35\u003c/p>\u003cp>\u003cstrong>从错误中学习\u003c/strong>\u003c/p>\u003cp>人类的学习的特征是从错误中学习，所以我们才会说“专家是在一个狭小的领域内犯过最多错误的人”。\u003c/p>\u003cp>我们都考过试，刷过题库，最有效的做题方式是，每做一遍，记下错误的题目，下一遍只做错题，而不是一遍遍从头开始做。\u003c/p>\u003cp>我的职业生涯里有过一次小转行，转过去之后，花了11个月，就从顾问升到了项目经理，就算是不转行的人，这个过程平均也是2-3年。\u003c/p>\u003cp>因为那一年，我整整写了6个月的项目日记，随时随地记录自己犯的错误，时时回顾。但是，哪有那么多机会让我犯错呢？我自己制造机会。比如，客户问一个问题，我心里先思考一个回答，然后项目经理说出她的回答时，我就暗暗对比：为什么她这么说，好处是什么，我为什么没想到，我下次可以怎么做。这样一来，我都不用真的犯错误，就可以从犯错中学习。后来，我的项目经理家里有事，我临时顶了她很多工作，大家都惊讶于，为什么我这么快就能上手。\u003c/p>\u003cp>有句话我之前一直记着，现在离开职场了，也送给大家：如果你的目标是升职为总监/经理，那么，让你的大脑先升职。\u003c/p>","explains":"\u003cp>【I：拆书家讲解引导】\u003c/p>\u003cp>好，我看很多小伙伴都已经阅读完了，下面我们就一起来共同拆解一下。\u003c/p>\u003cp>【Why】\u003c/p>\u003cp>大家都听说过一句话“失败乃成功之母”。好像只要失败的次数足够多，总可以等到成功的那一天。可是真是这样吗？现实生活中这样的频频的失败并不会一定会带来成功，反而会让人产生深深的自我怀疑。《请停止无效努力》这本书指出了失败并非成功的必要条件，学会从失败中学习才是成功之路。\u003c/p>\u003cp>【What】\u003c/p>\u003cp>作者能快速学习用的是“从错误中学习”的方法。什么是从错误中学习呢？\u003c/p>\u003cp>从错误中学习是指把（预演的）结果与标准相对比、分析，并不断检查修正的学习方法。\u003c/p>\u003cp>现在我们再回到拆页中来看，作者说要从错误中学习。\u003c/p>\u003cp>（互动1）拆书家：作者写了6个月的项目日记，她为什么要记录错误呢？\u003c/p>\u003cp>（回答）学习者：为了从错误中学习。\u003c/p>\u003cp>拆书家：对。\u003c/p>\u003cp>（互动2）：原文片段中是不是要真的犯错误才能从中学习？\u003c/p>\u003cp>（回答）学习者：不是\u003c/p>\u003cp>（互动3）拆书家：当作者没有机会犯错时她是怎么做的？\u003c/p>\u003cp>（回答）学习者：没有机会创造机会。\u003c/p>\u003cp>（互动4）拆书家：作者学习的对象是谁？\u003c/p>\u003cp>（回答）学习者：经理。\u003c/p>\u003cp>拆书家：对。\u003c/p>\u003cp>（互动5）拆书家：如果在事件发生前或发生后没有找学习的对象是不是从错误中学习呢？\u003c/p>\u003cp>（回答）学习者：不是。\u003c/p>\u003cp>拆书家：对，找到学习对象，明确学习内容，是开启从错误中学习的第一步。\u003c/p>\u003cp>（互动6）拆书家：原文中项目经理说出她的回答时，作者做了什么？\u003c/p>\u003cp>（回答）学习者：对比。\u003c/p>\u003cp>（互动7）拆书家：是的。如果找了学习对象，并与学习对象对比改正，是不是完成了错误中学习呢？\u003c/p>\u003cp>（回答）学习者：是。\u003c/p>\u003cp>（互动8）拆书家：其实并不完全。我们再来仔细阅读下原文，在作者与学习对象对比了”为什么她这么说，好处是什么“之外，还思考了什么？\u003c/p>\u003cp>（回答）学习者：我为什么没想到，我下次可以怎么做。\u003c/p>\u003cp>（互动9）拆书家：是的。这是从错误中学习的关键所在---找到形成偏差的根本原因。听经理回答，我们只能学习到这个问题应该怎么回答更好，但如果想要提升解决这一类问题的能力，我们必须找到我与学习对象偏差的原因，只有找到原因并把原因解决了，才能从根本上解决这一类问题。大家理解吗？\u003c/p>\u003cp>（回答）学习者：理解。\u003c/p>\u003cp>拆书家：好，我们来看看一般人的作法与作者做法的区别。 \u003c/p>\u003cp>一般人的作法是：遇到客户问——“我听”，经理答——“我听”；\u003c/p>\u003cp>作者的作法是：遇到客户问——“我心里答”，经理答——“我把自己的答案与经理的答案对比分析”。对比我与经理的差距在哪里？他说了4点，而我只想到1点；他为什么这么说，这么说的好处是什么？我为什么没想到？是因为我没有这类问题的思考框架吗？还是因为知识储备不够？……\u003c/p>\u003cp>【where】\u003c/p>\u003cp>学习无处不在。当我们想提升某个知识点或技能时，我们可以向书本学，向人学、向事学。在面对这3类学习的场景时，都可以用从错误学习法提升学习效率。\u003c/p>\u003cp>【举例】有种输出倒逼输入的办法是复述知识。\u003c/p>\u003cp>（互动10）拆书家：我们在学习一个新的知识点时，下面哪个运用了从错误中学习的方法？\u003c/p>\u003cp>A 用笔在书本上划线。\u003c/p>\u003cp>B对书本/作者作为学习/模仿对象，学习如何阐述或设计、举例\u003c/p>\u003cp>（回答）学习者：A。\u003c/p>\u003cp>拆书家：对。先明确学习内容，才容易找到学习对象。这是从错误中学习的第一步。\u003c/p>\u003cp>（互动11）拆书家：我们学习阐述新的知识点时，下面两种学习方法，哪种更高效？\u003c/p>\u003cp>A 把作者作为学习对象，看作者是怎么阐述知识点的；\u003c/p>\u003cp>B 把作者作为学习对象，看作者是怎么阐述知识点的；并且合上书，用自己的话阐述一遍； 再打开书，对照原书内容进行检查修正。\u003c/p>\u003cp>（回答）学习者：B。\u003c/p>\u003cp>拆书家：对。要与学习对象对比，我们才能够知道自己要改进什么。\u003c/p>\u003cp>（互动12）那是不是找到学习对象并与其对比，到此就是完整的从错误中学习步骤呢？\u003c/p>\u003cp>（回答）学习者：不是。\u003c/p>\u003cp>（互动13）拆书家：哪项是完整地从错误的中学习步骤？\u003c/p>\u003cp>A 把作者作为学习对象，看作者是怎么阐述知识点的；\u003c/p>\u003cp>B 把作者作为学习对象，看作者是怎么阐述知识点的；并且合上书，用自己的话阐述一遍； 再打开书，对照原书内容进行检查修正。\u003c/p>\u003cp>C 把作者作为学习对象，看作者是怎么阐述知识点的；并且合上书，用自己的话阐述一遍； 再打开书，对照原书内容进行检查修正。同时，思考下自己与作者间的偏差原因是什么，找到后消除偏差原因。\u003c/p>\u003cp>（回答）学习者：C。\u003c/p>\u003cp>拆书家：是的。从错误中学习一共有3个步骤。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>通过以上的例子，我们该如何去进行“在错误中学习”呢？虽然我们“在错误中学习”，但我们总结出的方法叫“对对对”。包括三个步骤：找对象、对照改错、对比找原因\u003c/p>\u003cp>（1） 第一步，找对象：第一步，先找到一个学习/模仿的对象，明确学习内容。\u003c/p>\u003cp>例如：比如向经理学习项目管理知识。\u003c/p>\u003cp> （2）第二步，对照改错：跟学习对象对照，把（自己预演的）结果与学习/模仿的对象对照，并检查修正。\u003c/p>\u003cp>例如：原文-自己心里回答，对照经理的回答检查修正；案例-合上书，用自己的话阐述一遍； 再打开书，对照原书内容进行检查修正。\u003c/p>\u003cp>（3）第三步，对比找偏差原因。在完成了第一步明确学习对象和学习内容，第二步完成与学习对象对照改错后，接着就是要找到导致偏差的原因——也就是从错误中学习的第三步。因为只有找到导致偏差的原因并消除原因，才能真正地解决这一类问题。\u003c/p>\u003cp>例如：原文-她为什么这么说？为什么我没有想到？ 案例-是我缺乏理解这个知识点所必需的背景知识吗？是我的思维模式与作者不一样吗？是我内心不认可这个知识点吗？……找到真正的原因才可以避免下次犯同样的错误。 \u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>有这种学习方法似乎很花费时间。但是你不这么做，学过的知识转眼就忘，反而是浪费了大量的学习时间，而有且未来因此浪费的时间恐怕要数倍于此。\u003c/p>","interaction":"\u003cp>【A2】编写故事\u003c/p>\u003cp>接下来，我请大家自己编写一个小故事，故事要用对话的方式开展的。小故事包括时间、地点、人物、起因、经过、结果。\u003c/p>\u003cp>场景是你未来3个月内你想学习的一项技能，比如学摄影、画画、健身、做短视频、写作、学英语、演讲、沟通、PPT、专业等……你为自己设计了一套用“对对对”的方案，最后学成了。故事可以是你把成功经验分享给别人；也可以是有人向你请教自己想学某项技能但不知道该怎么办，你把“对对对”方法教给他。用对话的形式把今天所学的“对对对”方法应用出来。\u003c/p>\u003cp>下面是我给大家的剧本范例，你可以参考范例把剧本写在下一页的空白框架里。时间4分钟，4分钟后我们请一位伙伴讲讲他的剧本。\u003c/p>\u003cp>好，大家讨论得都很热烈，哪位小伙伴愿意来分享下？好，掌声有请林七！\u003c/p>\u003cp>拆书家：林七，你想学习的技能是什么？\u003c/p>\u003cp>林七：我想学习的是英语口语，希望能够跟媒体一样、本地人说英语的国家的口语。这是我这个目标。\u003c/p>\u003cp>拆书家：想学英语口语是吧？\u003c/p>\u003cp>林七：对。假装我已经学成了之后，有一天上午在公司仙仙过来跟我打招呼，发现我能用英语跟她打招呼，仙仙说：“你的口语的语音、语调已经跟那种本地人差不多了，你怎么那么厉害？！” 于是我就把我的经验分享给她，我说：“因为三个月前我跟Andy学习了‘对对对’的三个步骤，我用这三个步骤进行学习取得的效果。首先第一步，找对象。我先找来了一部美剧，叫《肖申克的救赎》，他们里面的对话都是非常的强有力，而且发音非常的标准。第二步，我先截取前面一小段十分钟的先进行学习，先不看字幕，去回想一下自己能不能像他那样一遍一遍地去学习，跟电影对照，看发音跟他差距在哪里。最后面的是第三步，我会去分析为什么他能够说英语说的那么溜什么的。我觉得一方面是他身处在一个英语的环境中，然后是练的多、说的多，词库给的多，所以我也可以去营造这么一个环境。所以我在我家里面跟家人对话我也用英语。对于那种不熟悉的事物的名词，我就把英语的名字贴在冰箱面，经过不断的营造之后，家里面逐渐形成了一个英语氛围，我也在这种氛围中学习的更好。“\u003c/p>\u003cp>拆书家：好棒！祝贺林七运运用”对对对“三步法成功地学习到地道的英语口语，而且获得仙仙的仰慕！我们可以看到，这个学习方法其实是我们随时随地都可以用的，而且特别是林七在最后一步的时候，她会分析提高英语水平需要找到一个有利环境。虽然我没有这个英语环境，但我可以营造这种环境。并且跟别人比较英语对话这种方式去找差距，我觉得这些都做得很棒。好，掌声再次送给林七！\u003c/p>\u003cp>【片断间过渡】\u003c/p>\u003cp>通过刚才的案例讲解，我们学习了“在错误中学习”3步法（找对象——对照改正——对比找偏差”），原文中也说：人类的学习的特征是从错误中学习， “专家是在一个狭小的领域内犯过最多错误的人”。 希望大家养成在错误中学习的习惯，抓住生活和工作中随时可能出现的学习机会自我练习，提升学习能力。\u003c/p>\u003cp>学了一种新方法后，刚开始，我们会感觉到自己进步神速，有了很大的飞跃。那，是不是照这样下去，就会成为专家？然而，学习的规律曲线并不是抛物线，而是螺旋式前进的，当我们快速成长之后，随着你犯的错误越来越少，你会发现你学习的步伐越来越慢，甚至停步不前，就是遇到了所谓的“停滞期”。若是能够突破“停滞期”，我们就可以迎来第二次飞跃，从而不断螺旋式前进，从而走上成为专家之路。所以，我们不但要学会从错误中学习，还要学会如何突破“停滞期”。片断1和2是并列关系。接下来，让我们一起进入第二个拆页片段的学习。\u003c/p>\u003cp>【图书介绍2】这个方法来自于一本非常有名的书，叫做《刻意练习》\u003c/p>\u003cp>【FAB法介绍图书】\u003c/p>\u003cp>【F】《刻意练习》如何从新手到大师这本书的作者，心理学家安德斯·艾利克森提出一个术语“刻意练习”，指的是一种更高阶的、非常高效的学习方法。主要用找到学习共同体、隐性知识显性化、模仿榜样、培养多样性等方法进行练习。\u003c/p>\u003cp>【A】这本书豆瓣评分7.9分，被拆书帮创始人赵周先生、樊登读书会樊登等多位知名大咖推荐。与其他学习类书籍相比，“刻意练习”是作者从30多年的科学实验研究中总结提出的，并且书中列举了大量的研究案例。\u003c/p>\u003cp>【B1】这本书告诉我们“天赋”不是注定的，不要被天赋禁锢，每个人都可以成为专家。刻意练习就是你成为专家的向导，本书将向你显示登上巅峰的路径，和学习方法。\u003c/p>\u003cp>【B2】经过学习发展阶段的快速进步后，我们必将面对停滞期，怎么样在练习过程中快速跨越停滞期？今天我们要学习的这个片段将告诉你原因以及改变的方法。\u003c/p>\u003cp>【学习目的2】：在完成今天片段2的学习后，学习者能够使用跨越停滞三步法，在自我练习过程中遇到停滞的时候，设计一套行动方案，突破瓶颈，跨越停滞阶段。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":18105,"quote":"\u003cp>接下来我们花一分钟时间来阅读原文。\u003c/p>\u003cp>【R阅读原文】《刻意练习》\u003c/p>\u003cp>尽管打字和记数都是十分专业的技能，但在这两个领域中，跨越停滞阶段的方法都指向了一种有效而普通的方法。任何一项相当复杂的技能，都涉及一系列的组成部分，你可能更擅长其中的某些，不太擅长另一些。因此，当你发现自己再难以有所提高时，可能只是那项技能中的一两个组成部分在妨碍你，而不是所有的组成部分都在绊住你。问题是，到底是哪些呢？\u003c/p>\u003cp>为了弄懂这个问题，你得想办法稍微逼自己一下，但不要逼得太狠。只要使自己稍微超出正常状态便可以。这通常会帮助你搞清楚自己的“停滞点”在什么地方。如果你是一名网球运动员，试着找一个水平比你平常的对手稍微高一些的人来打球，你的弱点可能就会更加明显地暴露出来。如果你是一位经理，着重关注你在很忙碌或周边很嘈杂的情况下，你哪些地方容易出错，那些问题并不是异常，而是表明你的弱点，这些弱点时时刻刻都在，只是通常情况下不容易察觉。\u003c/p>\u003cp>考虑到所有这一切，我向约书亚建议，如果他想加快记住一副牌中每张牌的次序，应当想方设法比平常少花一些时间，然后看一看错误出在何处。一旦他准确辨认出是什么让记忆速度减慢了，便可以设计一些练习来提高在那方面的速度，而不是简单地一而再再而三地尝试着蛮记。如果是蛮记，只能带来一般的进步，那会占用他更多的时间，使得他不得不压缩花在记住整副牌上的时间。\u003c/p>","explains":"\u003cp>【what】我们想要高速学习，快速成长，但总会发现会有那么一个阶段我们总是原地踏步、止步不前。我们将这样的时间段称之为“停滞期”，也就是我们常说的“瓶颈期”。正如片段中作者表述的那样，我们是可以通过科学的方法找到“停滞点”，并从容的跨越“停滞期”。\u003c/p>\u003cp>【Why】如果停滞问题不能解决的话，就会练习很久但看不到进步，影响学习效果，让我们丧失继续的动力,从而放弃成长，止步不前。\u003c/p>\u003cp>【How】那我们到底该如何从容跨越“停滞期”呢？我们一起来看看一下三个步骤。\u003c/p>\u003cp>1. 走出舒适区：超出正常状态练习，逼迫自己走出熟悉的区间\u003c/p>\u003cp>2. 找出问题：找出影响进步的“停滞点”，可以自我反省，也可以请教他人；\u003c/p>\u003cp>3. 设计练习：针对“停滞点”设计出一项针对性的练习。\u003c/p>\u003cp>【举例】\u003c/p>\u003cp>我说话比较慢，这种慢节奏会影响我的表达效果，因此我想提升语速，我坚持一段时间每天利用上班路上的20分钟用讯飞语记说2000字，练习了一段时间后，我对于完成2000字的小练习已经很流畅了，但是，离1小时1万字（3500字/20分钟）还有很大的差距。于是我发现自己进入了语速练习的瓶颈期，只要语速加快，我就会断片。其实，我可以利用上述方法帮助自己提升语速的“停滞期”，达到3500字/20分钟。\u003c/p>\u003cp>1. 走出舒适区：逼迫自己走出舒适区，之前都是2000字/20分钟，现在要求自己说3500字/20分钟；\u003c/p>\u003cp>2. 找出问题：加快语速以后，我发现自己经常断片，不知道该说什么，有时语无伦次，重复以前的内容才能说到3500字/20分钟；\u003c/p>\u003cp>3.针对练习：针对不知道说什么这个问题，我的练习方法是，（1）加大输入量，每天阅读15分钟，把看到的文章用自己的语言复述出来。（2）第二天对照原文，补充细节后重述。（3）把对偏差原因分析过程快速说出来。\u003c/p>\u003cp>【适用边界】当我们学习某项技能达到一定水平后，遇到瓶颈时，可以用这种方法来帮助我们渡过停滞不前的困难阶段；但是当我们对一项技能一无所知时，这个方法就不适合了。\u003c/p>\u003cp>【预防异议】可能有的小伙伴会问，是不是我们只要通过上述3个步骤就能突破瓶颈期，实现快速成长了呢？不一定，有时候阻碍我们进步的，不一定是方法上的问题，也有可能是外部环境影响或其他原因，但是多一种方法就是多一次犯错的机会，在不断犯错的过程中学习，一定能找到解决问题的方法。\u003c/p>","interaction":"\u003cp>【A3】微行动学习步骤\u003c/p>\u003cp>(技能要点：在未包含how拆页的【A3】环节指令清晰，学习者在拆书家主持的微行动学习环节，讨论出了这类问题的解决方案。其中，微行动学习环节包含了5个步骤：1.拆书家引导学习者提出，并明确一个需要解决的问题；2.拆书家引导学习者分组讨论问题本质；3.拆书家引导学习者明确出问题本质；4.拆书家引导学习者分组讨论问题解决方案；5.请每组学习者代表讲解自己组的讨论成果。\u003c/p>\u003cp>一、明确问题\u003c/p>\u003cp>刚听完我想提升语速的小故事，大家有没有类似的经历呢？现在请大家回忆一下，在过去一年里你有没有遇到过学习某项技能遇到瓶颈期的情况？比如学摄影、画画、健身、做短视频、写作、学英语、演讲、PPT、专业等……你在学什么技能的时候遇到了瓶颈期？每人1分钟在小组内分享，3分钟后请每组的个小组代表来分享。\u003c/p>\u003cp>【第一小组内轮流分享】\u003c/p>\u003cp>林七：我是程序员，我想拓展自己的边界，想学编程方面的技能，但我总是看人家怎么做，我自己始终没有操作。所以，一直没什么进步。\u003c/p>\u003cp>小孙：我练过毛笔字，前几年练的时候觉得写对联写得很好，但是后来练着练着，感觉没信心了，这两年就没有再练了。\u003c/p>\u003cp>坛子：我想做到拆书脱稿，但总想看两眼稿子。即使稿子挺熟的了，但不看两眼就不安心。所以，总是不能脱稿。\u003c/p>\u003cp>【第二小组内轮流分享】\u003c/p>\u003cp>安宁：我学游泳总游不好，原来我怕水，好容易克服心理障碍学了游泳，但总也游不好。\u003c/p>\u003cp>仙仙：我在学设计过程中遇到一些障碍，不知道问题出在哪里，看了很多专业书，也学了网上的课，但进步总是不明显。\u003c/p>\u003cp>春华：我暂时没有什么问题。\u003c/p>\u003cp>【回应和反馈】\u003c/p>\u003cp>拆书家：好，时间到。接下来请每组推选出你们小组认为符合瓶颈期最具有代表性的问题。好，第一组认为小孙练书法的问题符合瓶颈期问题；第二组认为安宁学游泳的问题符合瓶颈期问题。接下来大家来决定接下来这2个问题中我们要讨论谁的问题，让大家群策群力一起讨论解决。现在我们就请大家投票，大家请大家举起自己的右手，伸出自己的食指。当我数三、二、一的时候，大家就把手指向你想要讨论的问题的人，我们就讨论TA的这个问题好不好？\u003c/p>\u003cp>学习者：好\u003c/p>\u003cp>拆书家：好，三、二、一！我看到4位伙伴指向小孙，小孙的问题也是个典型问题，练书法达到一定水平后，很长一段时间却停滞甚至退步了。4位小伙伴认为帮小孙解决练书法的问题比较需要一起讨论，其他2位小伙伴愿意一起讨论这个问题吗？\u003c/p>\u003cp>学习者：愿意。\u003c/p>\u003cp>拆书家：那我们就尝试用微行动学习的方法来帮小孙解决问题。大家可以向小孙提问，每个人都有向小孙提出一个问题的机会。通过提问来做出自己的判断：根据刚才的突破瓶颈期3个步骤（1.走出舒适区    2.找出问题     3.设计练习），从这个角度出发，大家认为因为哪个步骤没做好，导致出现了小孙现在这个问题的？\u003c/p>\u003cp>林七：你没有继续练习是因为不知道怎么练习吗？\u003c/p>\u003cp>小孙：我觉得我还没有找到我有什么问题，只有找到问题了才能设计出练习。\u003c/p>\u003cp>坛子：你是不是害怕失败，不愿意尝试新的技能？\u003c/p>\u003cp>小孙：我尝试过\u003c/p>\u003cp>安宁：你是看不到进步，所以失去信心了吗？\u003c/p>\u003cp>小孙：嗯，练到一定程度后，进步非常缓慢，确实让我失去了动力。\u003c/p>\u003cp>仙仙：练书法很枯燥，你原来为什么会想着练书法呢？\u003c/p>\u003cp>小孙：过年的时候邻居们找我写对联，看着别人家贴着我写的对联，很开心很得意哈！\u003c/p>\u003cp>春暖花开：那现在呢？\u003c/p>\u003cp>小孙：工作后，离开家乡离开小伙伴，来到南宁后，大家并不知道我会书法，感觉一个人练下去很没劲。\u003c/p>\u003cp>拆书家：好，经过以上提问，每个小组讨论得出你的结论：因为哪个步骤没做好，导致出现了小孙现在这个问题的？\u003c/p>\u003cp>第一组：第二步——找出问题\u003c/p>\u003cp>第二组：我们也认为第二步找出问题没做好。\u003c/p>\u003cp>【重述并明确问题】好的，现在大家一致认为小孙练书法过程中想要突破瓶颈期，第二步”找出问题“ 值得共同讨论。\u003c/p>\u003cp>二、【引导学习者讨论问题本质】\u003c/p>\u003cp>拆书家提问：现在请大家在小组内讨论一下，为什么第二步最难，而不是第一步或第三步？你们认为造成这个步骤实现困难的原因是什么？有什么本质原因造成我们很比较难”找出问题“？每个小组指定一位伙伴记录下你们的讨论结果。\u003c/p>\u003cp>给大家5分钟的时间，大家结合过往经验，在讨论的过程中可以使用启发式问题追问为什么。一次只问一个问题，每个人轮流问。每个小组的三位伙伴，可以把你们讨论的结果写在纸的背面。讨论时间结束，我们请伙伴跟大家分享一下你们讨论的结果。\u003c/p>\u003cp>【第1小组分享】\u003c/p>\u003cp>林七：我们讨论出的原因有以下几个：\u003c/p>\u003cp>（1）心态问题，缺少正反馈；\u003c/p>\u003cp>（2）环境的干扰；\u003c/p>\u003cp>（3）工作忙。\u003c/p>\u003cp>【第2小组分享】\u003c/p>\u003cp>安宁：我们讨论出的原因有以下几个：\u003c/p>\u003cp>（1）没有找到初心和动机；\u003c/p>\u003cp>（2）没有感受到练字带来的价值；\u003c/p>\u003cp>（3）没有共同爱好的圈子。\u003c/p>\u003cp>拆书家：谢谢大家！现在每组分别讨论出3个原因。那么根据大家给出的原因，我们再具体分析一下，多问几个为什么，然后确定最最本质的具体原因是什么?伙伴们要区分表象原因和本质原因。什么是表象原因？比如说：环境干扰——是什么样的环境会干扰？有没有同样的环境却不受干扰的情况？为什么？ 再比如说：工作忙，为什么工作忙会影响继续练字呢？有没有在什么情况下，哪怕你工作再忙，你也会抽时间来做的事情呢？这件事为什么与练字有区别呢？\u003c/p>\u003cp>小孙：好像工作忙并不是理由。以前上学时太阳再大、功课再忙，即使中午不睡觉都会去操场打蓝球……\u003c/p>\u003cp>拆书家：是的，可以多问几个为什么，就容易找出最本质的原因了。\u003c/p>\u003cp>小孙：好。\u003c/p>\u003cp>拆书家：又比如第2组提出的&quot;没有找到初心和动机&quot;,为什么没有找到初心和动机呢？是因为没有明确目标呢，还是因为对自己想成为什么样的人定位不够清晰呢？\u003c/p>\u003cp>安宁：哦哦，有启发，我们小组再讨论一下。\u003c/p>\u003cp>拆书家：嗯嗯，大家得出这么多的原因，哪一个才是最关键的本质呢？每个小组再讨论2分钟，三选一，统一选出一个最本质的原因。\u003c/p>\u003cp>拆书家：好的，时间到。那么我们帮小孙重拾信心”找出问题“ 感到困难的本质原因是什么？\u003c/p>\u003cp>第1组：缺乏动力。\u003c/p>\u003cp>第2组：目标不清晰。\u003c/p>\u003cp>三、明确问题本质\u003c/p>\u003cp>拆书家：好，现在我们每个小组各讨论出1个本质原因。分别是缺乏动力和目标不清晰。大家认可吗？\u003c/p>\u003cp>学习者：认可\u003c/p>\u003cp>小孙：认可\u003c/p>\u003cp>四、引导分组讨论解决方案。\u003c/p>\u003cp>拆书家引导：接下来，我们就各小组讨论出的问题本质（第1组讨论的议题是“缺乏动力”；第2组讨论的议题是“目标不清晰”），给大家5分钟时间在小组内讨论，探究可行的解决方案，看大家能给出多少思路来，再讨论怎么行动。在我们讨论如何明确目标之前我跟大家先确认一下，，我们讨论出的解决方案达到什么样的效果，就代表这个解决方案是有效的？\u003c/p>\u003cp>小孙：让我重新开始一小步。\u003c/p>\u003cp>学习者：设立清晰目标，并且有最小化的行动。\u003c/p>\u003cp>拆书家：好，大家明确了解决方案的目标，我们现在就开始讨论如何去明确目标、开始行动？请大家小组内讨论，希望大家在讨论的过程中，细化出具体步骤，3分钟后请小伙伴来分享。\u003c/p>\u003cp>五、请每组派代表讲解自己组的成果\u003c/p>\u003cp>第1组：1、找到相同爱好的圈子一起练习；2、设定“未来书法家”的新身份；3、每天在固定时间练习半小时。\u003c/p>\u003cp>第2组：1、确定自己的书法想达到的水平程度；2、网上找到书法家学习；3、有条件可以找线下的书法班学习。\u003c/p>\u003cp>拆书家反应和回馈：感谢大家集思广义给出这么多的方案，我把大家刚才讲的再归纳一下：1、设定“未来书法家”的新身份；2、确定自己的书法想达到的水平程度；3、找线下/下的书法家学习；4、到相同爱好的圈子一起练习 5、每天在固定时间练习半小时\u003c/p>\u003cp>拆书家引导：大家对这个最终答案，同意么？是否解决了实际问题？\u003c/p>\u003cp>学习者：值得试试\u003c/p>\u003cp>拆书家：小孙，你认为这些方法对你有帮助吗？能解决问题吗？\u003c/p>\u003cp>小孙：我觉得有用，我想试试\u003c/p>\u003cp>拆书家反馈：谢谢小伙伴们的积极参与和互动，其实，我们只要能够抓住问题的本质，深入研究和挖掘，就可以解决问题。那么，我们今天的微行动学习就到这里了。感谢大家的积极和热情。\u003c/p>\u003cp>【A2布置任务】\u003c/p>\u003cp>经过刚才的讨论，我们对如何突破瓶颈期有了更深的理解，请大家写出未来3个月你想突破瓶颈期的一项技能，写出你计划未来什么时间开始做这个练习？练习时，写下你的行动计划和方案，请在下周日前把你的练习情况分享给我。\u003c/p>\u003cp>收到仙仙的作业反馈：\u003c/p>\u003cp>在未来的3个月时间里，我要运用“跨越停滞三步法”来解决备稿演讲的问题，在3个月内完成L2级别演讲的突破。\u003c/p>\u003cp>加入头马已经有一年多了，但仅仅完成了第一级别演讲外，就一直没有开始第二级别演讲，我希望在演讲方面有所突破，能开始第二级的演讲。\u003c/p>\u003cp>第一步：走出舒适区。每个月完成一次备稿，把3个月内完成L2级别演讲作为目标。查询头马pathways过级手册，掌握L2级别的演讲过级要求。小区、中区、大区都有很多过级方面的分享讲座。主动链接导师及优秀的官员，并向他人请教学习。\u003c/p>\u003cp>第二步：找出问题。主要原因是心态问题。一直没有继续演讲是因为我的完美主义心态作怪，完美主义不是想赢而是怕输，因为怕演讲不如别人好，所以拖延着没有开始，\u003c/p>\u003cp>第三步：设计练习。针对心态需要调整问题，可采取针对性的措施是：\u003c/p>\u003cp>1、用输出倒逼输入的方法，先与教育副主席约好下个月第32期例会演讲。2、充分准备，增强信心。我要从多方面的去思考，并一一列出来，有针对性的去查询资料，通过讲故事 ，做好逐字稿准备、彩排练习；3、目标是40分。我需要避免急于求成的心态，正视目前自己的演讲水平只有40分，下次演讲能达到40分就算是达到我这次练习的目标了。\u003c/p>\u003cp>我相信经过调整和准备，我一定会按期完成L2级别的演讲。\u003c/p>\u003cp>【总结】\u003c/p>\u003cp>最后，我们再一起回顾一下，今天我们一共学习了两个片段，每一个片断学习了“在错误中学习”的三步法，有哪3个步骤呢？\u003c/p>\u003cp>1. 对象：找到定学习/模仿的对象和内容。 \u003c/p>\u003cp>2. 对照 ：检查改错。\u003c/p>\u003cp>3. 对比：找偏差原因\u003c/p>\u003cp>第二个片段我们学习了“跨越停滞期”的三步骤，大家一起回顾一下：1.走出舒适区 2.找出问题 3.设计练习\u003c/p>\u003cp>好，试错的成本很低，但错过的成本很高，希望大家在工作和生活中走出舒适区，大胆试错，在错误中螺旋式快速成长！感谢大家的聆听，今天的分享到此结束，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1661740346000,"updated_at":1662903880000,"ria":true},{"id":12191,"topic":"结构化思维让表达更轻松","learn_goal":"","remark":"你是否 在工作汇报时、现场演讲时常常头脑空白，不知所云？或者脑子里信息泛滥，结果反而无头绪？如果你想临场表达结构强,条理顺,展现能力,那么我们一起来学习吧","level":"TF2-1","duration":20,"status":19,"type":0,"chaishujia":{"username":"A苏杭","city":"杭州市"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"\u003cp> 伙伴们大家好！欢迎参加拆书帮活动！我叫苏杭，先用三个标签自我介绍一下：\u003c/p>\u003cp>① 1级拆书家，今天来过2-1。\u003c/p>\u003cp>② 理财爱好者，对指数型基金情有独钟。\u003c/p>\u003cp>③ “资深”HR，就不说工作多少年了，以免暴露年龄。\u003c/p>\u003cp>今天我给大家带来的拆书片段来自《请停止无效努力》，今日学习主题: 如何应用结构化思维快速表达想法和观点，尤其是在临场发言或向上汇报的时候。\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后,学习者能够在临场发言或汇报工作时，能够应用结构化的思维模式快速表达出自己的想法和观点。\u003c/p>\u003cp>【图书及作者介绍】：\u003c/p>\u003cp>【F】本书作者孙圈圈，本名孙园媛。曾任全球著名管理咨询公司咨询总监，现创业中，【领英洞察】专栏作家。本书围绕职业发展和个人能力提升所需的方法论展开，分为发掘天赋、提升能力、选择平台、回归自己等几大部分。\u003c/p>\u003cp>【A】 有别于自我成长的同类书籍，本书不仅能解答职场人士遇到的困惑还提供了实操性极强的方法，供职场人士借鉴。\u003c/p>\u003cp>【B】 在工作中，你是否常常做了很多事情却收获非常小，你可能正在无效努力。B1:如果你想改变，用正确的方法将学到的知识迅速转化为自己的能力，从而在职场中脱颖而出，这本书非常适合你阅读练习。B2:如果想临场表达结构强,条理顺,展现能力,本片段中介绍的方法可以帮到你\u003c/p>","ratings_count":2,"texts":[{"id":16105,"quote":"\u003cp>《请停止无效努力》\u003c/p>\u003cp>如何让你的演讲信息结构化 孙圈圈 P119\u003c/p>\u003cp>在本书之前关于结构化思维的文章里，曾经提到过，人类大脑在处理信息时有两个习惯：\u003c/p>\u003cp>第一、不能一次太多，因为信息太长会让大脑的负荷过大；\u003c/p>\u003cp>第二、喜欢有规律的信息。\u003c/p>\u003cp>临场发言时，我们是有压力的。这种压力，要不让我们的大脑一片空白、胡言乱语，要不让我们的大脑信息泛滥、毫无头绪。这两种情况，听众听起来都会比较痛苦，不明白你到底想表达的是什么。\u003c/p>\u003cp>如果说，有一个清晰的结构，发言就变得容易了。一方面，如果你的大脑是杂乱无章的状态，它可以帮你把信息快速整理并输出；另一方面，如何你的大脑是一片空白的状态，它可以做为提示语帮你联想起一些有用信息。\u003c/p>\u003cp>用结构化思维，帮助你在短时间内更好地沟通，关键是三步骤：\u003c/p>\u003cp>第一步，想主题：迅速找到一个切入点，第一句就说出自己的观点。\u003c/p>\u003cp>第二步，搭架子：在论证观点时，思考一个结构（时间、空间、程度），并只说三点，这称为三个“架子”。\u003c/p>\u003cp>第三步，填素材：每个架子里，填充一些事例、数据等，来推进论据向观点靠近。\u003c/p>","explains":"\u003cp>【What】\u003c/p>\u003cp> 这个片段主要讲述如何应用结构化思维快速表达想法和观点，尤其是在临场发言或向上汇报的时候。\u003c/p>\u003cp>【Why】\u003c/p>\u003cp> 人类大脑在处理信息时有两个习惯：第一、不能一次太多，因为信息太长会让大脑的负荷过大；第二、喜欢有规律的信息。基于此,一般我们在临场发言有压力时，通常是头脑空白、无话可说亦或者信息泛滥、毫无头绪。从而被误解能力不行.而学习了本片段中的方法,通过定主题，搭架子，填素材可以让我们的发言（表达）更有条理性。\u003c/p>\u003cp>【HOW】 \u003c/p>\u003cp> 我们如何学习和掌握这种思维结构呢？主要采用以下三个步骤：\u003c/p>\u003cp>第一步，定主题:不同场合,不同受众,主题通常不同。选择适合的主题，迅速找到一个切入点，最好第一句就亮明自己的观点，让别人清楚你要讲什么。\u003c/p>\u003cp>第二步，搭架子：在论证主题（观点）时，思考一个架构（时间、空间、程度），并只说三点。\u003c/p>\u003cp>第三步，填素材：每个架子里，填充一些事例、数据等，来支持论点，让架子充实起来，有内容。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>这个方法适合临场发言、工作汇报、演讲等这些有压力的发言场合。但日常朋友、亲人、恋人之间的交流，还是舒适、走心一些比较好，这时可以不用\u003c/p>\u003cp>\u003cstrong>举例（反例）：\u003c/strong>3月份刚到新单位，代表HR部门列席了一个总经理组织的会议：是关于市场部提交客户方案定稿，以及确认对接人员这样的主题。HR部门主要是对确认对接人员提供建议。没想到市场部长方案展示完之后，总经理问我对这个方案的看法。我瞬间懵圈，只说我刚来，对市场业务不太熟悉，给不出建设性意见。\u003c/p>\u003cp>学习本片段之后，我回忆了当时的场景，其实还是可以更好表现的。比如，我可以这样表述：\u003cstrong>\u003cem>（\u003cu>定主题\u003c/u>）\u003c/em>\u003c/strong>内容方面我给不出建设性意见，不过在排版上我觉得可以优化一下。（\u003cstrong>\u003cem>搭架子）\u003c/em>\u003c/strong>从字体，图片选择方面考虑。\u003cstrong>\u003cem>（填素材）\u003c/em>\u003c/strong>字体方面，客户提供过来的文件运用的是微软雅黑，我们是不是也可以运用呢？图片选择，客户公司官网上布局可以看出崇尚简约，所以我们是不是可以调整一下呢？ \u003c/p>","interaction":"\u003cp>【A1】激活学习者经验（显像提问）\u003c/p>\u003cp> 请回忆最近一周自己不满意的临场发言，比如你跟老板在茶水间遇到,老板问你:最近工作怎么样? 那工作这么多,你要说哪个呢?结果头脑中可能信息泛滥,毫无头绪。可能你会给老板一种能力不够的印象。给大家两分钟讨论，2分钟分享。\u003c/p>\u003cp>\u003cstrong>学习者案例分享（反例）：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>简：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>当时各代理商在北京总部汇报近半年业务发展情况，大概20个省级代理（除了西藏），挨个汇报。有些省级代理虽然资源不多，但做的很有成果。浙江省经济发展比较好，按理业绩会更好，但一对比发现很多工作做的都没有成果。当时比较懵，不知道怎么把自己做的工作更好的呈现出来。\u003c/strong>\u003c/p>\u003cp>【A1+】\u003c/p>\u003cp>学了今天的片段，了解了结构化思维的三步骤,请大家思考一下:若再回到【A1】中的场景,你会如何表达？请花三分钟的时间小组内讨论，然后请一位学习者分享一下怎样运用本片段中结构化思维的表达方式，言之有物且符合逻辑,条理清晰。时间控制在2分钟内；\u003c/p>\u003cp>\u003cstrong>简：若在回到当时场景,我会这么表述: \u003c/strong>\u003cem>（\u003cu>定主题\u003c/u>）\u003c/em>\u003cstrong>这半年，在我们浙江区域，“未来春藤”的业务推广方面虽然成效还没显现,但一直在尝试。\u003c/strong>\u003cem>（搭架子）\u003c/em>\u003cstrong>主要分为线下活动举办和招商两方面展开。\u003cem>（填素材）\u003c/em>第一，线下活动，一周有做4场线下活动；第二，招商方面，招募2家意向合伙人。\u003c/strong>\u003c/p>\u003cp>结尾：由于时间关系今天的拆书到此结束，希望本片段中的方法能在工作中帮到大家，也希望大家通过刻意练习掌握这个方法。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1629727366000,"updated_at":1630629868000,"ria":true},{"id":12064,"topic":"如何愉快沟通","learn_goal":"","remark":"这本书是职场类图书中非常畅销的一本，相比其他书籍《请停止无效努力》介绍的更多是术，是可以活学现用的方法。书中以方法为基础，案例为辅，详实的告知我们如何高效的锻炼自我成长的能力，全书讲得深入浅出，能懂能用。","level":"TF2-3","duration":15,"status":30,"type":0,"chaishujia":{"username":"羽沐-蚂蚁","city":"徐州市"},"club":{"name":"徐州筹备分舵","city":""},"prologue":"\u003cp>\u003cstrong>一、学习目标：\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次 RIA 现场学习后，学习者能够利用愉快沟通方法与他人进行愉快沟通聊天。\u003c/p>\u003cp>\u003cstrong>二、开场与分组1分钟\u003c/strong>\u003c/p>\u003cp>大家好，我是今天的拆书家羽沐，从事软件系统项目管理工作，喜欢一切美好的事物，目前在拆书帮是一名一级拆书家，热爱分享，热爱探究新事物。\u003c/p>\u003cp>为了方便大家更好的学习探讨，我先提前给大家分一下小组。\u003c/p>\u003cp>今天我们现场来了X位伙伴，那么我们就分为2组，XX和XXX是一组，XX和XXX是一组。\u003c/p>\u003cp>\u003cstrong>三、用FAB法介绍图书（1分钟）\u003c/strong>\u003c/p>\u003cp>今天带来的拆页选自《请停止无效努力》\u003c/p>\u003cp>\u003cstrong>F特征（feature）：\u003c/strong>这本《请停止无效努力》作者是孙圈圈，曾任全球知名\u003ca href=\"https://baike.baidu.com/item/%E7%AE%A1%E7%90%86%E5%92%A8%E8%AF%A2%E5%85%AC%E5%8F%B8/7903545\">管理咨询公司咨询总监，【领英洞察】专栏作家。现创业是干货、烧脑、长文公众大号“圈外”掌门。本书深入浅出的道出职场干货，以及思维和沟通的两个核心技能的练习和使用。\u003c/p>\u003cp>\u003cstrong>A优势（advantage）：\u003c/strong>这本书是职场类图书中非常畅销的一本，相比其他书籍《请停止无效努力》介绍的更多是术，是可以活学现用的方法。书中以方法为基础，案例为辅，详实的告知我们如何高效的锻炼自我成长的能力，全书讲得深入浅出，能懂能用。\u003c/p>\u003cp>\u003cstrong>B利益（benefit）:\u003c/strong>B1:你有没有发现自己努力常常仍看不到效果？有没有身边的人在处理同样问题时会做的更好更快？这本书将带你获得个人成长、掌握学习思考的正确模式、颠覆一个人过去的思维认知，并且能让工作和人生得到很大的提升，成为一名更优秀的高效人士。B2:今天的拆页片段是介绍大家如何利用愉快的闲聊，来避免我日常聊天中的尬聊等。\u003c/p>","ratings_count":1,"texts":[{"id":16015,"quote":"\u003cp>\u003cstrong>四、R阅读原文拆页（2分钟）\u003c/strong>\u003c/p>\u003cp>接下来给大家2分钟的时间进行阅读下原文，读完请举手示意，谢谢\u003c/p>\u003cp>如何愉快地闲聊。\u003c/p>\u003cp>曾经，在知乎上看到一个故事——一个程序员跟女友聊天。\u003c/p>\u003cp>女友打开一个网页，屏幕上出现一只很漂亮的蝴蝶飞来飞去，她惊讶地说：“这蝴蝶好漂亮”，程序员回头瞄了一眼，说：“这是JavaScript（某种脚本语言）”。然后女友怒了：“这明明就是蝴蝶！”\u003c/p>\u003cp>谁的答案错了呢？都没错。因为聊天本来就不是为了得出一个对的答案。\u003c/p>\u003cp>女友也只是想要分享这种惊喜的心情，并不想知道背后的原理。\u003c/p>\u003cp>再想象一下，长假过后的上班第一天，早上我们跟同事一见面，一般会聊什么呢？大概就是，假期去哪儿了。可我们为什么要聊这个话题呢？\u003c/p>\u003cp>第一，这个话题应景，而且可以聊一会儿，但又不会太长。我们不会在这种时候跟同事讨论房价或者学区房，因为这个话题可以聊很久，得午饭时间来聊。\u003c/p>\u003cp>第二，我们想让对方觉得，我们假期过得很好，希望获得认同，这跟朋友圈晒旅游照片是一个道理。\u003c/p>\u003cp>第三，我们想把某种感受分享给别人，可能是旅途中的惊喜，也可能是旅游被骗的气愤，让对方也感同身受。\u003c/p>\u003cp>所以，如果我们跟人聊天，想让对方觉得愉快，需要做什么呢？控制话题的长度和节奏；适时表达认同；与对方感同身受。而且我们需要记住，聊天不是辩论、不是汇报工作，更不是为了得出一个正确答案。\u003c/p>","explains":"\u003cp>\u003cstrong>五、I拆书家讲解引导（4分钟）\u003c/strong>\u003c/p>\u003cp>看到大家基本都读完原文了，那么就由我带领大家共同拆解下‘如何愉快的闲聊’。\u003c/p>\u003cp>片段主要告诉我们如何愉快的闲聊，帮助我们拉近与他人的距离。\u003c/p>\u003cp>我们在日常生活中发现有的人特别会聊天，有的人则是话题终结者，当然其中不乏个人不喜欢语言沟通者，但是在这个时代沟通是避免不了的，无论是当面聊天或者微信/QQ聊天，所以学会如何愉快的闲聊能够让我们拉近与他人的距离，也会在沟通中让他人感到愉快。\u003c/p>\u003cp>那么我们该怎么做才能做到愉快的闲聊呢？\u003c/p>\u003cp>1、 控制话题的长度和节奏\u003c/p>\u003cp>要想控制话题的长度和节奏，就需要能够自如地延展和结束话题。\u003c/p>\u003cp>结束话题一般大家都可能都知道如何去做，比如：看下时间说，与朋友约了吃饭。或者时间不早了，早点休息吧。都是一个很好的结束话题的方法。\u003c/p>\u003cp>那如何自如的延展话题呢？我猜这也是大家迫切想知道的。一般我们可以从时间维度，这个话题对比过去或未来会有什么不同；从空间角度，这个话题对比不同的城市或者国家有什么不同；从因果角度，这个话题内容是什么原因引起的，这个话题内容又又什么影响。\u003c/p>\u003cp>2、 适时表达认同或不认同\u003c/p>\u003cp>完全认同：获取认同是我们聊天的一大关键诉求，那我们就需要把自己的认同表达给对方，让他们知道。\u003c/p>\u003cp>①借助表情：比如收到礼物，我们时常以微惊讶的表情传递给对方很惊喜的信号。\u003c/p>\u003cp>②注意倾听，注视对方：有时候我们当一个听众就是最大的认同。\u003c/p>\u003cp>③赞美对方：适时的去赞美对方，当然，在赞美对方的时候，也需要注意：指出具体事实。（比如，“你好牛”跟“这么难的课程你竟然可以考90分，要知道及格率都只有30%”）\u003c/p>\u003cp>不完全认同：如果聊天中有些内容不完全认同，我们就要委婉的表达，可以采用先扬后抑的方式，先表达认可的地方，然后阐述自己的意见。\u003c/p>\u003cp>完全不认同：当某些观点你确实无法认同的时候，真诚地说出来，而不是曲意逢迎。如果完全没有自己的观点，一味地认同，只会让你的认同变得很廉价、不被珍惜、不被信任。\u003c/p>\u003cp>3、 与对方感同身受\u003c/p>\u003cp>主动建立自己与他人的感情联结、将心比心，让自己代入他人的感受。承认世界的多样性（你需要知道，与我们不同类型的人群的存在）、穿上对方的鞋（扮演一个截然不同的人，会让你发现更大的世界）、暂时放下自我（最好的方法就是放下自我，把“我”变成“我们”）。\u003c/p>","interaction":"\u003cp>\u003cstrong>六、A3促动参与（8分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>大家听完我所拆解的如何愉快的闲聊，想必都有一定的思考。\u003c/p>\u003cp>想想与相亲对象聊天、与新认识的朋友聊天、与朋友一起吃饭和他的朋友聊天、通过社群活动新认识的小伙伴聊天。\u003c/p>\u003cp>请大家思考一下，选择一个场景并与旁边的小伙伴进行讨论，进行一下场景演练。\u003c/p>\u003cp>接下来给大家5-10分钟的时间进行思考，然后邀请小伙伴展示下聊天内容或者小组角色扮演。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>静客：今天会场的这葡萄怎么样？\u003c/p>\u003cp>追风少年：这葡萄真的不错，很好吃，果肉很紧实，味道也蛮甜的。（又吃了一颗）\u003c/p>\u003cp>静客：是吧，这是我在批发市场买的，不仅新鲜而且便宜。\u003c/p>\u003cp>追风少年：去批发市场买肯定不方便吧，而且零卖人家愿意嘛？\u003c/p>\u003cp>静客：平时如果去批发市场肯定远啊，我这正好顺路，买了一些正好咱们一起边拆书边吃水果，多好。\u003c/p>\u003cp>追风少年：那还真不错呢，这是什么品种的葡萄，我下次吃也买点。\u003c/p>\u003cp>静客：听老板说好像是夏黑，下次你买可以找这个品种。\u003c/p>\u003cp>追风少年：好的啊。\u003c/p>\u003cp>静客：我这晚上老板刚好约了吃个便饭，我要先走了，我们下次再畅聊。\u003c/p>\u003cp>追风少年：好的，拜拜\u003c/p>\u003cp>整个环节：有话题，有认同，有建议，有结束。非常符合日常的愉快闲聊。\u003c/p>\u003cp>\u003cstrong>七、总结（1分钟）\u003c/strong>\u003c/p>\u003cp>非常感谢静客和追风少年，两位小伙伴的生动演绎。\u003c/p>\u003cp>这期的RIA拆书课就此结束了，希望这次的拆书活动能让大家在未来的生活中能够成为一个聊天高手，谢谢大家，下期再见！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1628567748000,"updated_at":1628743802000,"ria":true},{"id":12039,"topic":"如何用正确的方法快速进阶","learn_goal":"","remark":"没有什么天赋异禀，成功源于持续有效的努力。","level":"TF2-1","duration":20,"status":19,"type":0,"chaishujia":{"username":"A苏杭","city":"杭州市"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"\u003cp>伙伴们大家好！欢迎参加拆书帮活动！我叫苏杭，先用三个标签自我介绍一下：\u003c/p>\u003cp>① 1级拆书家，还在升级打怪中。\u003c/p>\u003cp>② 理财爱好者，对指数型基金情有独钟。\u003c/p>\u003cp>③ “资深”HR，就不说工作多少年了，以免暴露年龄。\u003c/p>\u003cp>今天我给大家带来的拆书片段来自《请停止无效努力》，今日学习主题: 如何应用结构化思维快速表达想法和观点，尤其是在临场发言或向上汇报的时候。\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后,学习者能够在临场发言或汇报工作时，能够应用结构化的思维模式：想主题、搭架子、填素材的方式快速表达出自己的想法和观点。\u003c/p>\u003cp>【图书及作者介绍】：\u003c/p>\u003cp>【F】本书作者孙圈圈，本名孙园媛。曾任全球著名管理咨询公司咨询总监，现创业中，【领英洞察】专栏作家。本书围绕职业发展和个人能力提升所需的方法论展开，分为发掘天赋、提升能力、选择平台、回归自己等几大部分。\u003c/p>\u003cp>【A】 有别于自我成长的同类书籍，本书不仅能解答职场人士遇到的困惑还提供了实操性极强的方法，供职场人士借鉴。\u003c/p>\u003cp>【B】 在工作中，你是否常常做了很多事情却收获非常小，你可能正在无效努力。B1:如果你想改变，用正确的方法将学到的知识迅速转化为自己的能力，从而在职场中脱颖而出，这本书非常适合你阅读练习。B2:如果想临场表达结构强,条理顺,展现能力,本片段中介绍的方法可以帮到你\u003c/p>","ratings_count":1,"texts":[{"id":16003,"quote":"\u003cp>《请停止无效努力》\u003c/p>\u003cp>如何让你的演讲信息结构化 孙圈圈 P119\u003c/p>\u003cp>在本书之前关于结构化思维的文章里，曾经提到过，人类大脑在处理信息时有两个习惯：\u003c/p>\u003cp>第一、不能一次太多，因为信息太长会让大脑的负荷过大；\u003c/p>\u003cp>第二、喜欢有规律的信息。\u003c/p>\u003cp>临场发言时，我们是有压力的。这种压力，要不让我们的大脑一片空白、胡言乱语，要不让我们的大脑信息泛滥、毫无头绪。这两种情况，听众听起来都会比较痛苦，不明白你到底想表达的是什么。\u003c/p>\u003cp>如果说，有一个清晰的结构，发言就变得容易了。一方面，如果你的大脑是杂乱无章的状态，它可以帮你把信息快速整理并输出；另一方面，如何你的大脑是一片空白的状态，它可以做为提示语帮你联想起一些有用信息。\u003c/p>\u003cp>用结构化思维，帮助你在短时间内更好地沟通，关键是三步骤：\u003c/p>\u003cp>第一步，想主题：迅速找到一个切入点，第一句就说出自己的观点。\u003c/p>\u003cp>第二步，搭架子：在论证观点时，思考一个结构（时间、空间、程度），并只说三点，这称为三个“架子”。\u003c/p>\u003cp>第三步，填素材：每个架子里，填充一些事例、数据等，来推进论据向观点靠近。\u003c/p>","explains":"\u003cp>【What】\u003c/p>\u003cp> 这个片段主要讲述如何应用结构化思维快速表达想法和观点，尤其是在临场发言或向上汇报的时候。\u003c/p>\u003cp>【Why】\u003c/p>\u003cp> 人类大脑在处理信息时有两个习惯：第一、不能一次太多，因为信息太长会让大脑的负荷过大；第二、喜欢有规律的信息。基于此,一般我们在临场发言有压力时，通常是头脑空白、无话可说亦或者信息泛滥、毫无头绪。从而被误解能力不行.而学习了本片段中的方法,通过定主题，搭架子，填素材可以让我们的发言（表达）更有条理性。\u003c/p>\u003cp>【HOW】 \u003c/p>\u003cp> 我们如何学习和掌握这种思维结构呢？主要采用以下三个步骤：\u003c/p>\u003cp>第一步，定主题：迅速找到一个切入点，第一句就亮明自己的观点。\u003c/p>\u003cp>第二步，搭架子：在论证观点时，思考一个架构（时间、空间、程度），并只说三点，这称为三个“架子”。\u003c/p>\u003cp>第三步，填素材：每个架子里，填充一些事例、数据等，来支持论点。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>这个方法适合临场发言、工作汇报、演讲等这些有压力的发言场合。但日常朋友、亲人、恋人之间的交流，舒适、走心一些比较好，可以不用。\u003c/p>\u003cp>\u003cstrong>举例（反例）：\u003c/strong>3月份刚到新单位，代表HR部门列席了一个总经理组织的会议：是关于市场部提交客户方案定稿，以及确认对接人员这样的主题。HR部门主要是对确认对接人员提供建议。没想到市场部长方案展示完之后，总经理问我对这个方案的看法。我瞬间懵圈，只说我刚来，对市场业务不太熟悉，给不出建设性意见。\u003c/p>\u003cp>学习本片段之后，我回忆了当时的场景，其实还是可以更好表现的。比如：我刚来，内容方面我给不出建设性意见，不过在排版上我觉得可以优化一下。主要需要从图片，字体选择。图片选择，客户公司官网上布局可以看出崇尚简约，所以我们是不是可以调整一下呢？字体方面，客户提供过来的文件运用的是微软雅黑，我们是不是也可以运用呢？ \u003c/p>","interaction":"\u003cp> 【A1】激活学习者经验（显像提问）\u003c/p>\u003cp> 请回忆最近一周自己不满意的临场表达，比如你跟老板在茶水间遇到,老板问你:最近工作怎么样? 那工作这么多,你要说哪个呢?结果头脑中可能信息泛滥,毫无头绪。可能你会给老板一种能力不够的印象。给大家两分钟讨论，1分钟分享。\u003c/p>\u003cp>学习者案例分享（反例）：\u003c/p>\u003cp>刘苏：应对客户提问时候，主题就是客户的问题，自己的回答的时候说了好多但是不记得前后都说了啥，导致就当时状况很囧。\u003c/p>\u003cp>【A1+】\u003c/p>\u003cp>学了今天的片段，了解了结构化思维的三步骤,请大家思考一下:若再回到【A1】中的场景,你会如何表达？请花2分钟的时间小组内讨论，然后请一位学习者分享一下怎样运用本片段中结构化思维的表达方式，言之有物且符合逻辑,条理清晰。时间控制在2分钟内；\u003c/p>\u003cp>(如果你想到的经历已经利用了结构化思维，那么恭喜，说明你日常工作中已经超越了很多人，我们可以深度思考下“根据刚才拆页中讲的建议，还有没有可以精进的地方？ )\u003c/p>\u003cp>学习者分享：\u003c/p>\u003cp>刘苏：再回到当时的场景，客户再问问题，问的问题就可以作为主题。自己在回答的时候，搭架子，使用前，使用中使用后等这样的时间线，然后再加一下数据或者其他成功客户的一些案例来作为素材来佐证解答客户的问题。\u003c/p>\u003cp>结尾：由于时间关系今天的拆书到此结束，希望本片段中的方法能在工作中帮到大家，也希望大家通过刻意练习掌握这个方法。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1628389278000,"updated_at":1628498670000,"ria":true},{"id":11993,"topic":"如何说服他人","learn_goal":"","remark":"这本《请停止无效努力》作者是孙圈圈，曾任全球知名管理咨询公司咨询总监，【领英洞察】专栏作家。现创业是干货、烧脑、长文公众大号“圈外”掌门。本书深入浅出的道出职场干货，以及思维和沟通的两个核心技能的练习和使用。","level":"TF2-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"羽沐-蚂蚁","city":"徐州市"},"club":{"name":"徐州筹备分舵","city":""},"prologue":"\u003cp>\u003cstrong>一、学习目标：\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次 RIA 现场学习后，学习者能够通过“讲故事”来说服他人。\u003c/p>\u003cp>（提前把原文拆页发给大家）\u003c/p>\u003cp>\u003cstrong>二、开场与分组1分钟\u003c/strong>\u003c/p>\u003cp>大家好，我是今天的拆书家羽沐，从事软件系统项目管理工作，喜欢一切美好的事物，目前在拆书帮是一名一级拆书家，热爱分享，热爱探究新事物。\u003c/p>\u003cp>为了方便大家更好的学习探讨，我先提前给大家分一下小组。\u003c/p>\u003cp>今天我们现场来了4位伙伴，那么我们就两两一组分为两组，XX和XXX是一组，XX和XXX是一组。\u003c/p>\u003cp>\u003cstrong>三、用FAB法介绍图书（1分钟）\u003c/strong>\u003c/p>\u003cp>今天带来的拆页选自《请停止无效努力》\u003c/p>\u003cp>\u003cstrong>F特征（feature）：\u003c/strong>这本《请停止无效努力》作者是孙圈圈，曾任全球知名\u003ca href=\"https://baike.baidu.com/item/%E7%AE%A1%E7%90%86%E5%92%A8%E8%AF%A2%E5%85%AC%E5%8F%B8/7903545\">管理咨询公司咨询总监，【领英洞察】专栏作家。现创业是干货、烧脑、长文公众大号“圈外”掌门。本书深入浅出的道出职场干货，以及思维和沟通的两个核心技能的练习和使用。\u003c/p>\u003cp>\u003cstrong>A优势（advantage）：\u003c/strong>这本书是职场类图书中非常畅销的一本，相比其他书籍《请停止无效努力》介绍的更多是术，是可以活学现用的方法。书中以方法为基础，案例为辅，详实的告知我们如何高效的锻炼自我成长的能力。\u003c/p>\u003cp>\u003cstrong>B利益（benefit）:\u003c/strong>这本书将带你获得个人成长、掌握学习和思考的正确模式、成为一名优秀的沟通者。(\u003cstrong>B2:\u003c/strong>今天的拆页片段是介绍大家如何通过“讲故事”来说服他人。)\u003c/p>","ratings_count":1,"texts":[{"id":15951,"quote":"\u003cp>\u003cstrong>四、R阅读原文拆页（2分钟）\u003c/strong>\u003c/p>\u003cp>接下来给大家2分钟的时间进行阅读下原文，读完请举手示意，谢谢\u003c/p>\u003cp>假设你是一家企业的CEO，有两位咨询顾问，分别帮你进行了管理体系的诊断，结论都是一样：组织架构冗余、资源重复配置（案例进行了简化，在此只是为了说明问题）。你听取了两位顾问的汇报，看看你更喜欢谁的方法：\u003c/p>\u003cp>顾问A：“我们访谈了贵公司高管，调研了主要竞争对手，也研究了贵公司的组织架构。我们发现，贵公司组织架构冗余，比如各工厂间研发资源重复配置，导致它们之间产品同质化、恶性竞争。”\u003c/p>\u003cp>顾问B：“正如您所知道的，行业面临严重产能过剩。贵公司要继续发展，优化资源配置、淘汰落后产能、开发高端产品是成功关键。”\u003c/p>\u003cp>“然而，目前组织架构冗余，比如各工厂间研发资源重复配置，导致内部恶性竞争（XX与XX两家工厂已在互相压价）；同时资源分散，导致高端产品开发能力弱（高端产品占比是XX，而竞争对手是XX），只能在中低端产品上打价格战。”\u003c/p>\u003cp>“因此，我们建议将XX与XX资源集中到总部来应对这些问题，实现继续发展，且这样做，可以节省10%的人力成本。”\u003c/p>\u003cp>两种汇报思路，显然顾问B更容易受到认同。我们不妨来拆解一下两种汇报思路的结构，看看为什么会这样。\u003c/p>\u003cp>就此可以知道，B相较于A有三大主要优势：\u003c/p>\u003cp>第一，通过制造冲突，让CEO更能意识到问题的重要性。渴望——面临产能过剩，需要优化资源配置、聚焦高端产品；障碍——组织架构的冗余，导致资源浪费、开发能力弱。所以，这就构成了一个冲突。\u003c/p>\u003cp>第二，通过数据、案例等展示方式来支持观点。\u003c/p>\u003cp>第三，给出了可行动的解决方案及正面展望（解决问题并节省10%人力成本）。\u003c/p>","explains":"\u003cp>\u003cstrong>五、I拆书家讲解引导（3分钟）\u003c/strong>\u003c/p>\u003cp>看到大家基本都读完原文了，那么就由我带领大家共同拆解下利用’讲故事’来说说服别人。\u003c/p>\u003cp>WHAT：\u003c/p>\u003cp>该片段主要告诉我们怎么通过埋点、枚举数据案例、给出解决方案这三步来说服他人。\u003c/p>\u003cp>WHY：\u003c/p>\u003cp>尤其在商业活动中，我们经常看到一些公司的商务人员用各种各样的方式去介绍自己的产品，为客户指出当前存在的题，而往往胜出的都是那些比较会“讲故事”的。同样在咨询服务中客户更喜欢倾听或采纳会“讲故事”的咨询师的建议，在生活中想说服他人也需要“讲故事”的能力，因此掌握利用“讲故事”来说服他人显得更加重要。那么我们具体该如何去做呢？\u003c/p>\u003cp>HOW：\u003c/p>\u003cp>第一步：造冲突，讲出对方的障碍以及对方的渴望，形成冲突为接下来做铺垫。\u003c/p>\u003cp>第二步：举案例，用数据或者案例来说话，这样才更有说服力。\u003c/p>\u003cp>第三步：给方案，不能只讲故事不干事，给出对应的解决方案，让他人有个展望。\u003c/p>\u003cp>预防可能的异议：有人说现在谈生意那用到这些，都是酒桌文化和关系网，第一、无论是酒桌文化或者关系网，其实对方都希望我们真正能为他们解决痛点或带来效益不是吗？而且随着市场不断的规范，竞争越发透明化更需要我们学习说服他的方法。\u003c/p>\u003cp>WHERE:\u003c/p>\u003cp>其实这个方案主要用于有目的的说服他人，比如你想喊着小伙伴去一家不错的馆子，你肯定会说这家经常爆满，这家美团排名很高等。\u003c/p>\u003cp>而说教或者夫妻之间的说服就少用这种方式，因为在生活中大家都偏感性。\u003c/p>","interaction":"\u003cp>\u003cstrong>六、A2催化应用（6分钟）\u003c/strong>\u003c/p>\u003cp>分步催化1\u003c/p>\u003cp>好，这个片段我已经给大家讲完了，现在请大家想一下，你在接下来的1到2周的工作或生活中，可能会遇到的一个场景，将会用到“讲故事”方式来说服他人。比如生活中，家人还在纠结到底去哪个馆子吃何种菜肴时；比如在工作中，你给客户介绍你的公司或者产品时。\u003c/p>\u003cp>想象一下这个场景，并把它写在便签纸上。给大家1分钟时间，写完之后，小组成员可以相互分享一下。\u003c/p>\u003cp>看到大家都在组内进行分享交流了，我们邀请一位老师给大家进行一个分享展示。哪位老师愿意起来分享一下呢？\u003c/p>\u003cp>学习者案例记录：分享者：静客\u003c/p>\u003cp>静客分享了一个他在商业谈判将会遇到的一个场景，客户场地已经安装了风机，暂未装净化机，这就是需要再次协商沟通的场景。\u003c/p>\u003cp>该场景下就需要静客去进行商业沟通，将会用到今天所讲的讲故事方法。\u003c/p>\u003cp>分步催化2\u003c/p>\u003cp>感谢这位老师分享的场景，那接下来按照刚才自己预见的情境，利用“利用讲故事”说服他人的步骤来试着在该场景下说服对方。\u003c/p>\u003cp>给大家3分钟时间，大家可以思考下，然后我邀请一位老师给大家分享。\u003c/p>\u003cp>3分钟时间到，哪位老师愿意起来分享一下呢？\u003c/p>\u003cp>学习者案例记录：分享者：静客\u003c/p>\u003cp>静客分享到，在这个项目谈判中。\u003c/p>\u003cp>他首先会找痛点，客户安装油烟机后首先收拢了大面积烟雾，但是整个排放仍然不达标，会引起周边居民的举报等不断的烦扰。\u003c/p>\u003cp>其次讲案例，在新城区XXX餐饮公司，备受周边居民举报不断有有关部门上门调查，随后我们为其做了环保处理以及设备的安装，现在XX餐饮公司运行良好，不仅室内环境好，对外也做到了低排放。\u003c/p>\u003cp>最后讲方案，我们将根据你们公司的实际需求，定制解决方案，为您公司安装净化机等相关设备以解决您的困扰。\u003c/p>\u003cp>\u003cstrong>七、总结（1分钟）\u003c/strong>\u003c/p>\u003cp>非常感谢静客小伙伴的分享（鼓掌）\u003c/p>\u003cp>这次我们学习了利用“讲故事”说服他人，讲故事其实主要是找痛点，讲案例，给方案，他刚好有需求，你刚好有方案，而你又会“讲故事”，最后肯定是一场成功的说服。\u003c/p>\u003cp>这期的RIA拆书课就此结束了，非常感谢小伙伴的参与，下期再见！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1627354299000,"updated_at":1627467046000,"ria":true},{"id":11819,"topic":"临时发言没有思路，怎么办？","learn_goal":"","remark":"临场发言时，我们要么头脑一片空白，不知道该说什么；要么千言万语涌上心头，不知道该如何说起？很多人觉得自己表达能力存在问题。但实际上，可能是因为你没有一个思路来让你的信息进行结构化。\n\n每天我们都接收到大量的知识和信息，如果不把它纳入到知识体系中，它们将作为碎片化信息短暂保存在我们的大脑中，要不了多久就被遗忘了，更谈不上遇到问题能迅速调用。只有纳入了知识体系的知识才能被我们调用，才能帮我们解决问题。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"Andy-2021","city":"南宁市"},"club":{"name":"南宁清澄分舵","city":"南宁"},"prologue":"\u003cp>\u003cstrong>一、分组（两两一组）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>二、图书介绍\u003c/strong>\u003c/p>\u003cp>这本书的作者孙圈圈，曾任全球知名管理咨询公司咨询总监，【领英洞察】专栏作家，“圈外学院”创始人，她书中的内容基本就是她在工作的总结，她从外企管理层、创业公司CEO、咨询顾问和职场人四种视角去看待人才发展问题，有助于人成长。\u003c/p>\u003cp>本书从发掘天赋、提升能力、选择平台、回归自己等几大方面，详细阐述了职业发展和个人提升的正确方法论。书里所讲的方法与思路，可以用来分析我们生活、学习和工作中遇到的大多数问题。\u003c/p>\u003cp>书中提供的科学以及实操的方法论，并非碎片化知识，而是一套体系化的方法论。同时，每篇文章都附有练习和实践方法，能提升我们分析和解决问题的能力。\u003c/p>","ratings_count":1,"texts":[{"id":15763,"quote":"\u003cp>【R】阅读原书拆页\u003c/p>\u003cp>临场发言时，我们是有压力的。这种压力，要不让我们的大脑一片空白、胡言乱语，要不让我们的大脑信息泛滥、毫无头绪。这两种情况，听众听起来都会比较痛苦，不明白你到底想表达的是什么、\u003c/p>\u003cp>如果说，有一个清晰的结构，发言就变得容易了。一方面，如果你的大脑是杂乱无章的状态，它可以帮你把信息快速整理并输出；另一方面，如果你的大脑是一片空白的状态，它可以作为提示语帮你联想起一些有用信息。\u003c/p>\u003cp>用结构化思维，帮助你在短时间内更好地沟通，关键是三个步骤：\u003c/p>\u003cp>第一步，想主题：迅速找到一个切人点，第一句就说出自己的观点。\u003c/p>\u003cp>第二步，搭架子：在论证观点时，思考一个结构（时间、空间、三角），并只说三点，这称为三个&quot;架子”。\u003c/p>\u003cp>第三步，填素材：每个架子里，填充一些事例、数据等，来推进论据向观点靠近。\u003c/p>\u003cp>这里给大家举个例子，乔布斯推出第一款苹果手机时进行过一段演讲，大意如下：\u003c/p>\u003cp>苹果公司是一家革命性的公司。为什么这么说呢？1984年，推出Mac电脑，改变了整个电脑行业；2001年，推出iPod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；2007年，推出苹果手机，我相信它将改变更多行业。\u003c/p>\u003cp>我们来剖析一下这段话的结构，就会是：\u003c/p>\u003cp>主题：苹果公司是一家革命性的公司。\u003c/p>\u003cp>架子：1984年、2001年、2007年。\u003c/p>\u003cp>素材：推出Mac电脑，改变了整个电脑行业；推出iPod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；推出苹果手机。\u003c/p>\u003cp>所以，乔布斯这段话的结构也是由三要素组成：主题、架子、素材。\u003c/p>","explains":"\u003cp>\u003cstrong>【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>你突然被点名，在毫无准备的情况下，需要在公众场合发言，这就是临场发言。\u003c/p>\u003cp>这时，我们的头脑中要么一片空白，不知道该说什么；要么千言万语涌上心头，不知道该从何说起。说的人语无伦次，听的人毫无头绪。你们双方都比较痛苦。\u003c/p>\u003cp>\u003cbr>怎么办？\u003c/p>\u003cp>要么很多人觉得自己表达能力存在问题。但实际上，可能是因为你没有一个思路来让你的信息进行结构化。这个片段介绍了结构化表达的3个步骤，让自己的临场发言变得逻辑清晰有条理。\u003c/p>\u003cp>第一步，想主题：迅速找到一个切人点，第一句就说出自己的观点。主题就是针对要讨论的问题，你的观点，你的看法，你的态度，打个比方的话，主题就相当于议论文中的论点。\u003c/p>\u003cp>第二步，搭架子：所谓架子是指我们在表达时，用于把信息分类汇总的结构关键词。架子一方面充当了提示语，有了它，你不至于一点都说不出来；另一方面又是帮你梳理信息的工具。最大的好处就是把问答题简化成了填空题。常用的架子有三种类型，时间架、空间架和三角架。时间架是按照时间的顺序，整理头脑中的信息，比如你是负责培训工作的，那么在向别人介绍你的岗位职责时，你可以按照培训前、培训中和培训后来表达，特别提醒的是时间架不只局限于时间这个狭窄的概念，一切有先后关系的结构都算，所以除了这些代表时间的词，代表阶段、代表步骤的词都算。空间架是按照地点的顺序分类信息，用空间架的好处是听众有画面感，比如，全国各地的人们都阖家团圆，一起喜迎春节。广州：虎龙舞狮。北京：全家一起包饺子。南京：写春联以及贴春联。怎么样，是不是很有画面感？常用的空间架包括。。。。三角架是按照三个方面总结信息，常用的三角架包括。。。\u003c/p>\u003cp>第三步，填素材，素材指的是用于支撑主题或观点的数据、事实和故事。\u003c/p>\u003cp>以上就是培养结构化思维，做好临场发言的三个步骤：想主题、搭架子和填素材。\u003c/p>\u003cp>为了便于理解这个模型，我们举个例子。\u003c/p>\u003cp>到了中午吃饭时间，你建议同事们去XX餐厅吃饭。\u003c/p>\u003cp>“去附近的XX餐厅去吃吧，那里挺好的。\u003c/p>\u003cp>一、那里的菜很好吃，去过的朋友都说好吃，晚上经常需要等位才能吃到呢！\u003c/p>\u003cp>二、那里环境也好，有室内的小花园，还有钢琴演奏，很多情侣选择在那里约会；\u003c/p>\u003cp>三、而且价格还不贵，吃得很饱人均才50+\u003c/p>\u003cp>我推荐去那里吃午餐，大家的意见呢？\u003c/p>","interaction":"\u003cp>\u003cstrong>A1 【激活经验】\u003c/strong>\u003c/p>\u003cp>拆书家提问设计：以上就是我对拆页内容的解读，接下来进入A环节。学完这个片段，我们了解了在需要做临场发言的场合，如果利用结构化的表达模型，就可以让自己的发言清晰有条理。现在请小伙伴们回想一下，在自己的过往经历中，有没有经历过因为缺乏结构化表达的能力，从而导致发言效果很差的情况？当然成功的经历也可以。你们当时都是怎么做的？然后写在便签纸上。写的过程中大家可以注意时间、地点、人物、起因、经过、结果这六大要素。现在给大家几分钟的时间，各位小伙伴可以在两两一组，在组内轮流分享一下。\u003c/p>\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>接下来，请大家思考后续可以如何应用这个知识点？想好后就把这个应用计划写下来，特别提醒，计划一定要具体可执行，有明确的完成期限，是否达成可验收可测量，遵循SMART原则。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1624810774000,"updated_at":1625121660000,"ria":true},{"id":11756,"topic":"把知识纳入知识体系的方法","learn_goal":"","remark":"每天我们都接收到大量的知识和信息，如果不把它纳入到知识体系中，它们将作为碎片化信息短暂保存在我们的大脑中，要不了多久就被遗忘了，更谈不上遇到问题能迅速调用。只有纳入了知识体系的知识才能被我们调用，才能帮我们解决问题。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"Andy-2021","city":"南宁市"},"club":{"name":"南宁清澄分舵","city":"南宁"},"prologue":"\u003cp>【自我介绍】我是Andy. 我来自新疆，我坚持最久的一件事是每周写一篇公众号文章，已经有61篇了。我还经常跑步，去年完成了500km.\u003c/p>\u003cp>其实，拆书是一种学习方法论，适用于提升能力、解决问题为目标的成人学习，强调以学习者为中心而不是知识为中心，要把知识关联学习者的经验、规划具体的运用。分为个人学习的拆书法和组织学习的拆书法：个人学习的应用是便签法，让人读一本书就能达到参加同主题培训的效果；而组织学习应用就好像我这样拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。从学习者的学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训师。\u003c/p>\u003cp>【拆书帮介绍】\u003c/p>\u003cp>拆书帮是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵（也叫拆书帮俱乐部）。拆书帮分舵是非营利性青年组织，其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>\u003cp>那拆书家又是什么呢？\u003c/p>\u003cp>拆书家是学习导师，拆书家是主动学习的最高境界。可以通过教会别人从而让自己得到最好的学习，可以把一本书加工成现场培训，也可以帮助身边的人搭建知识体系。\u003c/p>","ratings_count":1,"texts":[{"id":15708,"quote":"\u003cp>方法四，在架构中填充知识\u003c/p>\u003cp>现在，我们有了架构，那么如何在架构中填充知识内容呢？我建议的一个方法是：\u003c/p>\u003cp>首先，把你看到的任何有价值的信息，都记在手机里，用什么软件都无所谓。记的时候不需要组织语言，记关键词就可以，这样最快。如果是微信文章里的，你可以直接截图保存。\u003c/p>\u003cp>其次，每天对当天的知识进行整理，分门别类地列到某个应用，比如Evemote里面（如果你在上一步中也是用Evernote,那你需要分开不同的文件夹）。\u003c/p>\u003cp>最后，定期回顾，如果是重要的知识，再记入到知识架构里，作为知只体系的一部分，当然，这也是另一个文件夹。\u003c/p>\u003cp>用这种方式，即便是碎片化信息，也能够进入到知识体系。\u003c/p>","explains":"\u003cp>这个片段告诉我们把知识纳入知识体系的方法。\u003c/p>\u003cp>每天我们都接收到大量的知识和信息，如果不把它纳入到知识体系中，它们将作为碎片化信息短暂保存在我们的大脑中，要不了多久就被遗忘了，更谈不上遇到问题能迅速调用。只有纳入了知识体系的知识才能被我们调用，才能帮我们解决问题。\u003c/p>\u003cp>1、收藏知识：把看到任何有价值的知识，都保存在手机或电脑里，比如在印象笔记中建立“日常信息”文件夹。\u003c/p>\u003cp>2、整理知识：建立“整理信息”文件夹，每天对当天的知识按知识架构进行分类整理。\u003c/p>\u003cp>3、定期回顾：建立“知识体系”文件夹，然后把步骤2中的知识架构放入此文件夹。\u003c/p>\u003cp>这种方法可以用来整理每天收集的知识点，可以建立知识与知识的联系，也可以对知识体系进行查缺补漏。\u003c/p>","interaction":"\u003cp>※ A1 （故事+反思）\u003c/p>\u003cp>【故事】：干啥啥不行，收藏第一名。在我的收藏夹里收藏有大量自己认为以后可能会用上的知识，但一直没有整理，就像冬天收藏橡果的小松鼠一样，只是收藏。这些知识都很有道理，说得都对，但显得杂乱无章，很难记住，更别说能帮助我解决问题了。\u003c/p>\u003cp>【反思】：只收藏知识而没有整理，这些有用的知识并不能形成知识体系为我所用。我没有每天把收藏的知识进行整理、分类、建立体系，所以只有零散信息，而不是有用的知识，不能转化为我的能力。\u003c/p>\u003cp>※ A2 （目标+行动）SMART\u003c/p>\u003cp>【目标】：本周每天用30分钟时间整理当天收藏知识，纳入知识体系。\u003c/p>\u003cp>【行动】：\u003c/p>\u003cp>1、固定整理时间：每天晚上7：00-7：30整理当天收集的知识。\u003c/p>\u003cp>2、建立“日常信息”文件夹：对于每天想要收藏的知识，在印象笔记里建立“日常信息”文件夹，统一保存在里面；\u003c/p>\u003cp>3、建立“整理信息”文件夹：根据知识所解决的问题进行整理，建立知识架构；比如：个人需要提升的3种能力：专业能力、通用能力、认知能力。\u003c/p>\u003cp>4、建立“知识体系”文件夹：每周对“整理信息”文件夹进行一次整理，建立自己的知识体系。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1624195471000,"updated_at":1624324630000,"ria":true},{"id":11719,"topic":"“结构化思维”","learn_goal":"","remark":"《请停止无效努力》作者是孙圈圈，曾任全球知名管理咨询公司咨询总监，现创业，【领英洞察】专栏作家。干货、烧脑、长文公众大号“圈外”掌门。本书深入浅出的道出职场干货，以及思维和沟通的两个核心技能的练习和使用。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"羽沐-蚂蚁","city":"徐州市"},"club":{"name":"徐州筹备分舵","city":""},"prologue":"\u003cp>大家好，我是今天的拆书家羽沐，羽毛的羽，洗澡的沐。（我生求羽化,斋沐造仙居）目前在一家软件公司从事软件系统项目管理工作，业余爱好做做木工，并喜欢一切美好的事物。在拆书帮是一名一级拆书家，热爱分享，热爱探究新事物。\u003c/p>\u003cp>本期学习目标：\u003c/p>\u003cp>在跟随我完成本次 RIA 现场学习后，学习者能够利用结构思维进行临场演讲，并不断衍生自己的演讲套路。\u003c/p>\u003cp>为了方便大家更好的学习探讨，我先提前给大家分一下小组。\u003c/p>\u003cp>今天我们现场来了4位伙伴，那么我们就分为2组，两两为一组。\u003c/p>\u003cp>用FAB法介绍图书\u003c/p>\u003cp>今天带来的拆页选自《请停止无效努力》\u003c/p>\u003cp>F特征（feature）：这本《请停止无效努力》作者是孙圈圈，曾任全球知名\u003ca href=\"https://baike.baidu.com/item/%E7%AE%A1%E7%90%86%E5%92%A8%E8%AF%A2%E5%85%AC%E5%8F%B8/7903545\">管理咨询公司咨询总监，现创业，【领英洞察】专栏作家。干货、烧脑、长文公众大号“圈外”掌门。本书深入浅出的道出职场干货，以及思维和沟通的两个核心技能的练习和使用。\u003c/p>\u003cp>A优势（advantage）：这本书是职场类图书中非常畅销的一本，相比其他书籍《请停止无效努力》介绍的更多是术，是可以活学现用的方法。书中以方法为基础，案例为服，详实的告知我们如何高效的锻炼自我成长的能力。\u003c/p>\u003cp>B1利益（benefit）:你有没有发现自己努力常常仍看不懂效果？有没有身边的人在处理同样问题时会做的更好更快？这本书将带你获得个人成长、掌握学习和思考的正确模式、成为一名优秀的沟通者。\u003c/p>\u003cp>B2利益（benefit）:今天的拆页片段是介绍大家如何利用结构化思维，来改变我们日常的自我介绍，即兴演讲等。\u003c/p>","ratings_count":2,"texts":[{"id":15669,"quote":"\u003cp>临场发言时，我们是有压力的。这种压力，要不让我们的大脑一片空白、胡言乱语，要不让我们的大脑信息泛滥、毫无头绪。这两种情况，听众听起来都会比较痛苦，不明白你到底想表达的是什么。\u003c/p>\u003cp>如果说，有一个清晰的结构，发言就变得容易了。一方面，如果你的大脑是杂乱无章的状态，它可以帮你把信息快速整理并输出；另一方面，如果你的大脑是一片空白的状态，它可以作为提示语帮你联想起一些有用信息。\u003c/p>\u003cp>用结构化思维，帮助你在短时间内更好地沟通，关键是三个步骤：\u003c/p>\u003cp>第一步，想主题：迅速找到一个切入点，第一句就说出自己的观点。\u003c/p>\u003cp>第二步，搭架子：在论证观点时，思考一个结构（时间、空间、程度），并只说三点，这称为三个“架子”。\u003c/p>\u003cp>第三步，填素材：每个架子里，填充一些事例、数据等，来推进论据向观点靠近。\u003c/p>\u003cp>这里给大家举个例子，乔布斯推出第一款苹果手机时进行过一段演讲，大意如下：\u003c/p>\u003cp>苹果公司是一家革命性的公司。为什么这么说呢？1984年，推出Mac电脑，改变了整个电脑行业；2001年，推出iPod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；2007年，推出苹果手机，我相信它将改变更多行业。\u003c/p>","explains":"\u003cp>看到大家基本都读完原文了，那么就由我带领大家共同拆解下利用‘结构化思维’快速表达信息或沟通。\u003c/p>\u003cp>【是什么】WHAT———\u003c/p>\u003cp>片段提到结构化思维的三个步骤，帮助我们短时间形成更有效的沟通。\u003c/p>\u003cp>【为什么】WHY———\u003c/p>\u003cp>我们往往会被领导突如起来的要求汇报搞的头大，年会临时被要求发言整的语无伦次。那我们为什么不能加以练习结构化思维，来助力我们汇报工作，或者即兴演讲呢。\u003c/p>\u003cp>反面案例：记得18年年会，公司行政突然要求我代表优秀员工进行演讲，给我准备的时间完全不够撰写和打磨演讲稿的，匆匆在手机记事本上简单写了下内容。最终的演讲我只记得问好开头，感谢结尾，中间讲的东西很乱没有条理，甚至尴尬的出现了卡壳。\u003c/p>\u003cp>这本是一个表现的机会，而我并没有利用结构化思维方式，进行梳理演讲套路，导致演讲毕竟失败。\u003c/p>\u003cp>【怎么做】HOW———\u003c/p>\u003cp>原文针对结构化思维沟通，已经给了我们清晰的步骤，那么我来讲讲我的想法：\u003c/p>\u003cp>如何快速组织一个即兴演讲\u003c/p>\u003cp>1、 想主题\u003c/p>\u003cp>在不用的应用场景，我们需要不同主题，所以我们要根据现场的情形想一个切合的主题。比如汇报工作，那主题就是汇报的项目名称，如果是年后发言，那么主题可能就是感谢公司提供平台，感谢领导提供帮助\u003c/p>\u003cp>2、 搭架子\u003c/p>\u003cp>根据主题思考一个结构，可从时间维度、空间维度、程度上思考。如汇报工作，时间维度是最好的切入点，程度也是很好的切入点，如空间维度没有合适的想法可以不提。\u003c/p>\u003cp>3、 填素材\u003c/p>\u003cp>在每个维度进行阐述事实或在数据，比如汇报项目中：项目开始时间，截止目前历经多久，完成情况如何。\u003c/p>\u003cp>其实这一套主要针对汇报利用结构化思维思考，对于不同的场景小伙伴可以自行创建新的套路。\u003c/p>\u003cp>【适用边界】Where———\u003c/p>\u003cp>结构化思维适用项目汇报、即兴演讲、大型场合的自我介绍等场景。\u003c/p>\u003cp>在生活情感沟通中，大家就别用这些套路了，真诚的告白比结构化思考重要。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1激活经验：\u003c/strong>\u003c/p>\u003cp>好了，大家听完我对‘结构化思维’的拆解，想必也有了自己的认知。\u003c/p>\u003cp>请想想自己在没了解这个思维之前，是如何介绍自己？是如何在工作中沟通的呢？\u003c/p>\u003cp>是不是在介绍自己的时候，只是简单的说下姓名、爱好等简单的标签就想不起来讲些什么了？\u003c/p>\u003cp>又比如在汇报工作时，汇报内容很凌乱，领导常常打断并提问一些问题，你又答不上来呢？\u003c/p>\u003cp>大家可以回忆下生活或工作中遇到的场景。（思考讨论2分钟，然后分享）\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>分享者：静客\u003c/p>\u003cp>静客在5月份参加一场电商风云榜大会，总体利用了总分总结构，最终斩获了第二名的好成绩。\u003c/p>\u003cp>第一：结合电商风云榜已经有了一个大主题，即围绕电商指定一个主题。电商将为环保产业带来什么便利\u003c/p>\u003cp>第二：搭架子，静客为自己公司的演讲搭了个框架，企业简介、行业简介、电商运用成果、未来展望。\u003c/p>\u003cp>第三：在各个模块里进行填充内容。\u003c/p>\u003cp>静客的演讲PPT中其实已经简单的构建了结构化思维。\u003c/p>\u003cp>\u003cstrong>A1+反思加工：\u003c/strong>\u003c/p>\u003cp>通过学习了结构化思维，大家可以想想过去一个月或者半年中有没有汇报工作、自我介绍或者总结时，如果回到当时那个场景，运用今天学习的结构化思维想主题、搭架子、填素材这3个步骤，你会怎么做呢。\u003c/p>\u003cp>如果你想到的经历已经利用了结构化思维，那么恭喜说明你日常工作中已经超越了很多人，我们可以深度思考下“根据刚才拆页中讲的建议，还有没有更好的沟通套路呢？”\u003c/p>\u003cp>先在小组内互相分享一下，分享自己的故事、经验时，尽量加上时间、地点、人物、起因、经过、结果，最后还有反思。\u003c/p>\u003cp>好，先给大家4分钟时间进行思考讨论，讨论结束后我将邀请小伙伴进行分享。\u003c/p>\u003cp>分享时间为4分钟，每人2分钟，那么有哪位小伙伴主动分享下！\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>分享者：静客\u003c/p>\u003cp>静客在反思改进时思考：\u003c/p>\u003cp>1、紧紧围绕主题，以主题为核心进行输出内容，主题应该更加明确\u003c/p>\u003cp>2、在搭架子时更应该围绕主题并且各架子之间有衔接，避免让听者认为各模块分离\u003c/p>\u003cp>3、填内容时紧紧围绕电商主题，时间充足的情况下，可以反复打磨内容\u003c/p>\u003cp>\u003cstrong>总结：\u003c/strong>\u003c/p>\u003cp>非常感谢静客小伙伴的分享。\u003c/p>\u003cp>这次我们学习了利用结构化思维进行沟通，其实结构化思维不仅仅可以利用到沟通，大家可以进行举一反三，应用到更多场景中。\u003c/p>\u003cp>这期的RIA拆书课就此结束了，非常感谢小伙伴的参与，下期再见！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1623726389000,"updated_at":1623833706000,"ria":true},{"id":11629,"topic":"“刻意练习”","learn_goal":"","remark":"《请停止无效努力》，作者是孙圈圈。本书从发掘天赋、提升能力、选择平台、回归自己等几大方面，详细阐述了职业发展和个人提升的正确方法论。书里所讲的方法与思路，可以用来分析我们生活、学习和工作中遇到的大多数问题。\n","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"羽沐-蚂蚁","city":"徐州市"},"club":{"name":"徐州筹备分舵","city":""},"prologue":"\u003cp>\u003cstrong>一、开场自我介绍（30S）\u003c/strong>\u003c/p>\u003cp>大家好，我是今天的拆书家羽沐，目前从事软件系统项目管理工作，业余爱好玩木头，并喜欢一切美好的事物。\u003cbr>其他标签：看书、美食、游玩。\u003cbr>如果针对项目管理、木工、美食有兴趣的小伙伴我们可以进行探讨哦！\u003c/p>\u003cp>当然在拆书帮我们最主要的还是将书面知识进行学以致用。\u003c/p>\u003cp>\u003cstrong>二、分组（1分钟）\u003c/strong>\u003c/p>\u003cp>为了方便大家更好的学习探讨，我先提前给大家分一下小组。\u003c/p>\u003cp>今天我们现场来了5位伙伴，那么我们就分为2组，2位女式为一组，另外3位男士为一组。给大家一分钟的时间，大家互相认识下自己的小伙伴。\u003c/p>\u003cp>\u003cstrong>三、图书介绍（1分钟）\u003c/strong>\u003c/p>\u003cp>今天我要拆解的图书叫做《请停止无效努力》，作者是孙圈圈。\u003c/p>\u003cp>本书呢，从发掘天赋、提升能力、选择平台、回归自己等几大方面，详细阐述了职业发展和个人提升的正确方法论。书里所讲的方法与思路，可以用来分析我们生活、学习和工作中遇到的大多数问题。\u003c/p>\u003cp>很多时候，我们不是不努力，只是没找到正确的努力方法，极致往往源于持续有效的努力。如能好好利用此书，不仅会颠覆一个人过去的思维认知，并且能让工作和人生得到很大的提升。\u003c/p>","ratings_count":2,"texts":[{"id":15564,"quote":"\u003cp>\u003cstrong>四、阅读原文拆页（2分钟）\u003c/strong>\u003c/p>\u003cp>我今天带来的拆页主题是：“刻意练习”，原文拆页已经发到大家手里了，请大家用2分钟时间阅读，读完的请举手示意。\u003c/p>\u003cp>《请停止无效努力》P48-49  作者：孙圈圈\u003c/p>\u003cp>如何练习才能将天赋转化为能力\u003c/p>\u003cp>好了，劣势上面花的时间少了，如何花时间去开发自己的天赋呢？关键是刻意练习。\u003c/p>\u003cp>首次提出“刻意练习”这个概念的是心理学家K.Anders Ericsson安德斯·埃里克森，他对刻意练习的定义是：为了掌握某种能力，有意识地付出努力，投入到某项活动中。只有有意识的重复，才会引发大脑神经的变化。最终随着时间的推移，大脑不再对这项活动感到不适，成为我们无意识的一种能力。\u003c/p>\u003cp>研究表明，练习的“质”，比练习的“量”要重要很多。\u003c/p>\u003cp>那么，什么是正确的刻意练习方法呢？它必须符合四大特征：\u003c/p>\u003cp>第一，在学习区练习\u003c/p>\u003cp>我们的学习，一般有三个区域：一个是舒适区，就是你非常熟练、几乎是下意识就可以完成的事情；中间是学习区，就是有一些挑战，可以通过努力掌握的；最外层是恐慌区，远远超出你的能力，当前很难掌握。如果用比喻的话，舒适区就像是右手随意写字，学习区是用右手学写某种字体的字，而恐慌区是让你直接用左手写那种字体出来。\u003c/p>\u003cp>因此，你需要反思，你现在的8小时工作内容中，分布在各个区域的比例有多少？如果在学习区的都不到1小时，那你就需要考虑一下了。因为，长此以往，你工作八年，只相当于别人工作一年。\u003c/p>\u003cp>第二，大量重复\u003c/p>\u003cp>这里所说的重复，是指在学习区内重复。学习任何一样新东西，其实是打破思维惯性、进行大脑重构的过程，要建立起重构后的稳定神经结构，需要多次练习，才能掌握。这是一个将有意识变成无意识的过程。你看到很多人，面对问题快速梳理出思路，那是因为，你需要有意识、很努力才能做到的事情，他早已通过刻意练习形成无意识反应了。\u003c/p>\u003cp>第三，持续获得有效反馈\u003c/p>\u003cp>刻意练习是以错误为中心的，因为如果一样事情你从未做错过，证明你根本不需要学习它。我在之前的文章里说过，人类学习的特征是从错误中学习，所以我们才会说“专家是在一个狭小领域内犯过最多错误的人”。\u003c/p>\u003cp>我们都考过试，刷过题库，最有效的做题方式是，每做一遍，记下错误的题目，下一遍只做错题，而不是一遍遍从头开始做。\u003c/p>\u003cp>有句话我之前一直记着，现在离开职场了，也送给大家：如果你的目标是升职为总监/经理，那么，让你的大脑先升职。\u003c/p>\u003cp>第四，专注\u003c/p>\u003cp>同样在学习区里练习，练习时间也一样，而且也有反馈，最后的结果就没有差异吗？不是，差异很大。比如，同样是学写楷体字，一个在写字的时候听摇滚、想心事，而另一个则是沉浸其中，最后的结果是差异很大的。\u003c/p>\u003cp>K. Anders Ericsson提到过他的另一个发现，就是：那些顶尖的专家在进行刻意练习的时候有几个特点：不间断的刻意练习通常只能坚持1个小时、通常在早晨头脑清醒的时候练习、每天都练习而且周末不间断、每天的刻意练习加起来是四到五个小时、没有足够的休息他们会崩溃。\u003c/p>\u003cp>为什么连那些最顶尖的人也做不到长时间刻意练习？因为这是一样非常耗费精力和能量的事情，需要专注和持续。\u003c/p>\u003cp>所以，想要提升你的时间性价比，开始盘点你的天赋和劣势，将时间做个切换，并掌握正确的刻意练习方法吧！\u003c/p>","explains":"\u003cp>\u003cstrong>五、拆书家讲解引导（3分钟）\u003c/strong>\u003c/p>\u003cp>好的，我看大家已经都阅读完原文片段了，下面由我来带领大家分析一下原文片段的内容。\u003c/p>\u003cp>片段讲的什么呢？该片段主要是讲刻意练习的方法。\u003c/p>\u003cp>在生活中我们渐渐发现我们开始止步不前，开始重复劳动，开始变得机械化，那是因为我们在舒适区待得太久，没有踏足学习区。试着去改变自己，拾起你的天赋，突破一下自己，你才知道自己有多优秀。\u003c/p>\u003cp>如果没有一些练习方法的化，我们可能练着练着感受不到进步就放弃了。\u003c/p>\u003cp>那么我们该怎么做呢？\u003c/p>\u003cp>第一步：破圈；走出舒适区，在学习区进行练习，挑战下圈外的技能。\u003c/p>\u003cp>第二步：重复；大量的去练习，就像乒乓球发球，换一种发球并重复去练习。\u003c/p>\u003cp>第三步：纠错；在练习中去纠错，反思错在哪里，不断去复盘，并修正。\u003c/p>\u003cp>第四步：专注；在学习区里学习一定要专注，只有集中注意才能收获更多。\u003c/p>\u003cp>‘刻意练习’适用于练字、写作、演讲、运动等多类技能学习过程，当然这个方法需要有一定的自制力和兴趣为基础，如果我们要练习的项目恰好自己不是特别感兴趣，可能会半途而废。\u003c/p>\u003cp>有人会说，破圈我能做到，重复我能做到，但是不断的反馈，我们在练习过程中怎么识别呢？我想我们可以通过互联网去找到匹配的社群来获得反馈。比如拆书帮，比如各种兴趣打卡群\u003c/p>","interaction":"\u003cp>\u003cstrong>六、A1激活经验（5分钟）\u003c/strong>\u003c/p>\u003cp>大家读完了这个拆页、听过了我个人对片段的理解之后，应该了解了“刻意练习”的步骤方法，请想想自己有没有与片段相类似的情景、有没有过相关的经验呢？你们当时都是怎么做的？然后写在便签纸上。写的过程中大家可以注意时间、地点、人物、起因、经过、结果这六大要素。\u003c/p>\u003cp>\u003cem>（讨论2分钟，分享2分钟）\u003c/em>准备好举手示意。\u003c/p>\u003cp>好，现在请\u003cstrong>兔小灰\u003c/strong>来分享一下自己的经历。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>分享者：兔小灰\u003c/p>\u003cp>目前从事着轨道交通的信号设计建设工作，在很长一个阶段内，感觉工作内容重复无挑战。但是在去年独立主管一个完整项目时，走出了舒适圈，开始接触更多的技能，在刚开始阶段困难重重，但随着不断的重复练习，逐步适应了现阶段工作。\u003c/p>\u003cp>\u003cstrong>七、A2催化应用（2分钟）\u003c/strong>\u003c/p>\u003cp>感谢兔小灰小伙伴的分享，可以看到大家都潜意识的用到了刻意练习的前两部分。\u003c/p>\u003cp>大家在经过上一轮的讨论和倾听小伙伴的分享后，不知道对\u003cstrong>“刻意练习”\u003c/strong>方法有没有新的认识呢？\u003c/p>\u003cp>那我们已经学习了‘刻意练习’的四个步骤，大家未来几周或者一个月，有没有需要去学习下新的技能呢？或者学习一些新知识？比如练字啊，写作啊等，可以运用咱们今天学到的刻意练习方法。\u003c/p>\u003cp>请大家思考下，写在A2的便签纸上，那么给大家1分钟左右时间，稍后有时间我们请小伙伴分享下。\u003c/p>\u003cp>\u003cstrong>八、总结（30S）\u003c/strong>\u003c/p>\u003cp>由于时间原因，我们就不做分享了，大家把便签交给我就可以啦。\u003c/p>\u003cp>我们今天学习了刻意练习：破圈、重复、纠错、专注，三个步骤一个技巧。希望这个方法能够帮助到大家，在以后的学习生活中大家可以多多用起来。\u003c/p>\u003cp>非常感谢大家的聆听与参与，我们下期再见！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1622427859000,"updated_at":1622431609000,"ria":true},{"id":11565,"topic":"刻意练习的四要素","learn_goal":"","remark":"注重方法论的成功学书籍","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"吴韬","city":""},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>哈喽，大家好。我是今天的晋级者，我叫吴韬。下面开始我2-2的晋级。\u003c/p>\u003cp>学习目标\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够针对自己的某个兴趣爱好，现场制定出一个具备刻意练习四要素的练习方案。\u003c/p>\u003cp>分组\u003c/p>\u003cp>下面我进行一个简单的分组，这边两位小伙伴一组，这边两位小伙伴一组。\u003c/p>\u003cp>自我介绍\u003c/p>\u003cp>我现在三十多岁了。以前我特别的佩服那些讲话很精妙的人，他们好像总能说出一些让我受用终身的道理。可现在我有点改变，我越来越佩服那些从来不讲大道理，但总能给你提出各种各样务实解决方案的聪明人。因为只会说大道理都是别人的道理，改变不了自己的生活。只有学会一个一个的解决方案，才能让我们真正过的更好。那我有没有可能成为这样的聪明人呢？我觉得今天要介绍的这本书也许可以让我在成为聪明人的路上更进一步。\u003c/p>\u003cp>\u003cstrong>图书介绍\u003c/strong>\u003c/p>\u003cp>\u003cstrong>Feature： \u003c/strong>\u003c/p>\u003cp>这本书的名字叫做《请停止无效努力》。书的作者叫孙圈圈，他曾经是全球著名咨询公司的咨询总监。在创业的同时，也是一个专栏作家。虽然算不上特别有名气，但因为她的经历，她擅长于从多维度的视角来看待问题，这样的人写的书，是很值得读一读的。这本书17年出版，现在的豆瓣评分还高达8.1，算是一本经得住时间考验的书。\u003c/p>\u003cp>\u003cstrong>Advantage：\u003c/strong> \u003c/p>\u003cp>这本书乍一听名字特别像是成功学的鸡汤书籍，但它确实是本成长类的书籍，与其它同类书籍相比，在于这本书干货很多，它特别注重方法论，注重中我们如何实践到生活。所以这本书一点都不鸡汤。\u003c/p>\u003cp>\u003cstrong>Benefit： \u003c/strong>\u003c/p>\u003cp>【B1】这本书不仅讲述了如何与人愉快聊天的方法，还有教授人们搭建系统思维模型的思路 以及如何让我们快速成长一名斜杠青年的方法。（B2）当然也有今天拆页分享的，通过“针对性的练习”，实现快速成长的方法。总之方法很多，我相信你看了这本书，你一定会找到一个实用的方法运用到生活中，成为务实解决问题的聪明人。\u003c/p>","ratings_count":1,"texts":[{"id":15492,"quote":"\u003cp>介绍完了这本书，下面请大家用两分钟的时间阅读拆页，阅读完的小伙伴可以举手示意我。\u003c/p>\u003cp>【R】包含how的部分，内容不超过2页\u003c/p>\u003cp>阅读原文拆页\u003c/p>\u003cp>原文片段：\u003c/p>\u003cp>那么，什么是正确的刻意练习方法呢？它必须符合四大特征：\u003c/p>\u003cp>\u003cstrong>第一，在学习区练习\u003c/strong>\u003c/p>\u003cp>　　我们的学习，一般有三个区域：一个是舒适区，就是你非常熟练，几乎是下意识就可以完成的事情；中间是学习区，就是有一些挑战，可以通过努力掌握的；最外层是恐慌区，远远超出你的能力，当前很难掌握。如果用比喻的话，舒适区就像是右手随意写字，学习区是用右手学写某种字体的字，而恐慌区是让你直接用左手写那种字体出来。\u003c/p>\u003cp>　　因此，你需要反思，你现在的８小时工作内容中，分布在各个区域的比例有多少？如果在学习区的都不到１小时，那你就需要考虑一下了。因为，长此以往，你工作八年，只相当于别人工作一年。\u003c/p>\u003cp>\u003cstrong>第二，大量重复\u003c/strong>\u003c/p>\u003cp>　　这里所说的重复，是指在学习区内重复。学习任何一样新东西，其实是打破思维惯性、进行大脑重构的过程，要建立起重构后的稳定神经结构需要多次练习，才能掌握。这是一个将有意识变成无意识的过程。你看到很多人，面对问题快速梳理出思路，那是因为，你需要有意识、很努力才能做到的事情，他早已通过刻意练习形成无意识反应了。\u003c/p>\u003cp>\u003cstrong>第三，持续获得有效反馈\u003c/strong>\u003c/p>\u003cp>　　刻意练习是以错误为中心的，因为如果一样事情你从未做错过，证明你根本不需要学习它。我在之前的文章里说过，人类学习的特征是从错误中学习，所以我们才会说“专家是在一个狭小领域内犯过最多错误的人”。我们都考过试，刷过题库，最有效的做题方式是，每做一遍，记下错误的题目，下一遍只做错题，而不是一遍遍从头开始做。\u003c/p>\u003cp>\u003cstrong>第四，专注\u003c/strong>\u003c/p>\u003cp>　　同样在学习区里练习，练习时间也一样，而且也有反馈，最后的结果就没有差异吗？不是，差异很大。比如，同样是学写楷体字个在写字的时候听摇滚、想心事，而另一个则是沉浸其中，最后的结果是差异很大的。\u003c/p>\u003cp>　　所以，想要提升你的时间性价比，开始盘点你的天赋和劣势，将时间做个切换，并掌握正确的刻意练习方法吧！\u003c/p>","explains":"\u003cp>WHAT：\u003c/p>\u003cp>拆页内容告诉我们有效的刻意练习的方法。\u003c/p>\u003cp>WHY: （你需要讲刻意练习的概念是什么？让大家知识刻意练习的好处。 ） \u003c/p>\u003cp>1万小时的理论说时间足够长会成为专家，但是如果缺少刻意练习，可能也是白搭。\u003c/p>\u003cp> HOW： \u003c/p>\u003cp>那么有效的刻意练习怎么做呢？我用自己的练习演讲案例来说明。\u003c/p>\u003cp>第一。找到你在学习区里要做的事。\u003c/p>\u003cp>我的学习区是给熟悉的人正常说话和面对上百陌生人进行演讲之间的区域。找到学习区还要量化，于是我制定出每2周参加一次社群演讲活动和每天对着手机录一个即兴演讲。练习目标是1年内，获得两次演讲活动的最佳演讲。\u003c/p>\u003cp>第二，重复练习，达到下意识的程度。为了让我的演讲能力得提升，我需要重复练习比如手势、表情、语气的抑扬顿挫等。\u003c/p>\u003cp>第三，获得反馈。为了练习演讲，我参加了每日打卡练习群，每天上传打卡的录像。根据群里反馈，不断改进自己的演讲技能点。\u003c/p>\u003cp>第四，保持专注的状态。我每天会等孩子睡觉了以后用半个小时的时间，在在房间里练习，这就是设置专属的时间和场地。\u003c/p>\u003cp>WHERE：\u003c/p>\u003cp>当然这个方法需要有一定的自制力作为基础。如果我们要练习的项目恰好自己不是特别感兴趣，可能会半途而废。\u003c/p>\u003cp>可能存在的异议：\u003c/p>\u003cp>说到这里啊，你可能会有一些疑问。刻意练习的时候需要不断的获得反馈。道理对呀，但我们在练习的时候哪儿去找那么多反馈呢？我想我们可以通过互联网去找到匹配的社群来获得反馈。比如拆书帮，比如各种兴趣打卡群。\u003c/p>\u003cp>可能你还会有一个疑问。有些简单练习也不一定需要专注。比如练习跑步。不就有人一边跑步一边听音乐？我认为这就不算有效刻意练习，比如跑步看起来简单，但其实有很多细节，比如呼吸的节奏、腿部的动作、腰部的动作、脚掌的受力，都需要我们专注练习。\u003c/p>","interaction":"\u003cp>【A2】\u003c/p>\u003cp>催化应用\u003c/p>\u003cp>（分步催化1）\u003c/p>\u003cp>好了，说了那么多，大家不妨想一想，自己近期有没有什么是想通过刻意练习来提升的，比方兴趣技能方面，练字、画画、唱歌、跑步、足球、篮球、台球等等；工作方面，演讲、制作PPT、写作等等。请用两分钟时间在组内讨论一下，讨论完毕，我会请一位小伙伴来分享一下他未来有什么想要刻意练习的事情。\u003c/p>\u003cp> 学习者隆兄分享，自己希望刻意练习的事情是羽毛球。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>催化应用\u003c/p>\u003cp>（分步催化2）\u003c/p>\u003cp>刚刚我们已经有小伙伴分享了到想应用到的场景，接下来是学以致用的环节，针对刚才我们想到的我们未来想要练习的场景，使用我刚讲到的“刻意练习四要素”制定一个具体的练习计划。包括：你想达成的目标，不能是空洞的，要是可实现的、有时间期限，具体的一个目标。以及你练习的内容、频率、时段、地点、获得反馈的方式等。请大家在组内讨论，时间6分钟。\u003c/p>\u003cp>最后，我会请一位小伙伴来分享一下自己的刻意练习应用规划。\u003c/p>\u003cp>学习者隆兄分享：自己刻意练习的计划，目标是获得公司羽毛球比赛的前五名，练习周期1个月，从下周1开始。练习的内容是分解为挥拍、力道、姿势。 练习频率是每天1次，每个动作50次。练习的时段，每天晚上9点-9：30。地点是家里客厅。反馈的方式是周四单位与同事练习，互相点评。并且在练习的时候录视频看自己的动作。\u003c/p>\u003cp>好了，因为时间的关系，今天的分享就到此为止，非常感谢各位的聆听和配合。再次谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1621480696000,"updated_at":1622294692000,"ria":true},{"id":11332,"topic":"快速搭建临场发言框架","learn_goal":"","remark":"注重方法论的成功学书籍","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"吴韬","city":""},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>大家好，我叫吴韬，下面开始2-1的晋级。\u003c/p>\u003cp>\u003cstrong>学习目标\u003c/strong> \u003c/p>\u003cp>在跟随我完成本次现场学习后，大家可以运用今天的方法，在临场发言的时候，能够快速组织出主题明确的发言框架。\u003c/p>\u003cp>\u003cstrong>分组\u003c/strong>\u003c/p>\u003cp>下面我进行一个简单的分组，这边两位小伙伴一组，这边两位小伙伴一组。\u003c/p>\u003cp>\u003cstrong>自我介绍\u003c/strong>\u003c/p>\u003cp>好，进行完了分组，下面进行一下简单的自我介绍。我是一个三十多岁的奶爸。最近，人过中年，不断具有很多困惑，萦绕在心头。最大的困惑就是人说30而立。可我都三十多岁了，怎么还是一事无成呢？我觉得有时候我好像也挺努力的，怎么努力的半天，感觉和身边那些无不怎么努力的人混的也差不多，甚至还不如别人好。我好像就是那种，学了很多道理。却依旧过不好这一生的平凡人。最近看了一本书，他好像解答了我一部分人生的困惑。\u003c/p>\u003cp>\u003cstrong>图书介绍\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（FAB法）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>Feature： \u003c/strong>\u003c/p>\u003cp>这本书的名字叫做《请停止无效努力》。书的作者叫孙圈圈，他曾经是全球著名咨询公司的咨询总监。现在创业的同时，也是一个专栏作家。虽然算不上特别有名气，但确实是一个聪明人。聪明人的写的书，是很值得读一读的。像这本书17年出版，现在的豆瓣评分还高达8.1，算是一本经得住时间考验的书。\u003c/p>\u003cp>\u003cstrong>Advantage：\u003c/strong> \u003c/p>\u003cp>这本书乍一听名字特别像是成功学的鸡汤书籍，这本书和很多成功学的书籍最大的不同。就在于这本书干货很多，它特别注重方法论，注重中我们如何实践到生活。所以这本书一点都不鸡汤。\u003c/p>\u003cp>\u003cstrong>Benefit： \u003c/strong>\u003c/p>\u003cp>我觉得看到这本书可能会对我们生活有很多全方位的提升。作者介绍的方法我们可以实现到生活中去。比如构建思维能力的方法。比如我们如何与人愉快聊天的方法。比如如何成为一名斜杠青年的方法。当然也包括用我们今天分享的方法，做一个逻辑清晰的临场发言。总而言之，方法很多，我相信你看了这本书，你一定会找到一个方法。去用到自己的人生中，为自己带来真真正正的改变。\u003c/p>","ratings_count":2,"texts":[{"id":15258,"quote":"\u003cp>临场发言时，我们是有压力的。这种压力，要不让我们的大脑一片空白、胡言乱语，要不让我们的大脑信息泛滥、毫无头绪。这两种情况，听众听起来都会比较痛苦，不明白你到底想表达的是什么。\u003c/p>\u003cp>如果说，有一个清晰的结构，发言就变得容易了。一方面，如果你的大脑是杂乱无章的状态，它可以帮你把信息快速整理并输出；另一方面，如果你的大脑是一片空白的状态，它可以作为提示语帮你联想起一些有用信息。\u003c/p>\u003cp>用结构化思维，帮助你在短时间内更好地沟通，关键是三个步骤：\u003c/p>\u003cp>第一步，想主题：迅速找到一个切入点，第一句就说出自己的观点。\u003c/p>\u003cp>第二步，搭架子：在论证观点时，思考一个结构（时间、空间、程度），并只说三点，这称之为三个“架子”。\u003c/p>\u003cp>第三步，填素材：每一个架子里，填充一些事例、数据等，来推进论据向观点靠近\u003c/p>","explains":"\u003cp>\u003cstrong>WHAT：\u003c/strong>\u003c/p>\u003cp>拆页的告诉了我们一个即兴发言的框架结构。\u003c/p>\u003cp>\u003cstrong>WHY:\u003c/strong> \u003c/p>\u003cp>拆页告诉我们两个原因需要用到这样的结构。第一个原因，如果我们不用这样的结构，满脑子的信息，会缺乏分类，导致表达的信息非常散乱。第二是如果不用这样的结构，表达的时候我们会因为缺少关键提示信息，在即兴发言的时候出现忘记自己的思路，说着说着后面不知道说什么的情况。\u003c/p>\u003cp>\u003cstrong>HOW：\u003c/strong> \u003c/p>\u003cp>这种即兴发言的步骤很简单，只有三步，分别是：想主题、搭架子、填素材。\u003c/p>\u003cp>为了更清楚说明步骤，我们可以举个栗子，假设开会的时候，领导忽然让我们说说单位团建去什么地方，我们就可以按照步骤，这样回复领导。\u003c/p>\u003cp>第一步，想主题：我建议春游去三圣乡的农家乐。\u003c/p>\u003cp>第二步，搭架子： 建议去那里主要从以下三个方面来考虑，分别是：费用、场地、距离。\u003c/p>\u003cp>第三步，填素材：费用是因为上周我家里就去了，玩一天连吃带玩做多人均150，预算可控也不算贵。第二场地方面，现在的农家乐场地很宽敞，在一个地方，我们可以做活动，就餐，下午还可以玩各种农场体验或者打牌。第三，就在市区，距离很近。方便各位同事到达。\u003c/p>\u003cp>\u003cstrong>不那么做的坏处：\u003c/strong> \u003c/p>\u003cp>在工作中，很多人的即兴发言就是自己想到哪说到哪，说了一大堆，自我感觉还不错，可听众早就蒙了，完全不知道你说的是什么，或者是根本就不知道你想表达的主题是什么。比如，开会的时候，听完一个方案汇报，领导让大家说说自己的意见，有人可能会这样说：“我觉得方案里面第二页有文字没有对齐，第五页的图片有点low，第八页的颜色看起很杂乱，还需要调整一下。”这种表达听起来，主题就非常不清晰，显得随意专业度不高，搞不好还会给领导留下一个你业务能力不行的印象。如果用今天的公式，我们应该先说主题：“这个方案排版需要调整”，接着搭架子：“主要需要从文字对齐，图片选择和颜色运用三方面”。最后填素材：“文字方面，比如第三页的文字框没有对齐。图片选择，比如第三页图片太low了，可以用简约一点的。颜色运用，第八页用了8种颜色，非常杂乱。可以减少颜色使用。” 你看这样说是不是就更能让听众理解。\u003c/p>\u003cp>\u003cstrong>WHERE：\u003c/strong>\u003c/p>\u003cp>当然这样的方法，最核心的作用是帮你归类或者引导你的思路。前提是你需要对你发言的主题要有一定沉淀的。如果你面对一个完全一无所知的话题，脑中一片空白，你也很难用这种结构，完成即兴发言。比如，突然让你说说对低维量子物理的材料运用的看法。即便你用这种方法，也做不了即兴发言。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>激活经验\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（显像提问法） \u003c/strong>\u003c/p>\u003cp>大家可以回忆一下。在生活中这样的场景很多，比如开会的时候领导突然点名让我们对一个工作发表一下意见。被比如突然邀请做一次自我介绍，客户突然问道你们公司的产品有什么好处，坐电梯的时候和领导偶遇，他问到了最近工作进展等等。我们这时有没有出现脑子里有一大堆想法，可自己说了一大堆缺乏主题感的内容，从反馈上看，听众要么理解得完全不一致，要么根本不知道我们说的什么，表现出了不耐烦的情况。请大家用3分钟的时间，分组讨论一下，看看我们生活中，何时？何地？与何人？遇到过类似这种情况。请隆兄组织你们这组的伙伴讨论。小组讨论完毕后我会请1个学习者来分享，她想到的发生在过去的哪个场景。\u003c/p>\u003cp>\u003cstrong> 学习者隆兄分享\u003c/strong>了公司里自我介绍的经历。\u003cstrong>时间\u003c/strong>上周1 \u003cstrong>地点\u003c/strong> 公司 \u003cstrong> 人物 \u003c/strong>他和新领导。\u003cstrong>事件\u003c/strong> 单位新领导来，在新领导的见面会上，他做自我介绍案例。就是因为信息太多，反而不知道如何提炼信息。使得自我介绍表达很散乱，自我介绍做得很不好，既没有给到领导直观印象，自己的优势也没有很好的介绍。\u003c/p>\u003cp>\u003cstrong>【A1+】反思加工\u003c/strong>\u003c/p>\u003cp>好，下面进入到我们最重要的环节，大家既然学会了方法，就要学以致用。针对我们刚才回忆到的这种情况，比如隆兄刚才分享的在开会的时候，即兴做自我介绍的案例。现在学会了这种方法，给大家7分钟的时间，大家可以相互讨论一下，如果再遇到当时相似的场景，重新运用今天所学的步骤，你会怎么做？ \u003c/p>\u003cp>\u003cstrong>学习者子菱分享\u003c/strong>，如果运用今天的结构，在下周 公司公司人力部门组织讨论公司氛围建设的时候，自己可以针对自己想要的工作氛围的主题，可以从人员、沟通、工作交接三个方面搭架子，搭好架子以后，分别填内容，人员方面，需要同事之间见面互相问好，表达善意。沟通方面，遇到资源冲突，不在背后搞小动作，而是直接沟通。交接方面，收到新的交接内容，确认目的和有效信息。\u003c/p>\u003cp> 好了，由于时间关系今天的分享到此结束，非常感谢各位同学和观察家的听我的分享和配合。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1618206296000,"updated_at":1620553739000,"ria":true},{"id":10934,"topic":"如何找到真正的问题","learn_goal":"","remark":"帮助努力很久依旧没有成功的人，找到正确的努力方向，让人生少走弯路","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"树夏","city":"深圳市"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>【自我介绍】大家好，我是今天的拆书家树夏。先用三个标签作一下自我介绍。第一个标签，我是一名课程策划师，5年累计开发线上课程数量达300+，第二，我喜欢心理学。第三，我是旅行爱好者。\u003c/p>\u003cp>【介绍图书】今天，我拆解的图书是孙圈圈的《请停止无效努力：如何用正确的方法快速进阶》，这本书豆瓣评分8.1分，是同类职场畅销书万分之一，盖茨基金会中国区负责人李一诺称她的文章有格局、有深度、有理论、能指导实践。这本书能帮助大家在个人成长、人生规划、竞争力、品牌塑造以及寻找合适平台上少走很多弯路，是很棒的职场干货书籍。\u003c/p>","ratings_count":1,"texts":[{"id":14835,"quote":"\u003cp>\u003cstrong>　 如何找到真正的问题\u003c/strong>\u003c/p>\u003cp>1个小时=55分钟澄清问题+5分钟解决问题\u003c/p>\u003cp>如果给我1个小时解答一道决定我生死的问题，我会花55分钟来弄清楚这道题到底在问什么。一旦弄清楚了它到底在问什么，剩下的5分钟足够解答这个问题。 —— 爱因斯坦\u003c/p>\u003cp>可现实中，大多数人的做法完全相反——看到问题都有压抑不住马上跳进去找到答案的冲动。\u003c/p>\u003cp>在我刚做咨询不久的时候，老板让我做个行业研究，以便一周后见客户用。我当时很兴奋，因为做研究分析什么的，我最擅长了。于是各种埋头找资料、加班做PPT，拿出一份自认为非常完美的行研报告。\u003c/p>\u003cp>老板看了不到3分钟，说：“你做得很辛苦，但一点用都没有。客户的咨询目的是吸引和挽留人才，你的行研竟然没有劳动力市场的分析维度。还有你做了行业趋势分析，但竟然没有这些发展趋势对人才管理的启示，你要我怎么跟客户谈？”\u003c/p>\u003cp>我当时心情低落到几点。但也是那以后，我才意识到：\u003cu>花时间澄清真正的问题，以及知道哪些问题需要被解决，是多么重要的事情。\u003c/u>\u003c/p>\u003cp>首先，\u003cstrong>不是所有的问题都是真正的问题。\u003c/strong>\u003c/p>\u003cp>那么，\u003cstrong>如何找到真正的问题呢？\u003c/strong> \u003c/p>\u003cp>\u003cstrong>第一，\u003c/strong> \u003cstrong>提问，澄清事实\u003c/strong>\u003c/p>\u003cp>澄清的方法，就是向对方提问。如果这个问题是别人提出的，那么就会存在双方的理解偏差，你需要跟对方澄清真正的问题。\u003c/p>\u003cp>\u003cstrong>第二，\u003c/strong> \u003cstrong>挖掘对方的需求\u003c/strong>\u003c/p>\u003cp>每个人都有自己的社会角色，所说未必是所想的，所以，当你在面临与人冲突的问题时，不要急着解决表面问题，而要去挖掘别人内心的真正需求，从而找到真正的问题所在。\u003c/p>\u003cp>\u003cstrong>第三，\u003c/strong> \u003cstrong>分析背后的原因 \u003c/strong>\u003c/p>\u003cp>很多问题，其实背后是有原因的，如果不能把原因找出并解决，问题会不断暴露，所以，我们要搞清楚成因，解决根本问题，而不是只解决表象问题。\u003c/p>\u003cp>　　好了，经过这三个步骤，你终于找出什么是真正问题了。\u003c/p>","explains":"\u003cp>好的，我看到大部分小伙伴已经阅读完了。\u003c/p>\u003cp>大家有没有遇到过这样的情况：自认为领导交代的任务做得很不错，却被批得狗血淋头？在一某件事情上卡壳许久，终归找不到解决的办法？合作商总是百般出幺蛾子？或者是家里的孩子总是调皮捣蛋惹人生气。\u003c/p>\u003cp>实际上，光看表象，我们是没办法找到症结所在的，只有找到真正问题，打开突破口，自然迎刃而解。\u003cstrong>如果只解决表象问题，可能陆续会引发更多的小问题，结果不如意，甚至会徒劳无功。倘若解决了真正问题，才能称为真正解决。（why）\u003c/strong>那么真正的问题，是藏在表象之下的矛盾关键，需要我们进一步识别。\u003cstrong>（what）\u003c/strong>比如方案被毙，可能是没按照规范来写；在某件事上卡壳很久，也许是关键决策人没有找对；家里的小孩调皮捣蛋或许是为了引起你的注意，从而关注他。\u003c/p>\u003cp>在刚刚大家读的这个片段，作者以亲身经历来说明一个道理：方向找错了，只有苦劳没有功劳。花时间澄清真正问题，以及知道哪些问题需要被解决，是十分重要的事情。\u003c/p>\u003cp>那么应该怎么找到真正问题呢？\u003c/p>\u003cp>有三个步骤：\u003cstrong>（how）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一，提问，澄清事实。\u003c/strong>向对方提问，比如通过询问，沟通澄清问题，确认双方信息无偏差。比如，可以在领导给自己委派任务时，澄清背景、目标、展示对象；可用资源；篇幅以及必须的分析维度；什么时候需要初稿终稿等等\u003c/p>\u003cp>\u003cstrong>第二，挖掘对方的需求。\u003c/strong>简单来说从对方的利益出发挖掘其内心需求，比如挖掘领导的真正需求是什么？达到什么目的？还可以用过什么方法实现需求？等等。\u003c/p>\u003cp>\u003cstrong>第三，分析背后的原因。\u003c/strong>在挖掘对方需求之后，就要分析出背后的原因，解决根本的问题。比如，领导为什么会提出这样要求？是为了给客户提供更落地的洽谈，更符合客户实际，推进合作。分析知晓背后的原因，可以更聚焦问题。\u003c/p>\u003cp>这个方法应用的范围十分广泛，除了遇到他人需要你解决问题的时候，双方观点产生冲突的时候，还可以使用此方法寻找关键事件的真正问题。\u003cstrong>（where）\u003c/strong>\u003c/p>\u003cp>比如，小李是一个高级白领，工作认真负责，为了升职加薪，公司要求996，他自己搞007，是一个极度的工作狂，连年来工作全勤。可最近他经常迟到，工作也不得劲了，同事们高度怀疑他是不是准备跳槽。领导老王约谈小李，澄清事实，得知其父亲在医院住院治疗，小李每天晚上都要陪护，但是为了维持收入不想耽误工作，白天坚持上班，限于心理压力大，精力有限，加上医院与公司距离太远，不得已迟到。\u003c/p>\u003cp>表象问题：频繁请假，疑似要跳槽\u003c/p>\u003cp>真实问题：父亲住院，晚上要照顾父亲，白天上班，压力负担重\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1：激活经验】指令清晰。学习者在小组内分享了自已的经验，并有一个代表分享了本组的一个经验。\u003c/strong>\u003c/p>\u003cp>好啦，大家听完这个三步找到真正问题的策略，有什么启发呢？接下来，我邀请大家做一个小组讨论和简单练习。\u003c/p>\u003cp>\u003cstrong>【技能点：给学习者分组】\u003c/strong>\u003c/p>\u003cp>我先给大家分个组吧，两两一组。\u003c/p>\u003cp>首先，请大家花2分钟时间各自分享一下，在最近的生活或者工作中，你有没有遇到过你“以为已经解决”但并“未真正解决”的问题？或者正在处于冲突中的问题？\u003c/p>\u003cp>王静雯：就是原来我们老板让我写一个公众号的文章，然后他要求说你要把这个产品宣传给客户，让客户觉得我们产品很好。然后我就按照他的要求，我就去写一篇文章，然后把我们的产品那些图片贴上去了，介绍贴上去了，型号贴上去了，然后他说他说不行啊，你写的不行啊，没有就是没有达到客户想要的点。\u003c/p>\u003cp>\u003cstrong>【A2：催化应用】指令清晰，每个学习者都写下了一个包含具体做法、有明确时限和只衡量或可观测预期结果的便签。\u003c/strong>\u003c/p>\u003cp>下来我请大家拿出便签纸，作一个行动规划，请大家写一下，如果按照三步找到真正问题的策略进行规划，你会怎么去找到潜藏的真正问题？定位病灶所在呢？请大家写明规划的具体时间，具体的做法，可衡量或可观测的结果。\u003c/p>\u003cp>王静雯：嗯，那我来分享一下，下周的时候我就是会再写一篇那个宣传稿。然后写宣传稿之前就写产品宣传稿。写宣传稿之前我要先对老板进行提问。这个宣传稿是写给消费者呢？还是写给投资人？还是写给我们的股东呢？然后找到了，比如说是写给我们的消费者嘛，然后挖掘消费者的背后的需求。比如说消费者的需求可能就是买到更实用的，然后更符合他们要求的产品。那比如说，它的痛点就在于什么安全类的。然后呢，背后分析背后的原因。就比如说我发现了它就需要那种用起来更好的，然后不能保证它安全的那种产品。背后原因就是，那就推荐一下那个，他可能内心就比较需要那种质量好一点的，然后那个更有保障的产品用的时间更久，然后性能更好。然后就把这些体现出来。\u003c/p>\u003cp>好，那这样的话，我们就是用三部找到真正问题的那个办法，然后帮助你就是澄清问题，定位根源，找到真正的问题所在，那么我的分享就是到这里就结束了，希望对大家有所帮助，我的分享就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1610548557000,"updated_at":1610852285000,"ria":true},{"id":10556,"topic":"构建高价值人脉圈","learn_goal":"","remark":"1","level":"TF3-1","duration":20,"status":29,"type":0,"chaishujia":{"username":"林佳鸿","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>【学习目标】在跟随我完成本次RIA现场学习后，学习者能够在想要搭建高价值人脉圈的时候，使用拓展弱联系三步法，筛选出符合自己价值导向，且能认识不同行业的人的社群，并明确自己能提供的价值\u003c/p>\u003cp>大家好，我是今晚的拆书家———佳鸿\u003c/p>\u003cp>【场景】今天我来跟大家聊一聊人脉圈，每个人都希望自己可以有个高价值的人脉圈，但是呢，大多数人的情况是这的样子：\u003c/p>\u003cp>每天点开微信，扑面而来的是十几个群，上百条的未读消息，刷完了这些信息，发现都没什么价值，平时在群里也很少说话，不过也不舍得退群\u003c/p>\u003cp>【提问】我们加入了很多线上线下社群，但依然跟群里的人是陌生人，没办法建立起高价值的人脉圈？大家也有遇到这样的问题吗？\u003c/p>\u003cp>【影响】这种“无效社交”的情况，首先浪费我们的时间，刷很多微信群的消息，还不一定有价值。其次呢，跟太多人打交道也很消耗我们的精力，最后呢，可能会浪费钱，因为很多高质量的社群也要付费的嘛。\u003c/p>\u003cp>【解决】今天我来跟大家拆解的这本书——请停止无效努力，作者孙圈圈介绍了一个方法，叫拓展弱联系，可以帮助我们停止社交方面的无效努力，更高效地搭建高价值人脉圈！\u003c/p>","ratings_count":1,"texts":[{"id":14412,"quote":"\u003cp>弱联系，就是指你圈子以外的人，你认识、但不那么关心，可能是朋友的朋友，或者刚认识不久的人，你们的想法常常不同。弱联系通常建立在价值交换的基础上。这里的价值指的是广义的价值，不仅仅是指经济价值。\u003c/p>\u003cp>比如，你要找工作，但没有太多面试经验，你的好友，可以特地抽出时间来帮你准备面试，而这是弱联系的人不会、也没有必要帮你去做的事情。\u003c/p>\u003cp>但弱联系人的价值也很高，比如，他/她所在的公司正在招聘，而你恰好在找这样的工作，也是一个符合要求的候选人，帮你做一下内部推荐是举手之劳的事情，双方获益、双方开心。\u003c/p>\u003cp>人们靠自己的朋友介绍通常找不到工作，反而是靠一面之缘的人容易找到。事实上，熟悉的朋友跟你处于同一个圈子，了解的信息往往跟你差不多，有多少事情是你不清楚而只有他们知道的呢？反而是那些“泛泛之交”，他们的圈子跟你不同，才能够了解到你不清楚的信息。\u003c/p>\u003cp>“弱联系”的真正作用是把不同的社交圈子连接起来，从圈外给你提供有用的信息。它的本质是信息的传递，以及价值的交换。这也就是为什么，弱联系理论常常应用于找工作、商业合作、相亲这样的信息依赖性社交事件。\u003c/p>","explains":"\u003cp>好的，大家都阅读完了么？\u003c/p>\u003cp>【WHY】：\u003c/p>\u003cp>这个片段讲的是弱联系这个概念，其实特别好理解，在微信当中，有两种人，跟你就是弱联系的关系。第一种，是活在你朋友圈的人，俗称点赞之交。第二种，是跟你没加微信好友，都在一个微信群的人。\u003c/p>\u003cp>你跟这两种人，平时不会有什么情感上的深度交流，但可以有很多信息上的交流。比如说，人家转发一个招聘贴，那里新开了一家不错的火锅店。\u003c/p>\u003cp>所以，拓展弱联系的好处，就是你可以因为认识不同圈子的人，获得更多的信息。尤其是在找工作、商业合作、相亲这样的事情，都能发挥巨大的价值。\u003c/p>\u003cp>很多人呢，知道人脉很重要的，但不知道拓展弱联系的方法，加入社群时，常会出现以下的3种问题：\u003c/p>\u003cp>【概念对比1】：\u003c/p>\u003cp>【反例1】：\u003c/p>\u003cp>首先第1种情况，很多人可能会为了拓展人脉圈，加入很多的社群，但容易三分钟热度，过几个星期啊，就不出现了。\u003c/p>\u003cp>【关键点1】：\u003c/p>\u003cp>拓展弱联系的根本是要价值交换对吧，但如果你都没有想过你参加这个社群，你想要在这里获得什么价值。只是为了社交而社交，那没过多久一定就丧失了动力。所以不管是什么目的，你一定要先想清楚，你想获得什么价值，这个社群能不能给到你呢？\u003c/p>\u003cp>那这个价值可以是很多种，比如说锻炼演讲能力、获取商业合作的机会，想在这里脱单，都是可以的\u003c/p>\u003cp>【概念对比2】：\u003c/p>\u003cp>【反例2】：\u003c/p>\u003cp>有的朋友他想拓宽人脉圈，但也只想在自己行业的圈子里，不喜欢跟其他领域的人交流\u003c/p>\u003cp>【关键点2】：\u003c/p>\u003cp>但更好的做法是，拓宽自己的圈子，更加的多元，多去认识不同行业背景、年龄阶段的人\u003c/p>\u003cp>因为我们拓展弱联系，圈子更多，自然能获得更多信息。如果你是一个程序员，你就别只在互联网的圈子，可以多去认识做教育、搞文艺等不同圈子的人。\u003c/p>\u003cp>【概念对比3】：\u003c/p>\u003cp>【反例3】：很多人呢，加入这个社群后，基本不说话，一直潜水。可能发红包的时候才能看到他。\u003c/p>\u003cp>【提问，互动】：这样有拓展弱联系吗？\u003c/p>\u003cp>【关键点3】：\u003c/p>\u003cp>拓展弱联系的关键是价值交换，交换是双向的过程，要得到也要给予。但大多数人到一个社群，不说话、不付出，就只是索取\u003c/p>\u003cp>如果你要在这里链接到人脉，必须主动给予，给别人带来一些价值，当别人有好的机会好的信息，才会推荐给你。\u003c/p>\u003cp>【行动步骤】：\u003c/p>\u003cp>好的，那根据上面做的三个常见问题，我来帮大家总结出我们如何加入一个社群的三步骤，从而帮助我们拓展弱联系。\u003c/p>\u003cp>\u003cstrong>第一、明确价值\u003c/strong>\u003c/p>\u003cp>你在想加入某个社群之前一定要问自己一个问题，你想获得什么价值，这个社群能不能给到你呢？\u003c/p>\u003cp>\u003cstrong>第二、行业多元\u003c/strong>\u003c/p>\u003cp>你加入这个社群，能不能认识到不同行业背景的人？让你接触到不同的圈子\u003c/p>\u003cp>\u003cstrong>第三，主动给予\u003c/strong>\u003c/p>\u003cp>你可以给别人带来什么价值？很多人说啊，我就是个小白，什么都不懂？其实你可以给予的特别多，比如在群里多冒泡，主动参与活动，别人有一些什么小的问题帮忙解答，在现场活动中，可以承担时间官这些角色，帮忙摆一下椅子也行~\u003c/p>\u003cp>前两步，是加入社群前，对社群的筛选；第三步，是加入社群后，可以怎么展示自己，让别人认识你。\u003c/p>\u003cp>【正面例子】：\u003c/p>\u003cp>给大家举一个我自己加入拆书帮的例子\u003c/p>\u003cp>第1步明确价值我就很清楚，来到拆书帮的目的一方面我要在这里不断的修炼自己培训演讲的能力。另一方面我是一位优势教练，也想借拆书帮的平台，提升自己的影响力\u003c/p>\u003cp>第2点呢，行业多元。在拆书帮，我会认识很多会员，金融保险、律师、HR，培训师而且每次参加活动，都有很多新的学习者，大家也都说来自不同行业背景的\u003c/p>\u003cp>第3点主动给予，我目前是智荟分舵的组织长老，所有线下的拆书活动都是我在统筹组织，那确实付出了不少的时间精力，但我也因此获得了大家的信任。\u003c/p>\u003cp>【适用边界】：\u003c/p>\u003cp>用今天的方法，要构建一个高价值人脉圈，是需要你付出时间，才能慢慢形成的。但如果你那种急功近利的，想快速从别人身上获得利益，进一个社群，二话不说就发广告这种，今天的方法就并不适用。\u003c/p>","interaction":"\u003cp>为了帮助大家更好地应用，我们来做个有趣的编剧练习。\u003c/p>\u003cp>假如你有一位好朋友，最近想拓展人脉圈，不知道怎么加入一个适合TA的社群，请你用今天学到的方法，帮他梳理。\u003c/p>\u003cp>最终成果，要编写一个剧本。\u003c/p>\u003cp>小剧本内容要包含：人物角色、你们对话的过程，你说了什么，你朋友说了什么...请在拆页的右边按照格式填写，给大家5分钟时间。\u003c/p>\u003cp>哪一位小伙伴愿意分享一下自己的剧本？（2分钟）\u003c/p>\u003cp>欢迎Doris\u003c/p>\u003cp>Doris：我的一个同事，也是做招聘的，我们可能会约在吃饭的地方。她就向我请教一个问题，要怎么样加入适合自己的社群。\u003c/p>\u003cp>我就说，你要想你要获得什么，明确你加入社群要获得的价值是什么。\u003c/p>\u003cp>朋友：现在就是想多认识一点人，我想多赚一点钱\u003c/p>\u003cp>Doris：那可以呀，你可以参加一些金融方面的社群，学理财的东西。当然，我建议你也去认识不同行业的人，我这半年在拆书帮、也做副业，认识了各行各业的人，对我帮助特别大\u003c/p>\u003cp>朋友：那我可以多去尝试，也参加拆书帮的活动看看\u003c/p>\u003cp>Doris：第三点，你参加任何活动，也不能只索取，不给予。我在社群里，也经常主动分享养生的知识，对人有帮助有价值的内容。\u003c/p>\u003cp>朋友：那我可以主动分享招聘相关的干货，知识。\u003c/p>\u003cp>\u003cstrong>回应：\u003c/strong>OK，Doris特别棒，完整地从“明确价值”“行业多元”“主动给予”三个步骤跟我们分享了她跟朋友互动的剧本。\u003c/p>\u003cp>【总结】\u003c/p>\u003cp>在现在这个互联网的时代，我们都很乐意加入各种社群，但只是盲目为社交而社交的话，反而会浪费大量的时间精力。今天，我们学到了构建高价值人脉圈的三个步骤，明确价值导向、行业多元、主动给予。期待看到大家，未来可以在自己喜欢的社群持续深耕，与更多志同道合的小伙伴一路同行，谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1603182413000,"updated_at":1603803951000,"ria":true},{"id":10520,"topic":"如何构建高价值人脉圈","learn_goal":"","remark":"你身边有没有这样的人？当TA想要找到更好的工作机会，发条“票圈”，刚好就有HR找他内推；当TA想拓展项目合作伙伴，在几个微信群一说，刚好就有适合的人来链接......\n\n你会不会很羡慕这样的人呢？“我也好想拥有一个高价值的人脉圈，他们是如何做到的？”如果你也这么想，请停止无效努力，一起来学习——如何正确地拓展弱联系，为自己构建高价值人脉圈！！！","level":"TF3-1","duration":20,"status":29,"type":0,"chaishujia":{"username":"林佳鸿","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>【学习目标】在跟随我完成本次RIA现场学习后，学习者能够在想要搭建高价值人脉圈的时候，使用拓展弱联系三步法，筛选出符合自己价值导向，且能认识不同行业的人的社群，并明确自己能提供的价值\u003c/p>\u003cp>大家好，我是今晚的拆书家———佳鸿\u003c/p>\u003cp>【场景】今天我来跟大家聊一聊人脉圈，每个人都希望自己可以有个高价值的人脉圈，但是呢，大多数人的情况是这的样子：\u003c/p>\u003cp>每天点开微信，扑面而来的是十几个群，上百条的未读消息，刷完了这些信息，发现都没什么价值，平时在群里也很少说话，不过也不舍得退群\u003c/p>\u003cp>【提问】我们加入了很多线上线下社群，但依然跟群里的人是陌生人，没办法建立起高价值的人脉圈？大家也有遇到这样的问题吗？\u003c/p>\u003cp>【影响】这种“无效社交”的情况，首先浪费我们的时间，刷很多微信群的消息，还不一定有价值。其次呢，跟太多人打交道也很消耗我们的精力，最后呢，可能会浪费钱，因为很多高质量的社群也要付费的嘛。\u003c/p>\u003cp>【解决】今天我来跟大家拆解的这本书——请停止无效努力，作者孙圈圈介绍了一个方法，叫拓展弱联系，可以帮助我们停止社交方面的无效努力，更高效地搭建高价值人脉圈！\u003c/p>","ratings_count":1,"texts":[{"id":14373,"quote":"\u003cp>弱联系，就是指你圈子以外的人，你认识、但不那么关心，可能是朋友的朋友，或者刚认识不久的人，你们的想法常常不同。弱联系通常建立在价值交换的基础上。这里的价值指的是广义的价值，不仅仅是指经济价值。\u003c/p>\u003cp>比如，你要找工作，但没有太多面试经验，你的好友，可以特地抽出时间来帮你准备面试，而这是弱联系的人不会、也没有必要帮你去做的事情。\u003c/p>\u003cp>但弱联系人的价值也很高，比如，他/她所在的公司正在招聘，而你恰好在找这样的工作，也是一个符合要求的候选人，帮你做一下内部推荐是举手之劳的事情，双方获益、双方开心。\u003c/p>\u003cp>人们靠自己的朋友介绍通常找不到工作，反而是靠一面之缘的人容易找到。事实上，熟悉的朋友跟你处于同一个圈子，了解的信息往往跟你差不多，有多少事情是你不清楚而只有他们知道的呢？反而是那些“泛泛之交”，他们的圈子跟你不同，才能够了解到你不清楚的信息。\u003c/p>\u003cp>“弱联系”的真正作用是把不同的社交圈子连接起来，从圈外给你提供有用的信息。它的本质是信息的传递，以及价值的交换。这也就是为什么，弱联系理论常常应用于找工作、商业合作、相亲这样的信息依赖性社交事件。\u003c/p>","explains":"\u003cp>好的，大家都阅读完了么？\u003c/p>\u003cp>【WHY】：\u003c/p>\u003cp>这个片段讲的是弱联系这个概念，其实特别好理解，在微信当中，有两种人，跟你就是弱联系的关系。第一种，是活在你朋友圈的人，俗称点赞之交。第二种，是跟你没加微信好友，都在一个微信群的人。\u003c/p>\u003cp>你跟这两种人，平时不会有什么情感上的深度交流，但可以有很多信息上的交流。比如说，人家转发一个招聘贴，那里新开了一家不错的火锅店。\u003c/p>\u003cp>所以，拓展弱联系的好处，就是你可以因为认识不同圈子的人，获得更多的信息。尤其是在找工作、商业合作、相亲这样的事情，都能发挥巨大的价值。\u003c/p>\u003cp>很多人呢，知道人脉很重要的，但不知道拓展弱联系的方法，加入社群时，常会出现以下的3种问题：\u003c/p>\u003cp>【概念对比1】：\u003c/p>\u003cp>【反例1】：\u003c/p>\u003cp>首先第1种情况，很多人可能会为了拓展人脉圈，加入很多的社群，但容易三分钟热度，过几个星期啊，就不出现了。\u003c/p>\u003cp>【关键点1】：\u003c/p>\u003cp>拓展弱联系的根本是要价值交换对吧，但如果你都没有想过你参加这个社群，你想要在这里获得什么价值。只是为了社交而社交，那没过多久一定就丧失了动力。所以不管是什么目的，你一定要先想清楚，你想获得什么价值，这个社群能不能给到你呢？\u003c/p>\u003cp>那这个价值可以是很多种，比如说锻炼演讲能力、获取商业合作的机会，想在这里脱单，都是可以的\u003c/p>\u003cp>【概念对比2】：\u003c/p>\u003cp>【反例2】：\u003c/p>\u003cp>有的朋友他想拓宽人脉圈，但也只想在自己行业的圈子里，不喜欢跟其他领域的人交流\u003c/p>\u003cp>【关键点2】：\u003c/p>\u003cp>但更好的做法是，拓宽自己的圈子，更加的多元，多去认识不同行业背景、年龄阶段的人\u003c/p>\u003cp>因为我们拓展弱联系，圈子更多，自然能获得更多信息。如果你是一个程序员，你就别只在互联网的圈子，可以多去认识做教育、搞文艺等不同圈子的人。\u003c/p>\u003cp>【概念对比3】：\u003c/p>\u003cp>【反例3】：很多人呢，加入这个社群后，基本不说话，一直潜水。可能发红包的时候才能看到他。\u003c/p>\u003cp>【提问，互动】：这样有拓展弱联系吗？\u003c/p>\u003cp>【关键点3】：\u003c/p>\u003cp>拓展弱联系的关键是价值交换，交换是双向的过程，要得到也要给予。但大多数人到一个社群，不说话、不付出，就只是索取\u003c/p>\u003cp>如果你要在这里链接到人脉，必须主动给予，给别人带来一些价值，当别人有好的机会好的信息，才会推荐给你。\u003c/p>\u003cp>【行动步骤】：\u003c/p>\u003cp>好的，那根据上面做的三个常见问题，我来帮大家总结出我们如何加入一个社群的三步骤，从而帮助我们拓展弱联系。\u003c/p>\u003cp>\u003cstrong>第一、明确价值\u003c/strong>\u003c/p>\u003cp>你在想加入某个社群之前一定要问自己一个问题，你想获得什么价值，这个社群能不能给到你呢？\u003c/p>\u003cp>\u003cstrong>第二、行业多元\u003c/strong>\u003c/p>\u003cp>你加入这个社群，能不能认识到不同行业背景的人？让你接触到不同的圈子\u003c/p>\u003cp>\u003cstrong>第三，主动给予\u003c/strong>\u003c/p>\u003cp>你可以给别人带来什么价值？很多人说啊，我就是个小白，什么都不懂？其实你可以给予的特别多，比如在群里多冒泡，主动参与活动，别人有一些什么小的问题帮忙解答，在现场活动中，可以承担时间官这些角色，帮忙摆一下椅子也行~\u003c/p>\u003cp>前两步，是加入社群前，对社群的筛选；第三步，是加入社群后，可以怎么展示自己，让别人认识你。\u003c/p>\u003cp>【正面例子】：\u003c/p>\u003cp>给大家举一个我自己加入拆书帮的例子\u003c/p>\u003cp>第1步明确价值我就很清楚，来到拆书帮的目的一方面我要在这里不断的修炼自己培训演讲的能力。另一方面我是一位优势教练，也想借拆书帮的平台，提升自己的影响力\u003c/p>\u003cp>第2点呢，行业多元。在拆书帮，我会认识很多会员，金融保险、律师、HR，培训师而且每次参加活动，都有很多新的学习者，大家也都说来自不同行业背景的\u003c/p>\u003cp>第3点主动给予，我目前是智荟分舵的组织长老，所有线下的拆书活动都是我在统筹组织，那确实付出了不少的时间精力，但我也因此获得了大家的信任。\u003c/p>\u003cp>【适用边界】：\u003c/p>\u003cp>用今天的方法，要构建一个高价值人脉圈，是需要你付出时间，才能慢慢形成的。但如果你那种急功近利的，想快速从别人身上获得利益，进一个社群，二话不说就发广告这种，今天的方法就并不适用。\u003c/p>","interaction":"\u003cp>为了帮助大家更好地应用，我们来做个有趣的编剧练习。\u003c/p>\u003cp>假如你有一位好朋友，最近想拓展人脉圈，不知道怎么加入一个适合TA的社群，请你用今天学到的方法，帮他梳理。\u003c/p>\u003cp>最终成果，要编写一个剧本。\u003c/p>\u003cp>小剧本内容要包含：人物角色、你们对话的过程，你说了什么，你朋友说了什么...请在拆页的右边按照格式填写，给大家5分钟时间。\u003c/p>\u003cp>哪一位小伙伴愿意分享一下自己的剧本？（2分钟）\u003c/p>\u003cp>欢迎Doris\u003c/p>\u003cp>Doris：我的一个同事，也是做招聘的，我们可能会约在吃饭的地方。她就向我请教一个问题，要怎么样加入适合自己的社群。\u003c/p>\u003cp>我就说，你要想你要获得什么，明确你加入社群要获得的价值是什么。\u003c/p>\u003cp>朋友：现在就是想多认识一点人，我想多赚一点钱\u003c/p>\u003cp>Doris：那可以呀，你可以参加一些金融方面的社群，学理财的东西。当然，我建议你也去认识不同行业的人，我这半年在拆书帮、也做副业，认识了各行各业的人，对我帮助特别大\u003c/p>\u003cp>朋友：那我可以多去尝试，也参加拆书帮的活动看看\u003c/p>\u003cp>Doris：第三点，你参加任何活动，也不能只索取，不给予。我在社群里，也经常主动分享养生的知识，对人有帮助有价值的内容。\u003c/p>\u003cp>朋友：那我可以主动分享招聘相关的干货，知识。\u003c/p>\u003cp>\u003cstrong>回应：\u003c/strong>OK，Doris特别棒，完整地从“明确价值”“行业多元”“主动给予”三个步骤跟我们分享了她跟朋友互动的剧本。\u003c/p>\u003cp>【总结】\u003c/p>\u003cp>在现在这个互联网的时代，我们都很乐意加入各种社群，但只是盲目为社交而社交的话，反而会浪费大量的时间精力。今天，我们学到了构建高价值人脉圈的三个步骤，明确价值导向、行业多元、主动给予。期待看到大家，未来可以在自己喜欢的社群持续深耕，与更多志同道合的小伙伴一路同行，谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1601722170000,"updated_at":1603458101000,"ria":true},{"id":10333,"topic":"觉察自我情绪","learn_goal":"","remark":"----","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"微视觉","city":"深圳市"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>大家好，我是微视觉用三个标签自我介绍一下：\u003c/p>\u003cp>\u003cstrong>1：品牌设计\u003c/strong> 是我的职业\u003cbr> \u003cstrong>2：户外运动\u003c/strong> 是我的兴趣爱好\u003cbr> \u003cstrong>3：终身学习，持续精进\u003c/strong> 是个人成长目标\u003c/p>\u003cp>今天分享的这个拆页来自《请停止无效努力》作者孙圈圈。她曾是全球著名公司管理总监，现在是\u003cu>领英洞察\u003c/u>专栏作家。豆瓣评分8.1分，是一本关于自我成长的书籍。很多案例是作者亲身实践的内容，具有很强的实操性。而且书写结构非常清晰，这本书本身就是一部结构化思维的教科书。\u003c/p>","ratings_count":3,"texts":[{"id":14178,"quote":"\u003cp>觉察自己的情绪,是自我觉察中最基本的一项。在觉察自我情绪时,我们可以样做:\u003c/p>\u003cp>\u003cstrong>第一，\u003c/strong> \u003cstrong>拓展关于情绪的词汇量,并能说情绪的名称。\u003c/strong>\u003c/p>\u003cp>想管理和控制一个事物,了解它是必须的。如果你连它的名字都叫不出来,那你只会被它控制。描述情绪的词汇大概有几百个,所以,不妨多积累一些情绪的词汇量,并在出现情绪的时候,判断一下,它是哪一种。另外,你知道是哪种情绪之后,不妨大声说出情绪的名字。因为有研究表明,当你大声说出当下情绪名称的时候,这种情绪会减弱。\u003c/p>\u003cp>\u003cstrong>第二，说出每个情绪的特点。\u003c/strong>\u003c/p>\u003cp>只知道情绪的名字还不行,你还需要知道这种情绪的特点,比如它伴随的身体反应是什么、一般什么时候出现。多年前,我做过一次职业转型。转型之后做第一个项目的时候,我常常感到工作提不起劲,但我不知道为什么。后来我发觉,我当时的情绪其实是无关紧要(insignificant)，就是觉得自己渺小和人微言轻。每次当团队讨论的时候,就会出现这种情绪,身体反应是目光向下、肩膀无力、无心讨论。\u003c/p>\u003cp>\u003cstrong>第三，聆听情绪传递给你的声音。\u003c/strong>\u003c/p>\u003cp>还是刚才的例子,这种感到渺小的情绪,想要告诉我的是: “尽快找到你在团队中的位置和价值吧,否则,我会一直围绕着你。”所以,我才会开始思考自己的独特价值/优势、以及如何在团队中发挥它。\u003c/p>\u003cp>现在请大家花1分钟的时间，快速阅读下手里的原文片段，阅读完的小伙伴请抬头示意我一下。\u003c/p>","explains":"\u003cp>好的，我看大部分小伙伴已经读完了，没有阅读完的小伙伴，也请暂停一下，接下来我们一起分析一下这个拆页。\u003c/p>\u003cp>相信大家曾经或多或少的有被自己的情绪困扰过，如做了很久的方案被客户否决时的失落；被别人误解时的愤怒；有时遇上一件事，让你很长时间忧心忡忡，情绪低落，做什么事都提不上劲。情绪本身是不分好坏的，即使是那些消极的情绪，也是来自大脑的自我防卫。但处理不好情绪，就会给自己的生活和工作带来很大的困扰。如何解决这个问题呢？没错，知己知彼才能百战不殆，想要管理好自己的情绪，首先是要在情绪来临时候察觉到它的存在。\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>拆业中的“觉察自我情绪”这个方法，就是帮助我们时刻觉察自己的情绪，在情绪出现时能够客观理智的对待它。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>\u003c/p>\u003cp>那么如何觉察自我情绪呢？\u003c/p>\u003cp>\u003cstrong>第一步：说出情绪名称\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步：说出情绪特点\u003c/strong>（身体反应，心里反应）\u003c/p>\u003cp>\u003cstrong>第三步：聆听情绪传递给你的声音\u003c/strong>（挖掘自身需求，找到产生该情绪的根本原因）\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>\u003c/p>\u003cp>那么我们为什么要觉察自己的情绪呢？觉察自我情绪能够帮助我们跳出情绪的烦恼，避免因为情绪而做出错误的事和决定\u003c/p>\u003cp>\u003cstrong>【Where】\u003c/strong>\u003c/p>\u003cp>这个方法可以用在哪些地方呢？就是当我们在生活和工作中自己因为人、事、物的关系出现情绪困扰的时候，这个方法能够让我们客观理智的对待情绪，帮助我们脱离它的困扰。\u003c/p>\u003cp>\u003cstrong>【案例】\u003c/strong>\u003c/p>\u003cp>分享一个自己真实的案例，帮助大家更好地理解这个方法。就在上一个月的一天，老板把我和另外一个同事叫进办公室，突然让我停掉手上的项目，去做别的项目。我跟他说这个项目客户急着要，而且都答应客户什么时候给对方了，我没时间去做另外一个项目。当时他就不乐意了，叼了我一顿，后面紧接着客户来了，坐在旁边改稿，搞得我郁闷了一上午，最后啥事也没干。\u003c/p>\u003cp>\u003cstrong>反思：\u003c/strong>后来我在想，可能是当时自己说话的语气不对，才造成那种场面，当时一边是客户催着要稿，一边是说暂停。那时候因为客户的文件很大，导致操作非常的卡，所以当时的心情是很烦躁的，这种情绪下说出来的话有点火药味，并且给人非常不友好的感觉，所以才造成当时被老板教育那种不和谐的场面。\u003c/p>\u003cp>现在学习了“自我觉察情绪”这个方法，如果再来一次我应该这样做\u003c/p>\u003cp>\u003cstrong>第一步：说出情绪名称\u003c/strong>（在内心告诉自己这个情绪叫烦躁）\u003c/p>\u003cp>\u003cstrong>第二步：说出情绪特点\u003c/strong>（告诉自己烦躁的情绪会导致自己干啥都没耐心，看啥都不顺眼，说话语速快，并且有很大火药味，让听的人感到很不舒服。）\u003c/p>\u003cp>\u003cstrong>第三步：聆听情绪传递给你的声音\u003c/strong>（这种烦躁的情绪想要告诉我的是：“我需要1-2天时间把手头的项目先完成，我个人很看重诚信问题”）\u003c/p>\u003cp>我相信我通过这个方法，理性看待自己情绪后，能够更平和的和老板商量这件事，一定不会出现之前的尴尬场面。\u003c/p>","interaction":"\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>为了更好地掌握这一个方法，接下来会有小组讨论环节，所以先分一下组。\u003c/p>\u003cp>\u003cstrong> A1\u003c/strong>\u003c/p>\u003cp>好的，接下来请大家回忆一下，在过去几个月里有没有遇到类似的情况？因为情绪给生活和工作带来了困扰。比如努力争取的事没有完成时的失落，因为担忧害怕而迟迟未去做自己非常想做的事，等等。时间两2分钟可以小组讨论交流，稍后我会请一位小伙伴分享具体的故事情节\u003c/p>\u003cp>\u003cstrong>学习者Alice:\u003c/strong>\u003c/p>\u003cp>记得我上一年级的时候，我有次考了90分，爸妈很不高兴，说一定要考100分。我认真努力，期末时终于考了99分，爸妈还是不满意，一直数落我，为什么没有考满分。在爸妈这种批判数落中当时我非常失落，自己的努力没有被他们看在眼里，只要不是满分就是不符合要求。\u003c/p>\u003cp>非常感谢Alice小伙伴的分享。\u003c/p>\u003cp>\u003cstrong>A2\u003c/strong>\u003c/p>\u003cp>拆书讲的是学以致用，相信通过上面的分享，小伙伴们现在已经学会了觉察情绪的方法步骤\u003c/p>\u003cp>第一步：说出情绪名字\u003c/p>\u003cp>第二步：说出情绪特点\u003c/p>\u003cp>第三步：聆听情绪传递给你的声音\u003c/p>\u003cp>下面请大家用2分钟的时间给未来的运用做一个规划，预计在未来一周内的某个场景，如何用到我们今天学习的觉察自我情绪的方法。然后请大家在拆业背面写上你未来的运用计划。\u003c/p>\u003cp>\u003cstrong>学习者Linda:\u003c/strong>\u003c/p>\u003cp>目标：在未来一周内，因为工作不顺，孩子来打扰自己产生愤怒情绪的时候，去运用觉察自我情绪的方法，管理自我情绪\u003cbr> 行动：\u003c/p>\u003cp>\u003cstrong>第一步：说出情绪名称，\u003c/strong>告诉自己这个情绪叫愤怒\u003c/p>\u003cp>\u003cstrong>第二步：说出情绪特点，\u003c/strong>愤怒的情绪，说话很呛，“不要打扰我，走开”这样可能会让孩子内心受伤\u003c/p>\u003cp>\u003cstrong>第三步：聆听情绪传递给你的声音\u003c/strong>，这个情绪产生的根本原因是自己对工作上的事情失去掌控感。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1598365015000,"updated_at":1598963370000,"ria":true},{"id":9834,"topic":"请停止无效努力","learn_goal":"","remark":"没有什么天赋异禀，极致源于持续有效的努力。\n很多时候，我们不是不努力，只是没找到正确的努力方法。\n本书从发掘天赋、提升能力、选择平台、回归自己等几大方面，详细阐述了职业发展和个人提升的正确方法论。书里所讲的方法与思路，可以用来分析我们生活、学习和工作中遇到的大多数问题。\n书中提供的科学以及实操的方法论，并非碎片化知识，而是一套体系化的方法论，并且都通过形象生动的手绘图展现出来。同时，每篇文章都附有后续练习，如能好好实践，不仅会颠覆一个人过去的思维认知，并且能让工作和人生得到很大的提升。\n","level":"TF1-2","duration":20,"status":29,"type":0,"chaishujia":{"username":"楚江","city":""},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>\u003cstrong> 【自我介绍】\u003c/strong>\u003c/p>\u003cp>大家好，我是林楚江。按照拆书帮的惯例，用三个标签介绍下自己：\u003c/p>\u003cp>\u003cbr> 1. 潮汕人。相信在广州深圳之类的城市潮汕人是很多的，所以这个标签很平常，但是我觉得文化背景对人的影响还是很潜移默化的，所以我把它作为一个标签。\u003c/p>\u003cp>\u003cbr> 2. 伪斜杠青年。为什么是这个标签呢？在我看来，真正的斜杠是每个身份都是很专业的，而伪斜杠是指希望尝试且有不同的爱好，仅此而已，当然，我希望通过努力把伪斜杠变成真正的斜杠。\u003cbr> \u003c/p>\u003cp>3拆书家。虽然现在才刚准备过级，但是我希望明年这个标签会改为三级拆书家，谢谢！\u003c/p>\u003cp>\u003cstrong>【拆书帮介绍】\u003c/strong>\u003c/p>\u003cp>接下来我简单为大家介绍拆书法跟拆书帮\u003c/p>\u003cp>【拆书法介绍】\u003c/p>\u003cp>“拆书法”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。拆书法分为个人学习和组织学习：\u003cbr>\u003c/p>\u003cp>个人学习的应用是便签法，撰写 I 便签、A1 和 A2 便签，I 便签是指学习者用自己的语言对原文进行复述；而 A1 便签指向过去，要求学习者关联撰写过去经历，可以是成功的经验也可以是惨痛的教训；最后 A2 便签则指向未来，要求学习者运用原文知识规划未来的具体行动，达到拆为己用的目的。\u003c/p>\u003cp>组织学习的应用是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。\u003c/p>\u003cp>【拆书帮介绍】\u003c/p>\u003cp>“拆书帮”是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵（也叫拆书帮俱乐部）。拆书帮分舵是公益青年自组织，其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":13675,"quote":null,"explains":"\u003cp>\u003cstrong>【I】分享I便签\u003c/strong>\u003c/p>\u003cp>what：如何用结构化的思维进行结构化的表达\u003cbr>\u003c/p>\u003cp>why：人们在临场发言跟表达时，经常会因为压力等原因而出现思绪混乱等情况，而如果有一个清晰的结构，发言会变得容易些。 \u003c/p>\u003cp>where：结构化表达在很多场合都可以用到，特别在一些临场的发言、分享，甚至是复盘总结，都是可以采用这种结构化表达的\u003cbr>\u003c/p>\u003cp>那么如何在生活工作中应用这种结构化表达呢？有这样三个步骤？\u003c/p>\u003cp>how：\u003c/p>\u003cp>第一步，想主题：找到切入点，用一句话说出自己的观点\u003c/p>\u003cp>第二步，搭架子：用时间、空间、程度的结构，并且只说三点，也叫三个“架子”，比方时间架子：过去、现在、未来，活动前、活动中、活动后等，比方空间的架子，家里、公司、球馆......\u003c/p>\u003cp>第三步，填素材：每一个架子里，填充数据、故事等\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】分享A1便签\u003c/strong>\u003cbr>\u003c/p>\u003cp>故事：\u003c/p>\u003cp>记得在好几年前，刚工作没多久，那时候部门每周一早上都会开会，在早会上，每个人都需要汇报这周的工作计划跟安排。当时轮到我的时候，我基本都是说，我这周主要计划做一二三四几件事，然后就结束了汇报，这样导致的结果呢会让领导觉得你工作没有重点，甚至错失一些机会。 \u003c/p>\u003cp>反思：\u003c/p>\u003cp>现在想想当时是没注意，我们在很多工作场合的发言是需要结构化表达的，当然，更重要的是不清楚应该如何更好地表达，这样其实也会导致大家沟通时出现不清晰的情况，而结构化的表达在工作中的发言汇报，甚至写作反思中，都会有很大的帮助！\u003c/p>\u003cp>\u003cstrong>【A2】分享A2便签\u003c/strong>\u003c/p>\u003cp>目标：输出每日的总结反思记录模板，并每天坚持记录\u003c/p>\u003cp>行动：\u003c/p>\u003cp>按照结构化表达的三个步骤：\u003cbr>\u003c/p>\u003cp>第一步，想主题： 主题就是做好每日的总结反思记录\u003c/p>\u003cp>第二部，搭架子：首先我把每日分为工作、学习、生活\u003c/p>\u003cp>第三步，填素材：\u003c/p>\u003cp>工作上是今日完成与明日计划；\u003cbr>\u003c/p>\u003cp>学习上是记录今日的读书、写作收获；\u003cbr>\u003c/p>\u003cp>生活上主要是记录每日运动、每日小确幸；\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1590220450000,"updated_at":1591235552000},{"id":9795,"topic":"请停止无效努力","learn_goal":"","remark":"没有什么天赋异禀，极致源于持续有效的努力。\n很多时候，我们不是不努力，只是没找到正确的努力方法。\n本书从发掘天赋、提升能力、选择平台、回归自己等几大方面，详细阐述了职业发展和个人提升的正确方法论。书里所讲的方法与思路，可以用来分析我们生活、学习和工作中遇到的大多数问题。\n书中提供的科学以及实操的方法论，并非碎片化知识，而是一套体系化的方法论，并且都通过形象生动的手绘图展现出来。同时，每篇文章都附有后续练习，如能好好实践，不仅会颠覆一个人过去的思维认知，并且能让工作和人生得到很大的提升。\n","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"楚江","city":""},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>欢迎大家来参加今天晚上的拆书分享，事不宜迟开始我们今天的分享。\u003c/p>\u003cp>大家好，我是林楚江。按照拆书帮的惯例，用\u003cstrong>三个标签介绍下自己\u003c/strong>：\u003c/p>\u003cp>第一个标签是潮汕人\u003c/p>\u003cp>第二个标签是伪斜杠青年，其实是指喜欢尝试且有不同的爱好，仅此而已，当然，我希望通过努力把伪斜杠变成真正的斜杠\u003c/p>\u003cp>第三个标签是拆书家。虽然现在才刚准备过级，但是我希望今年这个标签会改为三级拆书家，谢谢！\u003c/p>\u003cp>接下来我简单为大家\u003cstrong>介绍拆书法跟拆书帮\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>【拆书法介绍】\u003c/strong>\u003c/p>\u003cp>“拆书法”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。拆书法分为个人学习和组织学习：\u003c/p>\u003cp>个人学习的应用是便签法，撰写 I 便签、A1 和 A2 便签，I 便签是指学习者用自己的语言对原文进行复述；而 A1 便签指向过去，要求学习者关联撰写过去经历，可以是成功的经验也可以是惨痛的教训；最后 A2 便签则指向未来，要求学习者运用原文知识规划未来的具体行动，达到拆为己用的目的。\u003cbr>\u003c/p>\u003cp>组织学习的应用是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。\u003c/p>\u003cp>\u003cstrong>【拆书帮介绍】\u003c/strong>\u003c/p>\u003cp>“拆书帮”是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵（也叫拆书帮俱乐部）。拆书帮分舵是公益青年自组织，其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":13633,"quote":"\u003cp>\u003cstrong>【R】阅读原文拆页\u003c/strong>\u003c/p>\u003cp>临场发言时，我们是有压力的。这种压力，要不让我们的大脑一片空白、胡言乱语，要不让我们的大脑信息泛滥、毫无头绪。这两种情况，听众听起来都会比较痛苦，不明白你到底想表达的是什么。\u003c/p>\u003cp>如果说，有一个清晰的结构，发言就变得容易了。一方面，如果你的大脑是杂乱无章的状态，它可以帮你把信息快速整理并输出；另一方面，如果你的大脑是一片空白的状态，它可以作为提示语帮你联想起一些有用信息。\u003c/p>\u003cp>用结构化思维，帮助你在短时间内更好地沟通，关键是三个步骤：\u003c/p>\u003cp>第一步，想主题：迅速找到一个切入点，第一句就说出自己的观点。\u003c/p>\u003cp>第二步，搭架子：在论证观点时，思考一个结构（时间、空间、程度），并只说三点，这称为三个“架子”。\u003c/p>\u003cp>第三步，填素材：每个架子里，填充一些事例、数据等，来推进论据向观点靠近。\u003c/p>\u003cp>这里给大家举个例子，乔布斯推出第一款苹果手机时进行过一段演讲，大意如下：\u003c/p>\u003cp>苹果公司是一家革命性的公司。为什么这么说呢？1984年，推出Mac电脑，改变了整个电脑行业；2001年，推出iPod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；2007年，推出苹果手机，我相信它将改变更多行业。\u003c/p>\u003cp>我们来剖析一下这段话的结构，就会是：\u003c/p>\u003cp>主题：苹果公司是一家革命性的公司。\u003c/p>\u003cp>架子：1984年、2001年、2007年。\u003c/p>\u003cp>素材：推出Mac电脑，改变了整个电脑行业；推出iPod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；推出苹果手机。\u003c/p>\u003cp>所以，乔布斯这段话的结构也是由三要素组成：主题、架子、素材。\u003c/p>","explains":"\u003cp>\u003cstrong>【I】分享I便签\u003c/strong>\u003c/p>\u003cp>what：如何用结构化的思维进行结构化的表达\u003cbr>\u003c/p>\u003cp>why：人们在临场发言跟表达时，经常会因为压力等原因而出现思绪混乱等情况，而如果有一个清晰的结构，发言会变得容易些。 \u003c/p>\u003cp>where：结构化表达在很多场合都可以用到，特别在一些临场的发言、分享，甚至是复盘总结，都是可以采用这种结构化表达的\u003cbr>\u003c/p>\u003cp>那么如何在生活工作中应用这种结构化表达呢？有这样三个步骤？\u003c/p>\u003cp>how：\u003c/p>\u003cp>第一步，想主题：找到切入点，用一句话说出自己的观点\u003c/p>\u003cp>第二步，搭架子：用时间、空间、程度的结构，并且只说三点，也叫三个“架子”，比方时间架子：过去、现在、未来，活动前、活动中、活动后等，比方空间的架子，家里、公司、球馆......\u003c/p>\u003cp>第三步，填素材：每一个架子里，填充数据、故事等\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】分享A1便签\u003c/strong>\u003c/p>\u003cp>\u003cstrong>故事：\u003c/strong>\u003c/p>\u003cp>记得在好几年前，刚工作没多久，那时候部门每周一早上都会开会，在早会上，每个人都需要汇报这周的工作计划跟安排。当时轮到我的时候，我基本都是说，我这周主要计划做一二三四几件事，然后就结束了汇报，这样导致的结果呢会让领导觉得你工作没有重点，甚至错失一些机会。\u003c/p>\u003cp>\u003cstrong>反思：\u003c/strong>\u003c/p>\u003cp>现在想想当时是没注意，我们在很多工作场合的发言是需要结构化表达的，当然，更重要的是不清楚应该如何更好地表达，这样其实也会导致大家沟通时出现不清晰的情况，而结构化的表达在工作中的发言汇报，甚至写作反思中，都会有很大的帮助！\u003c/p>\u003cp>\u003cstrong>【A2】分享A2便签\u003c/strong>\u003c/p>\u003cp>\u003cstrong>目标：\u003c/strong>输出每日的总结反思记录模板，并每天坚持记录\u003c/p>\u003cp>\u003cstrong>行动：\u003c/strong>\u003c/p>\u003cp>按照结构化表达的三个步骤：\u003cbr>\u003c/p>\u003cp>第一步，想主题： 主题就是做好每日的总结反思记录\u003c/p>\u003cp>第二部，搭架子：首先我把每日分为工作、学习、生活\u003cbr>\u003c/p>\u003cp>第三步，填素材：\u003c/p>\u003cp>工作上是今日完成与明日计划；\u003c/p>\u003cp>学习上是记录今日的读书、写作收获； \u003c/p>\u003cp>生活上主要是记录每日运动、每日小确幸；\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1588733298000,"updated_at":1591423826000,"ria":true},{"id":6505,"topic":"运用结构化思维，让临场表达更轻松","learn_goal":"在临场表达时学会运用结构化的方式进行表达","remark":"工作生活中，你可能会面临这样的情景：被人问到一个问题，比如有机会见到大领导，他/她突然问你“公司有什么吸引你的地方，让你在这里待了5年呢？”\r\n顿时，你头脑中有很多信息，他们杂乱无章、野蛮生长，你想开口，却不知如何组织语言。或者你很兴奋，滔滔不绝地讲了一堆，但老板却一脸茫然，觉得你头脑不清晰。\r\n很多人觉得，自己的表达能力存在问题。其实，当你无法清楚地表达想法的时候，可能的原因是：你的想法本身就不清楚。思路非常清楚的人，很少有表达不清晰的，因为表达本身就是思路的一部分。\r\n所以，让表达更加清晰，你需要的是有一个思路来将你的信息进行结构化。\r\n","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"sheren","city":"深圳市"},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":"\u003cp>【自我介绍】\u003cbr>\u003c/p>\u003cp>大家晚上好，我叫邢茹。今天很开心有这样的机会跟大家做分享。我将从自我介绍、图书及原文拆页介绍、及拆书法RIA三个步骤这几个方面来展开讲述。首先，用三个标签介绍自己：\u003c/p>\u003cp>1，&nbsp; 互联网公司财务管理；\u003c/p>\u003cp>2，&nbsp; 湖南人，爱吃辣；\u003c/p>\u003cp>3，&nbsp; 新手拆书家，我拆书的目的主要是为了解决职场中的困惑和问题。\u003c/p>\u003cp>\u003cstrong>【书籍及拆页介绍】（0.5分钟）\u003c/strong>\u003c/p>\u003cp>今天我带来的书籍是《请停止无效努力》。作者孙圈圈，一位在咨询公司工作多年的女性。\u003c/p>\u003cp>这本书从发掘天赋、提升能力、选择平台、回归自己等几大方面详细阐述了努力的正确模式。\u003c/p>\u003cp>书中通过形象的图画等阐述方法和观点。\u003c/p>\u003cp>书里所讲的关于努力的方法与思路，可以用来分析我们生活、学习和工作中遇到的很多问题。\u003c/p>\u003cp>今天的拆页来自于提升沟通能力的部分。下面给大家1分钟时间阅读原文。阅读完的同学可以举手示意我一下。\u003c/p>","ratings_count":1,"texts":[{"id":9820,"quote":"\u003cp>临场发言时，我们是有压力的。这种压力，要不让我们的大脑一片空白、胡言乱语，要不让我们的大脑信息泛滥、毫无头绪。这两种情况，听众听起来都会比较痛苦，不明白你到底想表达的是什么。\u003c/p>\u003cp>如果说，有一个清晰的结构，发言就变得容易了。一方面，如果你的大脑是杂乱无章的状态，它可以帮你把信息快速整理并输出；另一方面，如果你的大脑是一片空白的状态，它可以作为提示语帮你联想起一些有用信息。\u003c/p>\u003cp>用结构化思维，帮助你在短时间内更好地沟通，关键是三个步骤：\u003c/p>\u003cp>第一步，想主题：迅速找到一个切入点，第一句就说出自己的观点。\u003c/p>\u003cp>第二步，搭架子：在论证观点时，思考一个结构（时间、空间、程度），并只说三点，这称之为三个“架子”。\u003c/p>\u003cp>第三步，填素材：每一个架子里，填充一些事例、数据等，来推进论据向观点靠近。\u003c/p>","explains":"\u003cp>好的，我看大部分小伙伴都阅读完了。\u003c/p>\u003cp>（What）那说说我对这个片段的自己的理解。这个片段讲的是，用一个清晰的表达结构，去帮助我们在临场的发言的时候，在有限时间内更好地完成我们的表达，分三个步骤：想主题、搭架子、填素材。\u003c/p>\u003cp>（WHY）在职场中，我们经常在电梯间或者跟老板汇报的时候，老板突然想到一些问题问我们的想法，那这个时候呢我们可能经常要么是头脑空白，不知道从何说起；要么就是脑子里有太多信息，滔滔不绝。那这种时候呢，领导或者同事就睡觉得说连表达都不清楚，是不是工作能力有问题。这样可能会影响我们未来的职业发展，甚至影响升职加薪。所以，今天原文片段给我们提供了一个很好的清晰的结构，帮我们解决上述遇到的问题。\u003c/p>\u003cp>（HOW）它是从三个方面展开：\u003c/p>\u003cp>第一，\u003cstrong>想主题。\u003c/strong>理解起来就是，我们一开始就要抛出我们的结论，为什么呢？因为在职场当中，大家的时间都是很有限的，我们必须在第一时间就讲出重点，去抓住听众的注意力；同时也能避免听众因为我们一开始陷入细节而导致提前得出跟我们不一样的结论，免得后续再花口舌解释。\u003c/p>\u003cp>\u003cstrong>第二，搭架子。\u003c/strong>\u003c/p>\u003cp>其实就是应对第一步提出的结论，用理由也就是论据去证明。一般建议说三点，很多实践证明，因为在有限的时间内，人最容易记住三个项目。这三个理由的关系可以是时间、空间、并列关系、逻辑递进关系等。比如说想表达某款产品质量很好，可以说用户反馈很好、做过一些测试结果很好、销量数据也很好。讲理由时要注意，三个项目相互独立且尽量全面，不要有大的缺漏。\u003c/p>\u003cp>\u003cstrong>第三，填素材。\u003c/strong>\u003c/p>\u003cp>我们需要有一些数据、事例、故事等，来支撑理由。我们可以用数据做对比说明，或者用生动的事例故事去说明。那我举一个例子，当你的对象问你喜欢她哪一点，你的答案是有爱心，喜欢小孩子，可能没办法说服她。但如果你回忆一个具体生动的例子，比如你上个星期她在小区门口看到有小孩摔倒，立马就跑过去扶起小孩，还带着小孩去买糖吃哄他开。相信你的对象一定会很满意你的回答。\u003c/p>\u003cp>（WHERE）这个方法除了用于临场表达外，像写文章搭结构、做年底项目总结时使用也是比较适合的。\u003c/p>\u003cp>上述就是我对原文的一个解读。\u003c/p>","interaction":"\u003cp>\u003cstrong>【激活经验】\u003c/strong>\u003cbr>\u003c/p>\u003cp>下面我通过我一个负面的例子来回忆我的痛点，让我更印象深刻，促进我使用原文的方法来解决痛点。\u003c/p>\u003cp>今天下午我参加了公司的一个思维导图培训，其中有一个环节是小组讨论，面对职场压力我们如何释放。需要对小组内5个人的方法进行分类。讨论完了之后，我建议按照我的方法进行分类，但是我仅仅站在自己的角度，片面地说我的思路，是看书心理纾解、寻求外界帮助；而组员的分类有从用钱买买买、用不花钱的走路跑步运动方式的角度。我并没有全面地考虑组员的方法如何去纳入我的分类架构。那因为我们迟迟达成不了一致，拖延了小组分享环节的时间，给同事们留下了不那么好的印象。\u003c/p>\u003cp>相信在最近一两个星期内，小伙伴们都有过汇报、总结、提案、销售、或者想要说服别人接受你的观点的经历。\u003c/p>\u003cp>现在给大家2分钟时间，请回忆一个负面的案例，因为临场没有做出太好的表达，导致没有到达预期的效果.之后我将请一位学习者上来分享。现在现场给大家进行分组：按照就近三位三位一组。\u003c/p>\u003cp>好的，大家讨论得很激烈。由于时间关系，讨论告一段落。下面请永青来分享。\u003c/p>\u003cp>永青的分享：部门开晨会时需要回顾业绩，平时负责的理财经理今天请假了，临时由我来回顾。懵了片刻后，我参照以往理财经理的做法，掏出手机，挨个按人名说理财卖了多少套、保险卖了多少套、货币基金卖了多少套，语速也特别快，我说完了，发现很多人没有听清楚。我自己想了一下，是因为脑子一片空白，没有思路，照搬了理财经理以往的做法，又因为想表现好，着急就语速快，结果大家一脸懵逼没有听清。\u003c/p>\u003cp>我总结一下，永青的这个经历，其实是没有稍微花点时间去捋一下表达的结构，而是平铺直叙地罗列，于是大家没有get到永青想表达的中心点是什么。如果永青能够运用今天三步走的结构化思路去搭建表达结构，用结论、理由、数据支撑呈现，相信能够在领导和同事面前有很好的表现。\u003c/p>\u003cp>\u003cstrong>【催化应用】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>接下来，回归到我们拆书的目的：避免重复发生失败案例.接下来请大家花2分钟，规划一个在下星期内，实践运用的场景，运用今天所学的结构化的三步骤方法。比如向领导做汇报、用自己的观点去说服家人朋友等。\u003c/p>\u003cp>接下来，回归到我们拆书的目的：避免重复发生失败案例，接下来请大家花2分钟，规划一个在下星期内，实践运用的场景，运用今天所学的结构化的三步骤方法。比如向领导做汇报、用自己的观点去说服家人朋友等。\u003c/p>\u003cp>好，时间到，下面请晓晓来分享自己的规划。\u003c/p>\u003cp>晓晓的分享：下周我准备和我的两位领导谈我以后的职业生涯规划。首先，我用一句话说出我的重点：“领导想好了，我接下来要做职业转型。”接下来我会说三个阶段：2018年之前的我，2018年的我，2018年以后的我。2018年以前我在做咨询这个行业，业务方向的项目经理，很喜欢的状态；但是2018年比较迷茫，热情减少，会有时间和经历的浪费；2018年以后我的方向是走专业路线，会给我以及公司带来XX收益。\u003c/p>\u003cp>我的总结：晓晓的规划，运用了今天所学的结论-理由-素材的结构，一方面清楚表达了为什么想要转型，另外一方面也讲了往哪个方向转型，是一个很好的例子。\u003c/p>\u003cp>【总结】我的今天的讲解到此结束，真心希望大家能够将今天所学运用到未来的实际工作中去，帮助大家有更好的职场表现。谢谢大家！\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1542467774000,"updated_at":1542469056000,"ria":true},{"id":6488,"topic":"运用结构化思维，让临场发言更精彩","learn_goal":"掌握临场发言的结构化思维方法，让你的发言逻辑清晰，侃侃而谈。","remark":"在工作或生活中，我们经常会遇到临时发言，或者回答问题，却常因准备时间不足，未能认真组织语言和内容，从而导致两种后果，一是想开口却不知从何说起，另一种是滔滔不绝说了一大堆，对方却一脸茫然。\r\n造成上述情形的根本原因就是思路不清晰。\r\n本次拆书提供了简单有效的结构化思维方法，架构发言内容，帮助我们的大脑快速梳理、联想有用信息，使我们能在短时间内组织出一场有说服力的演讲。\r\n","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"美珍","city":"杭州"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"\u003cp>\u003cstrong>[分组]\u003c/strong>将现场7位参与者分成三组，每个组里都至少有一位学习爱好者和拆书家。\u003c/p>\u003cp>\u003cstrong>【自我介绍&amp;图书介绍】\u003c/strong>\u003c/p>\u003cp>大家好，我叫美珍，先介绍下我的三个标签：一是链条产品事业部负责人，二是户外运动爱好者，喜欢徒步、慢跑和爬山。三是新手拆书家。&nbsp;\u003c/p>\u003cp>今天我为大家带来的片断来自《请停止无效努力》，该书作者孙圈圈，曾任全球著名管理咨询公司咨询总监，【领英洞察】专栏作家。\r\n本书从发掘天赋、提升能力、选择平台、回归自己等几大方面详细阐述了努力的正确模式。书中所讲的关于努力的方法与思路可以用来分析我们生活、学习和工作中遇到的大多数问题。\r\n如我们能结合每章的后续练习，好好实践，会给我们带来更大的受益。&nbsp;\u003c/p>\u003cp>今天我们只选择其中一个片断进行拆解。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003cbr>\u003c/p>","ratings_count":1,"texts":[{"id":9799,"quote":"\u003cp>【过渡】下面进入我们的拆书环节，我们将分三部分对片断进行拆解，也就是RIA，首先进入【R】环节，请大家花2分钟时间进行阅读，阅读完后请举手示意我，谢谢！\u003c/p>\u003cp>如何让你的演讲信息结构化\u003c/p>\u003cp>在本书之前关于结构化思维的文章里,曾经提到过,人类大脑在处理信息时有两个习惯:第一,不能一次太多,因为信息太多会让大脑的负荷过大;第二,喜欢有规律的信息。\u003c/p>\u003cp>临场发言时,我们是有压力的。这种压力,要不让我们的大脑一片空白、胡言乱语,要不让我们的大脑信息泛滥、毫无头绪。这两种情况,听众听起来都会比较痛苦,不明白你到底想表达的是什么。\u003c/p>\u003cp>如果说,有一个清晰的结构,发言就变得容易了。一方面,如果你的大脑是杂乱无章的状态,它可以帮你把信息快速整理并输出;另一方面,如果你的大脑是一片空白的状态,它可以作为提示语帮你联想起一些有用信息。\u003c/p>\u003cp>用结构化思维,帮助你在短时间内更好地沟通,关键是三个步骤:\u003c/p>\u003cp>第一步,想主题:迅速找到一个切入点,第一句就说出自己的观点。\u003c/p>\u003cp>第二步,搭架子:在论证观点时,思考一个结构(时间、空间、程度) ,并只说三点,这称为三个“架子”。\u003c/p>\u003cp>第三步,填素材:每个架子里,填充一些事例、数据等,来推进论据向观点靠近。\u003c/p>\u003cp>这里给大家举个例子，乔布斯推出第一款苹果手机时进行过一段演讲，大意如下：\u003c/p>\u003cp>苹果公司是一家革命性的公司。为什么这么说呢？1984年，推出Mac电脑，改变了整个电脑行业；2001年，推出iPod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；2007年，推出苹果手机，我相信它将改变更多行业。\u003c/p>\u003cp>我们来剖析一下这段话的结构，就会是：\u003c/p>\u003cp>主题：苹果公司是一家革命性的公司。\u003c/p>\u003cp>架子：1984年、2001年、2007年。\u003c/p>\u003cp>素材：推出Mac电脑，改变了整个电脑行业；推出iPod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；推出苹果手机。\u003c/p>","explains":"\u003cp>【过渡】我注意到大家都已经看完，为了让大家更好的理解原文，请允许我重述原文片断，即【I】环节：\u003c/p>\u003cp>在工作中，你经常会遇到会议或培训的临时发言，却常因准备时间不足，未能认真组织语言，从而导致两种后果，一是想开口却不知从何说起，另一种是滔滔不绝说了一大堆，对方却一脸茫然。\u003c/p>\u003cp>这两种后果都让你怀疑起自己的表达能力是否太差，但根本原因是思路不清晰。\u003c/p>\u003cp>而原文片断中的结构化思维方法能帮你理清思路。\u003c/p>\u003cp>在发言前，你如果运用结构化思维方法，架构发言内容，大脑就能快速梳理、联想有用信息，短时间内组织出一场有说服力的演讲。\u003c/p>\u003cp>用结构化思维进行沟通或发言，以下三个步骤是关键：\u003c/p>\u003cp>第一步：想主题：从大脑中迅速找出一个切入点，第一句就表明自己的观点，让听众有预期，从而吸引听众。\u003c/p>\u003cp>第二步：搭架子：架子指的是提炼出来的结构关键词，架子可以是时间架、空间架、程度架，无论哪类架子，都只说三点即可。\u003c/p>\u003cp>第三步：填素材：每个架子里，再填入相应的例子和数据，使观点更具说服力。\u003c/p>\u003cp>说个自己的糗事，上个月，公司对新上任的中层干部，举办了三天的上岗培训班，在培训快要结束时，主持人提前5分钟通知我，作为内训老师代表对培训课效果进行点评，由于时间紧，当我上台发言时，还没想好说什么，结果自然是发言结结巴巴，不知所言，场面很尴尬。\u003c/p>\u003cp>如果当时我使用上述结构化思维模式的发言，比如：\u003c/p>\u003cp>想主题——这次的中层干部培训效果非常好。\u003c/p>\u003cp>搭架子——意识突破、员工留育、实操技能三方面来讲\u003c/p>\u003cp>填素材——在架子后面加入具体例子说明。\u003c/p>\u003cp>当我能这样发言时，同事们听起来就会轻松得多了。\u003c/p>\u003cp>这种方法较适用于会议临时发言，或向领导汇报工作，不太适用于朋友之间的聊天。\u003c/p>","interaction":"\u003cp>\u003cstrong>&nbsp;[A1 激活经验]\u003c/strong>\u003c/p>\u003cp>接下来我们进入A1环节-激活我们的过去经验，你可以回忆一下过去2个月的时间里， 工作中遇到的会议临时发言，生活中遇到的同事、朋友问你对中美贸易战、房价、教育的看法，在小组内部互相分享，按我们刚才的小组分组方式，时间为3分钟。\u003c/p>\u003cp>（时间快到时），还有20秒，请没有讨论完的小伙伴抓紧时间。\u003c/p>\u003cp>（时间到）三组小伙伴分享的都很热烈，那就请丁建阳来给大家分享一下。\u003c/p>\u003cp>（学习者丁建阳讲）我们学校有很多外面的来宾和客户来参观，作为培训科的培训老师需要给他们讲解，虽然行政部给了我们稿子，但那稿子有3000多个字，很难背下来，我刚开始讲解的时候经常忘东忘西，被领导批评。后面我们改进了背稿子的方式，以空间位置为单位进行拆分，走到机器或模具旁，先把它们的最主要一点先讲出来，再说出一些关键数据，这些关键数据不能记错，至于对功能性的形象化的描述就可以自己发挥了，这个背稿子的过程也类似于结构化思维的方式。\u003c/p>\u003cp>（反馈）您分享的是自己讲解的经历，非常不错。\u003c/p>\u003cp>\u003cstrong>[A2\u003c/strong>\u003cstrong>催化应用](2分钟)\u003c/strong>\u003c/p>\u003cp>刚才我们激活了过去经验，接下来是我们的A2环节—规划未来的应用，学习的目的就是拆为己用，在接下来一周或一段时间内，大家想一想，比如向领导汇报、或被父母催婚的时候如何回复才好啊，或者今年的公司年会中了大奖，需要上台发言啊，当你遇到上述等情况时，你将如何按照结构化思维—想主题，搭架子，填素材的方法来应用呢？大家花一分半的时间把它写在便签纸上。\u003c/p>\u003cp>大家在写的时候，写要点即可，但要有可测量的明确目标、具体的做法，目标确定可以实现，这样才能真正学以致用。\u003c/p>\u003cp>（时间快到时），还有半分钟，请没有写完的小伙伴抓紧时间，可以先将要点写下来。\u003c/p>\u003cp>（时间到）有没有哪位伙伴想和大家分享一下自己的A2的？好，接下来先请徐密给我们分享下：\u003c/p>\u003cp>（学习者徐密发言）我这边来跟大家分享一下，下周如果有品牌供应商的店长来询问怎样提高交易额，我就用结构化思维模式与他们分享：交易额有个公式，就是流量X转化率X客单价，那我就会说流量的变化因素有哪些，如何找首页的流量、频道的流量、其他渠道的流量等方面找素材，那转化率呢？影响转化率的变化因素有图片、产品描述、活动等，那可以从这些方面来优化，找素材，那第三个，就是客单价，客单价需要与订单有个平衡的关系，在保持订单的情况下如何让客单价最大化，可以从优化你的菜品结构等方面找素材。\u003c/p>\u003cp>（反馈）徐密的分享特别好，完全符合想主题-搭架子-填素材的结构化思维的方法，非常感谢徐秘的分享，希望大家能将今天所学的想主题-搭架子-填素材的结构化思维方法应用到日常生活工作中，多加练习，直至应用自如，最终成为临时发言或汇报工作的高手。\u003c/p>\u003cp>&nbsp; &nbsp; 由于时间的关系，这个片段的拆解就到这里，有问题下面讨论，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1542286353000,"updated_at":1542289022000,"ria":true},{"id":5735,"topic":"如何发现自己的优点","learn_goal":"学会运用三步骤来帮助自己找到自己的优势","remark":"","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"阿拉丁","city":"海口市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>\u003cstrong>【学习目标】\u003c/strong>在跟随我完成本次RIA现场学习后，学习者能够在小伙伴的帮助下通过提问找到自己“强项”和“优点”，发现自己的“天赋”，并能做出一个体现自己优势的求职自我介绍。\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>【技能点要求：学习目标包含学习者可被观察到/测量到的行为或动作，现场学习者设计清晰体现了该学习目标.】\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cbr>\u003c/p>\u003cp>【开场】大家好，我叫林枫淇，一个做了十年课外数学物理培训的老师，这个场地就是我的战场，我今天要拆的这个片段就是TF2-3，这个级别由几个要求，一个要求就是在I讲解的部分要细化行动步骤，还有一个要求就是要有一个现场演练，我大概介绍一下我今天这个级别的几个要求。\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;【F特征】\u003c/p>\u003cp>&nbsp;今天我们要拆解的这本书《请停止无效努力：如何用正确的方法快速进阶》作者孙圈圈，曾任全球顶级管理咨询公司做了八年咨询总监，用企业视角、管理者视角、咨询师视角和职场人视角，整合自己十年咨询职场工作，写了这本职场进阶指导；\u003cbr>\u003c/p>\u003cp>&nbsp;【A优势】\u003c/p>\u003cp>它和其他成长类书籍不一样，有些书贩卖理念，专讲道理，有些书精耕某一领域，如时间管理、精力管理、笔记工具，一般都是单一视角，很少有书像这本，从老板和HR的视角，也从个人出发，讲个人成长的方法论，从内而外地进阶自己，即讲外，又讲内，围绕着职业发展和个人提升所需的方法论展开；\u003c/p>\u003cp>&nbsp;【B利益】\u003c/p>\u003cp>道理都懂，依然过不好这一生？\u003c/p>\u003cp>书读了一堆，还是过不好这一生？\u003c/p>\u003cp>每天早起打卡，熬夜加班，学习一切知识，努力和精神都有了，却依然觉得焦虑？\u003c/p>\u003cp>职场的路越走越迷茫，人生越走越没有方向？\u003c/p>\u003cp>为什么？因为我们做了太多无效努力！是没有方向的努力，努力着努力着变成了努力焦虑。\u003c/p>\u003cp>&nbsp; 这本书将告诉你如何有效地努力，从专注于自己的“天赋”开始，做自己最擅长的事！今天我将给大家带来找到自己“优势”和“强项”的方法，找到需要发展和专注的自己的优点。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【技能点要求：FAB介绍法，清晰辨别出F、A、B】\u003c/strong>\u003c/p>","ratings_count":1,"texts":[{"id":8936,"quote":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>拆页选自《请停止无效努力：如何用正确的方法快速进阶》孙圈圈 著 P.031\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我现在发一下今天的原文片段的材料，大家用一分钟的时间看一下左边的原文片段，右边的表格不用看。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【R：原文片段】\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一类问题：自我效能相关\u003c/strong>\u003c/p>\u003cp>你认为，自己能够教别人什么？\u003c/p>\u003cp>或者，别人常常向你请教什么？\u003c/p>\u003cp>你跟他人聊天的时候，倾向聊什么？\u003c/p>\u003cp>以及，聊什么话题你会更有自信？\u003c/p>\u003cp>你在做什么事情的时候，不会感到焦虑和担心？\u003c/p>\u003cp>\u003cstrong>第二类问题：本能相关\u003c/strong>\u003c/p>\u003cp>你在做什么事情的时候，很少拖延？\u003c/p>\u003cp>长时间休假后，你最想念工作的哪个方面、哪个内容？\u003c/p>\u003cp>你宁愿放弃休息时间，也要做的事情，是什么？\u003c/p>\u003cp>\u003cstrong>第三类问题：成长／专注相关\u003c/strong>\u003c/p>\u003cp>有什么事情，让你沉浸其中忘记吃饭／睡觉？\u003c/p>\u003cp>你在做什么事情的时候，会暂时忘记刷社交网络？\u003c/p>\u003cp>你在做什么事情的时候，不容易感到疲倦和厌烦？\u003c/p>\u003cp>\u003cstrong>第四类问题：满足相关\u003c/strong>\u003c/p>\u003cp>过去的工作和生活中，有什么能让你获得巨大的成就感和满足感？\u003c/p>\u003cp>\u003cstrong>【技能点要求：\u003c/strong>包含How的内容，且总内容不超过2页图书内页】\u003c/p>","explains":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>I\u003c/strong>\u003cstrong>】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>好，大家都看完了，大家会发现这个片段没头没尾的，感觉就是一堆问题，这是从发现天赋的四个角度来问自己一些问题，来找到我们自己的天赋和优势。\u003c/p>\u003cp>我们最大的“优势”就是发现自己的劣势，最擅长做“批评和自我批评”，分析自己的“弱点”、“劣势”滔滔不绝。不信咱们做个小测验：\u003c/p>\u003cp>请列出你的“七大劣势”和“七大优势”！\u003c/p>\u003cp>相信用不了几分钟，你就会把“劣势”梳理完了，而“优势”可能像挤牙膏一样，而且还是挤快用完了的牙膏，半天想不出一个。\u003c/p>\u003cp>为什么这么困难呢？很大原因是我们对“优势”的误解，总觉得“优势”就是最好，就是第一名，刚想到一个自己擅长的，脑海中立刻浮现出另外厉害的同事、同学、朋友，于是立刻觉得这一点根本不值一提。\u003c/p>\u003cp>于是大多数人专注于去强化自己的弱项，当他们忙于把自己并不擅长的事情做得马马虎虎时，他们便错过了将这些时间利用起来做一些以他们的能力可以取得更突出成绩的事情。\u003c/p>\u003cp>而在一些场合，因为不知道自己有什么优势，白白失去了表现的机会，比如，相亲需要表现出什么特质优点，求职表现出什么优点，参加某项联谊活动或宴会表现出什么优点，都一筹莫展。\u003c/p>\u003cp>所以找到自己的优势，并且专注于把优势发挥到最佳，以使其对我们的人生产生更大的影响，我们需要多做擅长的事，少考虑要把你做不好的事做得更好，而且找到优势，也能有意识的在适当的场合有针对性地表现自己和展示自己的优势.\u003c/p>\u003cp>如何才能找到自己的优势呢？\u003c/p>\u003cp>\u003cstrong>首先，你问自己六个问题：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1、你人生中，包括求学、工作、成长、生活中，有哪些特别的经历？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2、你平时投入最多的活动是什么？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3、你收到最多的赞美是什么？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>4、你自认为最强的能力是什么？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>5、你最擅长使用的工具或软件是什么？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>6、与人交流、聊天时，你最有自信或最倾向表达的是什么类型的话题？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>其次，把每个问题的答案尽可能多地记录下来，画成表格或者画成思维导图，你会惊讶地发现每个问题后面会写上好多答案，于是你对自己充满了自信。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>最后，筛选优势，优势是相对的，也需要有针对性，根据不同的场合的特点，对上面列出的所有优势进行筛选，选出有针对性地优势，要么加以强化，指导你现在的工作和学习，要么组合突出，用于某一场合的表现。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【技能点要求：\u003c/strong>给出比原书拆页更加细化的行动步骤，或者将书中的案例进行了意译】\u003c/p>\u003cp>有人会问，我要是问完之后还是找不到优点怎么办？那请你找自己亲密的人和你一起探寻，因为你需要的是一个打开自我认可的钥匙，有时自己被自己禁锢住了，但是你亲密的人了解你，在这几个问题驱使下，会找到你自己忽略掉的答案，只要一个答案，你的思路就打开了，优点会像泉水般涌出。\u003c/p>\u003cp>\u003cstrong>【技能点要求：\u003c/strong>预防异议】\u003c/p>\u003cp>我老婆就是一个一直很悲观的人，总觉得自己没什么优点，那天我用这六个问题问了一下她，和她一起找了找，开了个头，谁知道，一下子找了十五个优点，连她自己都惊讶了，天啦，我这么优秀！\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【技能点要求：\u003c/strong>举一个实际的例子】\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cbr>\u003c/p>","interaction":"\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A\u003c/strong>\u003cstrong>3】\u003c/strong>\u003cstrong>促动参与\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【分组】现场六个小伙伴，左边三个一组，右边三个一组\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>最近有一个心仪已久的大公司招聘，职位与你的职业规划也特别吻合，比如行政部门、技术部门、销售部门、内训部门等的主管职位，你很想投一份简历，苦于找不到自己的优点和强项写在简历中，确保能引起公司HR的注意；大家有没有这种求职的经验啊？有的时候写简历确实很难受，我要写什么呢？我要突出什么呢？\u003c/p>\u003cp>\u003cstrong>【技能点要求1：\u003c/strong>\u003cstrong>给出了一个非常具体、确定场景，学习者可以在此场景中演练或讨论或应用新学技能；\u003cstrong>】\u003c/strong>\u003c/strong>\u003c/p>\u003cp>&nbsp; 利用刚才我讲解过程中的六个提问，小组三人，挑一个人作为准备去求职的人，然后另外两个可能是帮你来找优点的，其中一个帮你提问，而另一个帮你提炼和记录，梳理出每个问题的至少两个答案，提问表格我会发给你们，你们把答案记录在表格里，然后确定一个你心仪的职位，并从中答案中筛选出对这个职位有针对性的优点，整理成一个突出自己特征、能力、价值的参加这次求职的自我简介，最后由那个记录的小伙伴或者自己来分享一下这个简短而有力的自我介绍。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>问题\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>优点\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>你人生中，包括求学、工作、成长、生活中，有哪些特别的经历？\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>你平时投入最多的活动是什么？\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>你收到最多的赞美是什么？\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>你自认为最强的能力是什么？\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>你最擅长使用的工具或软件是什么？\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>与人交流、聊天时，你最有自信或最倾向表达的是什么类型的话题？\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>心仪职位\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>筛选优势\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>自我介绍\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>【技能点要求2：】\u003c/strong>\u003cstrong>使用【A3】技能点的环节指令清晰，学习者可以根据拆书家设定的案例场景，进行小组讨论、应用知识点并能形成一个解决方案，或者应用知识点进行组内角色扮演\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者A的表格记录\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>问题\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>优点\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>你人生中，包括求学、工作、成长、生活中，有哪些特别的经历？\u003c/p>\u003c/td>\u003ctd>\u003cp>为人亲和， 思维沉稳、全面、客观\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>你平时投入最多的活动是什么？\u003c/p>\u003c/td>\u003ctd>\u003cp>喜欢看书，喜欢看球踢球，爱学习，爱运动，有活力，阳光\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>你收到最多的赞美是什么？\u003c/p>\u003c/td>\u003ctd>\u003cp>靠谱，执行力强\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>你自认为最强的能力是什么？\u003c/p>\u003c/td>\u003ctd>\u003cp>做事条理清楚，逻辑性强，学习力强\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>你最擅长使用的工具或软件是什么？\u003c/p>\u003c/td>\u003ctd>\u003cp>WORD,工程类软件\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>与人交流、聊天时，你最有自信或最倾向表达的是什么类型的话题？\u003c/p>\u003c/td>\u003ctd>\u003cp>同学喜欢找我聊人生规划的问题\u003c/p>\u003cp>计划性强，知识渊博，洞察力强\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>心仪职位\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>内训主管\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>筛选优势\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>为人亲和， 思维沉稳、全面、客观，执行力强，逻辑性强，学习力强，计划性强，知识渊博，洞察力强，WORD\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>自我介绍\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我叫郑超林，毕业于华北电力大学，本次应聘内训主管一职，我本身就是个做事情计划性很强的人，每件事情想清楚逻辑顺序，然后条理清晰地去执行到位，并且开放的心态和平时爱好阅读的习惯让我有很强的学习能力，我很多同学都会让我给他们做职业规划上的参考，因为我洞察力比较强，而且为人亲和，所以我个人觉得自己很适合做内训主管一职。\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>\u003c/strong>\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1533601958000,"updated_at":1533603813000,"ria":true},{"id":5070,"topic":"当你感到自己陷入情绪而无法自拔的时候，我们到底该怎么办？","learn_goal":"调节负面情绪","remark":"  每次到周日晚上，就会烦躁不安，因为第二天又要开始工作或学习；每次跟老板说话都很紧张；每次被上级否定的时候感到恼怒；每次上台发言都胆战心惊；每次在公司受了气，回家都忍不住对家人发火……我们常常被这些情绪所困扰。当我们面临这些很焦虑、很迷茫、很紧张、很痛苦等情绪的困扰时，我们要做的不是去压制自己的情绪。情绪背后一定是反映一些问题的，只有正视背后的问题，才能根治情绪所带来的困扰。这样才能让自己真正从情绪中走出来","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"彭飞舞","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"\u003cp>测试\u003cbr>\u003c/p>","ratings_count":0,"texts":[],"created_at":1525250259000,"updated_at":1528773344000},{"id":5011,"topic":"拓展“弱联系”","learn_goal":"四步拓展“弱联系”，快速积累强人脉","remark":"","level":"TF3-1","duration":20,"status":29,"type":0,"chaishujia":{"username":"柯佳","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"大家好，我是安珂，目前从事IT的需求分析，兼内训讲师，同时是一位提升个人拆书能力的未来三级拆书家。\r\n【场景法介绍】\r\n今天给大家拆解的片段来自《请停止无效努力》这本书，它涵盖了“职业规划”、“思维”、“沟通”等自我提升的几个角度，是一本经典的职场进阶指南书。\r\n【事件】\r\n无论是我们跳槽找工作，投资谈合作，谈爱找对象，还是孩子的升学问题，我们都需要获取大量的信息，才能从中筛选并找到合适的信息资源。\r\n【提问】\r\n面对这些需要获取有效信息的场景，大家是怎么做的呢？ \r\n【影响】\r\n恩，有些人会上网搜，网上搜索确实很方便，但是如果我们没有一定的搜索能力，就如大海捞针，而且信息质量不高，碰到假消息就会造成精力金钱的损失。\r\n【解决】\r\n那有没有更真实有效的信息资源途径呢？对，相信有些小伙伴想到了，人脉！我们在获取信息的时候，可以多借助自己的人际关系，《请停止无效努力》这本书用整整一章介绍了沟通交往的思路及方法来帮助大家搭建人际网，今天给大家带来的片段就是如何利用“弱联系”来增加信息渠道，找到有价值的信息资源。","ratings_count":1,"texts":[{"id":8108,"quote":"\u003cp>\u003cstrong>《请停止无效努力》\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>是的，当你谈人生、谈理想、吐槽生活的时候，朋友就够了。\u003c/p>\u003cp>但是，当考虑找人合作、了解信息的时候，“弱联系”其实是最佳选择。\u003c/p>\u003cp>著名社会学家Mark Granovetter，曾经研究了在波士顿近郊居住的职场人士，看他们从什么样的渠道找到工作。\u003c/p>\u003cp>他找了282个人，然后从中随机抽取了100人做面对面访问。他发现，其中通过正式渠道申请的不到一半，而100人中有54人是通过个人关系找到的工作。\u003c/p>\u003cp>并且，让他惊讶的是，这些人利用的个人关系大都是“弱联系”，也就是说，人们靠自己的朋友介绍通常找不到工作，反而是一面之缘的人找到了。\u003c/p>\u003cp>事实上，熟悉的朋友跟你处于同一个圈子，了解的信息往往跟你差不多，有多少事情是你不清楚而只有他们知道的呢？\u003c/p>\u003cp>反而是那些“泛泛之交”，他们的圈子跟你不同，才能够了解到你不清楚的信息。\u003c/p>","explains":"\u003cp>【I拆书家讲解引导】 \u003c/p>\u003cp>【学习目标】【可观察动作/具体内容/完成程度】\u003c/p>\u003cp>希望大家学习完这个片段之后，能够运用“梳理好友-找到高质量弱联系人-每月联系-标签管理”四个步骤来主动拓展自己的“弱联系”，使自己拥有更多的信息资源渠道。\u003c/p>\u003cp>“没有谁是一座孤岛，在大海里独踞。每个人都像一块小小的泥土，连接成整个陆地”，几百年前大洋彼岸的诗人就发出这样的感慨。即便是网络高度发达的现在，我们也需要维系真实世界的人际关系。每个人的精力有限，普通人的人际网中最核心最亲密的可能就十个人左右，根据亲密疏远的程度，再往外层就是我们常说的“泛泛之交”了。\u003c/p>\u003cp>【类似概念】\u003c/p>\u003cp>“泛泛之交”就是很一般很平常，交情不深的人，我们说到“泛泛之交”脑中的印象似乎都是无足轻重，不值一提的人。\u003c/p>\u003cp>【类似概念的例子】\u003c/p>\u003cp>比方我们要做一项重大的决策如选工作、找对象，我们更有可能找到自己最要好最亲密的人请他们帮忙和支持，不大可能想到“泛泛之交”请求他们的建议和意见，因为交往的少，所以并没有引起我们的关注。\u003c/p>\u003cp>【概念提出】\u003c/p>\u003cp>但是，这本书的这个片段提到，根据社会学家调查研究，最有价值的信息和资源并非来源于你经常保持联系的那个圈子。整天跟你混在一起的这帮人，很可能干的事和你差不多，想法也很接近。如果想获得更多有价值的信息资源，那些联系并不多的“弱联系”的人才更有可能提供。\u003c/p>\u003cp>【概念讲解】\u003c/p>\u003cp>什么是“弱联系”呢，从字面上理解，弱联系就是联系的比较少的人，无论见面还是线上联系一年可能都只有几次。\u003c/p>\u003cp>【概念难点】\u003c/p>\u003cp>“弱联系”和前面讲的“泛泛之交”还是有区别的，“弱联系”包含的范围更广\u003c/p>\u003cp>联系的少有多种情况，最常见的有两种，一种是情感上的距离造成的，因为认识不久，只见过一两次面，你和他的交情不深，这是“泛泛之交”；还那有一种是因为空间距离造成的，我们那些多年不见的老朋友，因为联系的少而成为“弱联系”，但是我们的感情还在。\u003c/p>\u003cp>用一张图帮助大家理解：\u003c/p>\u003cp>所以弱联系的判断依据不是交情深浅，而是联系的频次。联系的越少，信息相同的可能性就越小。\u003c/p>\u003cp>那“弱联系”为什么能发挥关键作用呢？\u003c/p>\u003cp>第一个原因是差异化。同一个圈子里的人拥有很多相同的属性以及信息资源，当我们想拓展信息时，圈外的人自带不同的行业、领域或者学科背景，也就是带来差异化信息；\u003c/p>\u003cp>第二个原因就是基于概率。由于精力的分配，我们每个人拥有弱联系人的数量会比强联系人的数量多很多，古典老师曾经说过，“不要说你没人脉，每个人都有20万个你能找到的人。”其实表达的就是“弱联系的这个群体有着更多的可能性”。\u003c/p>\u003cp>【举出案例】\u003c/p>\u003cp>举个我自己运用“弱联系”高效获取资源的例子，家里的小朋友要生日了，我就想帮他办一场有意思的生日趴。平时也会上网找亲子论坛之类的，但一方面没有找到特别心动的，另一方面也考虑到信息是否可靠。\u003c/p>\u003cp>有一次因为手机日历提醒，发觉是一位前同事的生日，于是就用微信跟她发消息表示祝福，她就把我加进了自己的一个分享群里。原来她特别爱参加一些文艺类的文娱活动，因此了解的讯息比较多，也会经常分享到自己建的这个群中。后来也很巧地通过她分享的一条信息找到了合适的举行生日趴的场所。\u003c/p>\u003cp>这个例子就说明了，互联网时代，“弱联系”相比熟人圈有更强的实用性，更有可能提供有价值的资源信息。\u003c/p>\u003cp>【概念步骤 how】\u003c/p>\u003cp>既然弱联系不容忽视，那我们如何主动拓展自己的弱联系呢？具体可以有这么几个步骤：\u003c/p>\u003cp>首先定期梳理微信好友。可以是一个季度或者半年，在自己的微信好友当中，梳理出那些很少或者几乎没有联系的，可以是“泛泛之交”，也可以是好久没有联系的老朋友，单独为“弱联系”一类。\u003c/p>\u003cp>第二步， 找出高质量“弱联系”人。具体有两个标准，一是和你的重合度比较低，背景身份差异比较大的，二是你感兴趣或者价值观相投的，不是说和你没交集的人都要联系，而是筛选出兴趣相投的。\u003c/p>\u003cp>第三步，每个月至少和3个高质量“弱联系”人联系。可以是和许久不见的老朋友电话聊聊近况，也可以是一同参加“弱联系”人经常参与的活动进行深度链接……方法很多，大家可以根据自己情况进行。\u003c/p>\u003cp>第四步，标签化管理。和“弱联系”人联系之后，我们了解了一些基本情况，就可以根据我们掌握到的信息打标签。可以用微信通讯录里自带的标签进行管理，手帐爱好者也可以记录在自己的本子上。比如，一些人有场地资源，一些人能提供培训教育资源等等。\u003c/p>\u003cp>【预防异议 + 讲解】 \u003c/p>\u003cp>可能有些小伙伴有疑问啊，这么麻烦，如果我要谁帮忙或者问信息，到时直接讲就可以了啊！换位思考，一位你许久没联系的老同学突然问你事情，是不是很突兀，你会很热情去提供信息资源吗？另外，你不主动联系别人，你怎么知道人家有什么资源啊，要知道有一类人是不发朋友圈的。平时多积累，人脉维护成本不高还能收获意想不到的效果。\u003c/p>\u003cp>还有些小伙伴觉得，人生得一知己足矣，我不需要那么多的人际关系。是的，当你谈人生理想的时候，朋友能够给我们情感上的需求，有朋友就够了。但是，当考虑找人合作，了解信息时，弱联系是更好的选择，能够打通我们的信息渠道。\u003c/p>\u003cp>【适用边界】 \u003c/p>\u003cp>值得注意，任何知识都有它的使用条件。我们了解了“弱联系”的意义，可以通过它拓展我们的人际网，但人的精力有限，不要因为拓展弱联系而忽略了自己的好朋友。\u003c/p>\u003cp>第二，弱联系并不是固定不变的，在弱联系的人当中，遇到特别欣赏、相投的人，也可以成为真诚以待、互相帮助的朋友，并不是只有需要信息资源的时候才想到他。\u003c/p>\u003cp>最后很关键的一点，不要过度依赖人际关系，任何时候投资自己都比投资别人更重要，当你提升自己的能力，变得优秀的时候，你会发现那些资源、优秀的人会自动向你靠拢。\u003c/p>\u003cp>今天讲到了“弱联系”这个概念，以及如何主动拓展弱联系的四个步骤，一起回顾一下：\u003c/p>\u003cp>第一，梳理微信好友，列出弱联系人。\u003c/p>\u003cp>第二，找到兴趣相投、背景身份相异的高质量弱联系人。\u003c/p>\u003cp>第三，每个月和3位高质量弱联系人联系。\u003c/p>\u003cp>第四，标签管理。他有什么资源和信息是以后可以用上的。\u003c/p>","interaction":"\u003cp>好，接下来的时间交给各位。请大家设想一下，未来一周你有什么场景可能需要联系你的“弱联系”人，同时我们今天讲到了关于拓展“弱联系”的四步，你会如何具体运用来管理你的“弱联系”人。\u003c/p>\u003cp>来，编一个好玩的故事，几百字的小故事，设计出人物、情节（包括：起因、经过、结果）和当时的对话、动作等，并且小故事要能体现今天讲到的拓展“弱联系”四步法。比如，你的一位朋友看你朋友圈晒各种和大牛的照片、参加活动的信息，于是向你请教，自己怎么也能认识很厉害的人，你给他支招等等……还有很多场景，大家可以发挥自己的想象力！\u003c/p>\u003cp>给到大家5分钟的时间写在自己的便签纸上，之后请一位小伙伴进行分享！\u003c/p>\u003cp>【伙伴展示 】 \u003c/p>\u003cp>\u003cstrong>故事背景：\u003c/strong> 小王在销售会上分享，自己如何通过帮助客户生病的父亲联系到医院资源而被客户感谢，签到大单。\u003c/p>\u003cp>\u003cstrong>人物角色： \u003c/strong>小王和新业务员小李\u003c/p>\u003cp>\u003cstrong>故事内容： \u003c/strong>小李听到小王的故事后，很受启发，决定请教小王如何拓展自己的“人脉”\u003c/p>\u003cp>对话设计 ： \u003c/p>\u003cp>小李：王总，你刚才讲的故事我很有启发，我觉得很重要的一点就是你的人脉广，因此帮助到了客户，客户自然愿意帮你完成业务。你在经营人脉上有什么自己独特的方法吗？你看我的业绩这么惨淡，想跟你多学学！\u003c/p>\u003cp>小王：其实每个人手里都有人脉，关键看你怎么使用，怎么管理。\u003c/p>\u003cp>小李：真的吗？那怎么管理？\u003c/p>\u003cp>小王：你把你微信给我看看……你看你的微信好友里有上千号人，这就是一个搭建人脉的很好渠道啊！\u003c/p>\u003cp>你把你微信好友里不常联系的标记出来，然后再从里面选出你觉得有价值的“好友”，比如他有教育资源、医疗资源等等，之后给自己定个任务，每个月最少联系3个这样的不常联系、有价值的弱联系人，可以是打电话、简单聊一聊，或者记得别人的喜好，送个小礼物等等，最后啊，你要把这些人可用的资源进行一个整理和标记，以备将来需要的时候可以找到。\u003c/p>\u003cp>我那个客户需要的医院资源就是我通过这种方式，在我的本子里找到的。而那位朋友我偶尔也会和他联系，所以他在关键时刻能够帮我找到合适的医院和医生。\u003c/p>\u003cp>故事的结果： \u003c/p>\u003cp>小李：原来自己的人脉就在身边，自己居然没有发现，我赶紧试试这个方法！\u003c/p>\u003cp>【 给出反馈 】 \u003c/p>\u003cp>拆书家：特别生动形象，这两位小伙伴真是活学活用啊！掌声送给他们！\u003c/p>\u003cp>【 结语 】 \u003c/p>\u003cp>非常感谢大家热情的参与。通过短短二十分钟的学习和互动，我们把原文片段的这个概念运用起来了，今天第一次来听我拆书的小伙伴，我们相当于已经建立起了“弱联系”。希望以后有幸和各位成为强联系的朋友！谢谢各位！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1523942256000,"updated_at":1523942256000,"ria":true},{"id":4695,"topic":"临场发言没有思路，怎么破？","learn_goal":"临场发言没有思路，怎么破？","remark":"在我们的工作生活中，经常遇到需要做临场发言的情况，比如在开会的时候，当领导询问你对某个问题的看法或者建议时，你是否经历过大脑一片空白、思维短路或者是头脑中有N多个想法，却不知道从何说起这样的时刻？其实做好临场发言也是有套路可循的，只要掌握了结构化的表达方法，就可以让自己的临场发言逻辑清晰有条理，瞬间提升自己的职场专业度。\r\n本期活动，请跟着拆书家管凤华一起来拆解《请停止无效努力》，通过培养自己的结构化思维，做好临场发言，发现自己在职场上的更多可能。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"管凤华","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"大家好，我是今晚的拆书家管凤华。我的三个特色标签是：热爱学习；热爱分享；项目管理领域资深人士。很高兴今天有机会来这里与大家一起拆书学习。\r\n（学习目标的设定）今天的拆书主题是如何做好临场发言，各位小伙伴在跟随我完成本次现场学习后，能够运用结构化的表达方式，让自己的临场发言变得逻辑清晰有条理。\r\n（FAB法介绍图书）F：拆解片段选自《请停止无效努力》这本书，作者孙圈圈，曾任全球顶级咨询公司的咨询总监，现在创业中。这本书的定位是个人努力的方法论。\r\nA：本书是个人成长类书籍中非常畅销的一本，豆瓣上的评分高达8.7分。作者利用其做过咨询顾问的职业优势，从企业、管理者、咨询师和职场人四种视角，全方位向读者提供了一整套个人成长的底层方法论。\r\nB：所以，各位在座的小伙伴们，如果你当前正处于每天很努力，进步却很慢或者道理懂很多，依然过不好这一生的状态，那么强烈建议你来读读这本书，它会告诉你正确的努力方式，从而加速升级自己的心智和能力。","ratings_count":1,"texts":[{"id":7741,"quote":"\u003cp>【主题】如何做好临场发言\u003c/p>\u003cp>【图书】请停止无效努力——如何用正确的方法快速进阶\u003c/p>\u003cp>【章节】第4章 提升沟通能力\u003c/p>\u003cp>【页码】P119\u003c/p>\u003cp>R：\u003c/p>\u003cp>&nbsp; &nbsp; 临场发言时，我们是有压力的。这种压力，要不让我们的大脑一片空白、胡言乱语，要不让我们的大脑信息泛滥、毫无头绪。这两种情况，听众听起来都会比较痛苦，不明白你到底想表达的是什么。\u003c/p>\u003cp>&nbsp; &nbsp; 如果说，有一个清晰的结构，发言就变得容易了。一方面，如果你的大脑是杂乱无章的状态，它可以帮你把信息快速整理并输出；另一方面，如果你的大脑是一片空白的状态，它可以作为提示语帮你联想起一些有用信息。\u003c/p>\u003cp>&nbsp; &nbsp; 用结构化思维，帮助你在短时间内更好地沟通，关键是三个步骤：\u003c/p>\u003cp>&nbsp; &nbsp; 第一步，想主题：迅速找到一个切入点，第一句就说出自己的观点。\u003c/p>\u003cp>&nbsp; &nbsp; 第二步，搭架子：在论证观点时，思考一个结构（时间、空间、程度），并只说三点，这称为三个“架子”。\u003c/p>\u003cp>&nbsp; &nbsp; 第三步，填素材：每个架子里，填充一些事例、数据等，来推进论据向观点靠近。\u003c/p>","explains":"\u003cp>\u003cstrong>（负面一般做法）\u003c/strong>我们在工作和生活中，经常遇到需要做临场发言的情况，一个常见的场景就是在公司开集体会议时，领导询问你对某个问题的看法或解决建议，这时我们就面临着做临场发言的压力，在这种压力下，大脑一般会产生两种常见反应：要么一片空白，一句话都说不出来；要么信息泛滥，有N多个想法在头脑中打架，不知道从何说起。\u003c/p>\u003cp>\u003cstrong>（坏处）\u003c/strong>这两种情况都会导致我们无法清晰的表达自己的观点，给领导和同事留下思维混乱的不好印象。如果被贴上了思维不清晰的标签，这对我们的职场发展无疑是个很大的障碍。反过来说，如果我们的临场发言能够做到逻辑清晰，条理分明，那又是怎样的情景呢？想必领导和同事都会在心里为你点赞，认为你是一个头脑清楚，有认知深度的人，这种好印象绝对会助力你的职场发展。\u003c/p>\u003cp>\u003cstrong>（拆页提供的解决建议）\u003c/strong>想必小伙伴们现在一定很想知道该如何培养这种思路清晰的临场发言能力呢？拆页内容向我们介绍了一个结构化的表达模型，包括三个步骤：\u003c/p>\u003cp>第一步，想主题，主题就是针对要讨论的问题，你的观点，你的看法，你的态度，打个比方的话，主题就相当于议论文中的论点。\u003c/p>\u003cp>第二步，搭架子，所谓架子是指我们在表达时，用于把信息分组归类的结构关键词，常用的架子有三种类型，时间架、空间架和三角架。时间架是按照时间的顺序，整理头脑中的信息，比如你是负责培训工作的，那么在向别人介绍你的岗位职责时，你可以按照培训前、培训中和培训后来表达，除了这些代表时间的词，有先后关系的代表阶段、代表步骤的词都算。空间架是按照地点的顺序分类信息，用空间架的好处是听众有画面感，常用的空间架包括：北京、上海、广州；美洲、欧洲、亚洲等。三角架是按照三个方面总结信息，常用的三角架包括：亲情、友情、爱情；语法、修辞、逻辑等。\u003c/p>\u003cp>第三步，填素材，素材指的是用于支撑主题或观点的数据、事实和故事。\u003c/p>\u003cp>\u003cstrong>（反例变正例）\u003c/strong>回到开头提到的会议临场发言场景，该如何应用“想主题—搭架子—填素材”的结构化表达模型，进行逻辑清晰的现场发言呢？假如会议讨论的内容是：为了加快项目进度，领导计划在部门内推行强制加班制度，询问你的看法。你可以使用三角架进行如下表述：我不赞成推行强制加班制度，有如下三方面的原因：从公司角度看，强制加班会造成公司成本急剧增加；从领导角度看，强制加班会将部门领导的关注点引导到加班时间长短，而非价值贡献大小；从员工个人角度，强制加班会引起员工不满情绪，从而降低工作效率。\u003cbr>\u003c/p>","interaction":"\u003cp>【A1】激活经验+【A1+】反思加工\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（A1显像提问，包含具体场景）：\u003c/strong>\u003c/p>\u003cp>以上就是我对拆页内容的解读，接下来进入演练环节，我先说两个场景，小伙伴们感受一下是不是有似曾相识的感觉？场景一：假设在十一假期，你刚刚看了一部大热的电影《羞羞的铁拳》，好朋友问你，“怎么样啊，好看么？”你回答说“恩，挺好看的，你也去看看吧”，这个回答如何？是不是有点过于干巴巴了？如果能用几个架子支撑一下你的观点的话，会不会更有说服力？场景二：假设你刚刚参加完某个培训学习，好朋友向你询问“感觉怎么样，收获大不大？”，你内心很认可这个课程，于是你的回答可能就是这样的“嗯，课程非常好，特别棒，老师讲课可幽默了一点都不枯燥，关键人长的太帅了，简直就是我心中的男神，我还认识了一个志趣相投的小伙伴互加了微信，课程内容对我的工作特别有启发意义，对了，现场还给每个学习者准备了零食和饮料，组织者真是太用心了，总之这个课程真的非常好，下次你也去参加吧”，这个回答如何？信息量倒是很大，但是有点凌乱，如果能用几个架子将信息进行分组归类，听起来会清晰很多。\u003c/p>\u003cp>各位在座的小伙伴们，你们最近有做过类似的比较失败的临场发言么？如果有的话，是在什么时候什么情景下做的？\u003cstrong>(A1+指令)\u003c/strong>如果发言效果不好的话，想想看，根据今天学到的结构化表达模型，你可以怎样重新组织自己的语言让发言变得更有条理呢？\u003c/p>\u003cp>请想一想，想好后在小组内轮流分享一下。\u003c/p>\u003cp>\u003cstrong>学习者案例记录\u003c/strong>：\u003c/p>\u003cp>\u003cstrong>（A1）\u003c/strong>我是做人力资源的，负责公司培训工作的组织。困扰我的问题是，在培训正式开始前的介绍环节，不知道说什么，每次都是简单的一句“有请老师”作为开场，感觉干巴巴的。\u003c/p>\u003cp>\u003cstrong>（A1+）\u003c/strong>小组讨论的时候，同组小伙伴建议我使用三角架充实自己的开场介绍，分别从导语（比如今天天气不错，感谢大家百忙之中抽出时间参加今天的培训）、老师简介（比如今天请到的XX老师是XX领域的专家，有超过10年的工作经验）和培训内容简介三方面作为开场，经过这样的修改，我感觉开场内容充实清晰了很多，回到公司要尝试一下。\u003c/p>\u003cp>\u003cstrong>小结：\u003c/strong>\u003c/p>\u003cp>最后我们再来小结一下今天的学习内容：要想做好临场发言，我们可以借助一个结构化的表达模型，这个模型包括三个步骤，分别是：想主题、搭架子和填素材，主题是我们要表达的观点，架子是把信息归类的结构关键词，常用的架子有时间架、空间架和三角架，素材是支撑主题的数据、事实和故事。推荐2个积累架子的途径，一是到网站上搜索“36氪 思维模型”关键词，会有将近上百种的思维框架；二是日常读书时可以有意识的积累，比如马斯洛的五层次需求理论就是一个很好的分析问题的框架。\u003c/p>\u003cp>关于结构化表达模型的适用范围，其实不只适用于临场发言，任何需要沟通的场合都可以使用，包括写作和解决问题。\u003c/p>\u003cp>依照作者的观点，结构化思维是最值得刻意练习的能力，祝愿各位小伙伴都能习得这项价值度极高的能力。谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1519523596000,"updated_at":1523276188000,"ria":true},{"id":4479,"topic":"开拓自己的人脉圈","learn_goal":"开拓朋友圈，通过朋友圈来解决问题。","remark":"《请停止无效努力》这本书就是一本解决问题的工具书，作者不和你讲一堆道理，而是直接上方法，全是干货；","level":"TF3-3","duration":60,"status":29,"type":0,"chaishujia":{"username":"Tangcoco","city":"杭州"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"事件：目前的工作不是很理想，想换一份工作，和自己的闺蜜/好兄弟诉苦，这家伙也够意思，陪着你聊天、喝酒、骂老板，然后来个：“兄弟，打工不容易忍忍吧！”或者“兄弟，你那么有才华忍个X，再找份工作呗”，然后就没有然后了……\r\n提问：一般遇到这样情况大家会怎么处理？和兄弟/闺蜜抱头痛哭，觉得有他/她在身边让自己的心灵和情绪有个港湾？还是想，话虽然一吐为快，但是什么问题还没有解决，以后还是不要花太多时间、抱什么希望在他/她身上了。\r\n影响：无论用上述什么方法处理，都是非常可怕的，要么你会发现暂时情绪的舒缓对事情的解决没有任何帮助，要么身边没有了让自己放松、舒服、快乐的朋友。\r\n解决：所以今天两个关于弱联系理解和建设的片段让你正确认识“强联系”“弱联系”这两种联系给自己人际关系带来的不同的价值和意义，并且学会如何用差异化定位建设自己的“弱联系”!\r\n这两个片段来自于《请停止无效努力》这本书，这本书提供了很多类似解决一个个问题的有效方法，比如结构化表达、沟通等，提升自己职场竞争力的工具和方法。","ratings_count":1,"texts":[{"id":7492,"quote":"\u003cp>根据牛津大学人类学家罗宾邓巴(Robin Dunhar)的研究，每个人的社交网络中、最核心的圈子有3-5人，最为亲密。然后是12-15人，失去他们会给你带来重创。继而是30-40人，这是你经常保持联系的一群。然后是150人，而这150人是人类智力允许其拥有的稳定网络的人数上限(也被称为邓巴数字)。\u003c/p>\u003cp>社交产品Path，规定好友上限人数不超过150，就是基于这个理论。\u003c/p>\u003cp>至于150人以外的人际网络，你会认识这些人，但并不会那么在意他们，你们的交集一般也很少。\u003c/p>\u003cp>而根据斯坦福大学教授马克·格兰诺维特(Mark Granovetter)的研究，人际关系根据心理距离的远近，又分为强联系和弱联系。\u003c/p>\u003cp>强联系是指，你们处于同一个圈子，比如一起工作、一起居住、一起娱乐，你们的相处时间较长，通常想法也倾向于相似。\u003c/p>\u003cp>而所谓弱联系，就是指你圈子以外的人，你认识、但不那么关心，可能是朋友的朋友，或者刚认识不久的人，你们的想法常常不同。弱联系通常建立在价值交换的基础上。这里的价值指的是广义的价值，不仅仅是指经济价值。\u003c/p>\u003cp>我举个找工作的例子，来说一下两者的区别：\u003c/p>\u003cp>比如，你要找工作，但没有太多面试经验，强联系人，也就是你的好友，可以特地抽出时间来帮你准备面试，而这是弱联系的人不会、也没有必要帮你去做的事情。\u003c/p>\u003cp>但弱联系人的价值也很高，比如，他/她所在的公司正在招聘，而你恰好在找这样的工作，也是一个符合要求的候选人，帮你做一下内部推荐是举手之劳的事情，双方获益、双方开心。 \u003c/p>\u003cp>再比如：一个强联系人，每天发点无病呻吟、没有价值的朋友圈，你不会就此跟对方断绝关系，说不定还会关心一下他的现状：是不是碰到什么挫折了。而一个弱联系人，要是这么做，你可能就果断取关了。\u003c/p>\u003cp>明确这样的区别之后，我可以说明一下：这里讨论的是弱联系，而非如何维持好友关系。\u003c/p>\u003cp>可能你会认为：人生得一知己足矣，我不需要那么大的人际网络啊。\u003c/p>\u003cp>是的，当你谈人生、谈理想、吐槽生活的时候，朋友就够了。\u003c/p>\u003cp>但是，当考虑找人合作、了解信息的时候，“弱联系”其实是最佳选择。\u003c/p>","explains":"\u003cp>【学习目标】\u003c/p>\u003cp>学完后，学习者在遇到通过关系来解决一个问题的时候，能够判断使用自己朋友圈的哪种联系!\u003c/p>\u003cp>【I-&nbsp;通过对比概念和匹配例子引出知识点逻辑、步骤和边界】\u003c/p>\u003cp>在这个拆页，我们看过了“弱联系”的定义和重要性。\u003c/p>\u003cp>同事关系、亲戚关系哪个是我们的弱联系呢？\u003c/p>\u003cp>同事关系、亲戚关系看具体情况，如果彼此能联系上但是交往不多、圈子不同、思维方式也不是很接近，那么他们就是弱联系了；\u003c/p>\u003cp>举例：就算是你的亲哥哥，你们不生活在一起、教育背景不同、联系的也不多\u003cem>{此处加个包袱：我也不知道为什么会这样！结果全场哄笑}\u003c/em>，那么他也算你弱联系；如果是你远方亲戚，你们在一个生活、一起创业，那么他其实就不算是弱联系；他们之间的关键差异是亲密程度和圈子、思维的差异。\u003c/p>\u003cp>当然，弱联系可以随着接触的不断频繁，思维方式的不断的融合，会慢慢转化为强联系；比如，原本不熟悉的人，因为加入一个团队工作，经常一起奋斗，后来慢慢成了强联系。而强联系也会因为联系的减少，各自环境的变化转为弱联系。比如高中的同学，读书阶段非常要好，毕业后各自不同的发展和环境，慢慢的变成了弱联系。\u003c/p>\u003cp>&nbsp;【I-给出清晰的HOW】\u003c/p>\u003cp>遇到问题如何判断运用自己的哪种关系？\u003c/p>\u003cp>第一步，明确某个情景中我遇到了什么问题？（明确场景）\u003c/p>\u003cp>比如，在生完娃之后我是继续工作还是在家带孩子这件事和老公吵架；\u003c/p>\u003cp>第二步，解决这个问题的标准是什么？（理清要达到的目标）\u003c/p>\u003cp>是有人听我倾诉，吐槽下那个男人，我完成自己不良情绪发泄，还是帮助自己完成产后重归职场的规划；\u003c/p>\u003cp>第三步，梳理自己能够联系到，可能对这个问题有帮助的人，列出清单；（一般倾述类目标可以找强联系的朋友，一般解决类的目标可以找“弱联系”）（思考不同的运用，进一步清晰两种关系的作用）\u003c/p>\u003cp>比如吐槽老公，我找我妈就行，如果是完成产后重归职场的规划，我就要寻找我工作同类型的职场妈妈、有职场回归经验的生涯规划师等；\u003c/p>\u003cp>&nbsp;【I-环节的互动，且拆书家能精准掌控】\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;这些步骤中，大家觉得最困难的是哪步？\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; {学习者分享：第二步；第三步；}\u003c/p>\u003cp>大家说得都有道理，我觉得最不容易的是第二步，通俗的讲就是理清目标，清楚自己解决这个问题的标准是什么，明确目标找答案就容易很多，对不对？ &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>我理解讲第三步的同学，意思并不是“列出能帮我解决问题的人”而是“列出能帮我解决更多问题的人”，对不对？ &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>&nbsp;{学习者回答：对的；}&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","interaction":"\u003cp>【A2】（1.设计有人物角色、有起因经过结果、有对话的故事；2.学习者可以根据指令，写出一个未来具体要做的应用）\u003c/p>\u003cp>1、[故事设计]请大家自己编写一段小故事，二三百字左右即可，设计出任务、情节变化（包括起因、经过、结果）和当时双方的对话、动作等，故事要包括我们HOW中的前3步：某个情景中我遇到的问题、解决的标准、梳理可以解决这个问题的人，请大家把故事概要写在便签上，时间5分钟，5分钟后我们请小伙伴来分享下剧本。\u003c/p>\u003cp>{学习者分享：}\u003c/p>\u003cp>[起因]我是护士，不过很不喜欢这份工作，自己工作和生活就是完全的分裂，一直想换工作，不过父母和男友都认为我现在工作很好，不同意，我真的很困扰......\u003c/p>\u003cp>[经过]我想要解决这个问题的标准是，能够明确自己是否真的应该换工作，我除了做护士没有做过其他的事情，是否能够找到合适的工作；\u003c/p>\u003cp>我对我的人际关系做了分类：\u003c/p>\u003cp>第一类是非常熟悉我个性的强联系，比如：现在的同事、我的师傅让她们评估我工作表现及与工作的适应程度；\u003c/p>\u003cp>第二类也是强联系，和我有过工作接触，但是不是在我现在医护圈子里的人，请她们客观评估我的能力；\u003c/p>\u003cp>第三类是弱联系，找一些自己感兴趣的岗位去面试，从和对方人力资源的沟通面试中评估自己的位置。\u003c/p>\u003cp>[结果]\u003c/p>\u003cp>我在第一类关系中，能够客观了解我在目前工作的工作表现；\u003c/p>\u003cp>（我：A；我师父：B）\u003c/p>\u003cp>A：师父，你觉得我在工作中表现怎么样？\u003c/p>\u003cp>B：我觉得你不是很适合这份工作，大大咧咧的，粗线条，经常丢三落四，让人很不放心！\u003c/p>\u003cp>（我：A；我一起工作同事：B）\u003c/p>\u003cp>A：亲，你对我的工作表现怎么看？\u003c/p>\u003cp>B：我觉得你工作和生活完全是两个人，性格完全不一样，生活中很快乐，是个开心果，工作中感觉很压抑。\u003c/p>\u003cp>我在第二类关系中了解我自己未被发现的潜力；\u003c/p>\u003cp>（我：A；原来做过2个月兼职的老板：B）\u003c/p>\u003cp>A：X总，不知道你对我是怎么评价的？\u003c/p>\u003cp>B：小X，你非常乐观、开朗、活跃，思维跳跃，很适合与人打交道，如果做市场或销售类的工作，很有潜力啊。\u003c/p>\u003cp>我在第三类关系中，在市场上去销售自己，以评估市场价格。\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;明确“强联系”和“弱联系”带给我们的区别，明确我们要实现的目标，减少对“强联系”和“弱联系”的不合理期待，以让我们获得更加快速的进阶。\u003c/p>\u003cp>在这个片段中我们学会了遇到问题，如何运用现有的联系去解决问题，相对是被动使用；那么在下一片段中，我们讲用一种更主动的姿态去经营自己的关系，就是通过如何运用在弱联系中的差异化定位，以建立自己的高效人脉圈。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":7493,"quote":"\u003cp>有时候，即便你进入了一个社交网络，但是觉得自己没有存在感，没人在意你，你想认识的人、想了解的信息都没有获得。\u003c/p>\u003cp>如何刷存在感，实在是个深奥的问题。所以很多人去伪装自己，展现自己并不具备的那一面，极力讨好他人。其实，完全没有必要。\u003c/p>\u003cp>事实上，每个人的性格不同、优势不同，其在人际网络当中的角色也是不同的。\u003c/p>\u003cp>一般而言，人际网络中会有四种角色：\u003cstrong>节点\u003c/strong>、\u003cstrong>专家\u003c/strong>、\u003cstrong>明星\u003c/strong>、\u003cstrong>助理\u003c/strong>。\u003c/p>\u003cp>\u003cstrong>节点\u003c/strong>是把大家连接在一起的人，这个前面有讲过。\u003c/p>\u003cp>特别是在一个弱联系的社交圈子，不可能任意两个人都是很好的朋友，所以，一定是有一个或者一些人扮演节点的角色，把大家连接在一起。\u003c/p>\u003cp>适合做节点的人，通常具备这样的特征：可能是该人际网络的发起人，也有可能是人脉广的人。他们很善于跟大家打成一片，并且善于发现别人的优点，欣赏每一个人。\u003c/p>\u003cp>\u003cstrong>专家\u003c/strong>是掌握信息、知识甚至资源的人。\u003c/p>\u003cp>一个圈子当中，不可能每个人都有贡献，这个圈子80%的价值是由那20%的专家贡献的。典型的例子像知乎，大部分用户从未回答过问题，而有赞同有关注的用户连10%都不到。适合做专家的人，通常具备这样的特征：知识渊博，比常人阅读的新闻和书刊要多很多，\u003c/p>\u003cp>你想要了解的信息总能够从他那里听到。并且，他总能给你很多有用的建议，常常给你指点迷津。他们本身具有特定的社会资源和优势。\u003c/p>\u003cp>\u003cstrong>明星\u003c/strong>是那些善于说服的人，他们未必有很强的专业知识，但是他们很有人格魅力。\u003c/p>\u003cp>有时候，专家说出的观点，可能别人未必完全认可，但是经过明星的诠释，会获得极高的认同度。\u003c/p>\u003cp>适合做明星的人，通常具备这样的特征：善于把自己的观点以及自己推销出去，让别人信服。这是我们通常所说的那类有人格魅力的人。他们身上有种难以言说的特质，一种强大的、有感染力的、不可抗拒的东西，超越了语言的力量，能够让见到他们的人愿意相信和赞成他/她的观点。\u003c/p>\u003cp>\u003cstrong>助理\u003c/strong>是在圈子里面提供服务的人。\u003c/p>\u003cp>他们热心肠、乐于助人，未必有专业的知识、很高的人格魅力以及连接大家的社交能力，但是他们任劳任怨地提供服务。\u003c/p>\u003cp>这个角色不一定在所有社交网络都有，尤其是高端社交网络。\u003c/p>\u003cp>比如，企业家协会通常会由发起人的秘书来做很多服务性工作，而这个秘书，其实并不属于这个网络的一员，因为他/她的价值对于别人来说太可替代了。\u003c/p>\u003cp>适合做助理的人，通常具备这样的特征：热心肠、做事有条理、不计回报。\u003c/p>\u003cp>这四种角色，并非完全割裂的。\u003c/p>\u003cp>比如，你既是节点又是专家，自然在这个网络中的价值会更大。\u003c/p>","explains":"\u003cp>【学习目标】\u003c/p>\u003cp>学完后，学习者能够根据自己进入一个社群的目标，根据自己的优劣势清晰的界定自己在社群中的角色。\u003c/p>\u003cp>【对比概念与案例】\u003c/p>\u003cp>1、&nbsp;对比概念：\u003c/p>\u003cp>节点：把一群人连接起来的人；\u003c/p>\u003cp>专家：掌握重要的信息、知识、资源的人；\u003c/p>\u003cp>明星：善于说服影响他人的人；\u003c/p>\u003cp>助理：在圈子里提供服务的人；\u003c/p>\u003cp>比如在我们拆书帮，专家远的说是我们的赵周老师，近的说是我们各分舵自己的三级拆书家，比如小丫、李夏、菲尼、娜娜；节点在我们光明顶就是酱酱、倩倩老师为我们组织很多活动的人；明星就是分舵舵主这样影响大家的人，当然也包括我们的一些三级拆书家；助理我认为就是类似像小雯这样一直为大家默默付出的人，我要特别强调的是，像助理这样的角色是非常重要的，比如我进入拆书帮，小雯是我除了师父之外最早成为朋友的让人。\u003c/p>\u003cp>2、举例：（下面案例是可讲，可不讲的，如果不合适完全可以去掉）\u003c/p>\u003cp>举例一（反面案例）：\u003c/p>\u003cp>我之前在狮子会、学友会之类的组织，虽然角色是队长、分会长之类的头衔，但是只是出席活动并没有清晰明白优势，确定角色，导致的后果是在组织中的影响力并不足，并没有产生我期望中的结果。\u003c/p>\u003cp>举例一（正面案例）：\u003c/p>\u003cp>我们另外一个公司合伙人，参加的组织活动很有限，但是在每个团体中有限的时间都能产生很大的效益。回看他成功的原因是，首先他知道自己的优势，他的知识渊博、阅读量大、善于说服他人，但是能够投入的时间有限，所以他在团队中给自己的定位是专家角色+明星角色，每次出现都发挥推动作用。\u003c/p>\u003cp>【分享提问&amp;回应式反馈】\u003c/p>\u003cp>我们有没有小伙伴可以举一个你身边的社群或者朋友圈，你能感受和区分这几个角色的，可以和我们分享下？\u003c/p>\u003cp>{学习者现场分享}\u003c/p>\u003cp>学习者一：\u003c/p>\u003cp>就像我们的拆书帮，舵主就是明星，需要说服和推动他人；像酱酱这样就是属于节点人物；\u003c/p>\u003cp>学习者二：\u003c/p>\u003cp>我身边有个朋友是销售总监，同时也是个吃货，她甚至把市面上所有品牌的乳酸菌都买来，从口感、营养、外包装三个维度做对比测试，她在朋友圈中就是奠定了“吃货专家”的地位。\u003c/p>\u003cp>-你的意思是不是专家不一定是要好像“教授”“老师”这类的学术专家，只要在某一个领域有自己的理解和资源都可以，我的理解对吗？对的！ &nbsp;\u003c/p>\u003cp>感谢你给我的启发，谢谢。\u003c/p>\u003cp>学习者三：\u003c/p>\u003cp>我们有个“狼人杀”群，我们的群主就是个玩“狼人杀”最菜的人，但是所有人都是他组起来的，他就是个节点；另外有个人，“狼人杀”玩得非常好，能够引导大家，他就是属于专家级的人；还有个人，非常热心，一般活动的通知、准备、物资准备都是由他来做。\u003c/p>","interaction":"\u003cp>【A1】（量表的设计和解释）\u003c/p>\u003cp>先请大家花一分钟做下手上的自测题，并统计下总分，半开就是对半的意思\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>序号\u003c/p>\u003c/td>\u003ctd>\u003cp>题目\u003c/p>\u003c/td>\u003ctd>\u003cp>从不\u003c/p>\u003c/td>\u003ctd>\u003cp>较少\u003c/p>\u003c/td>\u003ctd>\u003cp>对半\u003c/p>\u003c/td>\u003ctd>\u003cp>经常\u003c/p>\u003c/td>\u003ctd>\u003cp>总是\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>我非常清楚自己在一个圈子里想要的东西\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>我非常清楚自己在一个圈子中的定位\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>我在一个圈子里做的事情都是围绕定位展开的\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>这套自测的目的，是看我们是否清晰自己的社交目标和去角色定位的。\u003c/p>\u003cp>如果你在12分以上，那么你真的是个人脉关系整合运用的达人了，如果你在9分以下，那么恭喜你，今天你来对了！\u003c/p>\u003cp>【A3促动参与】\u003c/p>\u003cp>Step1：请每位伙伴结合自己的经历，想象下未来有可能用到今天我们拆页内容的具体问题是什么？每人在一张便利贴上，然后贴在白板上。接下来给每人2个投票权，你选出两个你经常会碰到的集体问题，作为我们今天讨论的主题。\u003c/p>\u003cp>Step2：（分组）请我们X人为一组来讨论出具体的行动步骤；\u003c/p>\u003cp>Step3：大家可以把讨论出的步骤写在A3纸上，等下每组派一位代表来分享；\u003c/p>\u003cp>Step4：请每组带上自己的大白纸上来分享；一位同学分享完，请其他同学畅所欲言，补充；\u003c/p>\u003cp>Step5：整理、合并、优化出新的步骤。\u003c/p>\u003cp>{学习者现场总结出来的HOW}\u003c/p>\u003cp>问题：我们在一个社交圈中要有影响力，运用今天片段学到的差异化角色定位，该如何做？\u003c/p>\u003cp>1、在一个社群/圈子明确自己的目标是什么，要从这里获取什么资源；\u003c/p>\u003cp>2、这个社群/圈子存在的目标或则建立的目标是什么？\u003c/p>\u003cp>3、分析自己的优势和劣势；\u003c/p>\u003cp>4、根据自己的优势和劣势，以及自己要在社群/圈子的目标和圈子本身的目标，明确自己要在这个社群中的角色定位；\u003c/p>\u003cp>5、明确这个角色下，自己需要做的事情。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>1、请在本次学习结束后的一周内，把今天学习的“人际网络中的四种角色”分享给一个自己的好朋友，并且帮助他/她一起运用在HOW中学到的“在一个社交群体中要有影响力”的五个步骤制定一个让自己在社群中有影响力的计划。\u003cbr>\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>弱联系的建立是一个先投入、价值交换的过程，需要我们离开自己的舒适圈，摆正态度去经营，而非一早一夕见成效的事情，同时在建立“弱联系”的过程中，不要放弃维护“强联系”，他们之间是可以相互转化的，也不要过分依赖人际关系，这个是世界上所有的投资，最好的永远是投资自己！祝大家学习了解“弱联系”，成就自己开挂的人生。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":true}}],"created_at":1515934776000,"updated_at":1515998176000,"ria":true},{"id":4437,"topic":"巧用信息结构化，实现高效沟通","learn_goal":"学习者能陈述信息结构化的步骤，并且能够实际运用","remark":"","level":"TF1-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"石美英","city":""},"club":{"name":"厦门鹭岛抚琴分舵","city":"厦门"},"prologue":"大家好！我是美英，美术的美，英语的英，目前主要从事电商行业，是一名电商运营，平时喜欢阅读、瑜伽。很高兴今天下午和大家相聚在这里，祝愿大家度过一个愉快的下午。\r\n 今天我要拆解的这本书是《请停止无效努力》，作者是孙圈圈，她是原美世咨询总监、【领英洞察】专栏作家，同时也是圈外的创始人。这本书的内容主要包括天赋、沟通和思维，书籍一出版就被许多读者称赞为职场经典书籍，此外，这本书得到了盖茨基金会中国区负责人李一诺，前美世咨询全球合伙人张世东等的大力推荐。","ratings_count":1,"texts":[{"id":7448,"quote":"\u003cp>&nbsp;我们今天的学习主题是演讲信息结构化，学习目标是知道信息结构化的三个步骤并能实现运用。\u003c/p>\u003cp>【R】阅读原书拆页\u003cbr>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 如何让你的演讲信息结构化\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;在这本书之前关于结构化思维的文章里，曾经提到过，人类大脑在处理信息时有两个习惯：第一，不能一次太多，因为信息太多会让大脑的负荷过大；第二，喜欢有规律的信息。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;临场发言时，我们是有压力。这种压力，要不让我们的大脑一片空白、胡言乱语，要不让我们的大脑信息泛滥、毫无头绪。这两种情况，听众听起来都会比较痛苦，不明白你到底想表达的是什么。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;如果说，有一个清晰的结构，发言就变得容易了。一方面，如果你的大脑是杂乱无章的状态，它可以帮你把信息快速整理并输出；另一方面，如果你的大脑是一片空白的状态，它可以作为提示语帮你联想起一些有用信息。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; &nbsp; 用结构化思维，帮助你在短时间内更好地沟通，关键是三个步骤。\u003c/p>\u003cp>第一步，想主题：迅速找到一个切入点，第一句就说出自己的观点。\u003c/p>\u003cp>第二步，搭架子：在论证观点时，思考一个结构（时间、空间、程度），并只说三点，这称为三个“架子”.\u003c/p>\u003cp>第三步，填素材：在每个架子里，填充一些事例、数据等，来推进论据向观点靠近。\u003c/p>\u003cp>在这里和大家举个例子，乔布斯推出第一款苹果手机时进行过一段演讲，大意如下：\u003c/p>\u003cp>苹果公司是一家革命性的公司。为什么这么说呢？1984年，推出Mac电脑，改变了整个电脑行业；2001年，推出ipod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；2007年，推出苹果手机，我相信它将改变更多行业。\u003c/p>\u003cp>我们来剖析一下这段话的结构，就会是：\u003c/p>\u003cp>主题：苹果公司是一家革命性的公司。\u003c/p>\u003cp>架子：1984年、2001年、2007年。\u003c/p>\u003cp>素材：推出推出Mac电脑，改变了整个电脑行业；推出ipod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；\u003c/p>","explains":"\u003cp>【I】拆书家讲解引导 \u003c/p>\u003cp>Why：拆书原页中讲到一个信息结构化的问题，先来看下为什么要信息结构化呢?因为人类大脑在处理信息时有两个习惯：一是不能太多，二是喜欢有规律的信息，而信息结构化可以将信息归纳提炼，帮助我们更好地理解和记忆。运用信息结构化可以帮助我们全面而具体的描述一件事情，同时能够让对方别人理解和记住一点关键的东西。\u003c/p>\u003cp>How：那应该怎么做呢？书中讲到信息结构化的三个步骤：第一步想主题、第二步搭架子、第三步填素材。\u003c/p>\u003cp>举个例子，比如说你向别人介绍自己的时候，你希望别人能够全面地了解你，同时又希望别人能够理解并记住你说的一些点，这个时候运用信息结构化便有利于你的介绍。比如当初我在找工作面试的时候，面试官对我说，“请简单介绍一下你自己”“面试官早上好，我叫石美英，来自集美大学航海学院物流管理专业，接下来我将从工作、学习和生活三个方面简单介绍一下我自己。”从信息结构化的角度，第一步想主题，我的主题是确定的，我的大学生活；第二步搭架子，我将我的大学经历分为了三个架子，工作、学习、生活；第三步填素材，我分别从这三块讲了三个故事。既让我的面试官全面了解了我的大学生活，并且也让他记住了我在三大板块的特点：工作中认真负责、学习中勤奋努力、生活中乐于助人。\u003c/p>","interaction":"\u003cp>分组 \u003c/p>\u003cp>通过拆页的学习我们知道了信息结构化和信息结构化的三个步骤，由于接下来讨论的需要，我们先来分下组，两两为一组。\u003c/p>\u003cp>激活学习者经验 \u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>通过这个拆页，我们了解到利用信息结构化可以帮助我们理解和记忆信息，接下来请大家回想下自己之前有没有类似的经历。当你上台演讲的时候或者你要在短时间内向别人介绍或者解说某些东西的时候，有没有类似的经历呢？接下来请大家花3分钟时间在组内分享下自己的经历，之后我们会请一位伙伴来分享一下。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>3分钟时间差不多了，有没有哪位伙伴愿意和我们分享下自己的经历呢，那我们有请晓梅来和我们分享一下。\u003c/p>\u003cp>晓梅：我是一名培训师，搭框架运用的比较多，因为我们经常进行做关于知识点上面的培训。比如之前我和大家介绍拆书帮的时候，那我会先阐述什么是拆书帮，阐述完之后搭建几个对应的框架，同时对每个框架我会再举一个例子来填充。\u003c/p>\u003cp>拆书家： &nbsp;好的，谢谢晓梅的分享。晓梅介绍拆书帮的例子就运用到了信息结构化的三个步骤，第一步确定主题是介绍拆书帮；第二步对介绍拆书帮搭建相应的框架；第三步在每个框架下面去填充相应的素材。\u003c/p>\u003cp>催化应用\u003c/p>\u003cp>那在这里我给大家留个课后作业，如果要在未来1-2周内实际运用信息结构化，提升自己的信息结构化的能力，请问大家会如何做呢？请大家思考一下，在我们分享结束后在便签上写下你的行动计划。\u003c/p>\u003cp>总结\u003c/p>\u003cp>通过今天的拆页，我们知道了什么是信息结构化，为什么要信息结构化，如何实现信息结构化，希望大家能将今天所学用到自己的实际生活中去。那今天的分享就到这里了，谢谢大家!\u003c/p>\u003cp>学习者A2记录\u003c/p>\u003cp>佳音：在写今年的年终总结的时候用上信息结构化，搭建相应的框架，并选取不同的案例\u003c/p>\u003cp>纪巧：在下周三在小组开会的时候使用信息结构化。主题为资料整理的必要性，分为几个框架去阐述\u003c/p>\u003cp>雪艳：下周写销售总结时用结构化的方法去设计PPT\u003c/p>\u003cp>佳山：在写下周材料的时候运用信息结构化，一、明确材料主题；二、设计框架；三、寻找框架对应的素材\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1515502594000,"updated_at":1515502848000,"ria":true},{"id":4358,"topic":"用信息结构化让自己做优秀的临场表达","learn_goal":"学习者能够运用演讲信息结构化的方式，快速整理和表达自己的思想","remark":"拆书书目：《请停止无效努力――如何用正确的方法快速进阶》\r\n拆书主题：用信息结构化让自己做优秀的临场表达\r\n说明：工作生活中，你可能会面临这样的情境：被人问到一个问题，你头脑中有很多信息，他们杂乱无章、野蛮生长，你想开口，却不知如何组织语言。或者你很兴奋，滔滔不绝地讲了一大堆，但老板却一脸茫然，觉得你头脑不清晰。\r\n明明有很多见解，为什么就是表达不出来？\r\n表达不好很大原因是大脑没有想清楚，大多思维清晰人的表达都没问题，让我们学会信息结构化，让自己的临场表达更优秀。","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"Tangcoco","city":"杭州"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"B : 我们发现很多时间，我们已经很努力、很拼了，但依然得不到自己预期的成果，这本书可以帮助我们掌握正确的方法快速进阶。\r\nA: 《请停止无效努力》这本书就是一本解决问题的工具书，作者不和你讲一堆道理，而是直接上方法，全是干货；比如我们今天拆的片段来自于她关于“结构化表达”中的一小部分内容，她用很少的篇幅就能让你掌握“结构化的思维”，说不定你已经练习“结构化思维”很多时间了，你的小伙伴还没有把《金字塔原理》看完呢。\r\nF: 之所以有这样的特点，是因为这本书的作者孙圈圈，原来是位优秀的外资咨询公司项目负责人，她书中的内容基本就是她在工作的总结，她从企业、管理者、咨询师和职场人四种视角去款待人才发展问题，因此不仅实战有用，而且中立客观。","ratings_count":2,"texts":[{"id":7360,"quote":"\u003cp>在本书之前关于结构化思维的文章里，曾经提到过，人类大脑在处理信息时有两个习惯：第一，不能一次太多，因为信息太多会让大脑的负荷过大；第二，喜欢有规律的信息。\u003c/p>\u003cp>临场发言时，我们是有压力的。这种压力，要不让我们的大脑一片空白、胡言乱语，要不让我们的大脑信息泛滥、毫无头绪。这两种情况，听众听起来都会比较痛苦，不明白你到底想表达的是什么、\u003c/p>\u003cp>如果说，有一个清晰的结构，发言就变得容易了。一方面，如果你的大脑是杂乱无章的状态，它可以帮你把信息快速整理并输出；另一方面，如果你的大脑是一片空白的状态，它可以作为提示语帮你联想起一些有用信息。\u003c/p>\u003cp>用结构化思维，帮助你在短时间内更好地沟通，关键是三个步骤：\u003c/p>\u003cp>第一步，想主题：迅速找到一个切人点，第一句就说出自己的观点。\u003c/p>\u003cp>第二步，搭架子：在论证观点时，思考一个结构（时间、空间、三角），并只说三点，这称为三个&quot;架子”。\u003c/p>\u003cp>第三步，填素材：每个架子里，填充一些事例、数据等，来推进论据向观点靠近。\u003c/p>\u003cp>这里给大家举个例子，乔布斯推出第一款苹果手机时进行过一段演讲，大意如下：\u003c/p>\u003cp>苹果公司是一家革命性的公司。为什么这么说呢？1984年，推出Mar电脑，改变了整个电脑行业；2001年，推出iPod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；2007年，推出苹果手机，我相信它将改变更多行业。\u003c/p>\u003cp>我们来剖析一下这段话的结构，就会是：\u003c/p>\u003cp>主题：苹果公司是一家革命性的公司。\u003c/p>\u003cp>架子：1984年、2001年、2007年。\u003c/p>\u003cp>素材：推出Mac电脑，改变了整个电脑行业；推出iPod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；推出苹果手机。\u003c/p>\u003cp>所以，乔布斯这段话的结构也是由三要素组成：主题、架子、素材。\u003c/p>","explains":"\u003cp>【学习目标】\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，在需要临场表达的时候，学习者能够运用演讲信息结构化的方式，快速整理和表达自己的思想。\u003c/p>\u003cp>【片段总结】\u003c/p>\u003cp>这个片段是教给我们一种让自己头脑中的信息结构化，以更好应对临时表达的片段。\u003c/p>\u003cp>【I-不那么做的坏处】\u003c/p>\u003cp>当我们被临时问到一些问题的时候，如果不掌握演讲信息结构化，很容易出现这两种情况：\u003c/p>\u003cp>1、大脑一片混乱，很多信息杂乱无章，你想开口却不知从何说起，留下一个表达能力欠佳，难堪大任的印象；\u003c/p>\u003cp>2、很兴奋，滔滔不绝讲了一堆，结果对方一句“讲重点”，让自己蒙圈了，留下一个头脑不清的印象。\u003c/p>\u003cp>\u003cstrong>举例：\u003c/strong>\u003c/p>\u003cp>之前看一档真人相亲节目“相亲才会赢”，女主分别问两个相亲对象，一个相同的问题：“你对自己未来3年的事业规划是怎么样的？”\u003c/p>\u003cp>#两位男嘉宾的硬性条件都差不多，结果“女神”选了嘉宾B#\u003c/p>\u003cp>\u003cstrong>男嘉宾A：\u003c/strong>讲了很多自己的过往经历，但是都没讲点子上。\u003c/p>\u003cp>\u003cstrong>男嘉宾B\u003c/strong>：按照时间架的结构介绍了自己“未来3年的事业规划”\u003c/p>\u003cp>\u003cstrong>主题：\u003c/strong>事业发展同时多照顾家庭\u003c/p>\u003cp>\u003cstrong>架子（时间架）\u003c/strong>：现在、近两年、三年后\u003c/p>\u003cp>\u003cstrong>内容：\u003c/strong>现在（多赚钱）、近两年（多付出提升管理技能）、三年后（升经理）\u003c/p>\u003cp>结果节目事后采访女主的时候，人家说觉得男嘉宾A太夸夸其谈了，比较虚；采访男嘉宾A时，男嘉宾说的是“整个过程很紧张，又怕什么也不说冷场，让对方觉得我对她不重视，所以想什么说什么，最后说什么自己都不知道。”挺可惜的，因为不能很好的表达自己，错失女神。而男嘉宾B就给人踏实、稳重、有规划的感觉。抱得美人归。\u003c/p>\u003cp>【How】\u003c/p>\u003cp>第一步，想主题：迅速找到一个切人点，第一句就说出自己的观点。\u003c/p>\u003cp>第二步，搭架子：在论证观点时，思考一个结构（时间、空间、程度），并只说三点，这称为三个&quot;架子”。\u003c/p>\u003cp>第三步，填素材：每个架子里，填充一些事例、数据等，来推进论据向观点靠近。\u003c/p>\u003cp>【I-&nbsp;根据原书中案例脉络，给出了更贴近实际的例子】\u003c/p>\u003cp>比如有一次商务的饭局上，客户方老板问我：“汤老师，为什么选择这份工作，作为女性挺辛苦的”；当时期望一方面真实的表达自己，与客户有更好的关系，另一方面能展示公司的专业形象。所以我就说：\u003c/p>\u003cp>（主题）我期望我的职业能够给我带来独立和自由。我小时候（架子），父母事业做得不错，一直是我的榜样，我心中就埋下了一颗要像父母一样有成绩的人；我上大学后（架子），觉得真正的自由和独立首先要经济独立，只有经济独立才能自己决定人生，所有后来都是靠自己奋斗；后来工作后（架子），我发现独立和自由不仅仅是经济，还有思想和智慧，我们做选择和决定的时候要有经济基础，更需要有思想和智慧做选择。\u003c/p>\u003cp>所以，我的择业观是，工作能够给我带来自由和独立，我目前的工作是顾问公司项目经理，这份工作不仅让我能在杭州立足，也能让我处在不断学习和提升的状态，不断吸收和累积经验和知识。\u003c/p>\u003cp>例子总结：\u003c/p>\u003cp>主题：职业带来独立和自由\u003c/p>\u003cp>架子（时间架）：小时候、上大学后、工作后\u003c/p>\u003cp>内容：小时候（父母为榜样）、上大学后（经济独立）、工作后（思想独立）\u003c/p>","interaction":"\u003cp>1、接下来请每位小伙伴思考下，在过去的2周中\u003cstrong>，需要临场发表自己观点时你表现不佳让对方不满意的情景\u003c/strong>，（比如：领导问你竞争对手推出新品，你怎么看？朋友问你“拆书帮”值不值得参加？伴侣/爱人/家人问你你目前工作给你的意义是什么？）\u003cstrong>\u003cstrong>当初你是如何表达自己的观点和思想的？你为什么觉得不满意？你觉得不满意的是什么？是什么导致这个结果的？\u003c/strong>\u003c/strong>请简单记录下，给大家2分钟时间。\u003c/p>\u003cp>\u003cstrong>{\u003c/strong>\u003cstrong>学习者互动}\u003c/strong>\u003c/p>\u003cp>学习者一：圣诞节前，我们领导问题新项目的策划书做的怎么样了？我当时就把我的企划书做了什么讲了一下，谈话结果很不满意。我觉得不满意是看老板的面无表情，以往他都会有疑问或者认同，面无表情说明老板不满意。导致这个结果的原因，我认为是我只是顺序讲了我做的事情，没有从老板关心的角度，挑重点讲。\u003c/p>\u003cp>学习者二：前几天院领导问我，六顶思考帽蓝帽子和主持的区别。我当时就将蓝帽子是怎么怎么，主持人要做什么什么。讲完领导是说明白了，但是我不满意，我不满意的地方是我觉得自己讲的有点乱、有点啰嗦了，没有重点，领导并不是很满意。导致这个原因是自己没有准备，也没有想清楚这个问题。\u003c/p>\u003cp>2、如果结合我们今天刚刚学习到的“想主题+搭架子+填素材”，老天给你一个月光宝盒回到那个时间，你可以怎么讲？给大家2分钟时间，梳理下。\u003c/p>\u003cp>3、我们请一位小伙伴分享下你刚才重新组织过的发言，分享结构是：过去我在什么场景下有一次临场发言；当初我是怎么说的；通过今天学习，我可以这样说会更好。\u003c/p>\u003cp>\u003cstrong>{\u003c/strong>\u003cstrong>学习者互动}（与上一个学习者是同一个人）\u003c/strong>\u003cbr>\u003c/p>\u003cp>学习者一：场景（圣诞节前，我们领导问题新项目的策划书做的怎么样了？）老板，从我们要做这个企划书到现在已经有1个月，这一个月中我们的商业模式有很变化，所以我会汇报下策划书结构和相应关键，【主题】您需要审核下是否符合这个阶段的对外模式，如果有调整修正后也很快。【架子】1、商业模式（【素材】从原来的以AA为主体转向现在以AA为载体）；2、模式亮点（新商业消费模式演变）；3、财务模型（单店营业额VS平台营业额）\u003c/p>\u003cp>学习者二：场景（院领导问我，六顶思考帽蓝帽子和主持的区别）【主题】主持是从头到尾带蓝帽子的，但是蓝帽子不是只有主持带。【架子】主持的要求（【素材】时间关系并没有让学习者展开）；【架子】蓝帽子的规则（【素材】时间关系并没有让学习者展开）；【架子】帽子移动的规则（【素材】时间关系并没有让学习者展开）。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":7361,"quote":"\u003cp>架子指的是：提炼出来的结构关键词。架子一方面充当提示语，有了它，你不至于一点都说不出来，另一方面又是帮你梳理信息的工具。\u003c/p>\u003cp>大致来说，架子不外乎以下类型：\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;类型一，时间架：按照时间的顺序，把脑子里的信息整理输出，举例如下：\u003c/p>\u003cp>问：你是做什么的?\u003c/p>\u003cp>答：我在一家外资企业做员工培训工作。\u003c/p>\u003cp>问：你平时都做些什么呢?\u003c/p>\u003cp>答：总体来说，我的工作是保证培训工作的顺利进行。培训前，我会联系讲师、学员、酒店等确认准备工作。培训中，我会在现场进行协调、为讲师和学员服务。培训后，我会通过学员工作场所访谈等方式跟进培训效果，今后改进。\u003c/p>\u003cp>培训前、培训中、培训后就是按照时间的顺序来说话。\u003c/p>\u003cp>时间类的架子，其实不局限于时间这个狭窄的概念，还包括一切有先后或因果顺序的结构。因此，时间类的架子可以分成以下三类：\u003c/p>\u003cp>代表时间的词：过去、现在、将来；上午、中午、下午；一点、两点、三点。\u003c/p>\u003cp>代表阶段的词：研发、试产、投产；少年、青年、壮年；前期、中期、后期。\u003c/p>\u003cp>代表步骤的词：第一步、第二步、第三步；流程一、流程二、流程三；首先、然后、最后。\u003c/p>\u003cp>我们平时可以有意识地积累这些架子，脑子里积累的架子越多，整理思路的速度就越快。\u003c/p>\u003cp>时间架几乎可以用来说任何话题，应用很广，几乎是万能法。如果以后在紧急场合让你说话，一下子想不出来怎么说，那就思考时间架法，它一定会让你说出一些话来，因为架子特别多、特别好找。\u003c/p>\u003cp>类型二，空间架法：按照地点的顺序整理思路\u003c/p>\u003cp>之前关于培训的例子，如果不按照培训前、培训中、培训后来讲，按照办公室、酒店会议厅、学员工作场所这三个地点来讲，也同样可以表达出意思。\u003c/p>\u003cp>用空间架的好处是，听众脑子里很容易出现具体场景，有视觉化效果，能够更好理解你说话的意思。\u003c/p>\u003cp>举例如下：\u003c/p>\u003cp>全国各地的人们都合家团圆，一起喜迎春节。\u003c/p>\u003cp>广州舞龙舞狮。北京全家一起包饺子。南京写春联以及贴春联。\u003c/p>\u003cp>它的结构也是一样的：主题、架子、素材。只是架子是一些代表地名的词。\u003c/p>\u003cp>接下来给大家一些空间法的架子：\u003c/p>\u003cp>代表地理位置：美洲、欧洲、亚洲；北京、上海、广州；实验室、流水线、4S店。\u003c/p>\u003cp>代表视觉区域：外壳、屏幕、键盘；脑、肩、心。\u003c/p>\u003cp>类型三，三角架：按照三个方面的顺序整理思路\u003c/p>\u003cp>看如下例子：\u003c/p>\u003cp>斯滕伯格的爱情三元论：激情、亲密和承诺。\u003c/p>\u003cp>按照激情、亲密、承诺的顺序说话，这种方式叫做三角法、\u003c/p>\u003cp>三角法的架子通常有以下几类：\u003c/p>\u003cp>代表三个方面(三件事)的词：语法、修辞、逻辑；提高沟通效果、提高影响力、提高印象分；多学、多听、多练。\u003c/p>\u003cp>代表三类人的词：孩子、丈夫、自己；客户、员工、股东；领导、同事、下属。\u003c/p>\u003cp>三角法的最大特点是：能把一件事情客观地说清楚。\u003c/p>\u003cp>用三角法说话，可以起到客观全面的效果。但三个架子必须是具有高度代表性和概括的三个架子，这样才能把主题撑起来。\u003c/p>\u003cp>所以，三角法经常用来说一些严肃的话题，能体现出你的水平和深刻见解的话题。\u003c/p>\u003cp>用这三种方法找架子的时候，可以尽量使用MECE原则，即，架子之间相互独立、完全穷尽、这个原则在本书之前讲结构化思维的时候也提到过，这样会给人逻辑更加严密的感觉。\u003c/p>","explains":"\u003cp>【片段二学习目标】\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够累积不同的架子，并且结合片段一的内容，遇到临场发言的情况能够得体的表达自己的观点和想法。\u003c/p>\u003cp>【片段总结】\u003c/p>\u003cp>架子相当于为在我们大脑中搭建一个框架，在不知道如何表达自己想法时，调用架子做有序输出，当观点想法比较多涌出时，可以帮助我们梳理自己的思想，令输出内容没有重复和遗漏。架子需要自己不断的累积和学习，今天就有20个架子需要大家掌握。\u003c/p>\u003cp>【I-不那么做的坏处】\u003c/p>\u003cp>1、如果你不尝试着去学习和累积不同的架子来应对各种复杂问题，会让你失去一条比较有效、高效的构建自己知识框架的道路；\u003c/p>\u003cp>案例（反面）：\u003c/p>\u003cp>比如说我，我在培训行业有近10年的工作经历，在顾问&amp;培训交付、实施上有三年以上的直接工作经验，交付过5个50万+的顾问&amp;培训项目，经验非常丰富，客户满意率很高，但是我没有去构架自己工作内容的架子，也没有深度研究和累积培训项目交付理论上已经有的“架子”，都是凭感觉应该怎么做了。最后导致后果是，第一，没有培养优秀的下属；第二，当被客户临时问到一个问题时用本能反应回答，很容易遗漏信息（双方的：客户想传递的信息，我们应该传递的信息）；第三，不能推动公司顾问&amp;培训项目交付品质更上一层楼。\u003c/p>\u003cp>案例（正面）：\u003c/p>\u003cp>下一段《横向领导力》就是一个正面案例。\u003c/p>\u003cp>【关联到原文知识点的回应或反馈&amp;I-根据原书中案例脉络，给出了更贴近实际的例子】1、现在我们对片段有了一个大致的了解，现在我有个小案例请大家帮忙：有个下属（或朋友）去负责一个跨部门项目，需要协调很多不是本部门，甚至级别比他高的同事，他遇到了很多困难，感觉工作都没有办法推进了，他来向你求助，你会怎么对他讲？\u003c/p>\u003cp>2、&nbsp;我们请位同学分享下？\u003c/p>\u003cp>\u003cstrong>{学习者分享}\u003c/strong>\u003c/p>\u003cp>我会和他讲：第一你要尽可能获得正式或公开场合的认证或授权，第二和同事打好关系，尽可能争取更多群众支持。\u003c/p>\u003cp>3、&nbsp;分享的非常好，大家感觉这样的表达给到你的感受是什么？\u003c/p>\u003cp>\u003cstrong>{学习者分享}\u003c/strong>\u003c/p>\u003cp>我觉得有授权肯定比没有授权好，但是有时候问题应该很复杂，每个人都不同吧，而且团队的成员还都有本职工作。\u003c/p>\u003cp>好，我们接着往下看...\u003c/p>\u003cp>4、&nbsp;我以前碰到这种情况，会从他项目小组的每个人开始和他讲，这个人要XX合作，那个人要XX合作，一派大姐风范啊。那大家觉得这么做有什么的问题吗？\u003c/p>\u003cp>\u003cstrong>{学习者分享}\u003c/strong>\u003c/p>\u003cp>不了解实际情况、本身对这块工作不熟悉.....\u003c/p>\u003cp>5、大家讲得都很棒，就我自己来讲，最可怕得是都要对情况很了解的前提下，我如果不了解呢？对团队中本身的成员都不熟悉呢？对这个问题我也不知怎么办呢？\u003c/p>\u003cp>看完这本书之后，我了解到要不断累积“架子”，所以专门去看了关于如何领导没有职位任命的团队的书——《横向领导力》，在那里找到一个没有任命和职位如何带领团队的架子\u003cstrong>“培养技能-明确目标-影响他人”\u003c/strong>，这是一个三角架，架子的三个维度是：培养技能、明确目标、影响他人（如图）：\u003c/p>\u003cp>找到这架子我好兴奋，以后再遇到类似情况，我就可以这讲：“小陈，要带领一群人完成一项工作，有三个关键，培养技能-明确目标-影响他人（有做一些详细解释下），你看看，你可能在哪里没有关注到啊”，画风变成我引导他去思考和找问题了。\u003c/p>\u003cp>这样就会变成回答此类问题的万用套路了，这个架子就像个对照表，帮助问题提出者去看我是哪里出现问题了，针对这个问题做什么行动，变得非常有效。\u003c/p>\u003cp>【1-细化原文行动建议的步骤】\u003c/p>\u003cp>从原文中总结提炼如何累积架子以应对不同的问题：\u003c/p>\u003cp>1、根据问题及发言要达成的目的判断是用时间架、空间架、还是三角架；\u003c/p>\u003cp>2、在相应架子下面找能解决发言内容的分类；\u003c/p>\u003cp>3、&nbsp;选择关键词套入发言；\u003c/p>\u003cp>4、事后去累积和学习相应“架子”，为以后做准备。\u003c/p>\u003cp>TIPS:时间架能万用、空间架有画面、三角架展深度。\u003c/p>\u003cp>【为帮助大家记忆增加的导图】\u003c/p>\u003cp>【I-&nbsp;异议的预防讲解】\u003c/p>\u003cp>1、是不是在选择架子的时候一定要走这三个步骤呢？\u003c/p>\u003cp>一开始学习的时候可以，但是随着不断学习和练习的深入，架子的选择也就在电光火石间完成了，毕已经变成身体反应，所以不是需要每次都走完三步。\u003c/p>","interaction":"\u003cp>【A3】重点练习“架子”使用\u003c/p>\u003cp>1、我们刚刚学习了如何快速的运用结构，梳理自己的思维，以出色的做临场表达，现在一起来做一个演练。场景如下：小来是公司的电脑销售，今天来了一对夫妻买电脑，男士看上去一位是专业、严谨做研究的人，女士看上去则是一位非常重视视觉感受的人，当你刚想去介绍他们看中的一款电脑的指标的时候，男士突然就问：“你直接告诉我，我为什么要买你们这台电脑？”女士也认同的点点头，笑嘻嘻的看向小来。小来一下子就蒙了，现在请你用刚才学的如何针对一个问题搭架子的片段，帮助一下小来。给大家3分钟的时间，小组内讨论下。\u003c/p>\u003cp>2、（6分钟）现在我们请1个小组的小伙伴来演绎下这个场景，一位伙伴做小来，另外两个伙伴分别做这对夫妻，请把你们讨论的思路，来表演下。\u003c/p>\u003cp>\u003cstrong>{学习者表演（简述）}（A:卖电脑；B：采购者）\u003c/strong>\u003c/p>\u003cp>A：你好，我们这个电脑是.....\u003c/p>\u003cp>B：你直接告诉我，我为什么要买你们这台电脑？\u003c/p>\u003cp>A：我们这个电脑有如下优点：第一，品牌好，这是DELL的电脑，所以无论是先生带着这个电脑上班还是太太带着喝咖啡处理公事，大家都会觉得使用者是个比较有品位的人；第二，性能强大，这款电脑无论是带游戏还是做图形处理没有任何问题，看剧更加是全程无卡顿，办公娱乐全不误；第三，轻便，电脑非常轻便容易携带，特别是太太包包比较小，带着轻便的电脑顿时会让出行变得轻松。\u003c/p>\u003cp>B：你说的很好，就这个了。\u003c/p>\u003cp>总结：\u003c/p>\u003cp>\u003cstrong>这次用的是三角架：衡量一台笔记本的三个维度：品牌、性能、外形轻便。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>两个片段综合A\u003c/strong>\u003c/p>\u003cp>【A2】（两个片段内容综合练习）\u003c/p>\u003cp>1、（2分钟）如果未来你在工作生活中，会突然被要求对某件事/某个问题发表想法的场景可能会是哪个？比如：面试、相亲、领导谈话、客户访谈、产品介绍……\u003c/p>\u003cp>&nbsp;&nbsp;请你花一分钟思考下\u003c/p>\u003cp>2、（1分钟）在这个场景下，可能被问到的问题是什么呢？请简单记录下。\u003c/p>\u003cp>3、（5分钟）请在这个场景和问题下，用“主题+架子+素材”的方式加工一个具体的发言，今后能够在这样场景下，快速准确的表达自己的观点和想法。\u003c/p>\u003cp>4、（2分钟）我们请一位同学来分享下。\u003c/p>\u003cp>\u003cstrong>{学习者分享}\u003c/strong>\u003c/p>\u003cp>学习者一：\u003c/p>\u003cp>【场景】相亲的时候，私底下“红娘”会问你觉得对方怎么样？\u003c/p>\u003cp>【主题】我的回答：没有感觉；三角架，我很重视外形，外形从三个维度去前切入；\u003c/p>\u003cp>【架子】身高，【素材】只有170CM；【架子】谈吐，【素材】比较高傲，我不喜欢；【架子】衣着，【素材】衣着比较前卫不是我喜欢的。所以没感觉！\u003c/p>\u003cp>我的目标是拒绝相亲对象，用的是三角架，看一个人的外形我选择比较关注的身高、谈吐、衣着三个维度。\u003c/p>\u003cp>学习者二：\u003c/p>\u003cp>【场景】未来组织架构调整的事情，有一个阿里挖来的员工会抢我的部分工作机会，老板会问我你想做哪部分工作？\u003c/p>\u003cp>【主题】我要负责融资和组织架构；\u003c/p>\u003cp>【架子】技能准备，【素材】商业模式学习、众筹和天使轮做成；【架子】意愿，【素材】跟老板这么多年要帮老板把公司做上市；【架子】团队，【素材】我是创始人团队之一，对团队中的成员都很熟悉，有利于建设公司；\u003c/p>\u003cp>我的目标是获得我想要岗位的主动权，用的是三角架，从能力、意愿、团队三个维度陈述，因为这是我有优势的维度。\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>在这两个片段告诉我们可以用“主题+架子+素材”这种结构化思维方式在短时间组织自己的语言发表的观点和想法，同时在日常的工作、生活和学习中多累积各种解决问题的架子，从而让自己可以自己思维更清晰、表达更有力。训练自己的思维结构化，是职场人士最值得训练的技能之一，在这里投入训练回报远远大于你的想象，加油。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1514813862000,"updated_at":1514813862000,"ria":true},{"id":4155,"topic":"成人学习目标锁定","learn_goal":"筛选出当下最适合的学习内容","remark":"","level":"TF3-2","duration":25,"status":0,"type":0,"chaishujia":{"username":"朱依凌（鱼小刺）","city":"郑州"},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"【自我介绍】大家好，我是拆书家鱼小刺，用3个标签来介绍下我自己：怀孕7个半月的二胎麻麻、拆书帮小学生、郑州轩辕分舵会员发展长老。今天是我TF3-2的练级现场，感谢在座各位小伙伴的参与。\r\n【设定学习目标（包含学习者的行为=一个动词、澄清=用什么方式做、界定=能做哪些内容）】大家在跟随我完成今天的学习之后，能够学会利用成人学习的特点，（界定）在实际和精力都有限的情况下，筛选(行为)出当下真正对自己有价值、能够坚持的学习内容。","ratings_count":0,"texts":[{"id":7133,"quote":"\u003cp>\u003cstrong>【场景法图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（事件场景：\u003c/strong>\u003cstrong>学习者生活或工作中可能发生的事件，描绘出细致的场景）\u003c/strong>：\u003c/p>\u003cp>对于爱学习的小伙伴们来说，很多时候我们想学的东西很多吧。看见别人学跳舞或者乐器，报了班却坚持不下去；健身房的卡已经在家吃灰了，没脸去艳羡教练的八块腹肌！公号里的文章收藏了一大堆，后来再也没有整理和打开过；还有一个：买书如山倒，看书如抽丝！\u003c/p>\u003cp>\u003cstrong>（提问：\u003c/strong>\u003cstrong>引发学习者思考；目的是引发学习者的认知冲突\u003c/strong>\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>为什么我们对自己学习的期待值总是和现实有出入呢？明明觉得自己可以做很多事情，开始也做了很多事情，到最后怎么就没坚持下去呢？\u003c/p>\u003cp>\u003cstrong>（影响：说明事件的影响、后果；目的是调动学习者对本次拆书的期待和热情）\u003c/strong>\u003c/p>\u003cp>面对那么多想学习的内容，而自己的精力和时间总是不够用，不断询问自己的意志力去哪里了？到了最后焦虑情绪渐渐成为主导，对自己也渐渐失望……\u003c/p>\u003cp>\u003cstrong>（解决：\u003c/strong>\u003cstrong>说明书中解决问题的方法、好处；目的是增加学习者对图书和拆书家的信赖\u003c/strong>\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>今天带来孙圈圈的这本《请停止无效努力》，学习如何学习这一章节里，告诉我们如何按需学习、筛选出自己的优先级，而不是“靠意志力”学习，让我们在学习的过程中收获属于自己的价值感和快乐。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A1\u003c/strong>\u003cstrong>】自测题\u003c/strong>\u003c/p>\u003cp>发给大家的资料中有个测试表，请认真阅读，大家现在请根据成人学习的特点，来对照一下自己的真实情况，利用1分钟做下面的选择题，然后算出总分。（1分完全不符合， 6分完全符合。）\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>I\u003c/strong>\u003cstrong>】解释自测题\u003c/strong>\u003c/p>\u003cp>如果你的得分在25-30分，你很清楚自己目前的学习目标，而且对自己学习习惯等方面很了解，并且自主学习的能力比较强；\u003c/p>\u003cp>得分在15-24分，你基本有自己的学习方向，在养成学习习惯和目标确定方面，还需要进一步精进；\u003c/p>\u003cp>得分在5-14分，说明我们还得想清楚学习这件事对自己意味着什么，或者如何开始自己的学习目标。\u003c/p>\u003cp>\u003cstrong>（引入）\u003c/strong>好，那现在请大家用2分钟时间阅读一下今天的拆页，阅读后请举手示意我，谢谢。\u003c/p>\u003cp>\u003cstrong>拆页选自：\u003c/strong>\u003cstrong> \u003c/strong>\u003cstrong>按需学习才更有动力《请停止无效努力》\u003c/strong>\u003c/p>\u003cp>我们先来看看，学习都有什么特点，因为了解自己之后才能做出正确选择。关于成人学习有很多研究，成人教育领导人物马尔科姆·诺斯尔斯提出了成人学习的四个特点，区别于小孩子的学习：\u003c/p>\u003cp>第一，自愿。小孩学习一般是家长安排的，我们不会允许自己的孩子不上学，但成年人是有选择的，我们可以选择不学习、只娱乐。所以，成年人的学习内容，必须让我们看到紧迫性才行。\u003c/p>\u003cp>第二，经验。小孩的脑袋是空的，他/她可以接受任何新事物。但成年人有自己的经验，我们在学习的时候，往往会把学习内容跟经验做个对照，决定是否接受。同时，如果学习内容超出我们的经验太多，往往我们也很难看到价值。\u003c/p>\u003cp>第三，自主。相比小孩来说，成年人有更多主见。我们接受哪些信息、哪种方式，都是有自主性的。所以，我们选择的学习，应该是能让我们有参与感，而不是说教型的。\u003c/p>\u003cp>第四，行动。如果学习的东西，我们没机会应用，或者不知道如何应用的话，我们就会忘记。不管学习的内容有多好，只要不能使用，我们最终都会觉得没有价值。\u003c/p>","explains":"\u003cp>\u003cstrong>【技能点：互动提问】\u003c/strong>\u003c/p>\u003cp>大家已经看完片段了，那么接下来我对这个片段进行讲解，讲解的过程中需要大家对问题进行互动哦！\u003c/p>\u003cp>【\u003cstrong>互动\u003c/strong>】通过阅读这个片段，大家有没有发现这段话所讲述的关键点是不是\u003cstrong>成人学习的四个特点\u003c/strong>\u003cstrong>——自愿、链接个人经验、有参与感和基于行动的学习\u003c/strong>？这是不是和我们帮主曾经讲过很多次的成人学习特点相吻合？那么我现在来具体解释下这四点对应的原则。请看【图示】：\u003c/p>\u003cp>1、&nbsp;&nbsp; 我们成年人选择学习内容的时候是不是得具有有用性，才会自愿去学？\u003c/p>\u003cp>2、&nbsp;&nbsp; 是不是得和自己的经验相匹配？严重超过或者低于个人经验的学习内容，会不会让我提不起来兴趣？\u003c/p>\u003cp>3、&nbsp;&nbsp; 让我们有参与感而不是说教性质的内容是不是更能引起我们的注意？\u003c/p>\u003cp>4、&nbsp;&nbsp; 学以致用、能够落脚到行动的学习才能让我们更有动力吧？\u003c/p>\u003cp>\u003cstrong>【互动】【适用边界】\u003c/strong>你现在是不是什么都想学，什么又都学不好？希望自己在时间和精力有限的情况下快速锁定学习目标呢？\u003c/p>\u003cp>那么我们应该怎么做呢？在这我梳理了三个步骤分享给大家：\u003c/p>\u003cp>&nbsp; 【\u003cstrong>How\u003c/strong>】（现在请看刚才给大家发的资料三，利用这个表格分析当下自己的学习需 求，然后做出筛选结果——）\u003c/p>\u003cp>第一步，请列出你所有想学习学以致用的内容；\u003c/p>\u003cp>第二步，按照表格罗列是否符合成人学习四原则；\u003c/p>\u003cp>第三步，最后敲定目前需要的学习内容圈出来。\u003c/p>\u003cp>（感谢大家刚才的配合，现在我们已经了解到了如何利用成人学习的特点来筛选学习内容）\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp;\u003c/strong>\u003cstrong>【举例子】\u003c/strong>为了方便大家深入理解，我来举个例子对照：这段时间咱们拆书家练级活动比较多，在选择片段的问题上个别小伙伴遇到了难题，结合这三步骤四原则我来分享下如何锁定拆书片段内容的：\u003c/p>\u003cp>1、\u003cstrong>有用。\u003c/strong>“弱水三千只取一瓢”，茫茫书海我只取对我当下最有用的内容。最近我感觉自己的学习遇到了瓶颈进步很慢，分析一下应该是学习方法出了问题，针对这个情况，我翻阅了《好好学习》、《精进》、《请停止无效努力》、《跃迁》等书籍里关于学习的章节，来锁定我的学习目标——学会学习。\u003c/p>\u003cp>2、\u003cstrong>匹配。\u003c/strong>我的职业每天都在和大学生打交道，经常教导学生如何把握住青春大好时光去奋斗，所以关注的书籍大多是学习方法、自我管理、个人成长、职业规划等方面的，和我的经验背景相匹配的书籍读起来易于理解。\u003c/p>\u003cp>3、参与。拆书学习法要求我们读致用类书籍，这些书籍的共同点就是要么刷新你的认知，要么明确告诉你为人处世的方法是什么，那么我需要改变哪方面的认知，就去找相关的内容，这也是成人学习的自主性体现。\u003c/p>\u003cp>4、\u003cstrong>应用。\u003c/strong>比如我给学生分享过这些主题——阅读的方法、养成习惯的方法、如何制定学习计 &nbsp;划、学生干部如何学会上传下达，这些都是在一些经典书籍里学习到的方法，并且很快可以教会学生去实施行动。&nbsp;\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;在这里我要特别提到两点，或许有的小伙伴会问：有些学习对我的未来有用而现在看不到价值怎么办？比如我想学写作，但是短期之内不会显现价值，那么你可以把这个学习目标转化为短期有用的，比如坚持写作然后分享出来，哪怕只有几个人给你点赞，这也是一种即时反馈，会增加你的成就感。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;还有一种情形就是遇到大块的学习内容，需要拆分出有用的组成部分，比如说学吉他并不是想练就成为吉他高手，只为了放松和愉悦聚会气氛的话，那么会一些简单的和弦和弹奏动作，能弹一些曲子，其实就ok了。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3促动参与】\u003c/strong>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>我们刚刚学习了“筛选学习内容的原则”，接下来我们按照刚开始的分组，来进行一个\u003cstrong>【情景演练】\u003c/strong>，我给大家一个场景，\u003cstrong>【小组讨论】\u003c/strong>请大家根据场景在小组内讨论6分钟，用所学到的方法（可以直接写在“筛选”表格里）来帮助主人公选出当下最需要的学习内容，6分钟之后请小组来分享演练一下哦~\u003c/p>\u003cp>\u003cstrong>【场景】\u003c/strong>主人公：小花，女，25岁的行政助理。青春如水貌美如花，信奉努力的人生才是丰满的人生。同时学习了好多课程来提升自己：时间管理、英语口语、古筝、精英管理课……业余时间都花在各种学习活动上了，工作却进步很慢。领导知道她爱学习很积极，但最近也似乎对她越来越苛刻了，多方暗示她的个人工作能力该提升了。小花很苦恼，一边觉得自己身怀各种“绝技”，一边竟然被领导打击，于是在一个温暖安静的咖啡馆请单位的知心大姐（大哥）——一位同样保持很多爱好但工作生活发展都很好的同事，请教经验。\u003c/p>\u003cp>请小组内的知心大姐（大哥）用今天所学的筛选学习内容的原则，根据小花的职业特点和现状，去帮助她敲定在未来一个月内应该锁定的学习内容。两人演练，时间6分钟。\u003c/p>\u003cp>Ok，请开始你们的表演吧。\u003c/p>\u003cp>（非常感谢刚才小伙伴们的参与）\u003c/p>\u003cp>\u003cstrong>【A2布置任务】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【事后复盘】\u003c/strong>通过这个演练，大家更深刻地体会到了如何找到和自己需求相匹配的学习内容了吧，为了让这个方法更深入地帮助到大家，活动结束后：\u003c/p>\u003cp>1、&nbsp; 请在座的拆书家新手们根据这四个步骤，锁定现阶段的拆书片段的主题选择范围。\u003c/p>\u003cp>2、&nbsp; 其余的小伙伴筛选出现阶段对自己最有用的学习方面。\u003c/p>\u003cp>下周三发到群里分享一下你的筛选内容，下周日活动我们现场复盘哦！\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003cbr>\u003c/p>\u003cp>熊（小花）：最近苦恼比较多，我那么上进学习，工作上领导竟然说我能力不强。\u003c/p>\u003cp>豆（知心小妹）：你是不是学的东西太多太杂了？今天来帮助你筛选一下当下需要学习的内容吧，你先用把你现在的学习内容罗列下来。\u003c/p>\u003cp>熊（小花）：好的，我现在学的有时间管理、英语口语、古筝、精英管理课。\u003c/p>\u003cp>豆（知心小妹）：成人学习筛选内容有四原则——有用性、匹配经验、参与感和应用，你对照一下这四点看看哪个课程，目前对你来说并不是特别急需的。\u003c/p>\u003cp>熊（小花）：第一个是古筝吧，这个不是我自愿的；第二个去掉口语吧，这个不是特别着急学，只为了能看懂原版电影；剩下这两个和我领导对我的要求有关系耶，是必须的。\u003c/p>\u003cp>豆（知心小妹）：那就知道了，未来这一个月内你把时间和精力分配到这两个课程里，对你的工作有帮助哦！\u003c/p>\u003cp>熊（小花）：嗯，明白了，谢谢！\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>结语：\u003c/strong>\u003c/p>\u003cp>Ok，我今天的分享到此结束，希望能帮助到大家去明确自己目前的学习目标和内容，感谢大家今天的参与，谢谢。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1512285431000,"updated_at":1512285431000,"ria":true},{"id":4061,"topic":"如何练习才能快速掌握一项技能？","learn_goal":"了解刻意练习的概念，并运用刻意练习的4步关键方法掌握一项技能","remark":"你有没有在考驾驶证时，总是连续挂科？ \r\n你有没有想学英语，却迟迟没有进展？\r\n 你有没有反复练习一项技能，但收效甚微？\r\n 我是不是没有这个天赋？我是不是应该放弃？\r\n也许你只是用错方法，周六来拆书帮古城分舵升级吧。","level":"TF2-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"张诗悦","city":"西安"},"club":{"name":"西安古城分舵","city":"西安"},"prologue":"大家好，我是本轮的拆书家张诗悦，现在是安踏西安分公司的培训师一枚。（F）本次为大家拆解的原文片段来自于这本《请停止无效努力-如何用正确的方法快速进阶》，作者是孙圈圈，曾任全球顶级咨询公司咨询总监,现为移动学习内容品牌【圈外】的创始人兼CEO。这本书呢，讲得是努力的方法论，全书围绕着职业发展和个人提升所需的方法论展开，分为发掘天赋、提升能力、选择平台、回归自己等几大部分，（A）是市面上为数不多的写“术”的成长类书籍，读这本书呢，也许不会让你感到鸡血满满、精神倍增，但却极具实操性，一个大的亮点是在每节结束之后都有本节内容的精彩提炼和后续练习具体方法，是一本非常接地气，可以让你少走很多弯路的书，（B）为什么你找不到自己的天赋所在？为什么你发挥不出自己的优势？为什么你的辛苦付出总是换不回成绩？很多时候，我们不是不努力，只是没找到正确的努力方法，这本书将带给你答案！","ratings_count":0,"texts":[{"id":7020,"quote":"\u003cp>相信大家已经开始期待了，接下来就正式进入我们的拆书时刻，首先是R环节阅读原文片段，刚才我已经把拆页发给大家了，下面请小伙伴们用2min的时间仔细阅读一下，读完后请举手示意我：\u003c/p>\u003cp>\u003cstrong>如何练习才能将天赋转化为能力\u003c/strong>\u003c/p>\u003cp>如何花时间去开发自己的天赋呢？关键是刻意练习。首次提出“刻意练习”这个概念的是心理学家K.Anders Ericsson，他对刻意练习的定义是：为了掌握某种能力，有意识付出努力，投入到某项活动中。只有有意识的重复，才会引发大脑神经的变化。最终随着时间的推移，大脑不再对这项活动感到不适，成为我们无意识的一种能力。研究表明，练习的“质”，比练习的“量”要重要很多。\u003c/p>\u003cp>那么，什么是正确的刻意练习方法呢？它必须符合四大特征：\u003c/p>\u003cp>\u003cstrong>第一，在学习区练习\u003c/strong>\u003c/p>\u003cp>　　我们的学习，一般有三个区域：一个是舒适区，就是你非常熟练，几乎是下意识就可以完成的事情；中间是学习区，就是有一些挑战，可以通过努力掌握的；最外层是恐慌区，远远超出你的能力，当前很难掌握。如果用比喻的话，舒适区就像是右手随意写字，学习区是用右手学写某种字体的字，而恐慌区是让你直接用左手写那种字体出来。\u003c/p>\u003cp>　　因此，你需要反思，你现在的８小时工作内容中，分布在各个区域的比例有多少？如果在学习区的都不到１小时，那你就需要考虑一下了。因为，长此以往，你工作八年，只相当于别人工作一年。\u003c/p>\u003cp>\u003cstrong>第二，大量重复\u003c/strong>\u003c/p>\u003cp>　　这里所说的重复，是指在学习区内重复。学习任何一样新东西，其实是打破思维惯性、进行大脑重构的过程，要建立起重构后的稳定神经结构需要多次练习，才能掌握。这是一个将有意识变成无意识的过程。你看到很多人，面对问题快速梳理出思路，那是因为，你需要有意识、很努力才能做到的事情，他早已通过刻意练习形成无意识反应了。\u003c/p>\u003cp>\u003cstrong>第三，持续获得有效反馈\u003c/strong>\u003c/p>\u003cp>　　刻意练习是以错误为中心的，因为如果一样事情你从未做错过，证明你根本不需要学习它。我在之前的文章里说过，人类学习的特征是从错误中学习，所以我们才会说“专家是在一个狭小领域内犯过最多错误的人”。我们都考过试，刷过题库，最有效的做题方式是，每做一遍，记下错误的题目，下一遍只做错题，而不是一遍遍从头开始做。\u003c/p>\u003cp>\u003cstrong>第四，专注\u003c/strong>\u003c/p>\u003cp>　　同样在学习区里练习，练习时间也一样，而且也有反馈，最后的结果就没有差异吗？不是，差异很大。比如，同样是学写楷体字个在写字的时候听摇滚、想心事，而另一个则是沉浸其中，最后的结果是差异很大的。\u003c/p>\u003cp>　　所以，想要提升你的时间性价比，开始盘点你的天赋和劣势，将时间做个切换，并掌握正确的刻意练习方法吧！\u003c/p>","explains":"\u003cp>好，所有的小伙伴都已经读完了，那么接下来就进入到我们的I环节，也就是拆书家的引导讲解环节，我将用自己的话来复述一下原文的意思。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;原文讲得是要将自己的天赋转化为能力，关键是要用到一种叫做刻意练习的方法。（HOW）那正确的刻意练习必须符合四大特征：一是在学习区练习，也就是你的练习对你来说要有一定难度，不是轻而易举能做到，但这个难度一定是你努力就能完成的；二是要在学习区大量重复，也就是我们平时说的孰能生巧，要通过反复多次的练习让这件事变成你的下意识反应，像老司机开车一样，不用怎么思考就能做到；三是持续获得有效反馈，每一次的练习结果如何？哪里不到位？哪里还可以更好？我们要通过自己总结或去倾听他人的评价来获得反馈，这样才能从问题中积累经验从而下一次做得更好；第四就是专注，任何事全神贯注去做和随便做两下肯定结果截然不同，这个道理很好理解。那原文讲得是把刻意练习用在天赋转化为能力这个方面，其实学习任何一个新东西，或者精进任何一个技能，如果你想学有所成都可以用刻意练习这种方法，这也是我们今天学习这个拆页最重要的学习目标。\u003c/p>\u003cp>那举个我自己的例子吧，刚才自我介绍也说了，我是名培训师，那PPT制作肯定是一项必备技能。我去年系统学习PPT的时候就先报了秋叶PPT系列课程中的《和秋叶一起学PPT》，这对我来说就是一个学习区的课程，因为我本身有一定的PPT基础，所以就没有去学那些入门课；之后就是每天至少学习两个小时，每个技能点都去做大量的练习，一个快捷键也要练习上十几次甚至几十次，直到能够熟练操作；然后我会发微博作业让秋叶大叔和其他伙伴点评，再根据他们提出的问题修正，直到完全掌握了再学习下一课；而且我每次练习的时候手机都是飞行模式，保证自己不受任何干扰，一心一意的学习，就这样坚持了三个月我的PPT水平就有了大幅度的提升。\u003c/p>\u003cp>\u003cstrong>【I】拆书家讲解引导——预防可能的异议:\u003c/strong>那听到这可能有伙伴会说，要按这样的办法每次我学个啥还得控制着难度，完了还得找人点评反馈啥的也太麻烦了，不如就像自己之前那样，一股脑的去做就对了，反正啥事做得多了不是自然就会了。可事实上，如果你不按这个方法去做，就可能走进了一些学习误区，比如你想学英语，一上来就开始读英文原著，那这实际上是直接进入到你的恐慌区了，这种难度很容易让你备受打击就放弃了；或者你天天早起读英文报纸苦练口语，但是学了几个月外国人还是听不懂你在说些什么，因为你没有持续的反馈，得不到别人的评价和指导，你一直练习的发音可能是错的但你自己压根不知道。所以你不按照刻意练习的方法去做，带来的时间、精力的浪费会更加严重，因为我们说刻意练习这种方法还是很值得推崇的。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2】催化学习者应用——分步催化\u003c/strong>\u003c/p>\u003cp>好，那接下来我们进入到A2环节，也就是催化应用阶段，请大家先想一下，未来一个月内，你有没有打算要开始学习、精进的技能呢？比如说写作、手绘、思维导图、视觉笔记？还有某一种乐器、某一项运动、某一门外语、某一类办公软件？或者是阅读、书法、摄影、棋牌等等，请大家在纸上写下你们想学习的内容。\u003cbr>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;(小伙伴们写想要学习的内容中).......\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;好时间到，请一位小伙伴来分享一下未来想要学习什么。\u003c/p>\u003cp>&nbsp;\u003cstrong>小伙伴少侠的分享：\u003c/strong>未来一个月想学习公众号的运营。\u003cbr>\u003cstrong>【A2】催化学习者应用——分步催化\u003c/strong>\u003c/p>\u003cp>接下来请大家想象这样一个画面，下周你下班回到家里，吃过晚饭后，你打开工作台的灯，把手机调到飞行模式，拿出你要学习的资料后，你会如何用今天拆页当中刻意练习的方法来进行学习呢？给大家6分钟的时间在小组内讨论一下，我们按照今天的人数，两两一组，\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;（小组讨论中）......\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;请一位小伙伴来分享下自己未来的行动。\u003cbr>\u003cstrong>小伙伴高飞的分享：\u003c/strong>未来的一个月自己在演讲这一方面有更大的进步。\u003cstrong>那第一步\u003c/strong>，我要判断什么是我演讲的学习区，你像我和家人朋友沟通交流都没问题，也就是熟人小范围的公开发表言论这属于我的舒适区，但是要是几十人上百人就很有压力了，想都不敢想，这就是恐慌区，所以在我要先在十几人面前先练习演练，就想我们拆书帮这种升级打怪活动就很合适，还有一种方法就是每天午饭后抓住和同事交流的机会，这对我来说都是在学习区学习；\u003cstrong>那第二步大量重复的话\u003c/strong>就是每周坚持参加咱们拆书帮的升级打怪活动，自己也要开始升级打怪，再就是每天找一个话题跟同事交流，发表我的一些看法和见解；\u003cstrong>第三个获得反馈\u003c/strong>，像升级打怪过不过，大家听懂我的意思没，这都属于反馈；中午和同事的交流也是，去倾听他们对我的评价，比如我哪个比喻同事觉得很形象，哪个包袱同事觉得很有意思，那些观点特别犀利准确，那我就知道什么样的表达方式是大家比较喜欢的，然后把他们积累下来再不断的优化；\u003cstrong>最后就是专注\u003c/strong>，那我跟别人沟通时肯定我自己要认真，这也是对他人最起码的尊重，要是回家和家里做一些演讲的练习，那也保证先把孩子安排好，让丈母娘先帮忙带着，专门抽出一些时间去写一些演讲稿之类的。\u003c/p>\u003cp> &nbsp; &nbsp; &nbsp;&nbsp;感谢高飞的分享，你的每一步都是按照今天拆页当中刻意练习的方法去做的，相信你的演讲水平肯定能得到快速的提升，非常棒！那我今天的拆书就到这里，希望对大家有所帮助，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1511250162000,"updated_at":1511250162000,"ria":true},{"id":4000,"topic":"用结构化思维的模式汇报工作或临场发言","learn_goal":"在临场发言或汇报工作表达时，不再出现杂乱无章语无伦次的状况","remark":" 通过今天我们对本片段RIA的学习，学习者能够在临场发言或汇报工作表达时，不再出现杂乱无章语无伦次的状况，而是能够应用结构化的思维模式：主题、架子、素材快速表达出自己的想法和观点","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"上善若水jydd","city":"杭州市"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"各位伙伴大家上午好！欢迎参加拆书帮活动！我叫上善若水，今天我给大家带来的拆书片段来自《请停止无效努力》：临场发言或向上汇报如何让领导、同事对你刮目相看的思维模式-—结构化思维。","ratings_count":0,"texts":[{"id":6950,"quote":"\u003cp>&nbsp; &nbsp; &nbsp; 在本书之前关于结构化思维的文章里，曾经提到过，人类大脑在处理信息时有两个习惯：第一、不能一次太多，因为信息太长会让大脑的负荷过大；第二、喜欢有规律的信息。\u003c/p>\u003cp>&nbsp; &nbsp; 临场发言时，我们是有压力的。这种压力，要不让我们的大脑一片空白、胡言乱语，要不让我们的大脑信息泛滥、毫无头绪。这两种情况，听众听起来都会比较痛苦，不明白你到底想表达的是什么。\u003cbr>\u003c/p>\u003cp>&nbsp; &nbsp;如果说，有一个清晰的结构，发言就变得容易了。一方面，如果你的大脑是杂乱无章的状态，它可以帮你把信息快速整理并输出；另一方面，如何你的大脑是一片空白的状态，它可以做为提示语帮你联想起一些有用信息。\u003cbr>\u003c/p>\u003cp>&nbsp; &nbsp;用结构化思维，帮助你在短时间内更好地沟通，关键是三步骤：\u003cbr>\u003c/p>\u003cp>第一步，想主题：迅速找到一个切入点，第一句就说出自己的观点。\u003c/p>\u003cp>第二步，搭架子：在论证观点时，思考一个结构（时间、空间、程度），并只说三点，这称为三个“架子”。\u003c/p>\u003cp>第三步，填素材：每个架子里，填充一些事例、数据等，来推进论据向观点靠近。\u003c/p>","explains":"\u003cp>&nbsp;\u003cstrong>【学习目的】\u003c/strong>学习者通过对本片段RIA的学习，能够在临场发言或汇报工作表达时，不再出现杂乱无章语无伦次的状况，而是能够应用结构化的思维模式：主题、架子、素材快速表达出自己的想法和观点。\u003c/p>\u003cp>\u003cstrong>【图书及作者介绍】\u003c/strong>首先我对今天的所拆书籍及作者做一简要介绍：\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>F\u003c/strong>\u003cstrong>】\u003c/strong>《请停止无效努力》作者孙圈圈，本名孙园媛，曾任全球著名管理咨询公司咨询总监，【领英洞察】专栏作家。本书围绕职业发展和个人能力提升所需的方法论展开，分为发掘天赋、提升能力、选择平台、回归自己等几大部分。极具实战性。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A\u003c/strong>\u003cstrong>】\u003c/strong>\u003cstrong> \u003c/strong>有别于自我成长的同类书籍，作者由于咨询公司、管理者、职场人士的多种相关经历，不仅能将职场人士遇到的困惑给予解答，而且摸索出实操性较强的方法论，供职场新人老将借鉴。所以有很强的实战指导意义。得到众多知名人士的推荐。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>B\u003c/strong>\u003cstrong>】\u003c/strong>\u003cstrong> \u003c/strong>在工作中，你常常发现做了太多的事情却收获非常小，经常疲于奔命应付各种紧急情况而收效甚微，花了大量的时间学习，但效果不佳，说明你正在进行无效的努力。如果你想摆脱这种囧景，用正确的方法快速进步，将学到的知识迅速转化为自己的能力，在职场中脱颖而出，这本书非常适合你阅读练习。如果你想临场发挥潇洒自如、向领导汇报时展现惊人的工作能力，让同事上级对你刮目相看。本书片段的结构化思维模式：主题、架子、素材将使你的思维更缜密，观点表达逻辑性更强。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【过渡】\u003c/strong>首先，我们进入【R】环节，请大家花2分钟时间进行阅读，阅读完后，请举手。\u003c/p>\u003cp>\u003cstrong>【过渡】\u003c/strong>\u003cstrong>好！大家都已经看完，我们进入【I】环节:\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>I\u003c/strong>\u003cstrong>&nbsp;\u003c/strong>\u003cstrong>拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp;这个片段主要讲了在临场发言有压力时，需要有一个清晰结构，将信息快速整理并输出或大脑空白时，做为提示帮助我们联想起相关的有用信息，让发言非常有条理性。\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 人类大脑在处理信息时有两个习惯：第一、不能一次太多，因为信息太长会让大脑的负荷过大；第二、喜欢有规律的信息。\u003c/p>\u003cp>\u003cstrong>【HOW】 \u003c/strong>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;我们如何学习和掌握这种思维结构呢？主要采用以下三个步骤：\u003c/p>\u003cp>第一步，想主题：迅速找到一个切入点，第一句就亮明自己的观点。\u003c/p>\u003cp>第二步，搭架子：在论证观点时，思考一个架构（时间、空间、程度），并只说三点，这称为三个“架子”。\u003c/p>\u003cp>第三步，填素材：每个架子里，填充一些事例、数据等，来支持论点。\u003c/p>\u003cp>\u003cstrong>【不那么做的坏处】\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;记得刚参加工作的第一次工作汇报，虽然进行了精心准备，但没有按照主题-架子-素材的逻辑关系汇报工作，在整个汇报工作的十分钟里，领导一副不耐烦的样子，想象中惊喜的光芒并没有在领导眼中闪现，反而领导脸上堆满了疲惫和无聊。在我汇报结束后，发出了一声极为敷衍的“嗯”。那一刻我马上意识到，自己盼望已久的加薪转正的梦破碎了。所以不会用结构化的思维模式做工作汇报，就不能很好的在上级面前做一个清晰的表达，长远的话会让上级以为是个拎不清的人，影响升值加薪。\u003c/p>\u003cp>\u003cstrong>【举个例子】\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp; 为了让大家更好的理解这种思维结构，这里给大家举个例子，乔布斯推出第一款苹果手机时进行过一段演讲，大意如下：\u003c/p>\u003cp>&nbsp;苹果公司时一家革命性的公司。为什么这么说呢？1984年，推出Mac电脑，改变了整个电脑行业；2001年，推出iPod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；2007年，推出苹果手机，我相信它将改变更多行业。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 我们来剖析一下这段话的结构，就会是：\u003c/p>\u003cp>主题：苹果公司是一家革命性的公司。\u003c/p>\u003cp>架子：1984年、2001年、2007年。\u003c/p>\u003cp>素材：推出Mac电脑，改变了整个电脑行业；2001年，推出iPod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；推出苹果手机。\u003c/p>\u003cp>&nbsp; 所以，乔布斯这段话的结构也是由三要素组成：主题、架子、素材。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】激活经验（显像提问）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; \u003c/strong>&nbsp;现在我们进入【A1】环节，请回忆最近一次自己不满意的临场表达，比如周一上班，你刚到座位上，老板请你去一趟他的办公室，拿出一份投诉信，很生气的问你“小张，您们客户部把客户的货发错了，你给我解释一下？”你，忐忑不安讲了一大堆。老板很无语，认为你在狡辩。\u003c/p>\u003cp>比如说：周末，你和女友约好一起去看电影，临近下班，公司临时召开会议，你没有及时通知女友，见面后女友很生气，质问你，工作重要还是她重要，是不是不爱她了？结果你语无伦次表白半天，无法让女友原谅你。请各位回想一下自己临场混乱表达的一个经历，在小组内分享一下，时间2分钟。\u003c/p>\u003cp>\u003cstrong>【A1案例分享】\u003c/strong>\u003c/p>\u003cp>&nbsp;学习者A：上周五，我们向领导汇报“如何在年底50天内完成软件上市”的汇报PPT，领导说逻辑性太差，我心里挺不服气的，心里想，这份汇报的PPT是我熬夜赶出来的，怎么说，也不可能差。今天听了用于汇报工作的结构化思维模式，我才意识到我的PPT有主题，没有结构，仅仅是一系列产品数据罗列，难怪领导不满意。\u003c/p>\u003cp>学习者B：我现在手头的工作是6D模型的落地，领导交代我很长时间了，因为这个体系过于庞大，我在梳理过程中，进展非常缓慢，领导听了几次汇报，及其不满意。今天通过结构化思维模式，我认识到，这么庞大的体系，在确定主题的前提下，应该先将6D模型的结构梳理出来，然后，在落实具体内容，这样工作的进度会加快很多。\u003c/p>\u003cp>非常好，非常感谢两位的分享!\u003c/p>\u003cp>\u003cstrong>【A1+】\u003c/strong>最后我们进入【A1+】环节，学了今天的片段，了解了结构化思维的三步骤：\u003c/p>\u003cp>第一步：想主题；\u003c/p>\u003cp>第二步：搭架子；\u003c/p>\u003cp>第三步：填素材。\u003c/p>\u003cp>请每个人思考一下将【A1】中的不成功的临场表达，如果你有机会重新面对这样的情景，如何表达才能让对方满意？请应用刚刚学到的结构化思维，花三分钟的时间每个人在小组内都进行表述，然后小组选一个人，将自己的结构化思维的临场表达向大家分享一下，时间控制在四分钟内；\u003c/p>\u003cp>\u003cstrong>【A1+案例分享】\u003c/strong>\u003c/p>\u003cp>&nbsp;好，完成的小组请举手，谁愿意分享一下；\u003c/p>\u003cp>1组的学习者A请分享：\u003c/p>\u003cp>师师：我们考虑到整个项目所花时间大部分在设计阶段，我将上周五给领导汇报的PPT根据结构化思维模式修改如下：\u003c/p>\u003cp>主题：如何在年底50天内完成软件上市\u003c/p>\u003cp>架子：12月10日完成软件的设计\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 12月15日完成软件测试\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 12月18日完成软件交付\u003c/p>\u003cp>素材：设计环节：\u003c/p>\u003cp>&nbsp; &nbsp; 1）&nbsp; 人员由1人，增加到3人，加快设计进度；\u003c/p>\u003cp>&nbsp; &nbsp; 2）&nbsp; 将公司配置最好的3台设备调到项目组，运行效率上进行提升；\u003c/p>\u003cp>&nbsp; &nbsp; 3）&nbsp; 对初步设计进行优化，时间会缩短一半；\u003c/p>\u003cp>按照同样的思路，对软件测试、软件交付的三个素材进行重构，由于时间的关系，我在这里不多讲了。\u003c/p>\u003cp>\u003cstrong>【总结】\u003c/strong>\u003c/p>\u003cp>【结束语】非常好，非常感谢师师的分享，请大家将今天所学的想主题-搭架子-填素材结构化的思维模式应用到日常生活工作中，并持续不断的练习，最终应用自如，成为临场表达和汇报工作的高手。\u003c/p>\u003cp>&nbsp; &nbsp; 由于时间的关系，这个片段的拆解就到这里，有问题下面讨论，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1510492066000,"updated_at":1510547505000,"ria":true},{"id":3949,"topic":"如何做好临场发言","learn_goal":"学会用信息结构化做好临场发言","remark":"工作生活中，你可能会面临这样的情境：被人问到一个问题，你头脑中有很多信息，他们杂乱无章、野蛮生长，你想开口，却不知如何组织语言。或者你很兴奋，滔滔不绝地讲了一大堆，但老板却一脸茫然，觉得你头脑不清晰。\r\n明明有很多见解，为什么就是表达不出来？\r\n表达不好很大原因是大脑没有想清楚，大多思维清晰人的表达都没问题，让我们学会信息结构化，让自己的临场表达更优秀。","level":"TF2-4","duration":60,"status":0,"type":0,"chaishujia":{"username":"Tangcoco","city":"杭州"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"B:我们发现很多时间，我们已经很努力、很拼了，但依然得不到自己预期的成果，这本书可以帮助我们掌握正确的方法快速进阶。\r\nA:《请停止无效努力》这本书就是一本解决问题的工具书，作者不和你讲一堆道理，而是直接上方法，全是干货；比如我们今天拆的片段来自于她关于“结构化表达”中的一小部分内容，她用很少的篇幅就能让你掌握“结构化的思维”，说不定你已经练习“结构化思维”很多时间了，你的小伙伴还没有把《金字塔原理》看完呢。\r\nF:之所以有这样的特点，是因为这本书的作者孙圈圈，原来是位优秀的外资咨询公司项目负责人，她书中的内容基本就是她在工作的总结，她从企业、管理者、咨询师和职场人四种视角去款待人才发展问题，因此不仅实战有用，而且中立客观。","ratings_count":0,"texts":[{"id":6891,"quote":"\u003cp>在本书之前关于结构化思维的文章里，曾经提到过，人类大脑在处理信息时有两个习惯：第一，不能一次太多，因为信息太多会让大脑的负荷过大；第二，喜欢有规律的信息。\u003c/p>\u003cp>临场发言时，我们是有压力的。这种压力，要不让我们的大脑一片空白、胡言乱语，要不让我们的大脑信息泛滥、毫无头绪。这两种情况，听众听起来都会比较痛苦，不明白你到底想表达的是什么、\u003c/p>\u003cp>如果说，有一个清晰的结构，发言就变得容易了。一方面，如果你的大脑是杂乱无章的状态，它可以帮你把信息快速整理并输出；另一方面，如果你的大脑是一片空白的状态，它可以作为提示语帮你联想起一些有用信息。\u003c/p>\u003cp>用结构化思维，帮助你在短时间内更好地沟通，关键是三个步骤：\u003c/p>\u003cp>第一步，想主题：迅速找到一个切人点，第一句就说出自己的观点。\u003c/p>\u003cp>第二步，搭架子：在论证观点时，思考一个结构（时间、空间、程\u003c/p>\u003cp>度），并只说三点，这称为三个&quot;架子”。\u003c/p>\u003cp>第三步，填素材：每个架子里，填充一些事例、数据等，来推进论据向观点靠近。\u003c/p>\u003cp>这里给大家举个例子，乔布斯推出第一款苹果手机时进行过一段演讲，大意如下：\u003c/p>\u003cp>苹果公司是一家革命性的公司。为什么这么说呢？1984年，推出Mar电脑，改变了整个电脑行业；2001年，推出iPod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；2007年，推出苹果手机，我相信它将改变更多行业。\u003c/p>\u003cp>我们来剖析一下这段话的结构，就会是：\u003c/p>\u003cp>主题：苹果公司是一家革命性的公司。\u003c/p>\u003cp>架子：1984年、2001年、2007年。\u003c/p>\u003cp>素材：推出Mac电脑，改变了整个电脑行业；推出iPod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；推出苹果手机。\u003c/p>\u003cp>所以，乔布斯这段话的结构也是由三要素组成：主题、架子、素材。\u003c/p>","explains":"\u003cp>【学习目标】\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够运用演讲信息结构化的方式，快速整理和表达自己的思想。\u003c/p>\u003cp>【片段总结】\u003c/p>\u003cp>这个片段是教给我们一种让自己头脑中的信息结构化，以更好应对临时表达的片段。\u003c/p>\u003cp>【I-这样做的好处】\u003c/p>\u003cp>1、 当你大脑中信息很多且杂乱无章不知从何下手的时候，这种方式能够帮助你快速整理思路，清晰的表达你的想法和观点；\u003c/p>\u003cp>2、 当你容易滔滔不绝讲很多而听众抓不住重点的时候，这种方法可以帮助你快速梳理出重点，能让听众比较快的GET到你想表达的思想；\u003c/p>\u003cp>【I-不那么做的坏处】\u003c/p>\u003cp>当我们被临时问到一些问题的时候，如果不掌握演讲信息结构化，很容易出现这两种情况：\u003c/p>\u003cp>1、大脑一片混乱，很多信息杂乱无章，你想开口却不知从何说起，留下一个表达能力欠佳，难堪大任的印象；\u003c/p>\u003cp>2、很兴奋，滔滔不绝讲了一堆，结果对方一句“讲重点”，让自己蒙圈了，留下一个头脑不清的印象。\u003c/p>\u003cp>\u003cstrong>举例：\u003c/strong>\u003c/p>\u003cp>之前看一档真人相亲节目“相亲才会赢”，女主分别问两个相亲对象，一个相同的问题：“你对自己未来3年的事业规划是怎么样的？”\u003c/p>\u003cp>其中男嘉宾A讲了很多自己的过往经历，和自己周围朋友怎么样，讲了很多，但是从女嘉宾的表情看并没有得到想要的答案，男嘉宾A能感受到女嘉宾的不耐烦就讲得越多。不知大家有没有这样的经历或者看到过其他人这样，越紧张讲越多，但是都没讲点子上。\u003c/p>\u003cp>结果节目事后采访女主的时候，人家说觉得男嘉宾A太夸夸其谈了，比较虚；采访男嘉宾A时，男嘉宾说的是“整个过程很紧张，又怕什么也不说冷场，让对方觉得我对她不重视，所以想什么说什么，最后说什么自己都不知道。”\u003c/p>\u003cp>挺可惜的，因为不能很好的表达自己，错失女神。\u003c/p>\u003cp>同期的另个男嘉宾B就回答的很精彩，给他加分不少。他很简短的讲，“我对自己人生的期望是事业稳健发展，家庭美满，也就是说在事业发展的同时能多照顾家庭；我\u003cstrong>现在\u003c/strong>的岗位是销售主管，收入不错，但是工作特别忙，每一份收入都是在客户这里赚出来的；所以我为了我以后的目标我在\u003cstrong>近两年\u003c/strong>的工作计划是在团队管理和公司经营上多进修和学习，为以后转型为高级管理者做准备，所以这两年我会更忙，又要做现在的工作还要学习提升；我预计\u003cstrong>三年后\u003c/strong>，我可以晋升为经理级的管理者，这样无论收入、工作时间、上升通道都会稳定发展，我也可以更有基础来成家、结婚、要宝宝”。\u003c/p>\u003cp>事后采访女嘉宾，女嘉宾觉得男嘉宾B非常靠谱，而且很有想法，同意和他继续深入了解。其实，男嘉宾B讲得并不多，条件也一般，只是把想讲得东西按照时间搭了一个架子，主题句又博得女主好感而已。\u003c/p>\u003cp>【I-&nbsp;细化原文行动建议的步骤】\u003c/p>\u003cp>第一步，想主题：迅速找到一个切人点，第一句就说出自己的观点。\u003c/p>\u003cp>第二步，搭架子：在论证观点时，思考一个结构（时间、空间、程度），并只说三点，这称为三个&quot;架子”。\u003c/p>\u003cp>第三步，填素材：每个架子里，填充一些事例、数据等，来推进论据向观点靠近。\u003c/p>\u003cp>【I-&nbsp;根据原书中案例脉络，给出了更贴近实际的例子】\u003c/p>\u003cp>比如有一次商务的饭局上，客户方老板问我：“汤老师，为什么选择这份工作，作为女性挺辛苦的”；当时期望一方面真实的表达自己，与客户有更好的关系，另一方面能展示公司的专业形象。所以我就说：\u003c/p>\u003cp>（主题）我期望我的职业能够给我带来独立和自由。我小时候（架子），父母事业做得不错，一直是我的榜样，我心中就埋下了一颗要像父母一样有成绩的人；我上大学后（架子），觉得真正的自由和独立首先要经济独立，只有经济独立才能自己决定人生，所有后来都是靠自己奋斗；后来工作后（架子），我发现独立和自由不仅仅是经济，还有思想和智慧，我们做选择和决定的时候要有经济基础，更需要有思想和智慧做选择。\u003c/p>\u003cp>所以，我的择业观是，工作能够给我带来自由和独立，我目前的工作是顾问公司项目经理，这份工作不仅让我能在杭州立足，也能让我处在不断学习和提升的状态，不断吸收和累积经验和知识。\u003c/p>\u003cp>【不适用的场景】\u003c/p>\u003cp>这里想问下大家，觉得这个方法可能不适合用的场景会在哪里？……什么原因呢？\u003c/p>\u003cp>\u003cstrong>{学习者互动}\u003c/strong>\u003c/p>\u003cp>1、和亲密的人在一块不太好，觉得太正式。\u003c/p>\u003cp>本身自己不知道的内容、专业性的问题，请不要强撑，坦承不知会更好，不要给人留下不懂装懂、虚张声势的坏印象。\u003c/p>\u003cp>【I-&nbsp;异议的预防讲解】\u003c/p>\u003cp>1、 可能你会觉得这个方法很好，实际运用中感觉还是不是很熟练。\u003c/p>\u003cp>这是一个需要不断练习累积的技能。一开始我学结构化的时候，看着很兴奋觉得自己掌握这个方法了，\u003c/p>\u003cp>马上能让思想焕然一新的感觉，实际上在工作中经常打回原形，事到临头都忘了。后来回来复习，发现书中很重要的提到要不断的练习和累积，所以我们也一样，多练习、多累积。\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>1、接下来请每位小伙伴思考下，在过去的2周中，需要临场发表自己观点而你又觉得那时你可以表现得更好的场景是什么？（比如：领导问你竞争对手推出新品，你怎么看？朋友问你“拆书帮”值不值得参加？伴侣/爱人/家人问你你目前工作给你的意义是什么？）当初你是如何表达自己的观点和思想的，请简单记录下，给大家2分钟时间。\u003c/p>\u003cp>\u003cstrong>{学习者互动}\u003c/strong>\u003c/p>\u003cp>1、上一周领导问题，小张，最近工作怎么样？我的回答是：还好，就是客户不太配合。\u003c/p>\u003cp>2、昨天在我们2018年防晒产品策略会议上，老板问道，蒋工你谈谈对2018年防晒产品的看法？我的回答是：2018年防晒产品竞争格局比较复杂，除了传统的竞争对手，还有海淘的欧美品牌，和一直比较活跃的日韩品牌，各种路数都不同......\u003c/p>\u003cp>2、如果结合我们今天刚刚学习到的“想主题+搭架子+填素材”，老天给你一个月光宝盒回到那个时间，你可以怎么讲？给大家2分钟时间，梳理下。\u003c/p>\u003cp>3、我们请一位小伙伴分享下你刚才重新组织过的发言，分享结构是：过去我在什么场景下有一次临场发言；当初我是怎么说的；通过今天学习，我可以这样说会更好。\u003c/p>\u003cp>\u003cstrong>{学习者互动}\u003c/strong>\u003c/p>\u003cp>1、上一周领导问题，小张，最近工作怎么样？\u003c/p>\u003cp>优化回答：最近工作开展顺利，学到很多东西：第一，公司培训比较完整，基本工作碰到的问题都已经提前培训；第二，师傅是很细心的人，面面俱到的照顾；第三，实践中增长了经验，经常遇到客户不配合的问题，在一个个解决过程中累积了经验。\u003c/p>\u003cp>2、2018年防晒产品策略会议上，老板问道，蒋工你谈谈对2018年防晒产品的看法？\u003c/p>\u003cp>答：我们2018年防晒产品策略以明星产品为主打，第一，从消费者角度来讲，XXXX（应学习者要求，涉及商业机密不输入内容）；第二，从渠道门店角度来讲，XXXX（应学习者要求，涉及商业机密不输入内容）；第三，从我们厂家角度来讲，XXXX（应学习者要求，涉及商业机密不输入内容）；\u003c/p>\u003cp>拆书家回应：非常棒，掌声给到蒋工，蒋工运用了一个非常好的三脚架来阐述这个问题。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":6892,"quote":"\u003cp>架子指的是：提炼出来的结构关键词。架子一方面充当提示语，有了它，你不至于一点都说不出来，另一方面又是帮你梳理信息的工具。\u003c/p>\u003cp>大致来说，架子不外乎以下类型：\u003c/p>\u003cp>&nbsp;&nbsp; 类型一，时间架：按照时间的顺序，把脑子里的信息整理输出，举例如下：\u003c/p>\u003cp>问：你是做什么的?\u003c/p>\u003cp>答：我在一家外资企业做员工培训工作。\u003c/p>\u003cp>问：你平时都做些什么呢?\u003c/p>\u003cp>答：总体来说，我的工作是保证培训工作的顺利进行。培训前，我会联系讲师、学员、酒店等确认准备工作。培训中，我会在现场进行协调、为讲师和学员服务。培训后，我会通过学员工作场所访谈等方式跟进培训效果，今后改进。\u003c/p>\u003cp>培训前、培训中、培训后就是按照时间的顺序来说话。\u003c/p>\u003cp>时间类的架子，其实不局限于时间这个狭窄的概念，还包括一切有先后或因果顺序的结构。因此，时间类的架子可以分成以下三类：\u003c/p>\u003cp>代表时间的词：过去、现在、将来；上午、中午、下午；一点、两点、三点。\u003c/p>\u003cp>代表阶段的词：研发、试产、投产；少年、青年、壮年；前期、中期、后期。\u003c/p>\u003cp>代表步骤的词：第一步、第二步、第三步；流程一、流程二、流程三；首先、然后、最后。\u003c/p>\u003cp>我们平时可以有意识地积累这些架子，脑子里积累的架子越多，整理思路的速度就越快。\u003c/p>\u003cp>时间架几乎可以用来说任何话题，应用很广，几乎是万能法。如果以后在紧急场合让你说话，一下子想不出来怎么说，那就思考时间架法，它一定会让你说出一些话来，因为架子特别多、特别好找。\u003c/p>\u003cp>类型二，空间架法：按照地点的顺序整理思路\u003c/p>\u003cp>之前关于培训的例子，如果不按照培训前、培训中、培训后来讲，按照办公室、酒店会议厅、学员工作场所这三个地点来讲，也同样可以表达出意思。\u003c/p>\u003cp>用空间架的好处是，听众脑子里很容易出现具体场景，有视觉化效果，能够更好理解你说话的意思。\u003c/p>\u003cp>举例如下：\u003c/p>\u003cp>全国各地的人们都合家团圆，一起喜迎春节。\u003c/p>\u003cp>广州舞龙舞狮。北京全家一起包饺子。南京写春联以及贴春联。\u003c/p>\u003cp>它的结构也是一样的：主题、架子、素材。只是架子是一些代表地名的词。\u003c/p>\u003cp>接下来给大家一些空间法的架子：\u003c/p>\u003cp>代表地理位置：美洲、欧洲、亚洲；北京、上海、广州；实验室、流水线、4S店。\u003c/p>\u003cp>代表视觉区域：外壳、屏幕、键盘；脑、肩、心。\u003c/p>\u003cp>类型三，三角架：按照三个方面的顺序整理思路\u003c/p>\u003cp>看如下例子：\u003c/p>\u003cp>斯滕伯格的爱情三元论：激情、亲密和承诺。\u003c/p>\u003cp>按照激情、亲密、承诺的顺序说话，这种方式叫做三角法、\u003c/p>\u003cp>三角法的架子通常有以下几类：\u003c/p>\u003cp>代表三个方面(三件事)的词：语法、修辞、逻辑；提高沟通效果、提高影响力、提高印象分；多学、多听、多练。\u003c/p>\u003cp>代表三类人的词：孩子、丈夫、自己；客户、员工、股东；领导、同事、下属。\u003c/p>\u003cp>三角法的最大特点是：能把一件事情客观地说清楚。\u003c/p>\u003cp>用三角法说话，可以起到客观全面的效果。但三个架子必须是具有高度代表性和概括的三个架子，这样才能把主题撑起来。\u003c/p>\u003cp>所以，三角法经常用来说一些严肃的话题，能体现出你的水平和深刻见解的话题。\u003c/p>\u003cp>用这三种方法找架子的时候，可以尽量使用MECE原则，即，架子之间相互独立、完全穷尽、这个原则在本书之前讲结构化思维的时候也提到过，这样会给人逻辑更加严密的感觉。\u003c/p>","explains":"\u003cp>【片段二学习目标】\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够学会不同架子的应用场景，并且结合片段一的内容，遇到临场发言的情况能够得体的表达自己的观点和想法。\u003c/p>\u003cp>【片段总结】\u003c/p>\u003cp>架子是我们整个思维当中的一个个房间，把我们要表达的内容分门别类的放在不同的房间，让我们拿（发言）的时候很容易取用，方便让你梳理信息，还避免让自己一句话也讲不出来，让听的人又很容易理解。架子也不是凭空就获得的，一方面靠自己平常不断累积，另一方面我们今天片段从三个方面为我们整理了20个架子，让我们至少存了点基本的东西，了解架子的应用场景，在这个基础上不断累积整合。\u003c/p>\u003cp>【I-这么做的好处处】 &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>1、当一下子不知道如何表达自己观点和想法的时候，有一个“架子”相当于为你的思想搭建了一个框架，你可以自如和有序的输出；\u003c/p>\u003cp>2、当你脑海中信息比较多且杂乱的时候，一个“架子”可以帮助你有序的输出信息，让你想表达的内容没有重复和遗漏；\u003c/p>\u003cp>【I-不那么做的坏处】\u003c/p>\u003cp>1、如果你不尝试着去学习和累积不同的架子来应对各种复杂问题，会让你失去一条比较有效、高效的构建自己知识框架的道路；\u003c/p>\u003cp>案例（反面）：\u003c/p>\u003cp>比如说我，我在培训行业有近10年的工作经历，在顾问&amp;培训交付、实施上有三年以上的直接工作经验，交付过5个50万+的顾问&amp;培训项目，经验非常丰富，客户满意率很高，但是我没有去构架自己工作内容的架子，也没有深度研究和累积培训项目交付理论上已经有的“架子”，都是凭感觉应该怎么做了。最后导致后果是，第一，没有培养优秀的下属；第二，当被客户临时问到一个问题时用本能反应回答，很容易遗漏信息（双反的：客户想传递的信息，我们应该传递的信息）；第三，不能推动公司顾问&amp;培训项目交付品质更上一层楼。\u003c/p>\u003cp>案例（正面）：\u003c/p>\u003cp>下一段《横向领导力》就是一个正面案例。\u003c/p>\u003cp>【关联到原文知识点的回应或反馈&amp;I-根据原书中案例脉络，给出了更贴近实际的例子】1、现在我们对片段有了一个大致的了解，现在我有个小案例请大家帮忙：有个下属（或朋友）去负责一个跨部门项目，需要协调很多不是本部门，甚至级别比他高的同事，他遇到了很多困难，感觉工作都没有办法推进了，他来向你求助，你会怎么对他讲？\u003c/p>\u003cp>2、&nbsp;我们请位同学分享下？\u003c/p>\u003cp>\u003cstrong>{学习者分享}\u003c/strong>\u003c/p>\u003cp>（问了一些基础问题）我会和他讲：你要选对时间和对方谈这个问题，然后你要和他一起明确目标，第三你要获得老板的正式任命...\u003c/p>\u003cp>3、&nbsp;分享的非常好，......\u003c/p>\u003cp>4、&nbsp;我以前碰到这种情况，会从他项目小组的每个人开始和他讲，这个人要XX合作，那个人要XX合作，一派大姐风范啊。那大家觉得这么做有什么的问题吗？\u003c/p>\u003cp>\u003cstrong>{学习者分享}\u003c/strong>\u003c/p>\u003cp>不了解实际情况、本身对这块工作不熟悉.....\u003c/p>\u003cp>5、大家讲得都很棒，就我自己来讲，最可怕得是都要对情况很了解的前提下，我如果不了解呢？对团队中本身的成员都不熟悉呢？对这个问题我也不知怎么办呢？\u003c/p>\u003cp>看完这本书之后，我了解到要不断我自己累积“架子”，这个问题我专门去看了《横向领导力》这本书，在那里找到一个没有任命和职位如何带领团队的架子\u003cstrong>“培养技能-明确目标-影响他人”\u003c/strong>，找到这架子我好兴奋，以后再遇到类似情况，我就可以这讲：“小陈，要带领一群人完成一项工作，有三个关键，培养技能-明确目标-影响他人（有做一些详细解释下），你看看，你可能在哪里没有关注到啊”，画风变成我引导他去思考和找问题了。是不是很酷？这就是架子的意义和功效。\u003c/p>\u003cp>【1-细化原文行动建议的步骤】\u003c/p>\u003cp>从原文中总结提炼面对一个问题，如何提炼和对应合适的“架子”\u003c/p>\u003cp>1、根据问题及发言要达成的目的判断是用时间架、空间架、还是三角架；\u003c/p>\u003cp>2、在相应架子下面找能解决发言内容的分类；\u003c/p>\u003cp>3、&nbsp;选择关键词套入发言；\u003c/p>\u003cp>4、事后去累积和学习相应“架子”，为以后做准备。\u003c/p>\u003cp>TIPS:时间架能万用、空间架有画面、三角架展深度。\u003c/p>\u003cp>【I-&nbsp;异议的预防讲解】\u003c/p>\u003cp>1、是不是在选择架子的时候一定要走这三个步骤呢？\u003c/p>\u003cp>一开始学习的时候可以，但是随着不断学习和练习的深入，架子的选择也就在电光火石间完成了，毕已经变成身体反应，所以不是需要每次都走完三步。\u003c/p>\u003cp>【为帮助大家记忆增加的导图】\u003c/p>","interaction":"\u003cp>【A3】重点练习“架子”使用\u003c/p>\u003cp>1、我们刚刚学习了如何快速的运用结构，梳理自己的思维，以出色的做临场表达，现在一起来做一个演练。场景如下：小来是公司的电脑销售，今天来了一对夫妻买电脑，男士看上去一位是专业、严谨做研究的人，女士看上去则是一位非常重视视觉感受的人，当你刚想去介绍他们看中的一款电脑的指标的时候，男士突然就问：“你直接告诉我，我为什么要买你们这台电脑？”女士也认同的点点头，笑嘻嘻的看向小来。小来一下子就蒙了，现在请你用刚才学的如何针对一个问题搭架子的片段，帮助一下小来。给大家3分钟的时间，小组内讨论下。\u003c/p>\u003cp>2、（6分钟）现在我们请1个小组的小伙伴来演绎下这个场景，一位伙伴做小来，另外两个伙伴分别做这对夫妻，请把你们讨论的思路，来表演下。\u003c/p>\u003cp>\u003cstrong>{学习者表演（简述）}（A:卖电脑；B：采购者）\u003c/strong>\u003c/p>\u003cp>A：你好，我们这个电脑是.....\u003c/p>\u003cp>B：你直接告诉我，我为什么要买你们这台电脑？\u003c/p>\u003cp>A：（真诚而坚定）我们这个电脑有如下优点：第一，性价比很高，稳定、高性能、实惠的价格，在这个价位上能够让你满足办公的所有要求，而且非常安全稳定，也就是TA了；第二，你看的外观，金属磨砂手感，一体成型机身，轻薄漂亮，颜值杠杠的；第三，你看的键盘设计符合人体工学设计，带背光，无乱是你长时间输入还是看电影，都有很好的体验。\u003c/p>\u003cp>B：你说的很好，就这个了。\u003c/p>\u003cp>\u003cstrong>两个片段综合A\u003c/strong>\u003c/p>\u003cp>【A2】（两个片段内容综合练习）\u003c/p>\u003cp>1、（2分钟）如果未来你在工作生活中，会突然被要求对某件事/某个问题发表想法的场景可能会是哪个？比如：面试、相亲、领导谈话、客户访谈、产品介绍……\u003c/p>\u003cp>&nbsp; 请你花一分钟思考下\u003c/p>\u003cp>2、（1分钟）在这个场景下，可能被问到的问题是什么呢？请简单记录下。\u003c/p>\u003cp>3、（5分钟）请在这个场景和问题下，用“主题+架子+素材”的方式加工一个具体的发言，今后能够在这样场景下，快速准确的表达自己的观点和想法。\u003c/p>\u003cp>4、（2分钟）我们请一位同学来分享下。\u003c/p>\u003cp>\u003cstrong>{学习者分享}\u003c/strong>\u003c/p>\u003cp>第四季度工作会议的时候，汇报自己的工作目标：第四季度销售业绩预估是200万，又一下支撑：第一自己的成熟度的角度来讲，现在已经算是一个老的销售了，销售技术掌握的也比较到位；第二从客户开发看，目前在浙江区域已经开发15家客户；第三从业绩储备来看，目前已经储备50万的销售待成交，所以完成200万没有问题。\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>拆书家：我们给苹苹掌声，讲得非常好，清晰完整。\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>在这两个片段告诉我们可以用“主题+架子+素材”这种结构化思维方式在短时间组织自己的语言发表的观点和想法，同时在日常的工作、生活和学习中多累积各种解决问题的架子，从而让自己可以自己思维更清晰、表达更有力。训练自己的思维结构化，是职场人士最值得训练的技能之一，在这里投入训练回报远远大于你的想象，加油。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1509590019000,"updated_at":1509590019000,"ria":true},{"id":3944,"topic":"如何快速发现自己的天赋","learn_goal":"明确天赋的概念及特征，并能运用三种方法找到自己的天赋所在","remark":"每个人都有自己的相对天赋，正确运用天赋，可以让我们事半功倍。然后问题来了，你对自己的天赋是否有所了解？你的天赋是否用在了合适的领域？想知道答案，本周六来拆书帮古城分舵一起学习吧！","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"张诗悦","city":"西安"},"club":{"name":"西安古城分舵","city":"西安"},"prologue":"嘿，大家好，我是诗悦，我又来了，先给大家分个组，还按我们上轮分的继续进行好吧？（F）OK，那这次为大家拆解的原文片段来自于这本《请停止无效努力-如何用正确的方法快速进阶》，作者是孙圈圈，曾任全球顶级咨询公司咨询总监,现为移动学习内容品牌【圈外】的创始人兼CEO。这本书呢，讲得是努力的方法论，全书围绕着职业发展和个人提升所需的方法论展开，分为发掘天赋、提升能力、选择平台、回归自己等几大部分，（A）是市面上为数不多的写“术”的成长类书籍，它也许不会让你鸡血满满、精神倍增，但却极具实操性，特别大的一个亮点是每一节结束之后都有本节内容的精彩提炼和后续练习的具体做法，是一本可以让你少走很多弯路的、非常接地气的书，（B）如果你想更加清晰的认识自己，准确的定位自己，掌握学习和思考的有效模式，找到努力的正确姿势，都可以看看这本书，相信你一定会有所收获的！","ratings_count":0,"texts":[{"id":6887,"quote":"\u003cp>接下来就正式进入我们的拆书时刻了，下面我们首先来进行R环节，阅读原文片段，下面请大家用1-2min的时间仔细阅读手上的这个片段，看完之后举手示意我一下:\u003c/p>\u003cp>天赋包括能力天赋和意愿天赋，也就是说，只是“我很有乐感”这并不是天赋，因为你不一定有意愿去从事音乐创作。所以，真正的天赋，是能够让你感觉自己更强大的东西。因此，天赋有四个特征，简称为“SIGN”：\u003c/p>\u003cp>\u003cstrong>特征一，自我效能（Self\u003c/strong>\u003cstrong>－ efficacy\u003c/strong>\u003cstrong>）。\u003c/strong>对自己可以完成某项工作或任务的自信程度。比如，每当面对细节琐碎的事情时，还没开始，我就觉得自己做不好，但每当要我去解决一个难题时，我会充满信心。\u003cstrong>特征二，本能（\u003c/strong>\u003cstrong> Instinct\u003c/strong>\u003cstrong>）。\u003c/strong>当你还没开始做这件事的时候，你就迫不及待地想要开始了。比如，当我把整理的东西决定要开发成为课程、教给别人的时候，我会感到异常兴奋。\u003cstrong>特征三，成长／专注（\u003c/strong>\u003cstrong> Growth\u003c/strong>\u003cstrong>）\u003c/strong>。当你做这件事的时候，你充满好奇，十分专注，时间过得很快。比如，当我为了写文章，去阅读大量相关资料的时候，一上午对我来说，就跟２０分钟一样。\u003cstrong>特征四，满足（\u003c/strong>\u003cstrong> Needs\u003c/strong>\u003cstrong>）。\u003c/strong>做完这件事之后，就算感到疲劳和困倦，你依然会有满足感。比如，每次写文章的时候，我都累到不想再继续了，然而写完之后，又觉得充满了成就感。\u003c/p>\u003cp>从这四个特征出发，我们来看，可以有哪些方法，来帮你发现天赋。\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong>\u003cstrong>日记\u003c/strong>\u003c/p>\u003cp>既然天赋能让你感觉自己更强大，那么你需要记录：在哪些瞬间，你感到强大？具体做法是：找出一周时间，在这一周里，记录自己的每个瞬间，包括兴奋、有成就感、愉快的瞬间，以及沮丧、无助、反抗的瞬间。不仅仅是工作相关，还有业余生活的部分。\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong>\u003cstrong>问自己\u003c/strong>\u003c/p>\u003cp>如果你的阅历已经够丰富，并且也一直关注自己的行为、常常反思，那么，除了记录瞬间，也可以通过问自己一些问题，帮自己找到天赋。当然，问题还是围绕着天赋的四个特征。第一类问题：自我效能相关\u003c/p>\u003cp>　　你认为，自己能够教别人什么？或者，别人常常向你请教什么？\u003c/p>\u003cp>　　你跟他人聊天的时候，倾向聊什么？以及，聊什么话题你会更有自信？\u003c/p>\u003cp>　　你在做什么事情的时候，不会感到焦虑和担心？\u003c/p>\u003cp>第二类问题：本能相关\u003c/p>\u003cp>　　你在做什么事情的时候，很少拖延？\u003c/p>\u003cp>　　长时间休假后，你最想念工作的哪个方面、哪个内容？\u003c/p>\u003cp>　　你宁愿放弃休息时间，也要做的事情，是什么？\u003c/p>\u003cp>第三类问题：成长／专注相关\u003c/p>\u003cp>　　有什么事情，让你沉浸其中忘记吃饭／睡觉？\u003c/p>\u003cp>　　你在做什么事情的时候，会暂时忘记刷社交网络？\u003c/p>\u003cp>　　你在做什么事情的时候，不容易感到疲倦和厌烦？\u003c/p>\u003cp>第四类问题：满足相关\u003c/p>\u003cp>　　过去的工作和生活中，有什么能让你获得巨大的成就感和满足感？\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong>\u003cstrong>问他人\u003c/strong>\u003c/p>\u003cp>　　我们之前说过，天赋是天生的、下意识的，所以很多时候，你很难辨别出来。但是从别人的角度，他们会更容易帮你辨别。所以，把这些问题发给你亲近的朋友或者同事，让他们帮你回答：\u003c/p>\u003cp>　　你觉得，我身上有什么不同于别人的特质？\u003c/p>\u003cp>　　你最欣赏或者佩服我的方面是什么？\u003c/p>\u003cp>　　在你看来，我做什么事情的时候，看起来最兴奋？\u003c/p>\u003cp>你曾经看到我做过哪件事情，让你印象深刻？\u003c/p>\u003cp>在以下这些方面，你觉得我哪些更加擅长？思维方式：条理清晰、逻辑严密、脑洞很大、专注专业：沟沟通协调：化解冲突、争取资源、知人善任；计划执行：执行力强、追求完美、目标导向，等等。你会发现，你眼中的自己，和别人人眼中的自己，常常有很大的差异。\u003c/p>","explains":"\u003cp>好，所有的小伙伴都已经读完了，进入到我们的I环节，拆书家的引导讲解，也就是用自己的语言来重新复述原文片段的内容。\u003c/p>\u003cp>\u003cstrong>（What\u003c/strong>\u003cstrong>）\u003c/strong>每个人都有自己相对的天赋，正确的运用天赋可以让我们事半功。\u003cstrong>（\u003c/strong>\u003cstrong>Why\u003c/strong>\u003cstrong>）\u003c/strong>但是发现天赋并不是一件容易的事情，因为天赋是天生的、是我们下意识的反应，总是自然到让我们意识不到它的存在，\u003cstrong>不这么做的坏处：\u003c/strong>可是如果我们不能很准确的找到自己的天赋所在，就会浪费大量的时间做着我们并不擅长的事情，也就很难做出成绩或感到快乐。\u003cstrong>（\u003c/strong>\u003cstrong>How\u003c/strong>\u003cstrong>）\u003c/strong>那如何快速发现自己的天赋呢？其实有3个非常好的办法——\u003c/p>\u003cp>1.写日记记录自己的内在感受，具体方法是在一周内，记录下在工作或者生活中有哪些瞬间让我们感到强大或者沮丧，然后去对照天赋的几个特征，再筛选出跟我们天赋相关的瞬间，这样来总结、发现自己的天赋；\u003c/p>\u003cp>2.问自己有关效能、本能、成长/专注和满足的问题；什么事你去做会觉得信心满满？什么事还没开始去做你已经迫不及待？什么事你做得时候能够全神贯注觉得时间过得特别快？什么事你完成之后即使很累还是会觉得非常满足？\u003c/p>\u003cp>3.问别人有关自己的特质的问题，正所谓旁观者清，借助别人对我们的评价来帮助我们更好的认识自己。\u003c/p>\u003cp>\u003cstrong>适用边界：\u003c/strong>当然这些办法使用时也些需要注意的事项，对方法一和方法二使用时你首先要排除和欲望、和享受相关的事，比如你不能写日记写今天朋友请我大餐我感到很开心，我今天捡到200块钱我感到特兴奋，你问自己我什么时候感到最满足，然后你回答说我睡到自然醒我特别满足，这样对于我们找天赋是没有任何意义的；第三个问他人你也要去问一些和你比较亲近的人，他们不仅对你很熟悉而且能够对你做出客观的评价。\u003c/p>\u003cp>\u003cstrong>举个\u003c/strong>\u003cstrong>栗子：\u003c/strong>\u003c/p>\u003cp>举一个我自己的例子吧，小学的时候我们班表演一个话剧，我一开始被分到了伴舞组，但是几次排练下来我依旧记不清舞蹈动作，总是跳错，还因为受到了老师的批评和同学们暗地里的嘲笑，我自己压力也很大，觉得特别沮丧，一度想退出演出。但有次排练，念旁白的同学有事没有来老师就临时让我去念，没想到我念得特别好，深情并茂的，而且居然早都已经把词记到了心里，于是老师就换了我来念旁白，结果表演特别成功，老师和爸妈特别认可，我自己也特别有成就感。从那时候开始，我就发现我对于语言类的表现形式特别喜欢，之后我也有刻意去练习自己的语言表达能力，这也让我现在成为了一名高级讲师。所以大家看，其实我小的时候是无意识的按照这种方法去发现了自己这方面的天赋的，当时比赛完老师的认可和爸妈的表扬就属于方法三问他人，得到他人的评价和反馈；我自己做这些事获取了满足感和成就感就属于方法二问自己，这些都是发现自己天赋很好的一些办法。\u003c/p>","interaction":"\u003cp>&nbsp; &nbsp;&nbsp;那接下来我们进入到A1环节，就是激活大家过往的经验，大家想想看自己有没有这样的经历，尤其这两年知识付费时代的来临，像斜杠青年这样的词都很火，你有没有过比如说看到彭小六靠阅读火了起来于是自己也开始啃起书本来，但是没看两页就读不下去了？看到弗兰克靠写作创办了训练营自己也开始动手写文章，结果把自己搞得非常痛苦头发也大把大把的掉写出了的文章也没几个人点赞？看到秋叶大叔靠做PPT课程火了，自己去买了最新的OFFICE10软件开始苦练技巧，结果时至今日一个像样的PPT主题都没做出来？请想一想，最近一次遇到这种情况是什么时候？什么事情？你是怎么面对的？请在小组内分享一下。\u003cbr>&nbsp; （小组讨论中）......\u003c/p>\u003cp>&nbsp;&nbsp;好，时间到，我们请一位小伙伴来分享一下你刚才在小组内讨论的过往的案例。\u003c/p>\u003cp>【A1】:学习者若愚——大学毕业的时候看到当年明月出的《明朝那些事儿》，觉得人家写的特别的好，自己从小也酷爱历史，也有一些文字功底，就也想尝试写写这种书籍，当自己把这个想法给家人朋友一说时他们都不太支持，觉得写书多不靠谱的事，当下最主要的还是找个好工作，自己那时也不确定自己到底能不能写好，最后就不了了之了。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;好，谢谢这位伙伴的分享，关于写作的事例，那现在进行我们本次拆书最后一个环节，也就是A1+环节，请在场的学习者，也就是大家反思加工经验。请想想看，根据刚才拆页当中三个“快速发现自己天赋的方法”，再回到之前的那个时候，遇到当时想做、想学的事情但又有些犹豫迷茫，我们可以怎么做？给大家5分钟的时间在组内分享一下。\u003cbr>&nbsp; （小组讨论中）......\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;好，时间到了，我们还请刚才这位小伙伴来说说再回到你毕业时有想写一部历史类书籍的想法时，你会怎么做？\u003c/p>\u003cp>【A1+】:学习者若愚——再回到那个时候，我就先坚持写上一个星期，每天都写，然后记录下在这个过程当中让自己感到强大、兴奋的瞬间，然后去跟天赋的四个特征对比，看看自己到底是不是写作；第二就是问自己，有没有信心去写一本书？每天要写的时候有没有发自内心迫不及待的想去写这本书？写得时候能不能保持全神贯注的状态？写完一节后自己觉得满足吗？之后花费的心血琢磨一词一字都值得吗？第三就是把写出来一部分书稿拿去让这方面前辈，自己的编辑朋友和亲朋去评价，自己写的怎么样？自己的性格适不适合写书？如果最后答案都说明自己是有写作这个天赋的，自己就坚持把这本书写完，不管之后能不能出版，销量如何，如果结果说自己不适合写作，那就果断放弃这个想法，再也不想了，然后再用这三个方法去挖掘一下自己还有什么其他天赋。\u003c/p>\u003cp>&nbsp; 好，谢谢这位伙伴，他先是用这三个方法去判断自己到底有没有写作这个天赋，还打算再用这三个方法发掘一下其他天赋，可以说用的已经很到位了哈！那我今天的拆书就到这里，也希望对其他的小伙伴都能有所启发和思考，谢谢大家的配合！\u003cbr>\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1509500472000,"updated_at":1509500570000,"ria":true},{"id":3848,"topic":"如何运用结构化思维做好临场发言","learn_goal":"够运用结构化思维快速整理自己想表达的，让自己能够做好临场表达","remark":"由3个拆书家分别做不同主题的拆书。","level":"TF3-2","duration":25,"status":0,"type":0,"chaishujia":{"username":"Tangcoco","city":"杭州"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"事件场景：你是否在工作生活中遇到过这样的情境：被人突然问道一个问题，比如：老板说：小王，最近客户满意度下降了，你怎么看？\r\n提问：遇到这类情况你一般的表现是怎么样的？顿时哑口无言，大脑一片空白，思维杂乱无序，不知从何说起？或者滔滔不绝但是听众一脸茫然，不悦的说：讲重点......\r\n影响：如果我们在生活工作中，遇到这种即兴表达自己想法的情况，不能从容且牛X的吸个粉，那么就只能一次次的失去人生晋级的好机会；\r\n解决：这本书提出的思路你讲不清楚，一般都是你想不清楚，先让自己的信息结构化，演讲自然就有了。这里演讲是指你向他人表达，包括1V1。","ratings_count":0,"texts":[{"id":6782,"quote":"\u003cp>如何让你的演讲信息结构化\u003c/p>\u003cp>在本书之前关于结构化思维的文章里，曾经提到过，人类大脑在处理信息时有两个习惯：第一，不能一次太多，因为信息太多会让大脑的负荷过大；第二，喜欢有规律的信息。\u003c/p>\u003cp>临场发言时，我们是有压力的。这种压力，要不让我们的大脑一片空白、胡言乱语，要不让我们的大脑信息泛滥、毫无头绪。这两种情况，听众听起来都会比较痛苦，不明白你到底想表达的是什么、\u003c/p>\u003cp>如果说，有一个清晰的结构，发言就变得容易了。一方面，如果你的大脑是杂乱无章的状态，它可以帮你把信息快速整理并输出；另一方面，如果你的大脑是一片空白的状态，它可以作为提示语帮你联想起一些有用信息。\u003c/p>\u003cp>用结构化思维，帮助你在短时间内更好地沟通，关键是三个步骤：\u003c/p>\u003cp>第一步，想主题：迅速找到一个切人点，第一句就说出自己的观点。\u003c/p>\u003cp>第二步，搭架子：在论证观点时，思考一个结构（时间、空间、程\u003c/p>\u003cp>度），并只说三点，这称为三个&quot;架子”。\u003c/p>\u003cp>第三步，填素材：每个架子里，填充一些事例、数据等，来推进论据向观点靠近。\u003c/p>\u003cp>这里给大家举个例子，乔布斯推出第一款苹果手机时进行过一段演讲，大意如下：\u003c/p>\u003cp>苹果公司是一家革命性的公司。为什么这么说呢？1984年，推出Mar电脑，改变了整个电脑行业；2001年，推出iPod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；2007年，推出苹果手机，我相信它将改变更多行业。\u003c/p>\u003cp>我们来剖析一下这段话的结构，就会是：\u003c/p>\u003cp>主题：苹果公司是一家革命性的公司。\u003c/p>\u003cp>架子：1984年、2001年、2007年。\u003c/p>\u003cp>素材：推出Mac电脑，改变了整个电脑行业；推出iPod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；推出苹果手机。\u003c/p>\u003cp>所以，乔布斯这段话的结构也是由三要素组成：主题、架子、素材。\u003c/p>","explains":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【目标】\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够运用结构化思维快速整理自己想表达的，当对自己遇到临时发言的时候能快速表达自己的思想。\u003c/p>\u003cp>\u003cstrong>【量表题】\u003c/strong>\u003cbr>\u003c/p>\u003cp>填写说明：下面每道题一共5分，你觉得自己非常符合5分，非常不符合1分，根据程度选中间2-3分；\u003c/p>\u003cp>1、我在临场发言和沟通上，常常觉得脑子一团乱麻，不知从何说起。\u003c/p>\u003cp>2、我在临场发言和沟通上，经常滔滔不绝讲了很多，总是觉得对方没有听明白我讲得重点。\u003c/p>\u003cp>3、我在与人沟通上，常常觉得，明明有很多事实和数据，却很难说服对方。\u003c/p>\u003cp>说明：\u003c/p>\u003cp>3-6分：说明你有非常强大的临场反应及结构化的思维，今天的拆书可以帮你更好总结自己的经验，帮助他人也获得这方面的成长；\u003c/p>\u003cp>7-12分：说明你在临场发表自己想法这块不会给你减分，但是也并没有给自己很多加分，你可以做得更好，那么今天的拆书活动会让你找到一些法门，期待吧...\u003c/p>\u003cp>12-15分：恭喜你，你又找到一个让自己更优秀的地方了，其实临场表达都有套路的......\u003c/p>\u003cp>\u003cstrong>【具体方法】\u003c/strong>\u003c/p>\u003cp>第一步，想主题：迅速找到一个切人点，第一句就说出自己的观点。\u003c/p>\u003cp>第二步，搭架子：在论证观点时，思考一个结构（时间、空间、程度），并只说三点，这称为三个&quot;架子”。\u003c/p>\u003cp>第三步，填素材：每个架子里，填充一些事例、数据等，来推进论据向观点靠近。\u003c/p>\u003cp>*简单互动：\u003c/p>\u003cp>1、大家觉得想主题，要在很快的时间内找一个切入主题，自己的脑海中又有很多的观点在打架怎么办？深思熟虑后再讲还是快速的凭直觉选？\u003c/p>\u003cp>\u003cstrong>【学员互动】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>{\u003c/strong>\u003cstrong>学员回答}\u003c/strong>\u003c/p>\u003cp>学员A：我觉得应该深思熟虑后再回答；\u003c/p>\u003cp>学员B：凭直觉选主题切入；\u003c/p>\u003cp>学员C：看在什么场合讲，如果正式场合还是需要深思熟虑的。\u003c/p>\u003cp>拆书家引导：大家说得都不错，从大家刚才分享的我们能不能统一下，考虑的时间能不能太长？不能！最多3-5秒。可以有一句话过渡，就要给出主题，如果实在选不清楚，可以凭直觉选一个。\u003c/p>\u003cp>2、关于架子：大家想到的时间类架子有哪些？\u003c/p>\u003cp>\u003cstrong>{\u003c/strong>\u003cstrong>学员回答}\u003c/strong>\u003c/p>\u003cp>学员A：前、中、后；过去、现在、将来；\u003c/p>\u003cp>学员B：上午、中午、下午；以前、现在、以后；\u003c/p>\u003cp>拆书家引导：都很好，还有什么？比如阶段：研发、试产、投产；比如步骤：第一步、第二步、第三步。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】\u003c/strong>\u003c/p>\u003cp>我们刚刚学习了如何通过把脑海中的信息结构化，让自己可以快速的做临场表达，那么我们来一起做一个演练，请大家认真听一下演练的场景：中秋刚过，一个团圆的日子小王却一个人陪父母，被各种逼婚，自己也觉得应该找个伴了，这不，单位的张大姐帮安排了一个相亲，妹子/帅哥人也不错，前面聊着感觉他喜欢独立、有思想的另一半，想要给对方留个好印象……对方问我的择偶观/择业观，还一脸认真的想听我好好讲，让我们用今天学得信息机构化的方法，征服她/他。既要有主题，又要有三个架子，每个架子后面展开一定素材做解释说明。给大家3分钟时间，先选个主题，再思考下怎么讲，我们等下请两组伙伴来表演，双方做相亲对象来演练一下。\u003c/p>\u003cp>\u003cstrong>{示范\u003c/strong>\u003cstrong>}\u003c/strong>\u003c/p>\u003cp>我的择业观：我期望我的职业能够给我带来独立和自由。我小时候，父母事业做得不错，一直是我的榜样，我心中就埋下了一颗要像父母一样有成绩的人；我上大学后，觉得真正的自由和独立首先要经济独立，只有经济独立才能自己决定人生，所有后来都是靠自己奋斗；后来工作后，我发现独立和自由不仅仅是经济，还有思想和智慧，我们做选择和决定的时候要有经济基础，更需要有思想和智慧做选择。所以，我的择业观是，工作能够给我带来自由和独立，我目前的工作是顾问公司项目经理，这份工作不仅让我能在杭州立足，也能让我处在不断学习和提升的状态，不断吸收和累积经验和知识。\u003c/p>\u003cp>\u003cstrong>{学员分享\u003c/strong>\u003cstrong>}\u003c/strong>\u003c/p>\u003cp>我的择业观：我期望我的另一半是有责任、担当、成熟、孝顺。我生长的环境中，父母用他们的方式给我他们最好的爱，我心中就想，一定要找一个孝顺的另一半，而且孝顺父母人一般不会太差；工作后，看到周围一些不幸的婚姻，大都是不负责任造成的，所以我找另一半一定是责任心强的；现在我也是年龄一大把了，不喜欢比我年轻的人，能被我欣赏的一般是比我成熟的人，所以我要找一个责任、担当、成熟、孝顺的另一半。\u003c/p>\u003cp>\u003cstrong>【A2】\u003c/strong>\u003c/p>\u003cp>结构化的训练是你最值得花时间和精力训练的能力，接下来布置两个个作业：\u003c/p>\u003cp>1、对刚才开篇小王的问题，大家在今天用主题、架子、素材，帮他回答老板，分享在群里；\u003c/p>\u003cp>\u003cstrong>{学员分享\u003c/strong>\u003cstrong>}\u003c/strong>\u003c/p>\u003cp>小王的回答：老板，这件事我们已经关注到了，这个是属于这个阶段的正常现象，并且我们已经开始着手改进了。为什么这么讲，是因为：1、（外部因素）客户的满意率下降有80%是由于快递涨价导致我们成本上升，部分费用要嫁接给用户，所以导致满意率突发下降；2、（内部因素）目前团队客服团队新人比较多，所以导致客户满意度下降，我们会加强这块培训；3、（不可抗力因素）台风导致快递送货比较慢，有很多客户因此满意度下降。我们会给予合理红包作为补偿。\u003c/p>\u003cp>2、每天总结一个发言（可以是自己、他人、影视剧、广告等）总结他们的主题、架子、素材，并记录下来。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1508125408000,"updated_at":1508125408000,"ria":true},{"id":3783,"topic":"临场发言没有思路，怎么破","learn_goal":"临场发言没有思路，怎么破","remark":"在我们的工作生活中，经常遇到需要做临场发言的情况，比如在开会的时候，当领导询问你对某个问题的看法或者建议时，你是否经历过大脑一片空白、思维短路或者是头脑中有N多个想法，却不知道从何说起这样的时刻？其实做好临场发言也是有套路可循的，只要掌握了结构化的表达方法，就可以让自己的临场发言逻辑清晰有条理，瞬间提升自己的职场专业度。\r\n本期活动，请跟着拆书家管凤华一起来拆解《请停止无效努力》，通过培养自己的结构化思维，做好临场发言，发现自己在职场上的更多可能。","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"管凤华","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"大家好，我是管凤华，管是管理的管，凤是凤凰的凤，华是中华的华，管凤华。我给自己名字赋予的含义是，希望自己永远的风华正茂。\r\n我的三个特色标签是：热爱学习；热爱分享；项目管理领域资深人士。\r\n很高兴今天有机会来这里与大家一起拆书学习。","ratings_count":0,"texts":[{"id":6700,"quote":"\u003cp>【主题】如何做好临场发言\u003c/p>\u003cp>【图书】请停止无效努力——如何用正确的方法快速进阶\u003c/p>\u003cp>【章节】第4章 提升沟通能力\u003c/p>\u003cp>【页码】P119\u003c/p>\u003cp>R：\u003c/p>\u003cp>&nbsp; &nbsp; 临场发言时，我们是有压力的。这种压力，要不让我们的大脑一片空白、胡言乱语，要不让我们的大脑信息泛滥、毫无头绪。这两种情况，听众听起来都会比较痛苦，不明白你到底想表达的是什么。\u003c/p>\u003cp>&nbsp; &nbsp; 如果说，有一个清晰的结构，发言就变得容易了。一方面，如果你的大脑是杂乱无章的状态，它可以帮你把信息快速整理并输出；另一方面，如果你的大脑是一片空白的状态，它可以作为提示语帮你联想起一些有用信息。\u003c/p>\u003cp>&nbsp; &nbsp; 用结构化思维，帮助你在短时间内更好地沟通，关键是三个步骤：\u003c/p>\u003cp>&nbsp; &nbsp; 第一步，想主题：迅速找到一个切入点，第一句就说出自己的观点。\u003c/p>\u003cp>&nbsp; &nbsp; 第二步，搭架子：在论证观点时，思考一个结构（时间、空间、程度），并只说三点，这称为三个“架子”。\u003c/p>\u003cp>&nbsp; &nbsp; 第三步，填素材：每个架子里，填充一些事例、数据等，来推进论据向观点靠近。\u003c/p>","explains":"\u003cp>我们在工作和生活中，经常遇到需要做临场发言的情况，比如开会时，领导询问你对某个问题的看法或解决建议，又比如你的好朋友向你征求他是否应该跳槽的建议等等，所有这些时刻，我们都面临着临场发言的压力，在这种压力下，大脑一般会产生两种常见反应：要么一片空白，一句话都说不出来；要么信息泛滥，不知从何说起。这两种情况都会导致我们无法清晰的表达自己的观点，给听众留下思维混乱的不好印象。拆页内容向我们介绍了，如何通过结构化的表达方式，让自己的临场发言变得逻辑清晰有条理。\u003c/p>\u003cp>建立结构化思维，涉及到三个步骤：\u003c/p>\u003cp>第一步，想主题，主题就是针对要讨论的问题，你的观点，你的看法，你的态度，打个比方的话，主题就相当于议论文中的论点。\u003c/p>\u003cp>第二步，搭架子，所谓架子是指我们在表达时，用于把信息分类汇总的结构关键词，常用的架子有三种类型，时间架、空间架和三角架。时间架是按照时间的顺序，整理头脑中的信息，比如你是负责培训工作的，那么在向别人介绍你的岗位职责时，你可以按照培训前、培训中和培训后来表达，特别提醒的是时间架不只局限于时间这个狭窄的概念，一切有先后关系的结构都算，所以除了这些代表时间的词，代表阶段、代表步骤的词都算。空间架是按照地点的顺序分类信息，用空间架的好处是听众有画面感，比如，全国各地的人们都阖家团圆，一起喜迎春节。广州：虎龙舞狮。北京：全家一起包饺子。南京：写春联以及贴春联。怎么样，是不是很有画面感？常用的空间架包括。。。。三角架是按照三个方面总结信息，常用的三角架包括。。。\u003c/p>\u003cp>第三步，填素材，素材指的是用于支撑主题或观点的数据、事实和故事。\u003c/p>\u003cp>以上就是培养结构化思维，做好临场发言的三个步骤：想主题、搭架子和填素材。\u003c/p>\u003cp>为了便于理解这个模型，书中举了个例子，说的是乔布斯在发布第一款苹果手机时进行过一段演讲，大意如下：\u003c/p>\u003cp>苹果公司是一家革命性的公司，为什么这么说呢？1984年，推出Mac电脑，改变了整个电脑行业；2001年，推出iPod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；2007年，推出苹果手机，我相信它将改变更多行业。\u003c/p>\u003cp>我们分析一下这段话的结构：\u003c/p>\u003cp>主题：苹果公司是一家革命性的公司。\u003c/p>\u003cp>架子：1984年，2001年，2007年。\u003c/p>\u003cp>素材：推出Mac电脑，改变了整个电脑行业；推出iPod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；推出苹果手机。\u003c/p>\u003cp>所以乔布斯的这段演讲就是一个典型的结构化发言。\u003c/p>\u003cp>注：常用的时间架、空间架和三角架结构会单独打印出来，上面的省略号部分现场会以可视化的方式向大家演示。\u003c/p>","interaction":"\u003cp>【A1】激活经验\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>以上就是我对拆页内容的解读，接下来进入A环节。学完这个片段，我们了解了在需要做临场发言的场合，如果利用结构化的表达模型，就可以让自己的发言清晰有条理。现在请小伙伴们回想一下，在自己的过往经历中，有没有经历过因为缺乏结构化表达的能力，从而导致发言效果很差的情况？当然成功的经历也可以。现在给大家几分钟的时间，各位小伙伴可以在组内轮流分享一下。\u003c/p>\u003cp>学习者案例记录：\u003cbr>\u003c/p>\u003cp>A同学分享自己所在的公司，会在前1天发出第2天要学习的专业文章，然后第2天早上轮流分享学习心得，轮到自己发言时，因为未按照结构化发言的模型整理自己的思路，导致分享缺乏逻辑性，自己也不满意自己的表现。\u003c/p>\u003cp>【A2】催化应用\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>接下来，请大家思考后续可以如何应用这个知识点？想好后就把这个应用计划写下来，特别提醒，计划一定要具体可执行，有明确的完成期限，是否达成可验收可测量，不能是泛泛的表决心似的计划。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>未记录。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1506774567000,"updated_at":1506774567000,"ria":true},{"id":3683,"topic":"如何让你的演讲信息结构化 +如何讲好主题","learn_goal":"让自己演讲说话更具结构化+讲好一个主题，让自己先声夺人","remark":"拆书家树袋熊贝贝2-4定级","level":"TF2-4","duration":30,"status":0,"type":0,"chaishujia":{"username":"树袋熊贝贝","city":"合肥"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是今天分享的拆书家树袋熊贝贝，欢迎大家的到来。我的本名叫张红领，非常的好记，你们可以把我记忆成少先队员都会带的红领巾。这样是不是很容易记住我了。我有三个标签：第一，一名演讲培训师，希望通过演讲可以影响很多人，让大家爱上演讲。第二，跑步达人，2017年要达到800公里。第三，终身学习者。2017年要阅读50本书。给自己一个崭新的起点，希望在学习的过程中认识更多的小伙伴，大家可以一起前行。因为一个人可以走的很快，但是一群人可以走的更远。 我们的成长彼此见证\r\nF：今天拆解的图书片段来自《请停止无效努力》，是2016年12月团结出版社出版的自我提升类图书，作者是孙圈圈（孙园媛）。曾任全球知名管理咨询公司咨询总监，【领英洞察】专栏作家。A：本书从发掘天赋、提升能力、选择平台等几大方面，详细阐述了职业发展和个人提升的正确方法论。书里所讲的方法与思路，可以用来分析我们生活、学习和工作中遇到的大多数问题。B:每篇文章都附有后续练习，不仅会颠覆一个人过去的思维认知，并且能让工作和人生得到很大的提升。对我们未来的改变具有重大意义。","ratings_count":0,"texts":[{"id":6593,"quote":"\u003cp>如何让你的演讲信息结构化\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;—引自《请停止无效努力》p119-120\u003c/p>\u003cp>临场发言时，我们是有压力的。这种压力，要不让我们的大脑一片空白、胡言乱语，要不让我们的大脑信息泛滥、毫无头绪。这两种情况，听众听起来都会比较痛苦，不明白你到底想表达什么。\u003c/p>\u003cp>如果说，有一个清晰的结构，发言就变得容易了。一方面你的大脑是杂乱无章状态，它可以帮你把信息快速整理并输出；另一方面，如果你的大脑是一片空白的状态，它可以作为提示语帮你联想起一些有用信息。用结构化思维，帮助你在短时间内更好的沟通，关键是三个步骤：\u003c/p>\u003cp>第一步，想主题：迅速找到一个切入口，第一句就说出自己的观点。\u003c/p>\u003cp>第二步，搭架子：在论证观点时，思考一个结构（时间、空间、程度），并只说三点，这称为三个“架子”。\u003c/p>\u003cp>第三步，填素材：每个架子里，填充一些事例、数据等，来推进论据向论点靠近。\u003c/p>\u003cp>这里给大家举个例子，乔布斯推出第一款苹果手机时进行过一段演讲，大意如下：\u003c/p>\u003cp>苹果公司是一家革命性的公司。为什么这么说呢？1984年，推出Mac电脑，改变了整个电脑行业；2001年，推出iPod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；2007年，推出苹果手机，我相信它将改变更多行业。\u003c/p>\u003cp>我们来剖析一下这段话的结构，就会是：\u003c/p>\u003cp>主题：苹果公司是一家革命性的公司。\u003c/p>\u003cp>架子：1984年、2001年、2007年\u003c/p>\u003cp>素材：推出Mac电脑，改变了整个电脑行业；推出iPod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；推出苹果手机，我相信它将改变更多行业\u003c/p>\u003cp>所以，乔布斯这段话的结构也是由三要素组成：主题、架子、素材\u003c/p>","explains":"\u003cp>&nbsp; &nbsp;好的，多数小伙伴已经看完了这个片段。这个片段不长，却告诉我们一个非常重要的方法，那就是“好的演讲要具有信息结构化”。平时我们遇到演讲或者发言的时候，首先是非常紧张，说话的都会和平时不一样，有可能会出现身体僵硬，说话有点发颤。如果运用这个片段中的三个方法，则可以帮助我们游刃有余，展现自我的风采。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; （预防异议）你可能会觉得这样太麻烦了，非要按照上面的流程吗？会不会太有套路了。其实这样的方法可以让我们逻辑性更加完整，即使实在突然的情况下发言也会游刃有余，像一个拐杖一样为我们指路。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; （强调不这么做的坏处）这样的方法看起来是有点套路了，但大家也知道套路才是天下最远的路、最好走的路。运用这样的方式，逻辑结构清晰，会让我们不再像从前想到哪说到哪，到最后也不知道自己说了啥，听众同样也是一脸懵逼，底下悄悄地说，这孙子说的啥。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; （举例）平时在工作中遇到最大的问题，就是不会让自己的汇报或者例会具有结构化。天马行空，想到啥说啥，没有任何章法，如果会议太长，讲完后自己也忘记的差不多，这样带来的问题是，下属或者同事对公司的一些部署不是特别理解，或者会有一定的偏差。在执行中造成一些不必要的麻烦和损失。这种情况出现的多了，对自身在职场的发展也是十分不利的。&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003c/p>\u003cp>（细化行动步骤）这个片段的三个方法看起来很简单，但是真正要理解如何运用并把它运用好，可能还是下很大一番功夫的。正所谓看着容易做着难，需要我们在生活和工作中时刻觉察，做刻意的练习。这样才会让它变成我们的本能反应。在任何汇报或者演讲的过程中运用这三步：\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 第一步，迅速找准主题，也就是选择一个切入点。而这个切入点非常微妙，他是你在面对一个话题或者事件的时候，你的看法或者是心得体会，那如何能让别人知道并关注。那就是在开门见山亮出自己的观点，这样做的好处就是在一开始就让听众知道我们要说的是啥。先声夺人\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 第二步，搭架子，也就是我们常说的框架结构，好的架子可以让我们的内容更加立体直观。我们可以根据时间、空间、程度上思考一个结构，并且只说三点。因为大家的专注力只能到三，多了就记不住。就像现在谁还可以背出八荣八耻。时间这个维度：片段里的1984、2001、2007。空间比如合肥、南昌、青岛。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 第三步，在架子里，要有足够的素材来支撑我们的论据，为我们的观点和主题服务，要让我们言之有物。这部分就是表达或者演讲的血肉，它会让我们的演讲更加丰满，栩栩如生。\u003c/p>\u003cp>&nbsp;&nbsp;通过这三个步骤，主题先行、层层递进，让我们的演讲更具结构化。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 演讲、表达在我们的工作和生活中越来越重要，算是职场必备的技能，掌握一些演讲与表达的技巧，可以让我们的职业生涯增色不少。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 举例：我现在做企业的内训，在和企业沟通的时候我首先选一个主题，那就是我只做演讲培训这一块，主攻声音这个环节。其次在框架部分分为微笑、声音细节练习。在最后的再配合一些练习手册。\u003c/p>","interaction":"\u003cp>【A1 激活经验】\u003c/p>\u003cp>（显像提问法）\u003c/p>\u003cp>&nbsp; &nbsp; 每到季度或者年底，大家都会面临这样的情境：老板或者部门主管要求你，小张抓紧时间写一份年终总结或者季度总结给我，我要用。当你放弃和女朋友约会的时间加班加点刚出来一份报告，满怀欣喜的交上去的，结果却被老板责骂？你这些的是啥？也不是我想要的，乱七八糟都不知道你想给我表达什么？回想一下，之前你是如何写作的的，存在什么不足？大家可以在小组里讨论一下，一会我请两位小伙伴起来分享一下。\u003c/p>\u003cp>学习者分享\u003c/p>\u003cp>&nbsp; &nbsp; 因为我自己喜欢写散文，所以每次在写总结的时候都是喜欢用写散文的方式来写总结，追求文字的华丽，做到形散意不散，但是总结报告是老板需要用逻辑性和数字来体现的，结果被领导批，说总结不是散文，我都不知道你想表达什么，还要我自己看半天。\u003c/p>\u003cp>【A1+ 反思加工经验 】\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>对于你的年终总结或者季度总结，在接受任务的那一刻有没有用心想过你的主题是否够酷，够吸引人。第一时间就可以让别人通过你的总结知道你想表达什么？你的素材又是否对应主题。让人看起来有理有据。如果给你再来一次，你会怎样运用上面片段里的技巧重新组织一下你的总结，使其更具结构化，更能打动人。\u003c/p>\u003cp>（学习者分享）\u003c/p>\u003cp>&nbsp;根据今天学习到的方法，下次再写总结的时候，首先，会选择一个主题，不再是用散文的方式来写，这样一方面会更加直观。也更有利于老板知道这个报告体现什么。其次，根据主题会通过1.2.3.点来展开说明。再次是每一点下面都有数据来支撑。做到主题先行，逻辑归类，层层递进。\u003cbr>\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>刚才，我们一起学习了对于面临别人的临时提问如何让自己的表达更具有结构化，避免了让头脑里的信息杂乱无章、野蛮生长。导致让听众一脸茫然，觉得你头脑不清晰。学完了如何让你的演讲信息结构化以后，接下来我们一起学习如何如何讲好一个主题，让自己做到在一开始就能抓住听众的眼球。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":6595,"quote":"\u003cp>&nbsp;如何讲好主题（引自《请停止无效努力》p120-121 \u003c/p>\u003cp>首先迅速选取一个视角。\u003c/p>\u003cp>当你需要发言时，往往会有很多观点想要分享，甚至这些观点可能是相反的，这时候最重要的不是在自己脑中打架，而是迅速选取一个视角。\u003c/p>\u003cp>比如，有机会跟大领导见面，他突然问你“公司有什么吸引你的地方，让你在这里待了五年呢？”你很想表现一下，很想把公司的好处都说出来，比如发展机会、公司文化、同事关系等等，你试图比较所有这些因素，看哪个最吸引你。但是最好的策略是，凭直觉直接选取其中一点，比如公司文化，然后展开去讲。\u003c/p>\u003cp>为什么要这么做呢？\u003c/p>\u003cp>通常我们表达观点的方式可能有两种：一是全面的肤浅，二是片面的深刻。也就是说，你可以面面俱到但是不深入，也可以就一个点进行阐述但相对深入。但是在短时间里进行发言，片面的深刻往往比全面的肤浅更加打动人。一方面，因为短时间内讲求全面，本身就是一件艰难的事情。另一方面，当你只有几分钟的发言时间时，面面俱到，无法展开，别人听起来就会觉得，你说了很多，但好像又什么也没说。\u003c/p>\u003cp>其次，第一句话就抛出观点。\u003c/p>\u003cp>举例来说，你要阐述某项政策带来的影响，很多时候，你的习惯开头是“关于这个政策的影响，我从三个方面来说明”。这样的开头其实没有任何有用信息，并且显得比较枯燥、平凡。\u003c/p>\u003cp>比较好的开头是直接抛出观点，比如“我认为，这个政策对消费者是利好，当局企业来说有负面影响”。这类主题的好处是：直接摆明观点，听证有了预期；观点比无用信息更加吸引人，会吸引听众继续听下去；一个话题有很多的角度，如果不说明，听众的思路会很散，但是这样的观点摆出来以后，听众会跟着你去思考\u003c/p>","explains":"\u003cp>好的，多数小伙伴已经看完了这个片段。当我读到这里的时候，我的第一感觉是，原来我当初遇到这样的情况，我的做法是多么的傻。完全是想到哪说到哪，也没个重点，就想把自己知道的一股脑的全部说出来，毫无章法可言。导致领导也不知道我到底想说啥，也就只能看着我，一脸很懵，然后对我说：“小张，说重点”我还傻乎乎的说，我讲的就是重点呀？然后就没有然后了。。。。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; （预防异议）可能有的小伙伴心里在想，我就是想把自己知道的全部说出来，这样老板知道我对公司了解的多呀，我把知道的都说出来，不是更能获得老板的认可吗？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; （强调不这么做的坏处）看似你说的很有道理，但是什么都想讲，什么都会说不好的，没个主题，会导致眉毛胡子一把抓，没有逻辑性，别人也很难明白你说的是啥。反而会给对方造成一种你脑子不清晰的假象。就像我们现在看到手绘想学、看到PPT想学，屯了很多课程，结果呢？是什么都知道，但什么都是皮毛。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; （举例）有一次在电梯里，正好老板也在里面。老板突然问我：“小张，你对于我们要和珠江集团合作一起打造一个培训平台怎么看。”我当时一个劲的说好要，这样可以打造我们的企业品牌知名度。对于公司未来的发展至关重要。听起来貌似我说了很多，其实和没说一样，没有一点深入，怎么可能给老板留下深刻印象呢。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; （细化行动步骤）所以，如果以后遇到类似的情况，你一定要学会有技巧的回答，而不是天马行空，想到啥说啥。这样才能在同事中脱颖而出，获得老板认可，获得最大的价值，结合原文片段，大家可以按照这样二种方法去做：\u003c/p>\u003cp>第一、迅速选取一个视角。首先我们要知道视觉是什么？它是我们在接受外界环境的刺激后获得的一种主观感觉。看电视的时候我们看到一些画面，会主观判断一个人是好还是坏。所以在工作生活中也许你有很多的点想表达，但是要抓住一个点，深入去讲，把自己对事情的自我看法表达出来，可打动对方。增进对方对你的关注度。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 第二，第一句话就抛出自己的观点。因为在演讲或者表达中，一开始亮明自己的观点非常重要，它会让听众第一时间知道你要表达的是什么。会跟着你的思路走下去，从而也展开自己的思考。有利于你在一开始就吸引住听众。不然的话，听众容易走神。等你讲完，听众也是一脸茫然，不知道你说了啥，还会对你留下不好的印象\u003c/p>\u003cp>&nbsp;&nbsp; 知道这个方法以后，如果在遇到老板问我，我们要和珠江集团合作一起打造一个培训平台怎么看。首先，我会告诉老板，这对我们来说是一个千载难逢的好机会，这是一个强强联合，它有利于我们公司形象和品牌度的提升，对加快我们公司集团化运作有深远意义。更加有利于我们团队的打磨，应对更加激烈的市场竞争。其次，有利于我们整合全省的资源，对我们乐器的销售会有很大的促进。\u003c/p>\u003cp>（适用边界）如果是很短的时间，你又想吸引对方，可以用这种方法。如果他非常感兴趣。我想他一定还会找你，想了解更多。到了那个时候你就可以把你想说的全部说出来。保证对你大吃一惊的。\u003c/p>","interaction":"\u003cp>\u003cb>【A3】促动参与\u003c/b>\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>&nbsp; &nbsp; 我们刚才一起学习了如何讲好主题的二个小技巧，现在一起做一个演练，请大家认真听一下要演练的场景：\u003c/p>\u003cp>假设中午你去咖啡间接咖啡，在等待的时间里，你的老板也进来了，你主动的问好，向他介绍你自己，他对你有点印象，在等待的过程中，他突然问你“小王，你来公司应该很长时间了，你对最近客户满意度下降了，你怎么看？”有什么好的想法？此时你脑子里有很多想说的，这时候你该如何说，才能给你的老板留下深刻的印象呢？\u003c/p>\u003cp>注意运用好拆页片段中的方法。小组讨论一下，一会我邀请1-2两位小伙伴分享一下。\u003c/p>\u003cp>&nbsp;&nbsp;（学习者分享）\u003c/p>\u003cp>&nbsp; &nbsp; 在咖啡间突然被问到客户满意度下降，我会从我们售后客服回复速度比较慢这个主题出发，因为回复比较慢会导致客户认为公司对这一块不重视，对客户的维护也是有问题的。出现这个问题可以从两个方面解决，第一是产品质量要好，出现问题要求当地的经销商提供免费的零部件更换。第二，就是提高售后的服务反馈要及时。\u003c/p>\u003cp>&nbsp; &nbsp; （拆书家反馈）\u003cbr>\u003c/p>\u003cp>&nbsp; &nbsp; 这个方法就比较好，不管自己的想法有多少，先选定一个主题，也就是说我们售后客服的回复，然后再讲出自己的观点和解决的方案。这样老板会认为你对这个有关注，说明对公司很上心，另外你也有自己的见解。非常赞。\u003c/p>\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>\u003cbr>\u003c/p>\u003cp>拆书家提问设计：&nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; 在一次部门的例行会议上，部门经理在听各部门主管汇报工作，随着一个个主管的汇报，经历的脸色越来越阴沉，一阵压抑的气氛弥漫全场。当听完了各部门主管的汇报后，经理大发雷霆，对本季度的业绩下滑非常不满，他的目光看向谁，都感觉如芒在背，这时候他突然叫到你，问你对如何提高业绩有什么看法，你该如何去做，才能一方面让经理消消火，另一方面你的回答让经理对你刮目相看。又或者两个同事在办公室里争执的不可开交，一个说针对我们的销售量要加大运营费用，另外一个说之所以这个月销售量高是因为这个月是旺季，下个月是淡季，不需要增加运营费用，只需要保持服务就好，完全没必要，正好你路过，他们拉你来评论。你该如何？请加工一个你工作和生活中会用到的例子。大家在小组内分享一下，一会我邀请1-2位小伙伴分享一下。\u003c/p>\u003cp>&nbsp; &nbsp;（学习者分享）\u003c/p>\u003cp>&nbsp; &nbsp; 我是做人力资源的，我们老板是一个这个事跟你这个部门有没有关系，跟你有没关系，他都会问到我，下个月要和老板去上海，如果他再问我的话，我首先会选择一个跟人力资源相关的视角，因为这个是我最熟悉的，包括后面一些数据啥的我都会很上手。先选择一个观点，这个事我是怎么看的。然后我再从各个方面进行分析，让老板觉得我说的是有一定道理的\u003c/p>\u003cp>&nbsp; （拆书家反馈）\u003c/p>\u003cp>&nbsp; &nbsp;这个分享很棒，首先遇到老板问到的情况，会有很多点可以来说，我会从人力资源这个自己擅长的角度去。也许我们的职务会导致我们的观点会有一定的缺陷，但是这个不重要，重要的是老板通过我们的回答，可以看到我们对公司的关注和自己的见解。也会让老板认为你有主人翁的精神。\u003c/p>\u003cp>&nbsp;【结语】\u003c/p>\u003cp>&nbsp;&nbsp;今天我们一起学习了两个片段，现在我们简要回顾一下，第一个片段告诉我们如何让你的演讲信息结构化，这样一方面发言变得简单了。另一方面也会让对反觉得你的演讲或表达逻辑结构清晰。对你留下深刻印象。第二个片段让我们了解了在演讲或表达中如何讲好主题，才能更好的让对方知道我们要表达的内容。做到先声夺人。希望大家在今后的工作生活中，能够运用好今天学习的方法，实现更好的发展。今天的拆书到此结束，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1505643286000,"updated_at":1505643411000,"ria":true},{"id":3647,"topic":"构建临时发言的结构","learn_goal":"掌握主题、架子、素材三要素","remark":"","level":"TF3-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"雨点小","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"大家好，我是王蕾，欢迎大家来参加今天的拆书活动，今天我的拆书是来自《请停止无效努力》这本书。【场景法介绍书籍】 【场景】：在工作中很有可能出现这种情况，老板问：“小王，最近项目进度有些慢，你怎么看？”顿时，你头脑中有很多信息，它们杂乱无章、毫无头绪，你想开头都不知道从哪里说起。另外一种情况是你很兴奋，滔滔不绝讲了一大堆，老板却一脸茫然，觉得你没讲清楚、思路有问题。 【提问】：这样的情况经常发生，大家有想过要针对这样的临时提问，整理出套路来吗？ 【影响】：因为每次临时提问你都回答不上来或者让人听不明白的话，老板会觉得你不够专业或者工作不认真 【解决】：那这本书中提供的临时发言三步骤，找主题、搭架子、填素材，能够让你解决。","ratings_count":0,"texts":[{"id":6548,"quote":"\u003cp>很多人觉得，自己的表达能力存在问题。其实，当你无法清楚地表达想法的时候，可能的原因是：你的想法本身就不清楚。思路非常清晰的人，很少有表达不清晰的，因为表达本身就是思路的一部分。\u003c/p>\u003cp>所以，让表达更加清晰，你需要的是一个思路来将你的信息进行结构化。\u003c/p>\u003cp>人类的大脑在处理信息时有两个习惯：第一，不能一次太多，因为信息太多会让大脑的负荷过大；第二，喜欢有规律的信息。\u003c/p>\u003cp>临场发言时，我们是有压力的。这种压力，要不让我们大脑一片空白、胡言乱语，要不让我们大脑信息泛滥、毫无头绪。这两种情况，听众听起来都会比较痛苦，不明白你到底想表达什么。\u003c/p>\u003cp>如果说，有一个清晰的结构，发言就变得容易了。一方面，如果你的大脑是杂乱无章的状态，它可以帮你把信息快速整理并输出；另一方面，如果你的大脑是一片空白的状态，它可以作为提示语帮你联想起一些有用信息。\u003c/p>\u003cp>这里给大家举个例子，乔布斯推出第一款苹果手机时进行过一段演讲，大意如下：\u003c/p>\u003cp>苹果公司是一家革命性的公司。为什么这么说呢？1984年，推出MAC电脑，改变了整个电脑行业；2001年，推出ipod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；2007年，推出苹果手机，我相信他将改变更多行业。\u003c/p>","explains":"\u003cp>1.【学习目标】\u003c/p>\u003cp>我们在完成本次RIA现场学习后，能够用找主题、搭架子、填素材的方法，来解决（\u003cstrong>行为\u003c/strong>）临时发言思路混乱（\u003cstrong>界定\u003c/strong>）的问题。\u003c/p>\u003cp>2.【拆页讲解】\u003c/p>\u003cp>如果这个时候小王的脑海里忽然闪现出这些词汇，他准备把与之相关的内容都报告给上司，我们都是小王哈，给大家10秒钟时间，来记一下小王要说关键词。供应商、劳务、工期、数据、设计、纠纷、财报、流程、审批（以大字报示意）。现在你只需说出刚刚的关键词来，美人把你记住得告诉我们，美人说：“供应商、劳务、结算”，后面的没有记住。我知道大家记不全的，所以除了我大家记忆的时间比较短之外，大家没记住的原因可能是什么呢？\u003c/p>\u003cp>&nbsp; &nbsp;拆页告诉我们是因为1.信息太多了&nbsp; 2.信息没有规律 ，也就是临时发言，你要做到结构化，就需要内容不能特别多，并且内容需要有规律，这样才会利于我们记忆。如果你记不住就会导致不知道说什么或者思路不清晰。&nbsp;\u003c/p>\u003cp>&nbsp; 【混淆概念解释】\u003c/p>\u003cp>&nbsp; &nbsp; 所以结构化并不是你能说出1、2、3点就是结构化，而是你在信息不能太多且要有规律的基础上，有一个发言的框架。我们来看下刚刚让你们记忆的9个关键词，其中第二行的“ 数据、结构、纠纷 &nbsp;”，这三个词结构化吗？（向学习者提问），孙雷说：“不是结构化”。是的，从我们一般业务角度看，看不出的有什么规律，也看不出它用的是什么样的框架。\u003c/p>\u003cp>【行动步骤】\u003c/p>\u003cp>&nbsp;那什么才是结构化的临时发言呢， &nbsp;我们来看下拆页中的例子。\u003c/p>\u003cp>“苹果公司是一家革命性的公司”这是总结性的一句话，引出了后面具体的内容。后面这三句话，有个相似的地方，大家看到了吗？是什么？它是按时间顺序来的，一个具体时间后面跟的内容是，苹果推出的产品以及产品影响。简单来说就是主题+时间框架+具体内容。\u003c/p>\u003cp>&nbsp; &nbsp;所以我们归纳下到底如何来做临时发言，,第一步，想主题；第二步，搭架子；第三步，填素材。\u003c/p>\u003cp>【逻辑、步骤、明确边界】&nbsp;\u003c/p>\u003cp>&nbsp; &nbsp;来说第一个找主题：如果像上面的小王一样，我想说9个主题，而且我能记住要讲的这9个主题，那我可以向老板汇报这9个主题吗？可以的，但是你肯定说的相对肤浅，每个主题你只讲了3句话就没了。那这个时候你也可以选取其中几个或者只说1个主题，片段给出的苹果的例子就是只说了1个主题。这个看你情况，一般临时性发言，我们会有压力，给到你的时间也不多，所以只说一个主题，深入的讲，会好一些。\u003c/p>\u003cp>&nbsp;&nbsp;然后来看搭架子，除了时间，那肯定不是每次都用时间来做为架子的，还能用什么？用地点， 上午去了公园，打太极，下午去了百新书局，拆书，晚上去超市，买下周的食物。还能不能有其他架子smart、5w2h，那么这里还想说一个比较通用的，就是总体分为几个部分。\u003c/p>\u003cp>我们来看个例子，在一条长达几千公里的国道上，有一段路在一个山区，其中有一个弯道，称为死亡拐弯，因为在过去的几年时间内，这个弯道上的事故发生率比其他地方要大几十倍，死了几十个人。\u003c/p>\u003cp>&nbsp; &nbsp;你呢就是调查这个死亡弯道的交通局人员，但还没有具体展开调查，这个时候你的领导问你：“事故频发的原因是什么，你怎么看？”\u003c/p>\u003cp>&nbsp; &nbsp;我刚刚说的一个搭架子的方法是把总体分为几个部分，从这张图上你能看到几个部分。人、车、路面、四周环境。人有可能疲劳驾驶或是荒山野岭的被周围的声音等惊吓到，车有可能系统失灵，一到那个路段就有奇怪的磁场影响车，这也是有可能的。路面，这是个急转弯的弯道或者路面不平等。环境,这里的能见度很低等。这四个部分组成了事故发生原因可能性的总体，还有其他原因没有包含在这四个部分中的吗？没有了。这也是搭框架的一种方法，把总体划分为几个部分。\u003c/p>\u003cp>&nbsp; &nbsp;第三步填素材，我们可以用数据、事实和故事来填充，具体的说明一件事情，并用数据去支持它，比如刚刚的死亡弯道，经过调查其中一个原因四山区早上经常有大雾，能见度在5米左右，司机看不清前方的路，导致事故。\u003c/p>\u003cp>&nbsp; &nbsp;那如果现在不是临时发言，给小王足够时间去准备明天的主题会议发言，那我们是否还能用三个步骤。可以，但是在找主题中说过，你可能要考虑到底讲几个主题，那不用再像临时性发言一样只说一个主题了，搭架子的时候也可以同时用到好几种架子来搭。\u003c/p>","interaction":"\u003cp>【A2】 &nbsp;&nbsp;\u003c/p>\u003cp>&nbsp; &nbsp;下面请大家给自己设置一个情境，这个情境中他人要求你做一个临时发言，你会根据我们刚刚的三个步骤来构思去组织你的临时发言。要求具体说下这个情境，以及你和他人的这个对话，也就是编一个剧本。想象下你们工作或者生活中可能出现的临时发言的情景，编一个剧本，需要有对话、动作。\u003c/p>\u003cp>&nbsp;&nbsp;\u003cstrong>&nbsp;美人\u003c/strong>：我现在做的是单位的新闻工作，假设将来的有一天，我们老板找我说：“小蒋啊，你认为如何来提高我们单位新闻工作的管理呢？”，因为我们单位出的一个问题是，下面部门报上来的新闻稿很少，那我们作为总新闻管理办公室，需要完成每年考核指标，那所以总要有人来写新闻才行，那我逼着下面公司写，大家都是扯皮（剧本背景）。\u003c/p>\u003cp>&nbsp; &nbsp;我就需要做临时发言，我会分三点说：“如何提高我们单位的新闻管理工作（\u003cstrong>主题\u003c/strong>），第一点是自上而下的管理，每个部门选出通讯员拉到一个群里，给他们做培训，然后采用考核的方式，给每个部门定指标。\u003c/p>\u003cp>第二点是自下而上的动力，我们会把通讯员的稿件放在群里，然后鼓励这个部门的通讯员说：“你们部门的稿件写的很好！”，那这个时候其他部门的通讯员看到后，就会想我也要加油了，通讯员之间会形成相互鼓励，相互推动的作用。\u003c/p>\u003cp>第三点是第三方介入，我们新闻是受到再上一级的考核的。我们可以请上一级的老师做专业的讲座，用他们的考核标准来规范我们，提高我们单位的新闻管理能力”\u003c/p>\u003cp>&nbsp; &nbsp;\u003cstrong>荣荣\u003c/strong>：\u003c/p>\u003cp>&nbsp;有一个朋友觉得我家儿子的阅读习惯非常好，她问我说：“你是如何让孩子养成这样的阅读习惯的？”\u003c/p>\u003cp>我会这样说：“我主要用的微习惯（\u003cstrong>主题\u003c/strong>），1.微习惯是什么呢，微习惯就是每天重复做到一个小到不能再小的行为。 &nbsp;2.为什么选择微习惯来作为习惯养成呢，如果我们每天给孩子定下来阅读半小时的或者每天读半本书，那么他很可能觉得压力很大，这时候呢孩子就会去对抗这个压力，然后孩子就会产生内疚自责，认为自己不行等各种负面的情绪。但是微习惯就不会产生压力，因为容易完成 &nbsp;3.如何来养成微习惯呢，定一个小目标，每天读书5分钟，这是一个不可能失败的行为。”\u003cbr>\u003c/p>\u003cp>&nbsp;\u003cstrong>结尾：\u003c/strong> 今天我们已经学了临时发言的结构化的思路，先找主题，后搭架子，最后填充具体内容，希望大家以后在临时发言时，不再有压力。我的拆书就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1505101074000,"updated_at":1505111578000,"ria":true},{"id":3428,"topic":"打造临时发言的结构","learn_goal":"掌握想主题、搭架子、填素材三步骤","remark":"","level":"TF3-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"雨点小","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"\u003cp>在工作中很可能出现这种情况，老板问：“小王，最近项目进度有些慢，你怎么看？”顿时，你头脑中有很多信息，它们杂乱无章、毫无头绪，你想开头都不知道从哪里说起。另外一种情况是你很兴奋，滔滔不绝讲了一大堆，老板却一脸茫然，觉得你没讲清楚、思路有问题。\u003c/p>\u003cp>如果因为每次临时提问你都回答不上来或者让人听不明白的话，导致老板觉得你不够专业或者工作不认真。那么你立马需要解决的是临时发言的技巧，而不是自怨自艾的认为自己的确工作能力不够或者抱怨老板看不到自己的价值。\u003c/p>\u003cp>这样的情况经常发生，大家有想过要针对这样的临时提问，整理出套路来吗？今天推荐的《请停止无效努力》这本书中提供的临时发言三步骤，找主题、搭架子、填素材，能够为你解决以上棘手的问题。\u003c/p>","ratings_count":0,"texts":[{"id":6292,"quote":"\u003cp>很多人觉得，自己的表达能力存在问题。其实，当你无法清楚地表达想法的时候，可能的原因是：你的想法本身就不清楚。思路非常清晰的人，很少有表达不清晰的，因为表达本身就是思路的一部分。\u003c/p>\u003cp>所以，让表达更加清晰，你需要的是一个思路来将你的信息进行结构化。\u003c/p>\u003cp>人类的大脑在处理信息时有两个习惯：第一，不能一次太多，因为信息太多会让大脑的负荷过大；第二，喜欢有规律的信息。\u003c/p>\u003cp>临场发言时，我们是有压力的。这种压力，要不让我们大脑一片空白、胡言乱语，要不让我们大脑信息泛滥、毫无头绪。这两种情况，听众听起来都会比较痛苦，不明白你到底想表达什么。\u003c/p>\u003cp>如果说，有一个清晰的结构，发言就变得容易了。一方面，如果你的大脑是杂乱无章的状态，它可以帮你把信息快速整理并输出；另一方面，如果你的大脑是一片空白的状态，它可以作为提示语帮你联想起一些有用信息。\u003c/p>\u003cp>这里给大家举个例子，乔布斯推出第一款苹果手机时进行过一段演讲，大意如下：\u003c/p>\u003cp>苹果公司是一家革命性的公司。为什么这么说呢？1984年，推出MAC电脑，改变了整个电脑行业；2001年，推出ipod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；2007年，推出苹果手机，我相信他将改变更多行业。\u003c/p>","explains":"\u003cp>看完以上片段，我想你已经能够明白为什么在表达时你会蒙圈了，不过我还是想让你们亲自体验下。\u003c/p>\u003cp>假装你就是小王，现在脑海里忽然闪现出以上词汇，你准备把与之相关的内容都报告给上司，我允许你睁大眼睛盯着图片中的关键词15秒钟的时间。停止浏览，请告诉我，你还能记得什么，其实我已经猜到了结局，一般情况能记住3-5个左右。\u003cbr>\u003c/p>\u003cp>为啥大家记不住呢？1.信息太多了&nbsp; 2.信息没有规律，所以结构化的回答是以信息不能太多且要有规律为前提的。\u003c/p>\u003cp>如果信息能够满足以上前提，那又如何才能实现结构化的临时发言呢， &nbsp;我们回顾下原文中的例子。\u003cbr>\u003c/p>\u003cp>“苹果公司是一家革命性的公司”这是总结性的一句话，引出了后面具体的内容。后三句有个相似的地方，它是按时间顺序来的，一个具体时间跟着该时间点上苹果推出的产品以及产品影响。简单来说就是主题+时间框架+具体内容。\u003c/p>\u003cp>&nbsp; &nbsp;所以我们归纳下到底如何来做临时发言，第一步，想主题；第二步，搭架子；第三步，填素材。\u003c/p>\u003cp>除了时间的框架，根据不同的主题还可以选择用地点、smart、5w2h等不同的框架，那么这里还想说一个比较通用的，就是总体分为几个部分。\u003c/p>","interaction":"\u003cp>光说不练可不行，给两个小伙伴亲身运用的例子给大家作为参考。\u003c/p>\u003cp>例子1\u003c/p>\u003cp>我现在做的是单位的新闻工作，假设将来的有一天，我们老板找我说：“小蒋啊，你认为如何来提高我们单位新闻工作的管理呢？”，因为我们单位出的一个问题是，下面部门报上来的新闻稿很少，那我们作为总新闻管理办公室，需要完成每年考核指标，那所以总要有人来写新闻才行，那我逼着下面公司写，大家都是扯皮。\u003cbr>\u003c/p>\u003cp>我就需要做临时发言，我会分三点说：“提高我们单位的新闻管理是当前的重要工作，第一点是自上而下的管理，每个部门选出通讯员拉到一个群里，给他们做培训，然后采用考核的方式，给每个部门定指标。\u003c/p>\u003cp>第二点是自下而上的动力，我们会把通讯员的稿件放在群里，然后鼓励这个部门的通讯员说：“你们部门的稿件写的很好！”，那这个时候其他部门的通讯员看到后，就会想我也要加油了，通讯员之间会形成相互鼓励，相互推动的作用。\u003c/p>\u003cp>第三点是第三方介入，我们新闻是受到再上一级的考核的。我们可以请上一级的老师做专业的讲座，用他们的考核标准来规范我们，提高我们单位的新闻管理能力”\u003c/p>\u003cp>例子2\u003c/p>\u003cp>&nbsp;有一个朋友觉得我家儿子的阅读习惯非常好，她问我说：“你是如何让孩子养成这样的阅读习惯的？”\u003cbr>\u003c/p>\u003cp>我会这样说：“我主要用的微习惯，1.微习惯是什么呢，微习惯就是每天重复做到一个小到不能再小的行为。 &nbsp;2.为什么选择微习惯来作为习惯养成呢，如果我们每天给孩子定下来阅读半小时的或者每天读半本书，那么他很可能觉得压力很大，这时候呢孩子就会去对抗这个压力，然后孩子就会产生内疚自责，认为自己不行等各种负面的情绪。但是微习惯就不会产生压力，因为容易完成 &nbsp;3.如何来养成微习惯呢，定一个小目标，每天读书5分钟，这是一个不可能失败的行为。”\u003c/p>\u003cp>临时发言的结构化思路你记住了吗？如果你也学会了，那么临时发言不过是只纸老虎罢了。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1502697310000,"updated_at":1585536994000,"ria":true},{"id":3426,"topic":"讲故事","learn_goal":"掌握讲故事的五元素","remark":"TED演讲嘉宾，很多都是古板的学者，演讲技巧不足，但他们的演讲仍然很精彩，因为TED官方会在演讲前给他们进行特训，核心就是“如何讲好故事”。故事让你产生共情，胜过一切冷冰冰的数字和逻辑。","level":"TF2-4","duration":60,"status":0,"type":0,"chaishujia":{"username":"雨点小","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，欢迎大家来参加今天的活动，我是王蕾，今天由我给大家带来《请停止无效努力》中的拆页。\r\n【F 】《请停止无效努力》这本书的作者是原全世界最大的人力资源咨询公司总监，是位中国的一位女性，16年离职出来创业,创业时就写了这本书，内容主要是关于个人提升的。豆瓣评分8.6分，已经是很高的分数了。\r\n【A】那我们平时读的书很多都是关于一个单一的主题，比如逻辑思维、情绪、沟通等，像我这种理解能力不太好的人，读完整本书之后，会觉得有点懵。这本书的特别之处就在于，它的每一章都是一个主题，涵盖了个人成长的很多方面，包括天赋、学习能力、思维能力、沟通、职业规划、情绪等等，但都不是泛泛而谈的，它从定义、到原理、到行动步骤，都给你说的很详细。\r\n【B】所以这本书就像地图一样，可以作为你工作和生活中基本技能的指引，帮你了解个人提升包括哪些方面，如果你对个人提升很迷茫，你可以从这本书中找下方向。大家生活中是否会经常用道理或者数据去说服别人，但时常达不到好的效果，还被朋友贴上啰嗦或者是冷酷的标签，那今天就我们就来学习下用讲故事的方法来打动别人。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":0,"texts":[{"id":6288,"quote":"\u003cp>我们在解决问题的时候可以用逻辑、用理性，然而当我们要去影响别人，让他们认同我们的时候，只有逻辑是不够的，因为它没有情感。我们需要的是故事，因为只有故事才能达到共情，建立人与人之间的链接，让他们站在你这边。任何想要说服别人、激发对方情感的场合，你都需要故事。如何习得呢？我们会发现，一个有吸引力的故事，总是有相似规律的。\u003c/p>\u003cp>莎士比亚深谙此道:罗密欧与朱丽叶秘密结婚了,之后罗密欧被放逐已经够惨了，然而莎士比亚继续虐读者，朱丽叶的父亲要将女儿嫁给帕里斯。最后，莎士比亚又让假死逃婚的朱丽叶，醒来看到罗密欧殉情，跟着也自刎身亡。\u003c/p>\u003cp>这个故事有什么特征呢？虐！用行话来说就是“冲突”。\u003c/p>","explains":"\u003cp>1.【学习目标】\u003cbr>\u003c/p>\u003cp>我们在完成本次RIA现场学习后，希望我们在说服他人的时候能够学会描述冲突，讲一个有冲突的故事来吸引他人。\u003c/p>\u003cp>2.【拆页讲解】\u003c/p>\u003cp>为什么我们需要讲故事，作者给了我们两个理由，一个是吸引力，一个是说服力。怎么样的故事能具有这两个力，有冲突的故事，作者告诉我们想要制造冲突，就要有渴望和障碍，大家回忆下韩剧你看过的韩剧就能明白什么是渴望和冲突了，韩剧最常见的情感剧，女主角不是癌症就是失忆，不然就是失明，但这些都没能阻挡住主人公的爱，这个爱就与现实中的阻碍组成了冲突，然后我们就稀里哗啦两包纸巾没了。\u003c/p>\u003cp>【不这么做的坏处】一个故事没有渴望加阻碍产生的冲突，只有理性或者平铺直叙，是很难打动人的。因为听众没有与故事产生共情，没有建立起听众与故事之间的情感链接，听众自然就不能被打动。\u003c/p>\u003cp>【一般做法】讲故事可以无处不在，在给别人介绍书啊、电影啊，我们却很少用讲故事的套路，不是用数字、数据，就是加重语气词“特别感人啊！”，“真的很好啊！”等等。【一般做法的坏处】我们这样的介绍显然吸引不了他人，更不用说打动了。\u003c/p>\u003cp>【细化原文步骤】&nbsp;我们可以看到拆页用了朱丽叶和罗密欧的例子，我们来概括下作者给的这个例子，罗密欧和朱丽叶非常想在一起，但是由于两家的世仇，父亲的阻碍等等，最后两人没有在一起。好像很多故事都是这种套路，主人公想做一件事，但是由于种种阻碍，最后有的成了有的没成。想达成什么什么的愿望可以称为渴望，那么渴望+阻碍就是冲突。如何来描述冲突呢？，就是我们刚刚概括的，先描述一个渴望，然后描述现实中发生的阻碍，这就是渴望+阻碍=冲突\u003c/p>\u003cp>【反例】就拿拆书帮来说，我很多时候会向我朋友这样介绍拆书帮：“我们拆书帮的创始人是赵周老师，拆书帮全国有20多个分舵，拆书家人数达上千人，遍布全国。”，这里的数据并没有打动我的朋友，也没有让他产生进一步了解拆书帮的想法，因为数据不能让人产生情感链接。\u003c/p>\u003cp>【正例】但如果我用有冲突的故事来介绍拆书帮：“很多人对生活失去信心，对读书失去热情（阻碍），但他们一直都在寻找着能够点燃自己的精神家园（渴望），直到有一天拆书帮的出现让他们看到了希望。”虽然有点夸张，但是这里渴望与阻碍产生的冲突让我们能感受到拆书帮对这些参与者有着非常重要的意义。如果我给朋友这样介绍，我想我的朋友很有可能会被我的介绍打动，对拆书帮产生兴趣。\u003c/p>","interaction":"\u003cp>【A1指令】\u003c/p>\u003cp>&nbsp; &nbsp;大家回忆下我们平时如何向别人推荐喜欢的电影、小说，除了好看、幽默、打动人外，就没有其他词了。面试的时候面试官问你“你的优点是什么？”的时候，你总回答我是积极、热情、上进的人，说完后你在面试官脑海里什么印象都没留下？安慰朋友也只会说“都会好起来的”这种说了等于没说的话，朋友反而更加伤心。大家以往的经历是什么？来分享下\u003c/p>\u003cp>【A1分享】\u003c/p>\u003cp>&nbsp; &nbsp;美人：我是个热情的人，所以经常会向朋友推荐电影、电视剧，但是我经常跟人家说：“这个很好看，特别好看，你一定要看”，有些朋友比较信任我，会觉得我推荐的应该都是不错的。但是有很多人，会觉得你并没有说出到底如何好啊，没有说出道理来。\u003c/p>\u003cp>&nbsp; &nbsp;荣荣：遇到一些很好的书，会推荐给我儿子，特别希望他能读下，因为会对他有很多帮助，我就会有那种急迫的心情，跟他推荐说：“这本书特别好。”他回答说：“我不喜欢。”后来我就没办法了，我说：“我读给你听吧。”他说：“那你试试吧。”就是说，我知道这本书很好，但是不知道怎么说才能吸引到我儿子，怎么表述出这本书的好，让我儿子也觉得这本书好。\u003c/p>\u003cp>雷蒙德：我的事情是发生在工作中的，有时候给同事建议职业发展，会说得比较笼统，尝试不同挑战，思考怎么有进一步的提升。很多时候觉得道理大家都懂，但对方不一定能听进去。\u003c/p>\u003cp>【A1+】\u003c/p>\u003cp>&nbsp; &nbsp;如果用我们刚刚冲突的套路，就是渴望+阻碍，来说你刚刚描述的事情，你会怎么说呢？\u003c/p>\u003cp>&nbsp; &nbsp;美人：如果让我重新向朋友介绍《楚乔传》的话，我会说，每个人的人生中都会有遇到低谷的时候，楚乔也是这样的，那她想改变自己命运，这就是渴望。但她是一个出身很低微的人，当时的等级制度很森严，所以她成功改变命运的可能很小，那她是如何突破这些阻碍的呢，她非常有毅力，坚忍不拔的朝着她的目标迈进，而且超过了男人的意志力。在濒临死亡的绝望中，很多人都会自暴自弃，但是楚乔却有着非常强烈的求生欲望，在绝境中永不放弃。如果你看了这部电视剧，会对你的生活有启发。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":6289,"quote":"\u003cp>除了冲突之外，故事还需要什么要素呢？一个好的故事，需要包括三个基本要素以及两个附加要素。基本要素很容易理解，因为有冲突，必须是需要行动的，行动之后到底结果如何，这就是结局了。那么附加要素：情感和展示，到底是什么呢？\u003c/p>\u003cp>情感的作用是建立跟观众或读者的连接，引起共鸣。比如，“小明背负着巨大的家庭债务，还常被极品老板责骂、侮辱”，这样的一段叙述很难让你有共鸣，你需要把小明被辱骂的时候的情绪描写出来，他是愤怒、委屈、或是隐忍？而这些情绪他又是如何表现的？这样才能引起共鸣。\u003c/p>\u003cp>展示的作用是让观众或读者身临其境。比如你想说一个人很美，用沉鱼落雁，闭月羞花很难打动人，因为展示不够鲜活。可如果看到这段，“杨过抬起头来，只见一只白玉般的纤手掀开帷幕，一个少女走了进来。那少女披着一袭薄薄的白色布衣，犹似身在烟中雾里，看来约莫十六七岁年纪，除一头黑发之外，全身雪白，面容秀美绝俗，只肌肤间少了血色，显得苍白异常。”你脑海中便能想象出小龙女的美。\u003c/p>\u003cp>知道故事的五要素之后，你的女朋友问你：“为什么爱我？”你会如何回答呢？不用故事的话，你可能会说：“因为你漂亮、聪明、温柔、体贴、大方……” \u003c/p>\u003cp>然而，如果用以上故事要素的话，你可以这样:“去年我工作压力大的时候，经常失眠，没有食欲，还老跟你发脾气（冲突）。有天早上，我昏昏沉沉地起床，看到你在厨房，一边用手机查菜谱，一边帮我做早餐（行动）。后来，你把做好的鸡蛋饼端给我的时候，我暗暗发誓，一定会爱你一辈子（结局）。”说这些话的时候，你眼含泪花、深情款款的看着她（情感），说完之后，把她拥抱在怀里（展示）\u003c/p>","explains":"\u003cp>1.【学习目标】\u003c/p>\u003cp>我们在完成本次RIA现场学习后，希望我们在说服他人的时候能够学会用故事五要素来讲一个故事。\u003c/p>\u003cp>2.【拆页讲解】\u003c/p>\u003cp>刚刚我们讲了冲突，就是渴望+阻碍。讲一个好故事还需要其他要素，拆页中写的很清楚，我们还需要行动、结局、情感和展示。行动和结局相对好理解，行动就是产生冲突后做了什么，结局就是行动后的结果，拿上个拆页中的罗密欧与朱丽叶来说，行动就是他们俩不顾一切的在一起，包括最后朱丽叶为了要在一起假死逃婚。结局呢，不是很美好罗密欧殉情，朱丽叶也跟着自刎身亡。\u003c/p>\u003cp>附加要素的情感和展示我们在来回味下，我理解的情感元素是一直融合在冲突、行动、结局里的，并不是单独出来的。还是罗密欧和朱丽叶，比如他们遇到阻碍的时候，可以描写成为他们无奈的分别，心如刀削，就好像整个世界都变得昏暗了。就是对情节当下的感情做具体描述，不是单用一个形容词去形容。\u003c/p>\u003cp>展示是什么呢？我的理解是一个特写镜头，你把当下场景的细节描写出来，比如现在我正盯着我的逐字稿，磕磕绊绊的给大家讲解，大家有的不时看下拆页，紧锁眉头，好像在思考着什么。这个就是特写镜头，描述了自己和大家当下的表现。 \u003c/p>\u003cp>情感就是故事的情感描写，展示就是具体场景的特写镜头。\u003c/p>\u003cp>【预防性讲解】&nbsp;\u003c/p>\u003cp>那可能小伙伴会问我用了5个要素一定能说服别人吗？一个好的故事套路固然能帮助你影响他人，但我们不能只重视套路，而忽视了讲故事的初心。比如说，本来你是想给人家加油打气的，结果你讲了一个生离死别的爱情故事，很明显这个故事不会起到特别好的效果。\u003c/p>\u003cp>【贴近实际的例子】&nbsp;\u003c/p>\u003cp>那下面我给大家说个故事，听完后，大家来说下我的冲突、行动、结局、情感、展示分别是什么。加班到凌晨2点的我（阻碍），今天上午还要拆书（渴望），所以提前设定了3个闹钟。早上9点闹钟开始作响了，我一个翻身，顺手关掉，又开始呼呼大睡，三个闹钟并没什么用（阻碍）。9:50的时候我突然意识到今天还有重要事情，从床上跳了起来，手忙脚乱的开始洗漱，5分钟就出门了。在路边等了5分钟，还没有车来，心急如焚的我左手拦车，右手手机滴滴打车（情感、展示）。终于师傅愿意捎上我，上车后一直催促司机快快快，快到福州路的时候，特别幸运的发生了堵车，原本松了一口气的我整个人都不好了，毅然决然的打开车门，一路狂奔向百信书局。最后赶到时大家刚刚结束自我介绍，还没错过拆书，我庆幸着笑嘻嘻的落座，拿起拆页目不转睛的开始看起来，拆书活动就在我们欢笑和专注中开始了（情感、展示）。\u003c/p>","interaction":"\u003cp>【A3】\u003c/p>\u003cp>&nbsp; &nbsp;我们接下来做一个情景演练，假设大家现在每个人，我们都是三级拆书家，赵周帮主呢向我们征文，希望大家能表达对拆书或拆书帮的爱，来作为对拆书帮10周年的礼物，我们呢就用讲故事的套路来表达对拆书或拆书帮的爱。可以像我刚才一样用一个日常小故事来体现平凡的爱，也可以说自己的成长故事。\u003c/p>\u003cp>我们来看下她故事各元素具体对应的是什么。\u003c/p>\u003cp>&nbsp; &nbsp;\u003cstrong>雷蒙德\u003c/strong>：故事的主题是我和拆书的不解之缘，每个人都有自我成长的愿望，不管是生活还是工作中，都会想证明自己，证明自己能做的比别人更好（渴望），学习是一种途径，但在学习的过程中会遇到一个问题，我读了很多书，但我的生活依然没有什么改变，这种经历我也有，所以我也会产生挫败感，那我就会想是不是方法不对，或者是没有找到好的路径（阻碍）。所以会向他人学习怎么样才能做到高效阅读，后来就接触了拆书的方法，以及拆书帮这样一个互助型的学习组织。那我经常参加线下活动去体验拆书家的风采，自己也会慢慢产生变化（行为），自己学习是一方面，能促进他人学习，也是非常有成就感的一件事或者说是更让你期待的一件事情，自己会想往前进一步，努力成为一个拆书家，所以现在也已经走在拆书家路上了（结果）。也会向身边人介绍什么是拆书，拆书方法是什么，如何更好的学习等等\u003c/p>\u003cp>&nbsp; &nbsp;\u003cstrong>点评\u003c/strong>：从刚刚的故事中，你运用了渴望+阻碍成为的冲突、行为以及结局，其他稍显的弱了一点。我觉得从开始的迷茫的情感到最后找到了方向的喜悦的情感，可以再多一些描述。展示这个元素也弱了一点，可以去描述下拆书现场大家相互促进学习的场景，这样就能来说明你为什么你认为找到了对的路径。\u003c/p>\u003cp>&nbsp; &nbsp;\u003cstrong>荣荣\u003c/strong>：我是住在昆山这个小县城，但是我又是个非常爱学习的人。在我们那里读书活动是非常少的，大家都会觉得读书有什么用，读了书又不会加工资（阻碍）。但是我第一次参加拆书帮活动的时候，看到小伙伴们都非常的爱读书，而且速度很快，而且有一位呢是一天读一本书，我当时就被深深的吸引了，希望自己也能成为那样的人（渴望），但是我自己平时看10分钟的书就会睡着（阻碍）。晚上睡不着的时候就会抱一本书，看一小会就睡着了。\u003c/p>\u003cp>&nbsp; &nbsp;家里买了很多书，想尽各种办法去让自己成为爱读书的人，可是都没有成功。然后我就想逼自己一把，果断地加入了拆书帮（行为）。加入以后，我就开始升级打怪了，晚上7点钟，开始找拆书片段，就把手机扔到一边。一直到12点，为了找到一个好片段，一下子翻遍了5本书，在这个过程中自己都惊呆了（展示）。通过半年来和小伙伴的交流学习，自己得到了很多成长，比如以前不能控制自己的情绪，说出很多重伤别人的话，让家人都很讨厌我，现在完全能够控制情绪了而且能帮助他人，自己已经成为了一个温暖的人。（结果）\u003c/p>\u003cp>&nbsp; &nbsp;\u003cstrong>点评\u003c/strong>：五个要素相对完整，情感稍稍弱了一点，从五要素来看的话，已经算是不错的故事了。\u003c/p>\u003cp>&nbsp; &nbsp;\u003cstrong>美人\u003c/strong>：我虽然活到了30岁不到，但是我这一生都有一个很大的遗憾，我从小跟着爷爷奶奶长大，天天看武侠电视剧，所以我从小心中有个武侠梦，想成为玉树凌风的女侠（渴望）。长大之后才明白了武功这种东西是不真实的，所以我就想在学习方面或者是生活方面成为一个高手。然后在这个过程中，我遇到了很多困难，我读了这么多年的书，我没有什么改变，在找工作的时候也没什么社会竞争力（阻碍）。我特别渴望有展示自己的机会，像女侠一样展示自己，但是我现在的工作呢是一个国企的非常死板的工作，工作内容非常枯燥，和我想象的女侠的生活完全不沾边，在现在的工作中没有激情，没有梦想，没有有意思的事，我也没钱去世界各地旅游。我感觉自己现实生活被束缚了，精神生活也被束缚了（阻碍）。\u003c/p>\u003cp>&nbsp; &nbsp;那我们现实生活脱离不了，那总要在精神生活找到一条光明大道，这条路呢是欢乐的、充满热情的，同时是让我感到有价值的，这是我生命一直在寻找的东西，但是我找了那么多年都没有找到。后来终于有一天，我接触到了拆书帮（行为），是我们的舵主崔律把我带进来的，我真的非常的感恩，我们的舵主也后来成为了我的师父，在这条路上一直引领着我，现在也依然是我仰望的人（情感）。在拆书帮中我收获了三个好处（结果），第一个好处是感受到了爱与被爱的氛围，我相信这是每个人终其一生需要的东西。第二个好处是有一个展示自己的机会，我终于能够成为一个拆书的小女侠了，这个也是我人生的一个突破。第三个好处是它是一个帮助他人和帮助自己的道路。当我老了，当我回首往事，也许我这一生没有什么成就，但是我发现我参加了这么多次拆书，也拆了很多书，我觉得是没有什么遗憾了。（情感）\u003c/p>\u003cp>&nbsp; &nbsp;\u003cstrong>点评\u003c/strong>：非常有煽动性的一个故事，根据我要素，冲突、行动、结局、情感都有了。特别是情感部分非常充沛，展示这一部分稍微有点弱，你可以描述一个跟师父相处的具体场景或者和我们小伙伴一起学习的场景，就更能显示这种学习的氛围给你带来的精神上的享受。\u003c/p>\u003cp>【A2】\u003cbr>\u003c/p>\u003cp>想象下接下来你可能会遇到的讲故事场景，你正在安慰一个一蹶不振的朋友，想要帮他从挫折中走出来，给他打鸡血。也有可能是你在一场活动上认识了几个新朋友，你想要介绍下自己的特质、优点、性格等等，让人留下深刻的印象。\u003c/p>\u003cp>那么大家先说下这个场景是什么，然后用我们的故事5元素来说说这个场景下你和她对话中是如何描述这个小故事来的。\u003c/p>\u003cp>\u003cstrong>雷蒙德\u003c/strong>：\u003c/p>\u003cp>场景：同事工作没有做好，遭到客户职责，那么这时候同事就有点委屈和挫败感。\u003c/p>\u003cp>故事：我会跟他分享自己的一些经验，说自己的一个小故事，四五年前，我是在客户现场做系统层面的技术支持，但是当时系统有不同的模块，我是负责一个新的模块，而且和前同事交接的时候也比较仓促，所以专业性上不是很扎实（阻碍），但我也是非常希望能够解决客户问题的（渴望）。客户呢又在工作中会有很多问题来问，所以曾经也被客户责备过。具体是当时客户有个问题拉我过去问说：“系统为什么会有这样的问题”，我并没有办法帮他现场解决，那我当时是回复：“我需要回去研究下。”然后客户就生气了，他说：“你不是专家吗？为什么还要思考，你应该立马告诉我这个问题怎么解决啊”（展示），我回答说：“我现在刚刚接触这一块，我需要点时间研究下，晚点回复你”，然后我就黯然的离开了，但其实当时我心里是不太好受的（情感），因为我本身是一个专家的职位，但是没有办法给客户解决问题。\u003c/p>\u003cp>后来呢经过自己的反思、积累和总结，但也没有找到问题的答案（行为），当时客户直接跟我说：“你不用研究了，我已经知道怎么解决了。”，然后一脸懵懂的问客户：“您能告诉我是怎么解决的吗？”这时候客户就更怒了（情感），对我说：“我凭什么告诉你，你自己回去研究去。”（展示），所以说我也经历了很多由于自己基础不扎实，而遭到客户的职责和挑战的事情。但最关键的是我们怎么去吸收和积累这些经验，不停的去做总结，所以也是在那次事情之后，不断的有去总结自己的技术问题和客户沟通过的一些经验，那最终是获得了客户的认可，因为你慢慢帮他们解决问题之后，你会慢慢积累他们对你的信任（结果）。这就是我想和我同事说的故事，来告诉他遭到责备没关系，重要的是你收获了什么。\u003c/p>\u003cp>\u003cstrong>点评\u003c/strong>：和A3时的故事比起来这次的五个要素都用上了，故事比较完整，给你点赞。\u003c/p>\u003cp>\u003cstrong>美人\u003c/strong>：\u003c/p>\u003cp>场景：开导刚刚失恋的女朋友\u003c/p>\u003cp>故事：我有一个朋友，她失恋了，她觉得自己很悲哀，总是遇人不淑，我想给她讲的故事是我在五六年前，因为有些事情想不通然后就陷入了抑郁的症状中，每天躺在场上都会觉得自己第二天会死掉，然后每天晚上也睡不着觉，一直失眠，并且对整个世界充满了愤怒。每天醒来要么担心自己会没有呼吸，要么担心自己会得恶疾，要么担心出门会发生交通事故，要么担心家里人会发生不好的事情（情感），我当时觉得人生已经走不出来了（阻碍），但是天无绝人之路，在那样的低谷的人生中反而会有触底反弹的机制，当这种机制被开启后，我渴望自己活着，会有种什么都不怕的一种疯狂的状态（渴望），有句话说“女人柔弱，为母则刚”，就是你还没有孩子的时候是柔弱的，但是有了孩子，你会觉得即使我去要饭我都能把孩子养育长大，我的这种什么都不怕的状态就有点像“为母则刚”，摈除一切杂念，专注于让自己开心起来这件事情（行动），最后呢我从抑郁中走出来了（结果）。\u003c/p>\u003cp>我还会对这个朋友说我人生中所有这些糟糕的遭遇，当你走出来的时候，就会成为一份无可替代的礼物，这是多么珍贵的人生体验，你应该为有这样的人生体验而感到高兴。\u003c/p>\u003cp>\u003cstrong>点评\u003c/strong>：我们在次感受到美人强情感的特质，这个故事中展示的部分稍微弱了一些，如果想要更完整，可以把具体场景描述增多一些。\u003c/p>\u003cp>\u003cstrong>荣荣\u003c/strong>：\u003c/p>\u003cp>主题：介绍自己，主要介绍的是阅读给我带来的改变\u003c/p>\u003cp>故事：我是非常普通的一个女孩子，父母呢是工人和农民，毕业之后和大部分人一样到城里来打工，期待可以看到更大的世界（渴望）。然而这个愿望并没有实现，十年如一日的工作慢慢消耗自己的激情（阻碍），晚上回去呢，还会做梦，期待我的人生可以有华丽的改变（渴望）。在一个偶然的机会遇到了自己非常喜欢的工作，也因此有了可观的收入，但是好景不长，后来创业失败，自己的人生又回到了没钱没时间的状态（阻碍），并且害怕新的尝试，害怕再一次的失败，在迷茫无助时内心希望的火苗仍然没有被扑灭（情感），这个时候我开始逼自己去阅读，通过拆书倒逼自己去读书（行动），逐渐养成这样的习惯之后，我发现大部分的夜晚我不再孤独、焦虑、急躁，而是趴在桌上看书，家里的桌子上、饭桌上、地上，随处都是放着一本一本的书（展示），虽然这一年的读书日子没有让我读书加薪，可是她却让我内心充盈、思想饱满，不再对未来有恐惧，也不再对人生又很多焦虑，我这时候要比我过去任何时候都幸福圆满（结果）。\u003c/p>\u003cp>\u003cstrong>点评\u003c/strong>：这是一个非常完整的故事，五要素都有了。展示部分就是那一本本书放在了你家的每一个角落。\u003c/p>\u003cp>&nbsp; &nbsp;最后呢，希望大家在说服他人的时候能够多用故事5要素来说个动人的故事，既能让他人产生共情，又能给他人留下深刻印象，而不是冰冷的数据和空泛的大道理。\u003c/p>\u003cp>今天的拆书就结束了，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1502681286000,"updated_at":1529504178000,"ria":true},{"id":3422,"topic":"如何说服他人","learn_goal":"用说服他人的方法向领导汇报","remark":"你费心费力调查、研究，辛苦做的提案老板从来没有同意过，隔壁小王三分钟提案搞定老板。\r\n\r\n\r\n    是什么秘诀能让你在商业环境中，击中老板大人的痛点，得到他的认可，好奇的宝宝们周末一起来拆书吧。","level":"TF2-3","duration":30,"status":0,"type":0,"chaishujia":{"username":"雨点小","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"大家好，欢迎大家来参加今天的活动，我是王蕾，今天由我给大家带来《请停止无效努力》中的拆页。\r\n【F】这本书的作者是全世界最大的人力资源咨询公司原总监，是位中国的一位女性，16年离职出来创业时写了这本书，豆瓣评分8.6分。主要是关于个人提升的。\r\n【A】那我们平时读的书很多都是关于一个单一的主题，知识点比较多，像我这种理解力不太够的人，读完之后我会觉得有点懵。这本书特别的地方是，每一章都是一个主题，涵盖了个人成长的很多方面，包括天赋、学习能力、思维能力、沟通、职业规划、情绪等等，但并没有泛泛而谈的，从定义、到原理、到行动步骤，都给你说的很详细。所以这本书就像是浓缩液一样的，她把每个主题中经典的观点结合自身经历，给大家展示出来。\r\n【B】所以如果大家对个人提升没什么概念，你对工作和生活中需要掌握的基本技能不是特别了解的话，可以从这本书中找下方向。你工作中是否会遇到向老板提案的情况，和老板汇报了半天，老板一脸大写的懵，如果有的话，我们可以学习下这边书中的提案方法。","ratings_count":0,"texts":[{"id":6284,"quote":"\u003cp>假设你是一家企业的CEO，有两位咨询顾问，分别帮你进行了管理体系的诊断，结论都是一样：组织架构冗余，资源重复配置。你听取了两位顾问的回报，看看你更喜欢谁的方法：\u003c/p>\u003cp>顾问A：“我们访谈了贵公司的高管，调研了主要竞争对手，也研究了贵公司组织架构。我们发现，贵公司组织架构冗余，比如各工厂间研发资源重复配置，导致他们之间产品同质化、恶性竞争。”\u003c/p>\u003cp>顾问B：“正如您所知道的，行业面临严重产能过剩。贵公司要继续发展，优化资源配置、淘汰落后产能、开发高端产品是成功关键。”\u003c/p>\u003cp>“然而，目前组织架构冗余，比如各工厂间研发资源重复配置，导致内部恶性竞争（XX与XX两家工厂已在相互压价）；同时资源分散，导致高端产品开发能力弱（高端产品占比是XX，而竞争对手是XX），只能在中低端产品上打价格战”\u003c/p>\u003cp>“因此，我们建议将XX与XX资源集中到总部来应对这些问题，实现继续发展，且这样做，可以节省10%的人力成本”\u003c/p>\u003cp>两种汇报思路，显然顾问B更容易受到认同。作为一个CEO，每天看到的管理问题很多，只能挑最要命的去解决。如果不能够说清楚，你找到的问题（组织机构冗余）跟他的渴望（公司发展）之间到底有什么冲突，他不会意识到问题的关键性。\u003c/p>","explains":"\u003cp>1.【学习目标】\u003cbr>\u003c/p>\u003cp>我们在完成本次RIA现场学习后，希望我们学会在提案的时候和老板明确指出公司的渴望和事情目前发生的冲突，并给出相关建议。\u003c/p>\u003cp>2.【拆页讲解】\u003c/p>\u003cp>我们来想象下如果我们也是顾问，也都是说明同一结论，大家会说哪些内容呢？\u003c/p>\u003cp>会说为什么产生这个问题吗？会说产生这个问题的背景吗？&nbsp; \u003c/p>\u003cp>怎么样才算是一个较为受认同的汇报呢？拆页用一句话概括，就是最后一段中的，“说清楚你找到的问题跟他的渴望之间到底有什么冲突。”\u003c/p>\u003cp>如何来说出渴望和冲突，我们来分析下A、B两个人的汇报。\u003c/p>\u003cp>A顾问一共说了两句话，意思是我们通过调研发现了一个问题，这个问题导致了一个后果。有句话说的好“不是每个问题都值得被解决”，对于一个公司来说，什么样的问题才值得被解决，影响到公司的目标的问题才值得被解决。所以A提出的组织架构冗余，即使是实际情况，但如果组织冗余对公司的发展我不产生影响，我们还需要花大量人力物力去解决吗？也就是所A顾问没有说清楚这个问题到底会带来多大的影响，作为老板就不知道这个问题是否值得被解决。\u003c/p>\u003cp>我们来看B怎么说，意思是公司的目标是在行业中取得成功，在目前的行业环境下，取得成功关键是……。如果你是老板听到这里你会有什么想法吗？我会想“你说的很有道理，但是怎么了？我们公司难道不是一直朝着这个方向努力的吗？”\u003c/p>\u003cp>这时候，B又告诉你，老板大人：“其实不然，根据我们调查，这些成功的关键因素你们没有做到，而且正在脱离了成功的轨道。因为这些这些数据都能证明这一切。”这时候老板心里肯定一惊，那咋办，你有解决方法吗？有啊，机智的B马上献上自己的建议，这样的汇报老板怎么会不认同呢？\u003c/p>\u003cp>【细化行动步骤】\u003c/p>\u003cp>B的思路是摆出一个公司的渴望，可以理解成是希望达成的目标，给出通往目标路上的几个关键点，指出现在公司情况违背了这几个关键点，所以产生了冲突，实现目标堪忧啊，在这么危机的情况下给出建议，汇报就完成了。按步骤来就是1.希望达成的目标，及实现目标的关键&nbsp; 2.目前企业出现的哪些问题违背了关键点&nbsp; 3.给建议\u003cbr>\u003c/p>\u003cp>当然在商业环境中，我们也不能拍脑袋做事，所以讲事实摆证据很重要。如果B没有给出数据的支持，我就会对B的提案产生质疑，我会说：“你说我们公司有问题就有问题吗？拿出你的证据来。”，这也是拆页片段括号中的内容，给出数据作为支持，比如说要说明恶性竞争，那么到底是哪几家在竞争，价格分别是多少，你要拿得出事实，那么你的这些结论才站得住脚\u003c/p>","interaction":"\u003cp>【A3指令】\u003c/p>\u003cp>假设你是这家咖啡店的管理人员，你们老板年初定下的小目标是这年完成100万的销售小目标，但是呢半年过去了，总销售额却只有20万。老板要求你下周一做个提案，对目前情况做一个诊断。根据刚刚细化的三个步骤，来思考下如何提案。\u003c/p>\u003cp>我们重点是运用三个步骤，不是判断你给出的方案符不符合现实情况，你的数据到底准不准确，考量的不是这个。我给大家一些经营咖啡厅的关键点，供大家参考，比如说有卖的产品的口味、定价、提供的服务、店的特色、主题、经营时间、活动促销、线上线下渠道等等。根据这三个步骤来思考，然后进行下分享。\u003c/p>\u003cp>讨论中的引导：重点是运用这三个步骤，而不在于分析咖啡店发生了什么问题。最好是给到一些数据，来支持下你的结论。\u003c/p>\u003cp>【A3演练】\u003c/p>\u003cp>学习者1：如果我要向老板汇报，我们的目标是完成年底100万的销售额（希望达成的目标），达成这个销售额的关键是经营时间（达成目标的关键点），现在发现一个问题，就是我们经营的时间不是很合理（违背关键点的问题），所以我们要调整我们的经营时间，我们的经营时间是上午10点到下午5点，这个时间安排会错失掉一些客人，所以我们建议把时间做适当的延长，早上9点开始到下午6点，或者更晚一点结束（建议）。因为我们做过一些观察，早上9点的人次已经达到上千，这个时候周围开的咖啡店不多，就三四家，所以我们提早到9点的话会增加客源，提高销售额。（数据）\u003c/p>\u003cp>点评：咖啡店延迟结束时间到6点，如果这个建议能够有数据支持的话会更好\u003c/p>\u003cp>学习者2：假如要向老板汇报，我认为我们认为最大的问题是客流量不够，我们可以看到咖啡店的桌椅太少，客人都是进来看看就走，没办法坐下来消费（问题）。所以我们觉得这个是最大的问题。我们给的建议是200平的场地，50%作为场地，给散客用。另外划一两块区域做集中活动的用途，比如30-50人的一个活动场地，那活动呢每次都有2000-3000的营业额（建议），如果1个月有10场的话，就有2-3万的销售额，半年就能完成目标的20%-30%，如果散客能多一点的话，100万的目标就比较容易达到。\u003c/p>\u003cp>引导：那你刚刚的提案中，达成目标的关键点是什么？我从你们刚刚的描述中我认为，客流量是关键点，所以应该告诉你的老板，如果客流量不足的话，100万的销售目标很可能达不成，那目前情况就是客流量不足，接着再提出你们的建议。而不是一下子就说出问题，因为不说出这个问题会带来多大影响的话，老板不会认为这是个值得被解决的问题。\u003c/p>\u003cp>学习者3：我们的目标是达成100万的年销售量（目标），我们认为实现的关键是人流量（关键点），出现的问题是人流量不够，消费人数少（问题），我们的建议是可以做线上的销售，比如说外卖。（建议）\u003c/p>\u003cp>点评：如果能有一些数据的支持，这个提案就比较完整了。\u003c/p>\u003cp>从刚刚的分享中呢，我为什么一直在强调关键点，因为只有从这个关键点下手找到目前问题与关键点之间的冲突，有了冲突，老板才会觉得这是一个危机性的问题，才会去听你的建议。那么今天我的拆书就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}},{"id":6285,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1502676959000,"updated_at":1502702457000,"ria":true},{"id":3418,"topic":"美英TF1-2定级训练","learn_goal":"完成训练目标","remark":"职业成长技能","level":"TF1-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"石美英","city":""},"club":{"name":"厦门鹭岛抚琴分舵","city":"厦门"},"prologue":"大家早上好，我叫美英，美术的美，英语的英，很高兴认识大家。有一句话说“身体和心灵一定要有一个在路上”，先说说身体，我喜欢瑜伽，从去年开始练习瑜伽，通过瑜伽让我和自己的内心走的更近，学会了接纳自己，聆听自己内心的声音，提升了我的健康。再说说心灵，我喜欢阅读，喜欢阅读各类书籍，这让我的知识面得到了很大提升，同时也拓宽了我的眼界，以前的阅读更多的是为了趣味性，通过认识拆书帮，现在我学会了将阅读所学的知识运用到我的学习和生活中去。\r\n那接下来我们进行分组，今天我们现场总共有6位伙伴，采用就近原则分为两组，洪老师和树英一组，美华和宋坤一组。 \r\n 今天我要拆解的这本书是《请停止无效努力》，作者是孙园媛，曾任职全球顶级管理公司美世咨询项目总监，擅长职业发展、自我认知、个人提升等领域。这本书的内容主要分为三大块，包括天赋、沟通和思维，作者对每块都进行了具体的分析并给出了相应的提升步骤。","ratings_count":0,"texts":[{"id":6280,"quote":"\u003cp>如何让你的演讲信息结构化\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;在这本书之前关于结构化思维的文章里，曾经提到过，人类大脑在处理信息时有两个习惯：第一，不能一次太多，因为信息太多会让大脑的负荷过大；第二，喜欢有规律的信息。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;临场发言时，我们是有压力。这种压力，要不让我们的大脑一片空白、胡言乱语，要不让我们的大脑信息泛滥、毫无头绪。这两种情况，听众听起来都会比较痛苦，不明白你到底想表达的是什么。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;如果说，有一个清晰的结构，发言就变得容易了。一方面，如果你的大脑是杂乱无章的状态，它可以帮你把信息快速整理并输出；另一方面，如果你的大脑是一片空白的状态，它可以作为提示语帮你联想起一些有用信息。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;用结构化思维，帮助你在短时间内更好地沟通，关键是三个步骤。 \u003c/p>\u003cp>第一步，想主题：迅速找到一个切入点，第一句就说出自己的观点。\u003c/p>\u003cp>第二步，搭架子：在论证观点时，思考一个结构（时间、空间、程度），并只说三点，这称为三个“架子”.\u003c/p>\u003cp>第三步，填素材：在每个架子里，填充一些事例、数据等，来推进论据向观点靠近。\u003c/p>\u003cp>在这里和大家举个例子，乔布斯推出第一款苹果手机时进行过一段演讲，大意如下：\u003c/p>\u003cp>苹果公司是一家革命性的公司。为什么这么说呢？1984年，推出Mac电脑，改变了整个电脑行业；2001年，推出ipod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；2007年，推出苹果手机，我相信它将改变更多行业。\u003c/p>\u003cp>我们来剖析一下这段话的结构，就会是：\u003c/p>\u003cp>主题：苹果公司是一家革命性的公司。\u003c/p>\u003cp>架子：1984年、2001年、2007年。\u003c/p>\u003cp>素材：推出推出Mac电脑，改变了整个电脑行业；推出ipod随身听，不仅改变了人们听音乐的方式，也改变了音乐行业；推出苹果手机。\u003c/p>\u003cp>所以，乔布斯这段话的结构也是由三要素组成：主题、架子、素材\u003c/p>","explains":"\u003cp>&nbsp; &nbsp;【学习主题】\u003c/p>\u003cp>&nbsp; &nbsp; 如何实现演讲信息结构化\u003c/p>\u003cp>&nbsp; &nbsp;【学习目标】\u003c/p>\u003cp>&nbsp; &nbsp;在跟随我完成本次RIA现场学习后，学习者能够了解信息结构化的三个步骤，实现对信息结构化的简单应用。\u003cbr>\u003c/p>\u003cp>&nbsp; &nbsp; 拆书原页中讲到一个信息结构化的问题，先来看下为什么要信息结构化呢？相信大家在生活中有遇到一些这样的场景，比如说你向别人描述一件事情的时候，希望能够描述得全面而具体，让别人能够更好地了解，同时也希望能够让别人理解和记住一点关键的东西，那这个时候便需要用到信息结构化了。举个例子，比如说你向别人介绍自己的时候，你希望别人能够全面地了解你，同时又希望别人能够理解并记住你说的一些点，这个时候运用信息结构化便有利于你的介绍。比如当初我在面试的时候，我在向我的面试官介绍我的大学经历的时候分为了三个部分，工作、学习、生活，并且分别从这三块讲了三个故事，既让我的面试官全面了解了我的大学生活，并且也让他记住了我在三大板块的特点：工作中认真负责、学习中勤奋努力、生活中乐于助人，从而给我的面试官留下了很好的印象并且成功通过面试。又比如说，当你在开会的时候，领导问你，对于这次的会议主题你有什么想说的吗？这个时候，你想要把自己知道全部说出来，让领导知道你对这个主题是有所见解的，但是却又担心说了太多领导和同事没有办法理解和记住，因为人的大脑一次容纳的信息是有限的，这个时候，用上信息结构化便能够很好地解决这个问题。运用书中讲到信息结构化的三个步骤：第一步想主题、第二步搭架子、第三步填素材。首先把大致的框架说给领导听，让领导能够先对大的方面有个了解，接着如果领导有时间并且有兴趣就可以将框架中的素材详细讲解给他听，这样便能够让领导得到想要的信息，同时又能确保讲解的全面而具体。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;刚才我所举的例子，自我介绍和向领导汇报工作主题都可以很好地借助信息结构化让别人理解并记住，所以下一次当你向别人描述一件事，希望别人能够理解并记住一些东西的时候不妨采用信息结构化，充分利用书中所说的三个步骤：第一想主题、第二搭建架子、第三填素材。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】激活经验\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>接下来请大家回想下在最近有没有这样的经历，当你想向别人描述或者介绍一些东西的时候，明明你觉得自己已经讲的很细致了，别人却还是没有办法理解或是记住，比如说你在向别人介绍自己的时候，比如说你在向领导汇报工作的时候，再比如说你向别人介绍一座城市的时候，接下来请大家用5分钟时间在组内分享下自己的经历。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;树英：\u003c/strong>虽然我人比较文静，但是我是个性格比较急的人，同时我的领导又是个性格比较急躁的人，所以最初有一段时间我和他沟通的时候特别就容易起冲突，往往我还没有说几句，他马上就很烦躁了，没有耐心接着听我说下去，而且往往我感觉自己已经说得很清楚了，但是他总是没有耐心听我说完,所以我就比较担心和他的沟通。后来我就换了一种方式，和他沟通的时候，特别是针对一些大项目的时候，我会先把方案写出来，将方案写清晰，先发给他看，让他先理解一个大概，等他看过了再去找他沟通，后面发现这种方式还是比较有用的。\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;美华：\u003c/strong>我想起之前有人问我厦门怎么样， 那个时候我一般是想到什么说什么，那么通过今天的拆页学习，我会从厦门的美食、美景、气候三个方面去介绍，这样介绍更加全面而且更具逻辑性。\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;洪老师：\u003c/strong>我想到昨天鹏华问我的一个问题，他说“洪老师，厦门分舵的情况是怎么样的”，我当时听到这个问题就在思考要怎么介绍比较好，那如果按照今天的拆页我会从以下几个方面来介绍：分舵的历史、分舵的活动、分舵的未来规划，先介绍大的框架再对每个框架进行详细介绍。\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;拆书家：\u003c/strong>好，刚才听了那么多伙伴的分享，那我们举树英的例子来做一下解析，树英说她之前和领导汇报的时候，因为领导的性格比较急躁，往往没有办法听完所有的信息就会打断她，而树英作为一个下属，又必须尽到自己的责任，将工作详细汇报给上司，那么这个时候用信息结构化便可以很好地解决这个问题。第一步确定主题，就是确定你要汇报的工作主题；第二步搭架子，将汇报的内容分为几块，把大的点提炼出来，将结果先呈现给领导，第三步填素材，如果领导有时间并且有兴趣的话，便可以将每块的内容再详细说领导听。\u003c/p>\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;通过今天的拆页，我们学习了信息结构化，第一步想主题，第二步搭架子，第三步填素材，那么通过今天的学习，请大家回顾下自己之前分享的经历，如何更好地运用信息结构化来处理，请大家用1分钟时间在便签上写下你的计划。 \u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;美华：\u003c/strong>我会用在自我介绍和演讲的时候，第一步先确定主题，接着再搭建框架，最后填充素材，让整体更加饱满。\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;洪老师：\u003c/strong>我想会用自我管理上面，因为我现在时间安排越来越紧，我会想把时间细致化，把时间分为三块：第一块是家人陪伴时间，第二块是分舵活动时间，第三块是个人工作时间。做好三大块时间的协调。\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;拆书家：\u003c/strong>谢谢美华和洪老师的分享，那今天我们学习了信息结构化，知道了信息结构化包含三个步骤：第一步选主题，第二步搭架子，第三步填素材，那么在接下来的生活中就尝试去运用它吧。最后由于时间关系，那今天我们的拆书就到这里了，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1502634537000,"updated_at":1502634537000,"ria":true},{"id":3027,"topic":"如何与对方感同身受？","learn_goal":"通过学习，学习者能够掌握与对方感同身受的方法","remark":"《请停止无效努力：如何用正确的方法快速进阶》，这本书由职场大咖【李一诺】、【张世东】、【赵隽艳】强烈推荐！！！整本书帮你重新定义努力的真正涵义，找到努力的正确姿势，在这个追求个性的时代成为超级个体。","level":"TF1-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"龚陟","city":"南昌"},"club":{"name":"南昌滕王阁分舵","city":"南昌"},"prologue":"首先，我想来为大家做个简单的自我介绍：我的名字叫龚陟，龚是龙共龚，陟是耳朵旁走路一步两步的步。\r\n【分组】\r\n现在我来给大家做个分组，左边3人为一组。右边4人为一组。","ratings_count":0,"texts":[{"id":5826,"quote":"\u003cp>【图书介绍】\u003cbr>\u003c/p>\u003cp>今天要拆的书是《请停止无效努力：如何用正确的方法快速进阶》，本书由孙圈圈所著。这本书由职场大咖“李一诺”、“张世东”、“赵隽艳”强烈推荐！！！整本书帮你重新定义努力的真正涵义，找到努力的正确姿势，在这个追求个性的时代成为超级个体。\u003c/p>\u003cp>【R】阅读原书拆页\u003c/p>","explains":"\u003cp>【I拆书家讲解引导】\u003c/p>\u003cp>如何与对方感同身受？\u003cbr>\u003c/p>\u003cp>当你的闺蜜跟你倾诉，说她老公不求上进、邋里邋遢；你怎样安慰她才能让她心里平复？怎样教她跟她老公沟通才能让她老公愿意听？其核心在于同理心。下面有三个技巧，大家不妨借鉴下：\u003c/p>\u003cp>技巧一：承认世界的多样性\u003c/p>\u003cp>你跟不同人打交道的时候，会发现有的人很热情，有的人很冷淡；大多数情况下，这个只是内外向性格的差异。我们是做外贸的，每天跟不同国家的客人打交道，这种感受最为明显。我们对待不同片区的客人时，需要承认世界的多样性，采取不同的应对策略。 比如南美的客人，性格外向，热情奔放。家里几只猫几条狗几口人，都爱跟你聊。但是东欧的客人就不一样了。东欧客人性格内向，严肃内敛，公私分明。你要上班时间跟客人聊几口人几条狗几只猫，客人肯定不爱搭理你。所以对待不同片区客人需要采取不同的方式，感同身受，接纳和认可世界的客观性和多样性所呈现出来的不同表象。\u003c/p>\u003cp>技巧二：穿上对方的鞋\u003c/p>\u003cp>做角色扮演去演绎不同的人，你会更能看见这个世界真实的样子。我们做销售的就应该穿上对方的鞋，站在客户的立场上去看待问题。尤其是谈判的时候，多站在对方的角度想想，双赢，这生意才能长久。碰到客户提出的要求我们无法达成的时候，要做到感同身受，对客户的需求表示理解，即使不能全部满足客户要求，也需要找到一些折中的方法取得客户的谅解。\u003c/p>\u003cp>技巧三：放下自我，把“我”变成“我们”\u003c/p>\u003cp>英语里面有句谚语叫“check out your ego at the door”，意思是应该摈弃自我。我们做销售的，应该时刻谨记自己和公司对于客人来说是一个整体，所以我们说话时应该少说“I”，多说“WE”，而如果你能做到感同身受，就要知道其实你跟客人是一个利益共同体，客户赚钱就是我们赚钱。\u003c/p>","interaction":"\u003cp>【A1激活经验】\u003c/p>\u003cp>大家回忆一下我刚才的举例，在经过我的讲解之后，大家回想下以前是不是碰到跟闺蜜或者好基友沟通的时候，既理解不了TA为什么会那么做，也体会不到TA的烦恼，更不能很好的去帮助TA，安慰TA？想想自己有没有过经历过类似的情境，有没有过往的相关经验，请在小组里面进行分享。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>有的人喜欢发了朋友圈之后，自己点赞，以前我完全不能够理解这是为什么？\u003c/p>\u003cp>现在想来，这个就是缺乏同理心。没有意识到“世界的多样性”，每个人生活背景不同，不可能有同样的思维方式，所以并不是每个人都能理解别人的每个行动。如果想要理解别人的行动，就需要站在对方的角度思考。发了朋友圈之后，自己觉得自己写的特别好，或者这个转载的内容特别值得推广，欣喜之余，为自己点赞，表明自我评价和认知很高。\u003c/p>\u003cp>【A2催化应用】\u003c/p>\u003cp>请大家结合今天学的知识点，想想在未来碰到类似的案例，应该如何运用今天所讲的知识点，这个具体的步骤一定要符合SMART法则——Specific（计划有明确的目标）、Measurable（行动是可衡量的）、Attainable（目标是可达成的）、Relevant（运用今天的知识点）和Time-bound（有明确的时间要求）。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>我老婆现在还在怀孕，我下班之后在客厅看电视。我老婆总喜欢叫我去干这个干那个，比如说帮她拿水，拿零食水果，按一下肿胀的腿。以前不明白为什么，现在用同理心来看，站在她的角度看，她是希望我为她服务，花时间在她身上，我能够帮助她提供所需，那样她感觉到她是被关心被关爱的。\u003c/p>\u003cp>后期为了更好的理解“同理心”，我打算在未来1个月通过实践这三个步骤更好的运用“同理心”来促进我们夫妻关系更协调。每天下班之后到睡觉之前的这段时间里，至少花2个小时跟老婆相处，而不是一个人在餐厅看电视。\u003c/p>\u003cp>因为我老婆是属于那种心里有想法，但是不喜欢直接说明白告诉我的。我应该意识到我和她在表达方式上的“不同方式”——她总是通过一些“小要求”试图让我来理解她内心所想，而我常常不能GET她的真实需求。所以对于她提出的“小要求”，我应该站在她的角度来想，她那么说其实真正想要的是更多的关爱，自己怀孕身体不舒服，总是希望有人陪她多说说话，关心关心她。而我要做更多的努力，让她感觉心里和生理都舒畅，才能让我们的孩子在未来出生的时候更健康。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1498395833000,"updated_at":1499260613000,"ria":true},{"id":2814,"topic":"如何表达认同感","learn_goal":"掌握表达认同感的3种技巧，并学会运用","remark":"如何用正确的方法快速进阶。","level":"TF1-1","duration":12,"status":0,"type":0,"chaishujia":{"username":"黄淑群","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"大家好，我是Erica 黄淑群，群众中的淑女，名字很好记吧。\r\n我是一个写作爱好者，也爱好诗歌翻译。经常活跃在线下活动中，学习和成长是一个方面，结交新朋友对我来说也是很宝贵的体验。今天，大家有缘相聚。非常开心。\r\n在这里，先行感谢大家的耐心聆听。\r\n众所周知，我们身边不乏热爱读书的伙伴们。但是往往也有一些伙伴，书读了那么多，自身的成长却还是收效甚微。\r\n关键就在于，书中的知识如果只是在你的眼里过了一遍，但是没有经过你自己的系统梳理，无法形成你可以随手拈来的技能。\r\n那么这时候，救星出现了。拆书帮发起的拆书技能通过便签法RIA把一本书读透，把书拆为己用。R是阅读书中片段；I是用自己的话复述，总结书中片段的要点；A是应用。A1是链接学习者的过往经验，找寻与书中片段的共通之处或反例；A2是未来行动计划。通过激活书中分享的经验，进一步为未来的行动做好改善计划。通过这样的一种读书方式，我们读的不仅仅是几行知识，还结合到我们过去的经历","ratings_count":0,"texts":[{"id":5586,"quote":null,"explains":"\u003cp>I：\u003c/p>\u003cp>“认同”是对别人表达想法时候的一种回应，而获取认同是聊天的一大诉求，所以如何把自己的认同传递给对方特别重要，它奠定了一场聊天的对话气氛，决定聊天是否顺利和愉快。当别人想要从我们这验证她的衣着是否得体的时候，如果我们只是一味地说：是啊，很美啊。未免显得太过敷衍。\u003c/p>\u003cp>如何传递自己的认同呢？片段介绍了3种技巧：1、借助表情表达真挚情感。2、善于倾听，给予对方倾诉的支持。3、用事实赞美对方，真诚表达自己的看法。\u003c/p>\u003cp>1、借助表情。\u003c/p>\u003cp>曾有一项调查表明，语言信息的传递70%看动作表情，另外30%才是看内容。善用表情可以有效地佐证你想传达的信息力度，增加可信度，同时也让对方觉得你对他所反馈的内容是有积极响应的。\u003c/p>\u003cp>举个例子，女朋友们收到男孩子美丽的玫瑰花的时候，有很多可爱的女孩子们都是很夸张地把整个阳光和春天都搬了出来，脸上尽情洒满阳光般的笑容，开心地给了对方一个大大的拥抱。这时候，尽管她一句话也没说，脸上的神情已经让男朋友们受到了肯定，他们知道原来送美人美丽的花朵是件讨人欢喜的事情，自己也会觉得很开心的！\u003c/p>\u003cp>但也有很矜持的女生，默默地接过花朵，然后淡定地说了声，谢谢亲爱的。试想一下你是那些男朋友们，这肯定要在心理揣摩无数遍：她难道不喜欢我送花吗？难道我送的花不是她喜欢的品种？\u003c/p>\u003cp>所以说呀，有时候矜持，也未必是件好事。双方在沟通表达的时候，开心你就放心大胆加上你欢天喜地的表情，让对方从视觉上可以感受到你表达感情的场景，毕竟场景化的认同感让人觉得更加真实嘛。\u003c/p>\u003cp>2、善于倾听。\u003c/p>\u003cp>很多时候，有朋友处于情绪低落期的时候，往往只需要一个聆听者。这个时候，你静静地倾听，听她讲述事情的经过，一直保持眼神交流，适当的时候给予一些回应，表达自己的看法或安慰，都能让对方觉得你有在倾听，你也在“感同身受”的过程中。\u003c/p>\u003cp>当对方需要一个聆听者的时候，她只是觉得自己经历的事情有难过、委屈和不解的情绪，如果你也能够在那个情境中感受她所感受到的难过、委屈和不解，相当于你在关注她的感受，你在给予支持。即使是观点不一致，即使你未必觉得她委屈，但在倾听的这个过程中，她排解了自己的郁闷，这就足够了。\u003c/p>\u003cp>当你看着对方，让她感受到你的真诚，从你的真诚中她感知到其实在你心里，她所讲述的事情你也是重视的，你重视了她的感受，她的倾诉，她会很感激的。这也是为什么许多朋友能成为好朋友的原因。你们感受着彼此间的经历、情绪，并且在相互倾听中扶持走过。\u003c/p>\u003cp>3、赞美对方。\u003c/p>\u003cp>当对方有某一方面做得特别好的时候，不要吝啬你的赞美。赞美对方是拉近彼此距离的好方法。你赞美她，让她从心底里感受到了认同和喜悦，这对双方的关系也有进展。\u003c/p>\u003cp>同时，在赞美中要注意：尽量表达具体事实，而不要一味用很泛的语言。\u003c/p>\u003cp>比如“这个科目只有1/3的人及格，你却拿了90分，太厉害了”要比一句简单的“你好厉害”更真诚，更让对方信心满满。\u003c/p>\u003cp>收到赞美的人心中满怀信心和感激，自信地在某个方面去发挥所长，感激你的肯定，拉近了双方的关系。\u003c/p>\u003cp>所以，下一次，要表达你的认同的时候，不要忘记借助表情去大胆展现你的惊喜和赞叹之情；不要吝惜你的时间耐心去关注和倾听，也要记得用事实去赞美对方。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1：\u003c/strong>\u003c/p>\u003cp>我回顾了一下与一位部门主管A的相处过程，突然发现我们的关系能这么好应该也是跟我传递认同的方式有很大联系。\u003c/p>\u003cp>A是一位很有能力，也热爱分享的人。我经常会在工作之余请她跟我分享一些处事经验，每当她分享的时候，我都会很认真地聆听，集中注意力地看着她一点一滴讲述【倾听】，并且讲到重要部分，会拿出纸笔记录；我听到了精彩部分，还经常时不时地张大嘴巴“哇”了一声，并且情不自禁地鼓掌表示佩服【借助表情】；等她讲述完，我还会借助事实很认真地给予反馈：\u003c/p>\u003cp>A，你真的很厉害。因为你带团队的时候，经常能够很细心地关注下属的需求，并且时常找他们谈话，疏通员工的情绪，不定时地给予成长指导，这对员工来说真心很重要。公司很少人能做到这个程度，这也就是你为什么能受到大家的一致认可的原因。我一定要向你学习。【事实赞美】\u003c/p>\u003cp>每每A跟我分享完，也会觉得特别开心，并且时常很乐意主动跟我分享，我也从中受益颇多。\u003c/p>\u003cp>\u003cstrong>A2\u003c/strong>\u003c/p>\u003cp>我是做教学的相关工作，经常要接触课表。下一周课表会根据教学计划做很大改变，工作量也比较大，当我的助理在5.31号完成的时候，我会这么进行对话：\u003c/p>\u003cp>面带笑容，比出大拇指点赞，并且说：哇，C，这一次的工作量这么大，你却高效地把它排出来了并且没有出一点错，太难得。你真的是排表的专家了，好棒。\u003c/p>\u003cp>如有可能，我还会再引导她：“告诉我，这一次的排表相当不容易，但是这么高效准确地完成，你有什么技巧？从中总结了什么？”\u003c/p>\u003cp>我相信，通过这种让她自己总结自己工作的小技巧，满足了对方被倾听的需求，她会很高兴的。\u003c/p>\u003cp>如果谈话效果很成功，将这个运用记录进入我的“表达认同”的成功案例中。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":5587,"quote":null,"explains":"\u003cp>I：\u003c/p>\u003cp>“认同”是对别人表达想法时候的一种回应，而获取认同是聊天的一大诉求，所以如何把自己的认同传递给对方特别重要，它奠定了一场聊天的对话气氛，决定聊天是否顺利和愉快。当别人想要从我们这验证她的衣着是否得体的时候，如果我们只是一味地说：是啊，很美啊。未免显得太过敷衍。\u003c/p>\u003cp>如何传递自己的认同呢？片段介绍了3种技巧：1、借助表情表达真挚情感。2、善于倾听，给予对方倾诉的支持。3、用事实赞美对方，真诚表达自己的看法。\u003c/p>\u003cp>1、借助表情。\u003c/p>\u003cp>曾有一项调查表明，语言信息的传递70%看动作表情，另外30%才是看内容。善用表情可以有效地佐证你想传达的信息力度，增加可信度，同时也让对方觉得你对他所反馈的内容是有积极响应的。\u003c/p>\u003cp>举个例子，女朋友们收到男孩子美丽的玫瑰花的时候，有很多可爱的女孩子们都是很夸张地把整个阳光和春天都搬了出来，脸上尽情洒满阳光般的笑容，开心地给了对方一个大大的拥抱。这时候，尽管她一句话也没说，脸上的神情已经让男朋友们受到了肯定，他们知道原来送美人美丽的花朵是件讨人欢喜的事情，自己也会觉得很开心的！\u003c/p>\u003cp>但也有很矜持的女生，默默地接过花朵，然后淡定地说了声，谢谢亲爱的。试想一下你是那些男朋友们，这肯定要在心理揣摩无数遍：她难道不喜欢我送花吗？难道我送的花不是她喜欢的品种？\u003c/p>\u003cp>所以说呀，有时候矜持，也未必是件好事。双方在沟通表达的时候，开心你就放心大胆加上你欢天喜地的表情，让对方从视觉上可以感受到你表达感情的场景，毕竟场景化的认同感让人觉得更加真实嘛。\u003c/p>\u003cp>2、善于倾听。\u003c/p>\u003cp>很多时候，有朋友处于情绪低落期的时候，往往只需要一个聆听者。这个时候，你静静地倾听，听她讲述事情的经过，一直保持眼神交流，适当的时候给予一些回应，表达自己的看法或安慰，都能让对方觉得你有在倾听，你也在“感同身受”的过程中。\u003c/p>\u003cp>当对方需要一个聆听者的时候，她只是觉得自己经历的事情有难过、委屈和不解的情绪，如果你也能够在那个情境中感受她所感受到的难过、委屈和不解，相当于你在关注她的感受，你在给予支持。即使是观点不一致，即使你未必觉得她委屈，但在倾听的这个过程中，她排解了自己的郁闷，这就足够了。\u003c/p>\u003cp>当你看着对方，让她感受到你的真诚，从你的真诚中她感知到其实在你心里，她所讲述的事情你也是重视的，你重视了她的感受，她的倾诉，她会很感激的。这也是为什么许多朋友能成为好朋友的原因。你们感受着彼此间的经历、情绪，并且在相互倾听中扶持走过。\u003c/p>\u003cp>3、赞美对方。\u003c/p>\u003cp>当对方有某一方面做得特别好的时候，不要吝啬你的赞美。赞美对方是拉近彼此距离的好方法。你赞美她，让她从心底里感受到了认同和喜悦，这对双方的关系也有进展。\u003c/p>\u003cp>同时，在赞美中要注意：尽量表达具体事实，而不要一味用很泛的语言。\u003c/p>\u003cp>比如“这个科目只有1/3的人及格，你却拿了90分，太厉害了”要比一句简单的“你好厉害”更真诚，更让对方信心满满。\u003c/p>\u003cp>收到赞美的人心中满怀信心和感激，自信地在某个方面去发挥所长，感激你的肯定，拉近了双方的关系。\u003c/p>\u003cp>所以，下一次，要表达你的认同的时候，不要忘记借助表情去大胆展现你的惊喜和赞叹之情；不要吝惜你的时间耐心去关注和倾听，也要记得用事实去赞美对方。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1：\u003c/strong>\u003c/p>\u003cp>我回顾了一下与一位部门主管A的相处过程，突然发现我们的关系能这么好应该也是跟我传递认同的方式有很大联系。\u003c/p>\u003cp>A是一位很有能力，也热爱分享的人。我经常会在工作之余请她跟我分享一些处事经验，每当她分享的时候，我都会很认真地聆听，集中注意力地看着她一点一滴讲述【倾听】，并且讲到重要部分，会拿出纸笔记录；我听到了精彩部分，还经常时不时地张大嘴巴“哇”了一声，并且情不自禁地鼓掌表示佩服【借助表情】；等她讲述完，我还会借助事实很认真地给予反馈：\u003c/p>\u003cp>A，你真的很厉害。因为你带团队的时候，经常能够很细心地关注下属的需求，并且时常找他们谈话，疏通员工的情绪，不定时地给予成长指导，这对员工来说真心很重要。公司很少人能做到这个程度，这也就是你为什么能受到大家的一致认可的原因。我一定要向你学习。【事实赞美】\u003c/p>\u003cp>每每A跟我分享完，也会觉得特别开心，并且时常很乐意主动跟我分享，我也从中受益颇多。\u003c/p>\u003cp>\u003cstrong>A2\u003c/strong>\u003c/p>\u003cp>我是做教学的相关工作，经常要接触课表。下一周课表会根据教学计划做很大改变，工作量也比较大，当我的助理在5.31号完成的时候，我会这么进行对话：\u003c/p>\u003cp>面带笑容，比出大拇指点赞，并且说：哇，C，这一次的工作量这么大，你却高效地把它排出来了并且没有出一点错，太难得。你真的是排表的专家了，好棒。\u003c/p>\u003cp>如有可能，我还会再引导她：“告诉我，这一次的排表相当不容易，但是这么高效准确地完成，你有什么技巧？从中总结了什么？”\u003c/p>\u003cp>我相信，通过这种让她自己总结自己工作的小技巧，满足了对方被倾听的需求，她会很高兴的。\u003c/p>\u003cp>如果谈话效果很成功，将这个运用记录进入我的“表达认同”的成功案例中。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1496501724000,"updated_at":1496502660000},{"id":2420,"topic":"思考结构化","learn_goal":"自上而下找结构，把信息或解决方案放入框架","remark":"  这是以个人提升为主要内容的一本书，也许个人提升这个话题太大，但作为一个开端，促进自己在此基础上不断反思和总结，朝着正确的方向去努力，还是绰绰有余。\r\n    因为你的种种困惑，在这里都能找到答案：1.为什么靠意志力的学习是耍流氓 2.为什么我们的独立思考，既不独立，也不思考 3.为什么你租用海量信息，却无解决问题......","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"雨点小","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"我也是今年加入喜乐这个大团队，在年初的时候，也是刚刚进入拆书的阶段。那么其实和大家在一起活动我感到特别的开心，那么我们这些人有一些共同的爱好，然后能玩到一起，这个家庭就像是兄弟姐妹一样，我特别喜欢，所以我希望我今年能给大家带来一些更加有深度、有意义，然后更加实用的书。\r\n我本身刚刚我也说了，我是做广告行业的，平时身心都很疲惫，所以有什么空出来和大家聚在一起，我觉得特别的满足。\r\n然后我再来介绍下拆书方法和拆书帮。拆书是一种学习方法，简单来说就是把书中知识，链接到我们的经验，并用到下次的实践中去。个人学习是用RIA便签法。R阅读原文拆页，I是用自己的话重述拆页内容，A1是链接以往自己的生活经验， A2是做下一步计划，把书中的知识用到实践中去。\r\n组织学习就是由一位拆书家引导大家把书中的知识做一个现场应用，把书拆为己用。\r\n拆书帮呢自然就是由这样一群喜欢拆书的小伙伴组成的社群，那么它的使命就是把爱好成长的小伙伴培养成拆书家。我们是全国性的公益组织，目前上海有三个分舵，那么喜乐就是其中一个。","ratings_count":0,"texts":[{"id":5121,"quote":"\u003cp>我们来看一个问题：今天是周一，假设你这周需要做如下事情，做一个高管汇报、写一份项目建议书、审阅项目成员的方案初稿，写一篇行业洞察，参加公司组织的一场培训，跟国外专家团队开一次电话会议，跟团队成员吃一次饭。请问，你会如何安排自己本周的工作计划？这个问题对大部分人来说不难，因为我们都知道，在排任务的时候可以用紧急性和重要性的二维矩阵，来决定自己先做什么，再做什么。\u003c/p>\u003cp>再看一个问题，倘若有人问你：如何看待洋酒行业当前所处的宏观大环境？能够思考出一个结构的人可能会比上个问题少，宏观环境分析比较常见的结构是PEST（Political政治层面，Economic经济层面，Social社会层面，Technological技术层面），你可以用这个结构把对你的观点都放进去。\u003c/p>\u003cp>而如果你不用结构，可能会发现，你的回答有可能变成这样“嗯，总体经济不太好，经济都下滑了。”这种缺乏结构化、凭第一感觉得出的结论往往不够全面、非常主观，在主导商业决策、沟通的时候弱势就会非常明显。所以针对一些常见的问题，你可以很容易的找到一个结构，将思考结构化。\u003c/p>","explains":"\u003cp>作者向我们介绍了紧急性和重要性矩阵，我想大家生活中应该用到过。可以帮助大家很合理安排一天要做的事情，如果你用的话都会觉得。其实生活中有不少的二维矩阵会用到，比如适不适合和喜不喜欢，这个工作是适合的但不一定是喜欢的，包括恋人也是\u003c/p>\u003cp>好多小伙伴都说我瘦，其实我有在用二维结构来稳固体重这件事情，怎么用的呢，走进便利店，我们都会下意识的去找口感好的那些食物，俗称垃圾食品。然后我接着会问自己一个问题就是它是有营养的吗，它的二维是在有营养、好不好吃这两个维度，如果你用这两个维度去思考的话是不是就能控制一下你嘴馋的这个欲望。\u003c/p>\u003cp>刚刚说的二维矩阵，那书中还提到另外一个相对复杂的是PEST,，它是用来做宏观分析的，那作者他认为我们在思考问题的是否可以先找一个框架，然后把我们能想到的观点放入这个框架，我们的这些思考这些结论就会更加的全面，更加少带有个人的主观性。为什么需要减少主观性呢，因为我们的知识和经验会限制住自己的思维，我们很容易会习惯性的用我们旧的知识去做一个判断。比如说我妈想在小区对面开个小餐馆，这个时候我一定会立马跳出来说，这肯定不靠谱，为什么呢，开餐厅那么累，你看旁边那家餐厅，开三个月就关门了，我觉得我们肯定成不了。我这个结论特别的想当然，我没有用任何的理性的想法去考虑开餐馆这件事情。作者她是希望我们在下结论的时候，更加合理，更加科学。\u003c/p>","interaction":"\u003cp>那么再来说个我最近遇到的事情，这几年不是微商很盛行嘛，所以我有一个朋友想做卖鞋的这么个微商，然后她过来问我意见，因为做咨询的嘛，你懂的，会有很多人会问你这个建议，那个建议。我当时是这么回她的，我说：“微商很啊，我觉得这几年一定是个趋势，而且看大家发家致富的样子，我觉得完全可以去做。”我现在想来，我当时应该脑袋不怎么清晰才会这样说的。\u003c/p>\u003cp>我至少是要用PEST来分析下大的宏观环境，然后再给她一个相关指导。那我应该做什么样的建议呢。如果用PEST的话，它不是分为四个方面嘛，我们先说社会层面，我觉得不知道大家有没有发现我们的消费习惯和以往不太一样了，为什么呢？因为以往电视中的一些广告啊，我们看了之后可能会吸引去买，但是现在越来越不是这样子了，大街上满街的广告，手机上视频里都是广告，我们基本都不乐于去看了，反而如果有一个朋友用一个产品觉得非常好，然后向你推荐，你反而会去试一试。所以我们这个消费正在趋于社群化，其实微商也是基于我们这样一个趋于养成的消费习惯而兴起来的，那能够看到他们在我们的朋友圈里非常活跃，而不是在大街上做一个广告，它就是活跃在我们的生活当中。那么我们从社会层面讲，微商是可行的。那么再来说下技术层面，做微商没有特别大的技术难度，所这OK。经济层面，这个就很大了，那我们简单来说，如果是做鞋子来说的话，鞋子它不是一个奢侈品，我们人人能买得起。如果是10年20年前可能还是耐用品，但至少在现在，一年买个三四双鞋都不是大的问题。所以我认为在经济萧条的时候，鞋子仍然是一个必需品，所以从这个角度讲，经济层面也不是一个大的问题，是可行的。最后一个政治层面，那我觉得这两年就是因为微商兴起，已经出现了相关的政策去规范它，去支持它，那我觉得从这个方面也没有问题。\u003c/p>\u003cp>所以我应该给我的朋友这样的建议，从大的宏观环境来说做微商是可行的，那么可以看到它符合了我们逐渐在养成的消费习惯，那它也得到了国家的支持，但我们到底是不是去做鞋子这个产品、我们用什么样的手段去做宣传，这是我们需要思考的。我觉得给我的朋友这样的建议才是比较合理，比较客观，然后不带有很多主观的建议的。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1492612883000,"updated_at":1492950307000,"ria":true}]};